INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-e427b91ce9f574c3', 'sup-nam-kem-y', 415, 'Súp nấm kem tươi kiểu Ý', 'Súp nấm đùi gà xay nhuyễn sánh mượt cùng sữa tươi, kem béo, nước dùng rau củ và bánh mì nướng giòn Crostini', 'Bát súp nấm kem kiểu Ý thơm nức mùi nấm đùi gà xào vàng quyện sốt bơ bột mì béo dịu từ sữa tươi và kem tươi, kết cấu mịn mượt ăn kèm lát nấm áp chảo và bánh mì nướng giòn.', 'Múc súp nóng ra 4 bát sâu lòng, xếp vài lát nấm đùi gà áp chảo vàng lên mặt và rắc ngò tây tươi thái nhỏ; dùng kèm bánh mì nướng giòn Crostini.', 'Bảo quản phần súp trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hâm nóng trên lửa nhỏ và khuấy đều, tránh đun sôi bùng làm tách lớp kem sữa.', 'italian', 'mon_canh', NULL, 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Súp nấm kem","Ẩm thực Ý","Khai vị","Món nóng","Crostini"]', '["lunch","dinner"]', '["simmer","pan_fry"]', '["milk","wheat"]', 413, 412.5, 1725, 10.4, 26.3, 12.1, 36.3, 4.2, 9.2, 1046, 2.62, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169761","USDA FDC 170000","USDA FDC 170416","USDA FDC 170859","USDA FDC 170931","USDA FDC 171265","USDA FDC 171413","USDA FDC 171595","USDA FDC 172687","USDA FDC 173430","USDA FDC 173468"]', '7c8bbba944354c10730e3435804c39bdd1a45fe7adbec5a08794092784536a5d', 'dd55a31ed8167edb5db29303f845a55f2efab3d3481de44474a6800803405271', 4),
('imp-f3eb85959cb62d3e', 'sup-ga-rau-cu-y', 416, 'Súp gà rau củ thanh nhẹ kiểu Ý', 'Nước dùng gà trong ngọt tự nhiên hầm cùng cà rốt, khoai tây, cần tây thái hạt lựu và thịt ức gà xé mềm ấm bụng', 'Tô súp gà rau củ kiểu Ý nhẹ nhàng, thanh vị với nước dùng gà luộc trong vắt ngọt tự nhiên, kết hợp cà rốt, khoai tây bùi mềm, cần tây thơm dịu và thịt ức gà xé thớ mềm ngon.', 'Múc súp nóng ra tô sâu lòng, rắc thêm ngò tây tươi thái nhỏ và chút tiêu đen xay mới; rất thích hợp dùng kèm bánh mì nướng giòn cho bữa tối nhẹ nhàng.', 'Bảo quản súp trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng đun sôi nhẹ lại trên lửa vừa cho khoai tây và thịt gà nóng đều.', 'italian', 'mon_canh', NULL, 'easy', 15, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Súp gà","Rau củ","Ẩm thực Ý","Thanh nhẹ","Bổ dưỡng"]', '["lunch","dinner"]', '["simmer","boil"]', '["celery","chicken"]', 327, 327.2, 1369, 30.9, 12.7, 2, 22.1, 4.4, 5.6, 866, 2.17, '["USDA FDC 169230","USDA FDC 169988","USDA FDC 170000","USDA FDC 170026","USDA FDC 170393","USDA FDC 170416","USDA FDC 170460","USDA FDC 170917","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 173468","USDA FDC 173647"]', '242c11f9175823bd4a10d6e99b46a4a6cc8fc319995c8aba53e9107f6c449b00', '0c1b34b177b31edce0a6125ea0bfddc2201888708354f160ceabbc559e3346ec', 4),
('imp-f4c5afa7ccc2a9ed', 'ca-chua-nhoi-thit-nuong', 417, 'Cà chua nhồi thịt nướng lò kiểu Ý', 'Trái cà chua chín mọng ôm trọn nhân thịt heo xay trộn vụn bánh mì, trứng gà và phô mai Parmesan nướng thơm lừng', 'Món Pomodori Ripieni truyền thống đẹp mắt với từng trái cà chua chín chắc tay nhồi đầy nhân thịt heo xay mềm ẩm quyện ruột cà chua băm, trứng gà, bột chiên xù, tỏi thơm và phô mai Parmesan nướng vàng.', 'Dọn ra đĩa trang trí vài lá húng quế Tây tươi; ăn nóng cùng bánh mì giòn chấm nước sốt cà chua tươm ra trong khay hoặc dùng ở nhiệt độ phòng đều ngon.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn làm ấm lại bằng lò nướng 170°C khoảng 10 phút.', 'italian', 'mon_lau_tiec', NULL, 'medium', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Cà chua nhồi thịt","Ẩm thực Ý","Nướng lò","Chiêu đãi","Món chính"]', '["lunch","dinner"]', '["assemble","grill_roast"]', '["egg","milk","pork","wheat"]', 413, 412.9, 1727, 20.8, 29, 9.3, 17.7, 2.5, 4.7, 735, 1.84, '["Panko / Batter Mix Ref","USDA FDC 167902","USDA FDC 169230","USDA FDC 170416","USDA FDC 170457","USDA FDC 170848","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468"]', '3443de2cc2f1809db8908c0f4822c70468b07db86f1cd227dda9f041fff43f38', '65302bfa776f10d23f53949baaf6d963a34bbfedfbe42c75e3c6004ab766a561', 4),
('imp-0d54a1288223d8ac', 'ga-nuong-bo-toi-y', 418, 'Gà nướng bơ tỏi kiểu Ý', 'Đùi gà nướng lò da vàng giòn rụm, thịt mềm mọng đẫm vị bơ tỏi thơm lừng thảo mộc Ý', 'Đùi gà có xương nướng lò ở nhiệt độ cao giúp lớp da ngoài vàng giòn bắt mắt trong khi thớ thịt bên trong vẫn giữ trọn độ ngọt mọng, hòa quyện hương bơ lạt, tỏi phi dịu và thảo mộc Ý.', 'Xếp gà nướng ra đĩa lớn, rưới nước bơ tỏi từ khay và rắc ngò tây tươi thái nhỏ; ăn nóng cùng khoai tây nghiền, bánh mì giòn hoặc salad trộn dầu giấm.', 'Bảo quản thịt gà nguội trong hộp kín ở ngăn mát tủ lạnh tối đa 3 ngày. Khi dùng, làm nóng lại bằng lò nướng hoặc nồi chiên không dầu ở 180°C khoảng 8–10 phút để da giòn trở lại.', 'italian', 'mon_lau_tiec', NULL, 'easy', 15, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Nướng lò","Đùi gà","Bơ tỏi","Ẩm thực Ý","Món chính"]', '["lunch","dinner"]', '["grill_roast"]', '["chicken","milk"]', 424, 424, 1775, 36.5, 28.7, 11.2, 3.7, 0.9, 0.2, 692, 1.73, '["USDA FDC 169230","USDA FDC 170416","USDA FDC 170931","USDA FDC 171319","USDA FDC 171325","USDA FDC 172385","USDA FDC 173430","USDA FDC 173468","USDA FDC 173475"]', '9d32c22e15ac7c286d851f36e1140eedcf041e4a4a80bc081be5e71c5f5a336c', '212e260c9a7ec1399b97869c21565fce040c2afe6e2f8191de94392eeb19db60', 4),
('imp-70e5e19dd4073b76', 'bo-ham-ca-chua-y', 419, 'Bò hầm cà chua kiểu Ý (Stracotto)', 'Thịt bò áp chảo vàng cạnh hầm liu riu nhiều giờ cùng rượu vang đỏ, passata cà chua và rau củ ngọt thanh', 'Món bò hầm truyền thống miền Bắc nước Ý được nấu chậm cùng nền rau củ xào thơm, rượu vang đỏ và sốt cà chua passata, cho thớ thịt bò mềm tơi đậm đà cùng nước sốt sánh quyện tuyệt hảo.', 'Múc thịt bò hầm nóng hổi ra đĩa sâu lòng cùng nước sốt sánh đặc, ăn kèm bánh mì giòn chấm sốt, khoai tây nghiền hoặc polenta nóng.', 'Món hầm để qua đêm trong ngăn mát tủ lạnh sẽ càng thấm vị ngon hơn, bảo quản được tối đa 3 ngày. Hâm lại trên lửa nhỏ, thêm 2–3 muỗng canh nước hoặc nước dùng nếu sốt quá đặc.', 'italian', 'mon_kho', NULL, 'hard', 25, 110, 5, '/frigo/illustrations/delicious-meal.png', '["Stracotto","Bò hầm","Rượu vang đỏ","Ẩm thực Ý","Mùa lạnh"]', '["lunch","dinner"]', '["braise","simmer"]', '["beef","celery","milk","sulphites","wheat"]', 638, 638, 2670, 51.1, 37.4, 14.1, 19.7, 3.8, 7.1, 1231, 3.08, '["USDA FDC 169072","USDA FDC 169761","USDA FDC 169988","USDA FDC 170000","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 171593","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173475"]', 'ae45ed65324a3f5b2bc88be379cd85784ac172b90aacda793b92e8489d3ace9a', '7142bd127adbda02adeb961894284703e4892dbe56741a693ffd7520169dade0', 4),
('imp-500ffbf4fd05f9da', 'mi-y-muc-ot', 420, 'Mì Ý mực sốt cà chua cay', 'Sợi mì spaghetti al dente áo đẫm sốt cà chua bi chua ngọt quyện mực ống săn giòn và vị ớt cay nhẹ', 'Sự kết hợp chuẩn vị biển Địa Trung Hải giữa mực ống tươi áp chảo xém cạnh, om mềm trong sốt cà chua bi nấu cùng rượu vang trắng, tỏi và ớt tươi cay nhẹ, bám quyện hoàn hảo quanh từng sợi mì Ý.', 'Chia mì mực ra 4 đĩa sâu lòng khi còn nóng hổi, rắc thêm ít ngò tây tươi, lá hẹ thái nhỏ và tiêu đen xay; món mì hải sản Ý truyền thống không dùng kèm phô mai để giữ trọn vị ngọt thanh của mực.', 'Mì Ý trộn sốt ngon nhất khi dùng ngay sau khi nấu. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hâm lại trên chảo với 2 muỗng canh nước ở lửa nhỏ.', 'italian', 'mon_bun_pho', NULL, 'medium', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Mì Ý","Hải sản","Mực tươi","Sốt cà chua","Cay nhẹ"]', '["lunch","dinner"]', '["boil","simmer","stir_fry"]', '["molluscs","squid","sulphites","wheat"]', 502, 501.6, 2098, 26.5, 12.5, 2, 67.7, 3.9, 4.5, 393, 0.98, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 169994","USDA FDC 170106","USDA FDC 170416","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223"]', 'f553e7e7396fdd8e4d9de921f8d0efb1a15fb3f1b14a50a75b938d04037e4080', 'a035f9cf8eb30af313f1af857cee33d8567ee0dc9e0159e907a1f3cc513294f6', 4),
('imp-ebc8bf739393ac91', 'canh-tom-dau-phu', 421, 'Canh tôm nấu đậu phụ cà chua', 'Tôm tươi bóc vỏ ngọt săn nấu cùng đậu phụ non mềm mịn và cà chua đỏ au, món canh nhanh 20 phút thanh mát cho bữa cơm tối', 'Canh tôm nấu đậu phụ cà chua là món canh dễ nấu, giàu đạm và nhẹ bụng. Nước canh có màu đỏ cam dịu nhẹ từ cà chua xào, hòa quyện vị ngọt tươi của tôm bóc vỏ cùng đậu phụ mềm mịn và hương thơm thoang thoảng của gừng, hành ngò.', 'Dọn canh nóng ra tô, rắc hành lá, ngò rí và chút tiêu xay; ăn kèm cơm trắng và đĩa rau xào hoặc thịt kho tiêu.', 'Món canh ngon nhất khi dùng nóng trong bữa; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và đun sôi nhẹ 2 phút trước khi ăn.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 10, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Tôm tươi","Đậu phụ","Cà chua","Nấu nhanh"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp","soybean"]', 146, 146.3, 612, 17.2, 6.9, 1, 6.1, 2, 3.2, 1135, 2.84, '["USDA FDC 169231","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '70409cd0634d8a0768eed59b18e9b5ce7a35d8c2503bfee79e59e5e9456a92b4', '69055b03602a378687878976197f61553e3cd710bc5903ab983523a7ee765c90', 4),
('imp-3446b3924b05eb7b', 'canh-bo-bap-cai-ca-rot', 422, 'Canh thịt bò bắp cải cà rốt', 'Nước canh trong veo ngọt lịm từ bắp cải và cà rốt, kết hợp thịt bò thái mỏng mềm thơm cho bữa cơm ấm bụng', 'Canh thịt bò bắp cải cà rốt là biến tấu đầy đủ sắc màu và dinh dưỡng của món canh bò truyền thống. Vị ngọt bùi của cà rốt hòa cùng bắp cải mềm ngọt và lát thịt bò thăn thơm mùi tỏi phi tạo nên tô canh ấm nóng dễ chịu.', 'Dọn canh nóng vào tô lớn, rắc hành lá và tiêu đen xay; ăn kèm cơm trắng nóng và chén nước mắm ớt cắt lát.', 'Nếu còn dư, để nguội rồi bảo quản hộp kín trong ngăn mát tối đa 24 giờ; khi hâm lại đun sôi nhẹ 2 phút trên lửa vừa để tránh thịt bò bị dai.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Bắp cải","Cà rốt","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["beef","fish"]', 211, 211.4, 885, 17.4, 11.4, 3.6, 10.2, 3.1, 5.1, 1287, 3.22, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '899283b9448a9e996d011af9cf278098f656c9866bb62f7ed5eeb241f2a5c166', '721b7d290ef3724cf371fde08a3997b84fc2b17478189e9f98a14df173c3d6f7', 4),
('imp-6e3eb737c7d88a2c', 'ga-kho-trung', 423, 'Gà kho trứng', 'Đùi gà chặt miếng kho mềm cùng trứng gà luộc trong nước màu cánh gián sánh keo, món mặn đậm đà chuẩn vị cơm nhà Nam Bộ', 'Thịt đùi gà săn ngọt quyện cùng những quả trứng gà thấm đều nước kho màu nâu cánh gián sánh mượt, dậy mùi thơm của hành tím, tỏi, ớt giã nhuyễn và nước mắm ngon.', 'Múc gà kho trứng ra tô sâu lòng, rắc hành lá thái nhỏ và tiêu đen xay lên trên; dùng nóng với cơm trắng và dưa cải chua.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng hâm lại trên lửa nhỏ cho gà và trứng nóng đều, nước kho đậm vị.', 'vietnamese', 'mon_kho', 'nam', 'easy', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt gà","Trứng gà","Nam Bộ","Cơm nhà"]', '["lunch","dinner"]', '["braise","boil","stir_fry"]', '["chicken","egg","fish"]', 470, 469.5, 1965, 41.9, 27.7, 7.7, 10.9, 0.6, 7.9, 1243, 3.11, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '47add4ab015821f929e8da48c099e3b503448f700c4884509d10ded1e1fec35e', '7f9821f6467df6d1c0df944ce196f65e9e4a867725c10d9071f1ba9a38801426', 4),
('imp-6251f57b97918111', 'tom-kho-tuong-dam', 424, 'Tôm kho nước tương đậm vị', 'Tôm tươi thịt chắc kho sánh cùng nước tương, dầu hào, rượu nấu ăn và dầu điều đỏ đẹp, món mặn nhanh gọn 15 phút cho bữa cơm tối', 'Tôm tươi rút chỉ lưng thấm đẫm nước sốt nước tương và dầu hào sánh bóng, lên màu đỏ cam bắt mắt từ dầu điều, thơm lừng mùi hành tỏi phi và tiêu đen cay nhẹ.', 'Gắp tôm kho ra đĩa sâu lòng, rưới phần sốt sánh đậm và rắc hành lá cùng tiêu đen xay; ăn nóng với cơm trắng và rau luộc.', 'Ngon nhất khi ăn nóng trong bữa; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo lửa nhỏ.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Tôm tươi","Nước tương","Nhanh gọn","Đưa cơm"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["crustaceans","fish","molluscs","shrimp","soybean","wheat"]', 230, 229.6, 961, 28, 9.1, 1.4, 8.9, 0.7, 5, 1391, 3.48, '["Annatto Infused Oil Ref","MEXT Sake 16021","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '0cccab87392e7c1d147e58186be395ac696e303685bacb16cc5528eb44254ee4', '8942ad36bd6f05b4bd02d44c54c4067c7813a7fd3bc70506fb809e56ecce90b8', 4),
('imp-977a3409383d743f', 'muc-xao-bong-cai', 425, 'Mực xào bông cải xanh', 'Khoanh mực tươi giòn sần sật xào lửa lớn cùng bông cải xanh mướt thấm sốt nước tương và hành tím phi thơm', 'Mực xào bông cải xanh kết hợp giữa những khoanh mực giòn ngọt không hề tanh với bông cải xanh chần sơ xanh mướt, thấm đều gia vị nước tương, hành tím phi thơm và vị cay nhẹ kích thích vị giác.', 'Gắp mực xào bông cải xanh ra đĩa nóng, rắc tiêu đen xay và chút ớt bột nếu thích cay; dùng ngay cùng cơm trắng.', 'Mực xào ngon nhất khi thưởng thức nóng ngay; nếu bảo quản tủ mát trong ngày, hãy đảo nhanh trên chảo lửa lớn khoảng 1 phút để mực không bị dai.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Bông cải","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["molluscs","soybean","squid","wheat"]', 250, 249.6, 1044, 24.2, 9.3, 1.5, 18.7, 3.6, 5.6, 1114, 2.78, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170379","USDA FDC 170499","USDA FDC 170931","USDA FDC 171319","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 174223","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '91482137d85714c73db7543b6d2aefa1b39ab9b330888a3f9f4b4b0842b4f7cc', '3142f42895531c91c833aa31c174f9db96e3960b97d6879e13e8ad853612974b', 4),
('imp-a4ff266c02427746', 'bong-cai-xao-toi', 426, 'Bông cải xanh xào tỏi', 'Bông cải xanh chần sốc lạnh giòn ngọt sần sật xào nhanh trên lửa lớn cùng tỏi phi vàng và chút nước tương thơm dịu', 'Bông cải xanh xào tỏi là món rau xanh thanh mát, giữ nguyên sắc xanh ngọc bích và độ giòn ngọt tự nhiên của từng bông súp lơ nhờ kỹ thuật chần sốc nhiệt, quyện hương tỏi phi vàng thơm lừng và vị mặn dịu của nước tương.', 'Gắp bông cải xanh xào tỏi ra đĩa phẳng khi vừa tắt bếp để giữ độ giòn xanh; dùng nóng kèm cơm trắng và các món mặn.', 'Món rau xào nên ăn hết trong bữa để giữ trọn màu xanh và độ giòn tự nhiên.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 12, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau xanh","Tỏi","Thanh đạm","Dưới 20 phút"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["soybean","wheat"]', 128, 128.3, 537, 4, 8.8, 1.3, 10.8, 3, 2.3, 1042, 2.61, '["USDA FDC 169230","USDA FDC 170379","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Monosodium Glutamate","VN/Asian Seasoning Powder Avg"]', '4322ba7a2ea89c286d85e6455c994f831c0c0423eed749a6db1142e23ba89a53', '829e68521a10ad294a2589ff9a571a0c3f3f37d5e32e6838e28a25bc3ab4cdae', 4),
('imp-f9f08651bc712e93', 'cha-ca-ha-noi-nghe', 427, 'Chả cá Hà Nội tẩm nghệ (Chả cá Lã Vọng)', 'Cá lăng phi lê ướp riềng mẻ nghệ mắm tôm áp chảo thơm vàng, đảo nóng cùng thì là hành lá và lạc rang', 'Chả cá Hà Nội tẩm nghệ là tinh hoa ẩm thực Tràng An nổi tiếng. Cá lăng phi lê ít xương được ướp đậm đà với riềng giã, nước mẻ lọc mịn, bột nghệ và chút mắm tôm rồi áp chảo vàng ươm, sau đó đảo nóng tại bàn cùng thật nhiều hành lá và thì là xanh mướt.', 'Múc chả cá cùng hành lá, thì là ra đĩa hoặc chảo gang nóng, rắc đậu phộng rang giã dập lên trên; ăn kèm bún tươi, rau húng láng, ớt thái lát và mắm tôm đánh bông sủi bọt.', 'Cá sau khi ướp và áp chảo sơ có thể bảo quản ngăn mát 24 giờ; khi ăn chỉ cần đảo nóng lại trên chảo dầu 3–4 phút rồi mới thả hành lá và thì là vào sau cùng để giữ màu xanh giòn.', 'vietnamese', 'mon_chien', 'bac', 'medium', 35, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Chả cá","Hà Nội","Bắc Bộ","Đặc sản"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["crustaceans","fish","peanut","shrimp"]', 483, 483, 2020, 36.3, 19.1, 3.2, 42.7, 4.5, 6.5, 1121, 2.8, '["Asian Shrimp Paste Ref","NIN VN Fresh Bun Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172231","USDA FDC 172233","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 175176","USDA FDC Monosodium Glutamate","VN Com Me Ref"]', 'ffee401f7697af5523a53bb69e581aec59b450990dfdf295d289017350adf105', '4b512f3c182ad64598b040ae5ff7e51f79f3172cd4d41c263a74071f8bc18785', 4),
('imp-0d6c454ae1073ef6', 'su-su-hap-toi', 428, 'Su su hấp tỏi rưới mắm thơm', 'Su su non hấp chín tới giữ nguyên độ giòn ngọt, rưới dầu tỏi phi thơm hòa nước mắm đậm đà cho bữa cơm nhẹ bụng', 'Những miếng su su non xanh mướt hấp cách thủy vừa chín tới giữ được vị ngọt thanh tự nhiên và độ giòn nhẹ, rưới đều hỗn hợp nước mắm dầu tỏi phi vàng thơm nức cùng hành lá xanh tươi.', 'Bày su su hấp ra đĩa sâu lòng, rưới đẫm phần nước mắm dầu tỏi thơm lừng lên trên, ăn nóng kèm cơm trắng hoặc chấm thêm xì dầu ớt.', 'Su su hấp ngon nhất khi ăn nóng ngay trong bữa để giữ độ giòn ngọt; nếu còn dư bảo quản ngăn mát tối đa 24 giờ và hấp lại nhanh 3 phút.', 'vietnamese', 'mon_hap_luoc', 'trung', 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Su su","Thanh đạm","Dễ nấu","Dưới 20 phút"]', '["lunch","dinner"]', '["steam"]', '["fish","soybean","wheat"]', 115, 114.7, 479, 3.1, 6.2, 0.9, 14.2, 3.8, 5.5, 1061, 2.65, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169990","USDA FDC 170005","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '2d39aa22711258adcb8db306d281321578e2b48d3c0839cd2a660f3e1f114af5', 'bb7a09fd308a1f564a4b0465526d64003b8ebd192a3ac008dd287655fdde13c2', 4),
('imp-4d81607829384874', 'ga-hap-gung-hanh', 429, 'Đùi gà hấp gừng hành thơm mềm', 'Đùi gà ướp đậm vị hấp chín mềm mọng cùng gừng sợi, hành tím và hành lá tươi, rưới dầu mè thơm chấm muối tiêu chanh', 'Đùi gà tơ khứa nhẹ ướp thấm gia vị rồi hấp cách thủy cùng gừng non thái sợi, hành tím và hành lá giúp giữ trọn độ ẩm ngọt trong từng thớ thịt, dậy hương thơm ấm bụng rất hợp bữa cơm gia đình.', 'Chặt hoặc để nguyên đùi gà xếp ra đĩa, rưới thêm nước hấp thơm gừng hành và dầu mè; dọn nóng chấm muối tiêu chanh hoặc xì dầu ớt.', 'Gà hấp bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi ăn hấp lại 6–8 phút ở lửa vừa để thịt nóng mềm mà không bị khô.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'easy', 20, 28, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Gà","Gừng","Gia đình","Cơm nhà"]', '["lunch","dinner"]', '["steam"]', '["chicken","sesame","soybean","wheat"]', 364, 364.2, 1525, 36.8, 20.7, 5.6, 6.1, 1.2, 1.5, 1361, 3.4, '["USDA FDC 168155","USDA FDC 169231","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'a9b8458243995913cf6ff16969d41411619ca54ae2f5e1204f8c96f8a5c06071', '503f82046707782b3106372ca923f8e3b3c9feb76253f70315ee87bfee011f7a', 4),
('imp-1b518ba2f068f3ab', 'nom-dua-chua-cay', 430, 'Nộm dứa chua cay giòn mát', 'Dứa chín vàng thái lát quyện cà rốt ngâm đá giòn sần sật, hành lá xanh tươi và đậu phộng rang trong nước trộn chanh ớt hiểm chua cay thanh mát', 'Nộm dứa chua cay mang hương vị nhiệt đới tươi mới với từng lát dứa chín vàng mọng nước, cà rốt bào sợi ngâm đá giòn sần sật, hành lá xanh mát và nước mắm giấm chanh tỏi ớt hài hòa, điểm đậu phộng rang thơm bùi.', 'Bày nộm ra đĩa sâu lòng, rắc đậu phộng rang giã dập và vài lát ớt hiểm lên trên; dùng ngay làm món khai vị giải ngấy.', 'Nộm dứa nên trộn trước khi ăn khoảng 10 phút và dùng hết trong ngày; nếu chuẩn bị trước, giữ riêng dứa thái lát, cà rốt ráo nước và bát nước trộn trong ngăn mát tủ lạnh.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Nộm dứa","Chua cay","Khai vị","Thanh mát","Nhiệt đới"]', '["lunch","dinner"]', '["pan_fry","toss_mix"]', '["fish","peanut"]', 227, 227.1, 950, 6.7, 8.5, 1.1, 35.7, 5.2, 24.4, 1398, 3.5, '["USDA FDC 168155","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647"]', '18f406ea5773b5641570768b74aac904c26d0ca7d62c97924316dcb9c78fee8c', 'a3146e5270cb2448072a6830dc66c1881a0fdce213b2f071c4eb2045f82bdcb5', 4),
('imp-0f336e8735d9ce75', 'goi-muc-dua-leo', 431, 'Gỏi mực dưa leo sả ớt giòn mát', 'Khoanh mực ống trụng giòn ngọt trộn dưa leo bỏ ruột và cà rốt vắt ráo, thơm nức hương sả khoanh, rau răm, húng quế và tỏi phi vàng giòn', 'Gỏi mực dưa leo sả ớt là món gỏi biển giòn mát với từng khoanh mực ống trụng vừa chín tới trắng giòn, hòa quyện cùng dưa leo bỏ ruột và cà rốt vắt ráo, sả thái khoanh thơm nồng, rau răm húng quế và chút tỏi phi vàng rụm.', 'Bày gỏi mực dưa leo ra đĩa, rắc tỏi phi vàng giòn và vài lát ớt lên trên; dọn ăn ngay kèm bánh phồng tôm giòn tan.', 'Nên thưởng thức gỏi trong vòng 30 phút sau khi trộn để dưa leo và mực giữ độ giòn sần sật; nếu chuẩn bị trước, để riêng phần mực trụng, rau củ vắt ráo và nước trộn trong tủ lạnh.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi mực","Dưa leo","Sả ớt","Khai vị","Mát lành"]', '["lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["celery","fish","molluscs","squid"]', 264, 264.1, 1105, 18.6, 4.6, 0.9, 38.1, 2.6, 10.5, 1164, 2.91, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169988","USDA FDC 170106","USDA FDC 170393","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","VN Banh Da Ref","VN Rau Ram Ref"]', '6016d336c0d189b58fdc04b93a98bfd4cd4110fe0bb4a655a06a5addcfe7c627', '46ae58a1a823b3b9805300b780915a87de9e5dec634cdcba77d2e6ac6cd8482e', 4),
('imp-f93013fb234d39d0', 'bun-xao-chay-nam', 432, 'Bún xào chay nấm đùi gà rau củ', 'Sợi bún gạo tươi tơi mềm không bết dính, xào thơm cùng nấm đùi gà, bắp cải, cà rốt và nước tương đậm đà', 'Đĩa bún xào chay mộc mạc mà tròn vị với từng sợi bún gạo tơi mềm thấm đều nước tương thơm lừng, kết hợp nấm đùi gà giòn ngọt, bắp cải và cà rốt thái sợi giòn tươi, dậy hương tỏi phi và hành lá.', 'Gắp bún xào nóng ra đĩa lớn, rắc thêm chút tiêu xay và ớt thái lát nếu thích cay; dùng nóng kèm chén nước tương ớt hoặc dưa leo rau sống.', 'Bún xào ngon nhất khi thưởng thức nóng ngay sau khi nấu; nếu còn dư bảo quản ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo lửa vừa 2–3 phút với 1 muỗng nước lọc.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Bún xào","Nấm đùi gà","Rau củ","Ngày rằm"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry"]', '["soybean","wheat"]', 301, 300.5, 1258, 7.3, 9.5, 1.4, 49.3, 5.5, 7.2, 1516, 3.79, '["NIN VN Fresh Bun Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'f665cba686e6da185c386aba9e09295ad1bb319e876887abd10c1ed43bf85f66', '94a9646b0255d986cdf03e45ba83019cdd9f608535c9b9c2da207bc3d5608b80', 4),
('imp-6af3e18fdac79061', 'mien-tron-ga', 433, 'Miến trộn gà', 'Sợi miến dong dai giòn trộn đều nước tương chua ngọt đậm đà cùng thịt đùi gà luộc giòn mềm, giá đỗ chần, rau răm thơm và lạc rang bùi béo', 'Món miến trộn gà thanh mát nhẹ bụng rất hợp cho bữa trưa mùa hè với sợi miến dong không bị dính bết, thịt đùi gà luộc gừng ngâm lạnh giòn da mềm thịt, quyện sốt nước tương nước mắm chua ngọt cùng rau thơm và lạc rang giã dập.', 'Trộn đều miến dong, giá đỗ, thịt gà thái lát và rau thơm với nước trộn chua ngọt ngay trước khi ăn, rắc lạc rang giã dập và hành lá thái nhỏ lên trên để giữ độ giòn thơm.', 'Gà luộc và nước trộn pha sẵn có thể bảo quản ngăn mát 1–2 ngày; chỉ nên trụng miến dong và trộn cùng rau thơm, lạc rang ngay trước bữa ăn để sợi miến không bị trương nở.', 'vietnamese', 'mon_bun_pho', 'bac', 'easy', 20, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Miến trộn","Thịt gà","Món trộn thanh mát","Bữa trưa"]', '["lunch","dinner"]', '["boil","toss_mix","assemble"]', '["chicken","fish","peanut","soybean","wheat"]', 456, 456.2, 1909, 24.7, 16.1, 3.6, 53.6, 2.9, 5.3, 2051, 5.13, '["USDA FDC 168155","USDA FDC 168952","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 172185","USDA FDC 172238","USDA FDC 172385","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC 174277","VN Culinary Herb Ref","VN Rau Ram Ref","VN/Asian Seasoning Powder Avg"]', '4bdf6baefc2f17e185e40dc3d54e34c5650470569802cd2276ad56e48c644712', 'be80a7cc22818303997be42329af17aea11c8f1665a647f4b6553343960494d0', 4),
('imp-2e39be75d8f72249', 'ca-chua-xao-nam-chay', 434, 'Cà chua xào nấm đùi gà chay', 'Nấm đùi gà xào săn giòn ngọt hòa quyện sốt cà chua chín đỏ mọng sánh mịn, thanh đạm đưa cơm', 'Món xào chay thanh nhẹ nhanh gọn với từng lát nấm đùi gà xém cạnh giòn dai thấm hương tỏi phi, quyện trong phần sốt cà chua chín đỏ mọng chua ngọt dịu, thêm chút dầu hào chay và bột năng giúp nước sốt sánh bóng quyến rũ.', 'Múc cà chua xào nấm ra đĩa sâu lòng khi còn nóng hổi, rắc thêm phần lá hành xanh thái nhỏ lên trên; dùng kèm cơm trắng nóng rất bắt cơm.', 'Món xào ngon nhất khi ăn nóng ngay trong bữa; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, hãy đun nóng lại trên chảo lửa vừa 2–3 phút.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món xào","Cà chua","Nấm đùi gà","Dưới 20 phút"]', '["lunch","dinner"]', '["stir_fry"]', '["soybean","wheat"]', 146, 146.2, 611, 5.6, 8, 1.2, 16.6, 4.3, 6.6, 816, 2.04, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170457","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref"]', '54f494c0506d043fdb1c35af6ae2d92177950bb78c5c4905fe58802b2e488415', 'd025df7fec30106ae191e708cbc862ba2bd6ec0a5b72701e8a0693228b5dff15', 4),
('imp-11b65c6b18266849', 'dau-phu-kho-dua-chay', 435, 'Đậu phụ kho dứa chay chua ngọt', 'Đậu phụ rán vàng giòn kho liu riu cùng dứa chín thơm ngọt trong nước sốt nước tương dầu hào sánh đậm bắt cơm', 'Món kho chay mới lạ kích thích vị giác với đậu phụ trắng chiên vàng giòn bên ngoài, mềm béo bên trong, rim thấm cùng những miếng dứa chín chua ngọt thanh dịu, quyện sốt nước tương dầu hào chay sánh bóng thơm lừng hành tỏi.', 'Múc đậu phụ kho dứa ra đĩa sâu lòng, rưới nước sốt sánh vàng lên trên rồi rắc hành lá, ớt lát và tiêu xay; thưởng thức nóng cùng cơm trắng.', 'Để nguội rồi bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; hâm nóng lại trên lửa nhỏ 4–5 phút cùng 1–2 muỗng nước lọc trước khi ăn.', 'vietnamese', 'mon_chay', 'nam', 'easy', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Nam Bộ","Món kho","Đậu phụ","Dứa"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["soybean","wheat"]', 279, 279.1, 1167, 18.5, 16.3, 2.4, 20.4, 3.1, 11.2, 1520, 3.8, '["USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref"]', 'b2ad2056e8eed27f13f09aed3ec1e10506917787bc4599041d0b1c64db4e17c1', 'b86772bb5d375635120425236b68dd2785a8153b377358756e17d76b9a420019', 4),
('imp-2ae4c4cdd97c5d02', 'com-bo-hanh-tay', 436, 'Cơm bò hành tây', 'Thịt bò thăn xào lửa lớn mềm ngọt cùng hành tây giòn thơm sốt xì dầu, dầu hào, chan lên đĩa cơm trắng nóng dẻo', 'Bữa cơm bò hành tây nhanh gọn chỉ trong 20 phút với thịt bò thăn xào tái chín mềm mọng đậm vị xì dầu, dầu hào, từng múi hành tây chín tới giòn ngọt tự nhiên và phần nước sốt sánh thơm rưới đẫm cơm trắng nóng hổi.', 'Xới cơm trắng nóng ra đĩa sâu lòng, múc phần bò xào hành tây và nước sốt rưới lên trên, rắc hành lá cùng tiêu đen xay và ăn kèm dưa leo hoặc cà chua.', 'Thịt bò xào hành tây ngon nhất khi ăn nóng ngay. Nếu còn dư, bảo quản riêng phần bò xào trong ngăn mát tối đa 24 giờ và đảo nóng lại thật nhanh trên chảo lửa vừa để thịt không bị dai.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm bò","Xào nhanh","Dưới 20 phút","Cơm văn phòng","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","soybean","wheat"]', 535, 535, 2239, 27.8, 18.3, 5.3, 63.1, 2.4, 4.7, 990, 2.48, '["USDA FDC 168878","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '906220caa1a39c810ca2add2cd6437cec447586af26c6ff77b2d2e30315ee415', '477bdb303d022c54561f8cf03a73009eff5f958a26961609b21196c65c713294', 4),
('imp-9a2994a529126adb', 'mi-xao-trung-rau', 437, 'Mì xào trứng rau', 'Sợi mì dai săn xào lửa lớn cùng trứng gà chiên tơi xốp, bắp cải và cà rốt giòn ngọt đậm sốt xì dầu, dầu hào', 'Món mì xào trứng rau đơn giản nhưng đủ sắc hương vị với sợi mì dai săn bóng bẩy quyện sốt xì dầu, dầu hào, trứng gà đánh tơi vàng ươm mềm xốp cùng bắp cải trắng và cà rốt giòn ngọt.', 'Bày mì xào trứng rau ra đĩa nóng, rắc hành lá và tiêu đen xay; dùng kèm tương ớt hoặc ớt tươi thái lát rất tròn vị.', 'Nên ăn nóng ngay sau khi xào để sợi mì tơi dai và rau củ giữ được độ giòn. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ rồi đảo nóng nhanh trên chảo lửa vừa.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Trứng rau","Ăn nhanh","Dưới 20 phút","Tiết kiệm"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry"]', '["egg","fish","molluscs","soybean","wheat"]', 462, 462.4, 1935, 17.5, 14.9, 3.2, 65.3, 5.2, 7.6, 1861, 4.65, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '959d7530bc4a6892152a88e6121c7b1a7f03029916bc5526077e8ea1971c70a7', '39e061c73f6035f9a77370d946b212c29df6aa8a92cae1d5462c36b994adc90c', 4),
('imp-990934aa20b70964', 'lau-bo-rau-thom', 438, 'Lẩu bò rau thơm cà chua', 'Nước lẩu hầm xương bò ngọt sâu hòa quyện vị chua thanh cà chua và chanh tươi, nhúng thịt bò thăn tái mềm cùng rau húng quế, ngò rí', 'Lẩu bò rau thơm cà chua là món lẩu dễ ăn và tròn vị cho những buổi sum họp cuối tuần. Nước lẩu được ninh kỹ từ xương ống bò cho vị ngọt đậm tự nhiên, kết hợp cà chua xào đỏ đẹp và nước cốt chanh thanh mát, nhúng thịt bò thái mỏng chín tới cùng hương thơm nồng nàn của húng quế, ngò rí và rau muống.', 'Bày đĩa thịt bò thái mỏng, nấm đùi gà, rau muống, húng quế, ngò rí và bún tươi quanh nồi lẩu sôi; nhúng thịt bò trong 20 giây cho tái mềm ngọt nước rồi thưởng thức nóng.', 'Thịt bò sống chưa nhúng bảo quản ngăn mát tối đa 24 giờ; phần nước dùng còn dư đun sôi lại 5 phút trước khi dùng tiếp với rau và thịt mới.', 'vietnamese', 'mon_lau_tiec', 'toan_quoc', 'medium', 25, 45, 5, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Lẩu bò","Rau thơm","Cà chua","Tiệc gia đình"]', '["lunch","dinner"]', '["simmer","boil"]', '["beef","fish"]', 587, 587.2, 2456, 42.7, 26.6, 9.5, 45.4, 5.3, 6.5, 1740, 4.35, '["NIN VN Fresh Rice Noodle Ref","USDA Beef Rib / Bone Ref","USDA FDC 168155","USDA FDC 168580","USDA FDC 169230","USDA FDC 169378","USDA FDC 169655","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'd8874f901e38fef4f204a5487eea57c9e7e3608d410d5c5879018734129189a6', '703eb09d0a231801af7c80e50de9bae5496c0960833b0351fda47c3655605f94', 4),
('imp-d0569e8ec34b2bfc', 'bo-xao-gia-do', 439, 'Thịt bò xào giá đỗ lửa lớn', 'Thịt bò thái lát mỏng xào nhanh lửa lớn giữ độ mềm ngọt, kết hợp giá đỗ giòn sần sật thấm vị xì dầu và dầu hào thơm tỏi', 'Đĩa thịt bò xào giá đỗ đậm đà hương vị cơm nhà kiểu Hoa với từng lát thịt bò mềm mọng thấm gia vị và cọng giá đỗ trắng mập vẫn giữ nguyên độ giòn thanh không ra nước.', 'Trút bò xào giá đỗ ra đĩa khi còn bốc khói, rắc chút tiêu đen xay lên trên và ăn ngay cùng cơm trắng nóng, chấm thêm xì dầu ớt lát nếu thích.', 'Món xào giá đỗ nên dùng hết ngay trong bữa để giữ độ giòn tươi; nếu bảo quản tủ mát chỉ nên giữ tối đa 12 giờ và đảo nóng lại rất nhanh trên lửa lớn.', 'chinese', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Giá đỗ","Bữa nhanh","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","sesame","soybean","wheat"]', 277, 276.8, 1159, 20.6, 17.9, 4.8, 8.7, 1.7, 4.6, 1183, 2.96, '["Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '824af3ec1fb57e3672b677be98e41b588ffcdeb9bf0651f2e9cc4732edecce39', 'e696b366cad65bdf7bbc5a8dae3d42d073ac3f554a30dfd92369c3d159590501', 4),
('imp-531f59c246a56bcb', 'vien-thit-chien-trung', 440, 'Thịt viên chiên giòn kiểu Hoa', 'Thịt heo xay quết dẻo cùng trứng gà, gừng hành và ngũ vị hương, vo viên chiên ngập dầu vàng giòn bên ngoài, mềm mọng bên trong', 'Những viên thịt heo chiên vàng rộm, vỏ ngoài hơi xém giòn thơm nức mùi ngũ vị hương, gừng và xì dầu đặc, cắn vào bên trong vẫn giữ được độ dẻo dai và nước thịt ngọt mềm.', 'Bày thịt viên nóng ra đĩa, rắc thêm chút hành lá hoặc ăn kèm dưa leo thái lát; chấm muối tiêu chanh hoặc tương ớt cay.', 'Thịt viên chiên dư có thể để nguội hoàn toàn, bảo quản ngăn mát tối đa 2 ngày (hoặc cấp đông 2 tuần); khi ăn chiên lại bằng nồi chiên không dầu ở 180°C trong 5 phút cho giòn vỏ.', 'chinese', 'mon_chien', NULL, 'medium', 25, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Thịt viên","Món nhậu","Trung Hoa","Giòn rụm"]', '["lunch","dinner"]', '["deep_fry"]', '["egg","pork","soybean","wheat"]', 466, 465.5, 1947, 23.5, 36.8, 11.5, 8.4, 0.5, 2.7, 887, 2.22, '["Dark Soy Sauce Label Ref","Five Spice USDA Ref","Shaoxing Wine Ref","USDA FDC 167902","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '49dbde7cd7208204b2c3551bfe67cd37ed830cc34e64dec743a61e547ba34bd4', '380b9d75ca148b9e218955d40a30f222a170c7cdf8e7c745a89ec9621378fab2', 4),
('imp-3767b2e36f535b7b', 'ga-nuong-tuong-trung', 441, 'Gà nướng xì dầu mật ong kiểu Hoa', 'Ức gà ướp xì dầu đặc, ngũ vị hương, tỏi gừng rồi nướng lửa vừa kết hợp phết mật ong cho mặt ngoài bóng đẹp cánh gián thơm lừng', 'Những miếng ức gà nướng óng ả màu cánh gián từ xì dầu đặc và mật ong, thấm sâu hương thơm ấm áp của ngũ vị hương, tỏi gừng và dầu mè, thịt bên trong vẫn mềm mọng khi thưởng thức.', 'Để gà nghỉ 5 phút rồi thái lát xéo dày 1,5 cm xếp ra đĩa, rưới nước sốt nướng còn lại và rắc hành lá; dùng nóng với cơm trắng hoặc rau cải chần.', 'Bảo quản thịt gà nướng trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại trong lò 160°C khoảng 6–8 phút hoặc áp chảo lửa nhỏ có đậy nắp để thịt giữ độ ẩm.', 'chinese', 'mon_lau_tiec', NULL, 'easy', 20, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Món nướng","Ức gà","Xì dầu","Mật ong","Cơm nhà"]', '["lunch","dinner"]', '["grill_roast"]', '["chicken","sesame","soybean","wheat"]', 308, 308.3, 1290, 41.1, 10.3, 1.8, 11.1, 0.7, 7.4, 943, 2.36, '["Dark Soy Sauce Label Ref","Five Spice USDA Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169640","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 171477","USDA FDC 174277"]', '27e7f7c0c67e933ed17858c3f846ad8c5a915c2010732b3d216eaae722293325', 'd887b64d8ec6b53821389dbbf48eeef7210482e2b7388a34d5196fe1ef9fc821', 4),
('imp-08b08cad387c7c9f', 'dau-phu-chien-toi', 442, 'Đậu phụ chiên giòn sốt tỏi', 'Đậu phụ trắng áo bột bắp chiên vàng giòn rụm, rưới sốt tỏi phi dầu nóng cùng xì dầu nhạt và dầu hào chay đậm đà đưa cơm', 'Đậu phụ cứng chiên áp chảo giòn rụm lớp vỏ ngoài nhờ phủ bột bắp, bên trong vẫn béo mềm, quyện cùng bát sốt tỏi hành lá xèo thơm trong dầu nóng pha xì dầu và dầu hào chay.', 'Xếp đậu phụ chiên còn nóng giòn ra đĩa, rưới đều sốt tỏi lên mặt rồi rắc hạt mè trắng rang và ớt sừng đỏ thái lát; dùng ngay cùng cơm trắng nóng.', 'Món chiên rưới sốt ngon nhất khi ăn ngay lúc vừa làm xong; nếu cần để riêng phần đậu chiên và sốt trong ngăn mát tối đa 2 ngày, khi ăn áp chảo lại đậu cho giòn rồi mới rưới sốt.', 'chinese', 'mon_chien', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Đậu phụ","Món chay","Sốt tỏi","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry"]', '["sesame","soybean","wheat"]', 376, 375.9, 1572, 15.8, 28.4, 4.1, 18.8, 2.1, 7.1, 880, 2.2, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 174277","Vegan Mushroom Sauce Ref"]', '7b2fa3d5c6ad975fad0a6cbed39a4c20257bc5479c5d31fe47233dd41ca31e4f', '4bb1262db0bfbf4d8e10b4be78968c89e77a47fc8352d7ceae9b52d90d8f823d', 4),
('imp-cbbfa59518b7d47d', 'mi-tron-toi', 443, 'Mì trộn dầu hành tỏi phi xì dầu', 'Sợi mì trứng dai ngon trộn đều trong sốt xì dầu nhạt, xì dầu đặc sánh dịu cùng dầu phi hành lá và tỏi vàng thơm nức', 'Món mì trộn kiểu Thượng Hải nhanh gọn chỉ trong 15 phút với từng sợi mì bóng bẩy áo đều dầu hành phi giòn thơm, tỏi phi vàng nhạt cùng hỗn hợp xì dầu nhạt và xì dầu đặc đậm đà.', 'Gắp mì trộn nóng ra đĩa sâu lòng, rắc hành lá phi giòn lên trên, trộn thêm một lần nữa trước khi thưởng thức; có thể ăn kèm trứng ốp la hoặc cải thìa luộc.', 'Mì trộn ngon nhất khi ăn nóng ngay sau khi trộn; nếu dư bảo quản ngăn mát tối đa 1 ngày và xào đảo nóng lại cùng 1–2 muỗng canh nước lọc.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 10, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Bữa nhanh","Tỏi phi","Hành phi","Bữa trưa"]', '["breakfast","lunch","dinner"]', '["boil","toss_mix"]', '["egg","sesame","soybean","wheat"]', 538, 538.4, 2253, 13.7, 22.5, 3.5, 71.1, 3.2, 5.1, 1739, 4.35, '["Dark Soy Sauce Label Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '3f2e2ad68221e100fb1e9330cd81025f83e72e69bf52c95eec13aa909ad3857d', '9a87b6f48885a60b471a8e992bb3737b9b1a2e02bdc689f802ac3225310b2813', 4),
('imp-266587069d92cb79', 'cua-hap-gung', 444, 'Cua biển hấp gừng chấm giấm đen', 'Cua biển tươi hấp chín giữ trọn vị ngọt thịt trên lớp gừng thơm, dùng kèm nước chấm giấm đen Trấn Giang gừng băm hài hòa', 'Món cua hấp gừng thanh tao kiểu Trung Hoa tôn vinh trọn vẹn độ ngọt tự nhiên và thớ thịt săn chắc của cua biển tươi, kết hợp cùng bát nước chấm giấm đen Trấn Giang pha gừng băm dịu vị ấm bụng.', 'Bày cua hấp đỏ au ra đĩa lớn, dọn nóng ngay cùng bát nước chấm giấm đen gừng hành và kẹp càng cua để tách vỏ dễ dàng.', 'Cua hấp ngon nhất khi thưởng thức nóng ngay sau khi lấy khỏi xửng; nếu còn dư có thể gỡ lấy thịt cua bảo quản ngăn mát tối đa 24 giờ và hấp lại 3–4 phút trước khi ăn.', 'chinese', 'mon_hap_luoc', NULL, 'medium', 15, 12, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Cua biển","Hải sản","Gừng tươi","Thanh tao"]', '["lunch","dinner"]', '["steam"]', '["crab","crustaceans","soybean","wheat"]', 169, 169.4, 709, 30.3, 1.8, 0.4, 5.2, 0.3, 3, 1006, 2.52, '["Chinkiang Black Vinegar Ref","Shaoxing Wine Ref","USDA FDC 168833","USDA FDC 169231","USDA FDC 170005","USDA FDC 172238","USDA FDC 173647","USDA FDC 174208","USDA FDC 174277"]', 'd57fa7aeb0a56ff85083e9fdb538ded0d83876700c38c52de73f1bc4a5c7bd39', 'ea1b6ad3a7b78205e785d7b1ef610a762fac3a3abd2daf3bd88d5a415ce0abff', 4),
('imp-b02fdf7cecfae119', 'muc-kho-tuong', 445, 'Mực ống kho xì dầu gừng', 'Khoanh mực ống tươi săn giòn ướp rượu Thiệu Hưng và xì dầu, kho nhanh cùng gừng sợi tạo nước sốt sánh nâu cánh gián thơm hương dầu mè', 'Món mực ống kho xì dầu gừng kiểu Hoa với những khoanh mực trắng dày thịt săn giòn, thơm hương rượu Thiệu Hưng và gừng sợi ấm nồng, thấm đẫm nước sốt hai loại xì dầu sánh nâu bóng mượt điểm dầu mè thơm lừng.', 'Múc mực kho cùng nước sốt sệt ra đĩa sâu lòng, rắc hành lá cắt khúc và tiêu đen xay; dùng nóng kèm cơm trắng dẻo rất bắt vị.', 'Bảo quản mực kho trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại nhanh trên chảo lửa nhỏ khoảng 2–3 phút, tránh đun lâu làm mực bị dai.', 'chinese', 'mon_kho', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Mực ống","Xì dầu","Cơm nhà","Đậm đà"]', '["lunch","dinner"]', '["braise"]', '["molluscs","sesame","soybean","squid","wheat"]', 319, 319.1, 1335, 30.7, 13, 2.2, 17.9, 0.7, 9.3, 1359, 3.4, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 174277"]', 'f6f1b70b0517adb77f41f869313d03f5968c5b45c5c9d4ebb037e44ea56f7f2d', '7bfa2e178cb64310786a5285564c758771542799b9dcf357eea423252d2f1cd1', 4),
('imp-4693d6520fbd9d49', 'bo-nuong-toi', 446, 'Thịt bò nướng tỏi lát kiểu Hoa', 'Thịt bò thái lát mỏng ngang thớ ướp xì dầu nướng lửa lớn xém cạnh, phủ tỏi lát phi vàng giòn và hành lá chấm muối tiêu đậm đà', 'Món thịt bò nướng tỏi thơm lừng với từng lát bò thăn mềm mọng cháy cạnh nhẹ, hòa quyện hương xì dầu dầu hào đậm đà, điểm xuyết những lát tỏi phi vàng giòn rụm và muối tiêu chấm kèm.', 'Xếp thịt bò nướng nóng ra đĩa, rắc tỏi lát phi vàng cùng hành lá xanh lên mặt; thưởng thức ngay cùng muối tiêu và cơm trắng hoặc cuốn rau sống.', 'Thịt bò nướng ngon nhất khi dùng ngay lúc nóng; phần dư bảo quản ngăn mát tối đa 24 giờ và áp chảo nóng lại trên chảo gang khoảng 1 phút cho vừa ấm.', 'chinese', 'mon_lau_tiec', NULL, 'easy', 20, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món nướng","Thịt bò","Tỏi phi","Cháy cạnh","Món nhậu"]', '["lunch","dinner"]', '["grill_roast","pan_fry"]', '["beef","molluscs","soybean","wheat"]', 367, 366.5, 1534, 32.9, 23, 7.2, 6.2, 0.9, 0.8, 1493, 3.73, '["USDA FDC 169230","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '63825ac212546f1837503016f8c9bc1eb3582f9d7028058f89211e888b7f63ca', 'b3497dbf333c4794f197090361532b9451188ee3a8b1dbf3d33d3ef4ef8f8881', 4),
('imp-dd48c08a9b9ed207', 'suon-chien-gion', 447, 'Sườn non chiên giòn ngũ vị', 'Sườn non ướp thấm xì dầu, dầu hào và ngũ vị hương, nhúng hỗn hợp trứng gà bột chiên giòn rồi chiên ngập dầu vàng rụm mềm ngọt', 'Từng khúc sườn non thơm lừng ngũ vị hương và tỏi, được bao bọc bởi lớp bột trứng vàng ruộm giòn tan bên ngoài trong khi thớ thịt sát xương bên trong vẫn mềm ngọt mọng nước.', 'Xếp sườn chiên nóng ra đĩa, dọn kèm chén muối tiêu hoặc tương ớt cay; ăn cùng cơm trắng nóng và dưa leo thái lát giúp cân bằng vị béo.', 'Bảo quản sườn chiên trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn làm nóng giòn lại bằng nồi chiên không dầu ở 180°C trong 6–8 phút.', 'chinese', 'mon_chien', NULL, 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Sườn non","Giòn rụm","Ngũ vị hương","Cơm nhà"]', '["lunch","dinner"]', '["deep_fry"]', '["egg","molluscs","pork","soybean","wheat"]', 522, 522.1, 2185, 23.2, 35.3, 11.1, 26.9, 1.2, 2.4, 1179, 2.95, '["Five Spice USDA Ref","Panko / Batter Mix Ref","USDA FDC 167861","USDA FDC 169230","USDA FDC 169655","USDA FDC 170931","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '6b6b65f49d20c5877f58b95c115bd4c6ed66c6050a13642e1399c839ec181a14', 'ffdc230151157ecaee29db8d31d2faf6dcb64141d34a42b4a58b975f8c715de6', 4),
('imp-b4924a7d33d5acff', 'chao-trung-trung', 448, 'Cháo trứng vân mây kiểu Hoa', 'Cháo trắng ninh nhừ sánh mịn rưới dòng trứng gà đánh tan tạo vân hoa mềm mượt, điểm hành lá, gừng sợi và tiêu trắng ấm bụng', 'Nồi cháo trắng sánh nhừ bông mịn kiểu Hoa với những sợi vân trứng gà vàng óng mềm mượt hòa quyện, thoang thoảng mùi tiêu trắng ấm nồng, hành lá tươi và chút xì dầu nhạt dịu vị.', 'Múc cháo nóng ra tô, rắc gừng tươi thái sợi và hành lá xanh; dọn kèm chén xì dầu nhạt để mỗi người tự nêm thêm theo khẩu vị.', 'Cháo để nguội sẽ đặc lại; bảo quản hộp kín trong ngăn mát tối đa 2 ngày và khi hâm nóng hãy thêm chút nước sôi khuấy đều trên lửa nhỏ.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 15, 45, 3, '/frigo/illustrations/delicious-meal.png', '["Cháo nóng","Trứng gà","Bữa sáng","Dễ tiêu","Thanh nhẹ"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["egg","soybean","wheat"]', 268, 268, 1121, 9.6, 6.1, 1.7, 42.2, 1.2, 0.6, 1083, 2.71, '["USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '72871a2fc746552ac6e78133bc0ed9bcd2492780c7b69628ed27fb2f12f7a63c', '71bfca88335e031c523fcfc1ee4d25cf3fef4a58432f94a506be3462ddcc2bb1', 4),
('imp-4a712c9f5f9913be', 'mi-tom-nong', 449, 'Mì nước tôm tươi gừng hành', 'Tô mì trứng dai ngon chan nước dùng gà trong ngọt thanh, thơm gừng tỏi phi với tôm tươi săn ngọt, cải thìa và nấm giòn tươi', 'Tô mì nước nóng hổi kiểu Hoa với nước dùng gà thanh ngọt quyện hương gừng tỏi phi dịu nhẹ, sợi mì trứng dai mềm ăn kèm tôm tươi săn giòn, cải thìa xanh mướt và nấm thái lát.', 'Múc mì, tôm và rau ra tô sâu lòng, chan ngập nước dùng nóng hổi, rưới chút dầu mè thơm và rắc hành lá tươi; dùng ngay khi còn nóng.', 'Nên nấu và dùng ngay để mì không bị trương nở và tôm giữ độ giòn ngọt; nếu bảo quản tủ mát tối đa 24 giờ, nên để riêng mì với nước dùng rồi đun sôi lại phần nước dùng trước khi chan.', 'chinese', 'mon_bun_pho', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì nước","Tôm tươi","Bữa sáng","Thanh ngọt","Nhanh gọn"]', '["breakfast","lunch","dinner"]', '["boil","simmer"]', '["crustaceans","egg","sesame","shrimp","soybean","wheat"]', 393, 393.3, 1646, 32, 8.3, 1.5, 47.8, 2.9, 2.8, 1826, 4.57, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169251","USDA FDC 170005","USDA FDC 170390","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '77dfdf08c281b1e059a2f0efb33b0e5de7af05b5b06ee6880b516b5947da74aa', '9112bf61989ba5f5c8413a0bfd440dad5c25784e59b73e9429b94a93a86098f0', 4),
('imp-a27445c786a3fd67', 'com-bo-donburi', 450, 'Cơm bò Gyudon Nhật Bản', 'Thịt bò thái lát mỏng om mềm cùng hành tây ngọt dịu trong nước dùng Dashi xì dầu Mirin Sake, phủ lên cơm trắng nóng và hành lá trứ danh Nhật Bản', 'Tô cơm bò Gyudon trứ danh của Nhật Bản với từng lát thịt bò mềm mọng thấm đẫm nước sốt ngọt mặn cân bằng từ Dashi, xì dầu Nhật, rượu Sake và Mirin, hòa cùng hành tây thái lát chín mềm đặt trên cơm trắng hạt ngắn nóng hổi.', 'Xới cơm trắng nóng ra 3 tô lớn, chan một ít nước sốt om xuống cơm trước rồi gắp thịt bò và hành tây phủ đều lên mặt, rắc hành lá và ăn kèm gừng tươi thái sợi mỏng.', 'Nếu còn dư, bảo quản riêng phần thịt bò nước sốt và cơm trong hộp kín ở ngăn mát tối đa 2–3 ngày; khi ăn chỉ cần đun nóng lại phần bò trên lửa nhỏ 2–3 phút rồi chan lên cơm vừa hâm nóng.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Gyudon","Cơm bò Nhật","Donburi","Bữa trưa nhanh","Nhật Bản"]', '["lunch","dinner"]', '["simmer","assemble"]', '["beef","fish","soybean","wheat"]', 578, 577.5, 2417, 31.6, 12.8, 4.8, 75.9, 1.8, 14.4, 1420, 3.55, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 168878","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 174277"]', '17301b1ed091904c487ee0f6e50f09c9ff061f1e11d5505189ed26287c6a592d', '9e61ebe8f64df677ec53eba0498922451bec17b3c3c6ae04c9b8da5627eb1bd0', 4),
('imp-aba623dc468a9569', 'canh-ca-nam-nhat', 451, 'Canh cá hồi nấu nấm kiểu Nhật', 'Canh trong nước dùng tảo bẹ Kombu nấu cùng phi lê cá hồi chần khử tanh kiểu Shimofuri, nấm đùi gà, gừng lát, rượu Sake và xì dầu Nhật thanh ngọt', 'Tô canh cá hồi nấu nấm kiểu Nhật trong vắt và thanh nhẹ với nước dùng ngâm tảo bẹ Kombu ngọt umami tự nhiên, thịt cá hồi phi lê xử lý chần sơ kiểu Shimofuri hoàn toàn không tanh, kết hợp nấm đùi gà và hương gừng rượu Sake ấm áp.', 'Múc canh nóng ra 4 bát, chia đều các miếng cá hồi và nấm đùi gà, thả hành lá lên trên để dậy mùi thơm; dùng nóng kèm cơm trắng hoặc các món kho mặn.', 'Canh ngon nhất khi ăn nóng trong ngày; nếu bảo quản tủ mát tối đa 1–2 ngày, hâm nóng nhẹ trên lửa nhỏ đến khi vừa sôi lăn tăn, tránh khuấy mạnh làm vỡ miếng cá hồi.', 'japanese', 'mon_canh', NULL, 'easy', 20, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Canh cá Nhật","Cá hồi","Nấm đùi gà","Tảo bẹ Kombu","Thanh ngọt"]', '["lunch","dinner"]', '["simmer"]', '["fish","salmon","soybean","wheat"]', 238, 238.1, 996, 22.9, 13.7, 3.1, 4.4, 1.4, 0.8, 871, 2.18, '["MEXT Sake 16021","USDA FDC 168457","USDA FDC 168580","USDA FDC 169231","USDA FDC 170005","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175167"]', '7c3c4687425844448aeff9f8d62f16bcdde03c954e0ed7fecbe1a8e11b931541', '8b12d93532906aedb8027ff4142ac10debcad55aab1a165c5f810e14f9e8b916', 4),
('imp-4f398ac575200416', 'mi-udon-ca-ri', 452, 'Mì Udon cà ri gà Nhật Bản', 'Sợi mì Udon dai mượt chan nước sốt cà ri Nhật sánh đậm từ viên cà ri, nước dùng Dashi, đùi gà mềm ngọt, cà rốt và hành tây ấm nồng', 'Tô mì Udon cà ri gà chuẩn vị Nhật Bản kết hợp sợi mì lúa mì bản to dai mềm với phần nước dùng cà ri sánh mượt đậm đà từ nước dùng Dashi, viên cà ri Nhật, xì dầu, rượu Sake cùng thịt đùi gà và rau củ ngọt thanh.', 'Xếp mì Udon vừa trụng nóng vào 3 tô sâu lòng, chan ngập nước cà ri gà nóng hổi lên trên, rắc hành lá xanh thái khoanh; có thể ăn kèm một ít ớt bột 7 vị nếu thích vị cay ấm.', 'Mì Udon nên luộc và dùng ngay để sợi giữ độ dai; phần nước cà ri gà thừa có thể bảo quản hộp kín ngăn mát tối đa 3 ngày, khi ăn hâm nóng lại với ít nước lọc và trụng mì mới.', 'japanese', 'mon_bun_pho', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Udon","Cà ri Nhật","Đùi gà","Món nước ấm","Nhật Bản"]', '["lunch","dinner"]', '["simmer","boil"]', '["chicken","fish","soybean","wheat"]', 654, 653.5, 2734, 31.9, 27.7, 8.5, 64.6, 5.1, 6.6, 1827, 4.57, '["MEXT Boiled/Fresh Udon","MEXT Curry Roux Ref","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 171413","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277"]', '029fd3635ce1534f94d1d3cbb7de905d4cd98c429ae0a9d02e68f2fae2076b7d', '77a607c294bce2aff865c1ed6488ac5264ed289ddd06d63cd2c0dbe4802aa0a1', 4),
('imp-b8731e057182331b', 'bap-cai-tron-me-nhat', 453, 'Bắp cải trộn mè rang kiểu Nhật', 'Bắp cải thái sợi bóp muối vắt ráo giòn mát trộn cùng hạt mè trắng rang giã dập, xì dầu Nhật, dầu mè, giấm gạo và hành lá thanh vị', 'Món rau phụ bắp cải trộn mè kiểu Nhật thanh mát và giòn sần sật: bắp cải thái sợi được ủ nhẹ với muối cho mềm giòn tự nhiên rồi trộn đều trong hỗn hợp mè trắng rang giã dập quyện xì dầu Nhật, đường, dầu mè thơm và giấm gạo.', 'Bày bắp cải trộn mè ra đĩa nhỏ, rắc thêm chút mè nguyên hạt lên mặt; dùng mát làm món rau phụ giải ngấy rất hợp bên cạnh thịt nướng, cá chiên hoặc cơm cà ri.', 'Món trộn ngon nhất khi dùng trong ngày để giữ độ giòn tươi của bắp cải; có thể bảo quản ngăn mát tối đa 1–2 ngày trong hộp kín và chắt bớt nước tiết ra nếu có trước khi ăn.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món trộn Nhật","Bắp cải","Mè rang","Rau phụ","Giòn mát"]', '["lunch","dinner"]', '["toss_mix"]', '["sesame","soybean","wheat"]', 109, 108.8, 456, 3.4, 5.6, 0.8, 13.4, 4.3, 7.9, 428, 1.07, '["USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 172238","USDA FDC 173468","USDA FDC 174277"]', '2224bcbe84f1f5d3b9be274976e4a2b31b7f312643beafadfb4e833491a08a32', 'a27cf0b9a5c4235a5918ce66936cce8739d838d7442dfa01dd6209b498e25ec8', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-f04b28987d7cd34a', 'cua-nuong-muoi-nhat', 454, 'Cua nướng muối biển kiểu Nhật', 'Chân cua biển cắt hở nửa vỏ ướp rượu Sake, muối hạt và quết nhẹ bơ lạt nướng than hồng cháy cạnh thơm lừng vị biển Hokkaido, chấm xì dầu chanh tươi', 'Món cua nướng muối kiểu Nhật (Yaki-kani) trứ danh vùng Hokkaido: từng thớ thịt cua biển tươi ngọt mọng nước được bảo vệ bởi lớp vỏ nướng xém cùng muối biển, rượu Sake và chút bơ lạt thơm béo, ăn kèm chanh vàng tươi và xì dầu.', 'Dọn cua nướng muối còn nóng hổi ra đĩa lớn, rắc thêm hành lá xanh và xếp các múi chanh vàng bên cạnh; khi ăn vắt chanh tươi lên thịt cua và chấm thêm xì dầu Nhật nếu thích.', 'Cua nướng ngon nhất khi thưởng thức nóng ngay tại bàn; nếu còn thừa, tách lấy phần thịt cua bảo quản hộp kín trong ngăn mát tối đa 1 ngày và áp chảo làm nóng nhanh với chút bơ trước khi dùng.', 'japanese', 'mon_lau_tiec', NULL, 'medium', 20, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Cua nướng muối","Hải sản Nhật","Tiệc nướng","Hokkaido","Cao cấp"]', '["lunch","dinner"]', '["grill_roast"]', '["crab","crustaceans","milk","soybean","wheat"]', 142, 141.5, 592, 20.6, 4.9, 2.6, 2.1, 0.5, 0.5, 939, 2.35, '["MEXT Sake 16021","USDA FDC 167746","USDA FDC 170005","USDA FDC 173430","USDA FDC 173468","USDA FDC 174208","USDA FDC 174277"]', '1dff837557626b9103ea8365e94224e7fdacb9f319f1f89a53b44c8ec3d79627', '00a37d510676eb95f279699e8e9c5315bc82cb21205f26cead47876f4b72f533', 4),
('imp-bf6c9c4d92b2e04c', 'tom-om-gung-nhat', 455, 'Tôm om gừng nước tương kiểu Nhật', 'Tôm tươi nguyên con om mềm đậm vị trong nước dùng Sake Mirin xì dầu Nhật và gừng thái lát thơm ấm nồng, dùng nóng chan cơm cực kỳ đưa miệng', 'Món tôm om gừng Shogani kiểu Nhật Bản với những con tôm tươi săn giòn, đỏ au đẹp mắt thấm đẫm nước sốt om ngọt mặn hài hòa từ xì dầu Nhật, rượu Sake, Mirin, đường và hương gừng tươi cay ấm.', 'Gắp tôm om ra đĩa sâu lòng, rưới 2–3 muỗng canh nước om ấm lên trên, phủ gừng thái sợi mảnh cùng hành lá xanh; dùng nóng kèm cơm trắng dẻo.', 'Có thể bảo quản phần tôm và nước om trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn chỉ cần hâm nóng nhẹ trên lửa nhỏ khoảng 2 phút hoặc thưởng thức nguội theo kiểu món nguội Nhật cũng rất ngon.', 'japanese', 'mon_kho', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Tôm tươi","Gừng tươi","Nhanh gọn","Đưa cơm"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","shrimp","soybean","wheat"]', 162, 162, 678, 17.2, 0.6, 0.1, 17.1, 0.5, 13.1, 973, 2.43, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '1494c153a97c61068bd81c0f6a34af390048665377a77ee56a46a0f3d9279865', '11afc0db5d6c391c184f4a77aa5b8af750777e4ce386e0eb88c08db55dadde91', 4),
('imp-92aabff659e3c551', 'ga-xao-toi-han', 456, 'Gà xào sốt tỏi Hàn Quốc', 'Thịt đùi gà rút xương áo bột áp chảo vàng giòn, phủ đều lớp sốt tỏi băm mật ong xì dầu óng ả đậm đà cực kỳ đưa cơm', 'Món gà xào sốt tỏi kiểu Hàn hấp dẫn với từng miếng thịt đùi gà rút xương ngoài giòn rụm, bên trong mọng nước, quyện đều lớp sốt tỏi băm mật ong, giấm gạo và xì dầu đặc sánh bóng thơm lừng.', 'Bày gà xào sốt tỏi ra đĩa lớn, rưới phần sốt sánh còn lại trong chảo lên trên, rắc hành lá thái nhỏ và mè trắng rang; dùng nóng cùng cơm trắng và củ cải muối.', 'Món ngon nhất khi dùng nóng ngay để cảm nhận lớp vỏ giòn; phần thừa bảo quản ngăn mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu 170°C trong 4 phút hoặc đảo nhanh trên chảo.', 'korean', 'mon_xao', NULL, 'easy', 15, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Thịt gà","Món xào","Sốt tỏi","Hàn Quốc","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["chicken","sesame","soybean","wheat"]', 444, 444.4, 1860, 29.3, 20.5, 4.9, 34.9, 1.1, 17, 1071, 2.68, '["Dark Soy Sauce Label Ref","USDA FDC 168833","USDA FDC 169230","USDA FDC 169640","USDA FDC 169698","USDA FDC 169761","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171319","USDA FDC 171325","USDA FDC 171413","USDA FDC 172238","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647"]', 'f2d3a38f7f9578cbe8c6248e0a1a514c23f23f8ad1fc6fc3d9e959e1e4d89e20', '0fc2b61f8edd3d9ad573942afa7b3473dfec799c267590e4509bd76d9e7893a9', 4),
('imp-4b592ae31a81a527', 'bo-kho-tuong-han', 457, 'Thịt bò kho tương Hàn Quốc', 'Thịt bò hầm mềm tơi xé dọc thớ thấm đẫm nước tương mặn ngọt cùng tỏi nguyên tép và ớt sừng thơm lừng chuẩn món Jangjorim', 'Món thịt bò kho tương Hàn Quốc (Jangjorim) mang hương vị mặn ngọt đậm đà đặc trưng: thịt thăn bò được hầm mềm rồi xé dọc thớ thấm vị xì dầu, ăn kèm tỏi kho bùi béo và ớt sừng cay dịu rất bắt cơm.', 'Xếp các thớ thịt bò xé ra đĩa sâu lòng cùng tỏi kho và ớt sừng, rưới nước kho sánh đậm lên trên; ăn nóng hoặc nguội cùng cơm trắng dẻo.', 'Món kho mặn giúp bảo quản rất tốt trong hộp kín ở ngăn mát tủ lạnh đến 5–7 ngày; khi ăn chỉ cần gắp lượng vừa đủ hâm nóng lại cho tan mỡ.', 'korean', 'mon_kho', NULL, 'medium', 15, 75, 5, '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt bò","Nước tương","Hàn Quốc","Cơm nhà"]', '["lunch","dinner"]', '["boil","braise"]', '["beef","soybean","wheat"]', 248, 248.3, 1039, 25.3, 11.9, 4.5, 9.5, 0.5, 6, 1489, 3.72, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170931","USDA FDC 173647","USDA FDC 174277"]', '0716880b968e8f3486ee16ac356efc7294374b8f322929723e2a32459b3ed90f', '1def3af2778313e504838c2fd330838750b0dd3ac3838098d5416eeb9da2b2a4', 4),
('imp-72e70eb4e8fba4db', 'tom-xao-kim-chi', 458, 'Tôm xào kim chi Hàn Quốc', 'Tôm tươi áp chảo bơ tỏi gừng săn ngọt, xào nhanh cùng kim chi chua cay, cải thảo giòn và ớt chuông đỏ đậm vị đưa cơm', 'Đĩa tôm xào kim chi Hàn Quốc bắt mắt với thịt tôm hồng tươi giòn ngọt thấm hương bơ tỏi gừng, quyện cùng kim chi cải thảo chua cay nhẹ, cải thảo giòn sần sật và ớt chuông đỏ rực.', 'Trút tôm xào kim chi ra đĩa, rắc thêm hành lá và hạt mè trắng rang; thưởng thức nóng ngay cùng cơm trắng dẻo.', 'Tôm xào ngon nhất khi ăn ngay lúc vừa nấu xong; nếu bảo quản ngăn mát tối đa 24 giờ, chỉ đảo nóng nhanh 1–2 phút trên chảo lửa vừa để tôm không bị dai.', 'korean', 'mon_xao', NULL, 'easy', 20, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Tôm tươi","Kim chi","Hàn Quốc","Bữa tối nhanh"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["crustaceans","milk","sesame","shrimp","soybean","wheat"]', 266, 265.9, 1113, 29.3, 14.2, 5.4, 7.6, 2.7, 2.8, 1255, 3.14, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169977","USDA FDC 170005","USDA FDC 170108","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', 'adde2cf414ee9f879fa041bdd8ba5fe561a7ff99789a15f1afccdc543336f515', 'b231514a60a11ef1276e537e2c5129538e168ebe74049ff174250f04375de99e', 4),
('imp-88b58c0233dec53e', 'trung-xao-kim-chi', 459, 'Trứng xào kim chi Hàn Quốc', 'Trứng gà đánh bông chiên mềm mịn quyện cùng kim chi cải thảo xào thơm cay dịu và hành lá tươi mát cho bữa cơm 10 phút', 'Đĩa trứng xào kim chi mềm mịn tan trong miệng với từng mảng trứng vàng ươm béo nhẹ xen lẫn kim chi cải thảo chua cay giòn sần sật, cực kỳ gọn nhẹ cho bữa sáng hoặc bữa tối bận rộn.', 'Gạt trứng xào kim chi ra đĩa ấm ngay khi vừa chín tới, rắc hành lá thái nhỏ và hạt mè trắng rang; dùng nóng kèm cơm trắng hoặc bánh mì nướng.', 'Món trứng xào ngon nhất khi thưởng thức ngay sau khi nấu để giữ độ mềm mướt; không nên hâm đi hâm lại nhiều lần vì trứng sẽ bị khô xác.', 'korean', 'mon_nhanh_sang', NULL, 'easy', 5, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Món nhanh","Trứng gà","Kim chi","Hàn Quốc","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","sesame","soybean","wheat"]', 204, 203.6, 852, 12.1, 15.9, 3.8, 3.1, 1.3, 1.1, 677, 1.69, '["USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '0eb7170993398c3f7bad14095422a4414e07733eb7aee9543591d2998064a70c', '3d2afb61c7731f4dc6263b88d24dda2637ee36530691568a9fb2feaa432177db', 4),
('imp-e5d49dd8dc1449d1', 'ba-chi-kho-kim-chi', 460, 'Thịt ba chỉ kho kim chi Hàn Quốc', 'Thịt ba chỉ heo kho mềm béo ngậy cùng kim chi lên men chua sâu, tương Doenjang và bột ớt Hàn trong nước kho sánh đậm', 'Nồi thịt ba chỉ kho kim chi Hàn Quốc (Kimchi Jjim) đậm đà quyến rũ với từng miếng ba chỉ ninh mềm tan béo ngậy, thấm trọn vị chua cay nồng nàn của kim chi lên men kỹ và hương tương đậu Doenjang trầm ấm.', 'Dùng kéo cắt kim chi thành khúc vừa ăn ngay trong nồi, rắc hành lá và ớt sừng thái lát lên trên; dọn nóng cùng cơm trắng và trứng cuộn hoặc đậu phụ trắng.', 'Thịt ba chỉ kho kim chi bảo quản hộp kín trong ngăn mát tủ lạnh đến 4 ngày hoặc cấp đông 1 tháng; khi hâm nóng lại trên lửa nhỏ hương vị càng ngấm sâu và ngon hơn.', 'korean', 'mon_kho', NULL, 'easy', 15, 65, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Ba chỉ heo","Kim chi","Hàn Quốc","Đưa cơm"]', '["lunch","dinner"]', '["braise"]', '["pork","soybean","wheat"]', 704, 704, 2945, 14.8, 65, 23.4, 14.9, 4.3, 8.1, 1331, 3.33, '["Korean Chili Flake Ref","Korean Doenjang Ref","MEXT Hon-Mirin 16031","USDA FDC 167820","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170497","USDA FDC 170931","USDA FDC 173647","USDA FDC 174277"]', '0909709f7910e43ddb2e20804ed638cb82433aff0a70b52132f0840e8cc012d7', 'd4cdb1144995af63ed21fb08ff35ac41e6806d2581134cdfbd12c688fa08e0d9', 4),
('imp-daec3b038c4f43af', 'ca-nuong-tuong-han', 461, 'Cá thu nướng chấm tương Hàn Quốc', 'Cá thu nướng vỉ da vàng giòn thơm thịt trắng ngọt béo, rưới nước tương xì dầu tỏi ớt chanh tươi kiểu Hàn', 'Món cá thu nướng kiểu Hàn hấp dẫn với lớp da cá giòn rụm vàng ươm, phần thịt bên trong trắng mềm béo ngậy giữ trọn vị ngọt tự nhiên, kết hợp nước chấm xì dầu tỏi ớt chanh tươi cân bằng vị béo rất bắt cơm.', 'Bày cá thu nướng ra đĩa dài, rưới một nửa chén nước tương chấm lên thân cá và rắc ngò rí thái nhỏ; phần nước chấm còn lại để riêng chấm kèm cơm trắng nóng.', 'Cá nướng ngon nhất khi dùng nóng ngay vừa ra lò; phần dư bảo quản ngăn mát tối đa 2 ngày và làm nóng lại trong nồi chiên không dầu hoặc lò nướng 180°C khoảng 5 phút để da giòn lại.', 'korean', 'mon_chien', NULL, 'medium', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Cá nướng","Cá thu","Hàn Quốc","Nước chấm tương","Bữa cơm gia đình"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","mackerel","sesame","soybean","wheat"]', 360, 360, 1507, 26.2, 26, 5.4, 3.7, 0.9, 0.5, 1394, 3.49, '["Korean Chili Flake Ref","MEXT Sake 16021","USDA FDC 168155","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175119"]', 'a3a1750e81f4fb71526aeacba7648a34e22a04792bfdc4527e051721f73a2d71', 'c74715e81e8ed5e412fca257bf5e51af8241f53cd4292bbef2ebce790200bdf7', 4),
('imp-4ca7d6f55d5b7937', 'mi-xao-bo-han', 462, 'Miến xào thịt bò Hàn Quốc (Japchae)', 'Miến khoai lang Hàn dai bóng trộn đều cùng thịt bò thăn xào mềm, nấm hương, rau chân vịt và cà rốt thấm sốt xì dầu mè thơm', 'Đĩa miến trộn Japchae Hàn Quốc óng ả sắc màu với sợi miến khoai lang dai mềm quyện hương dầu mè rang và đường nâu ngọt dịu, kết hợp thịt thăn bò mềm thơm cùng nấm hương, rau chân vịt, cà rốt và hành tây giòn ngọt.', 'Bày miến xào thịt bò ra đĩa lớn, rắc thêm chút hạt mè trắng rang; thưởng thức nóng hoặc ở nhiệt độ phòng đều giữ nguyên độ dai ngon.', 'Japchae bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi hâm nóng bằng lò vi sóng hoặc đảo nhanh trên chảo với 1 muỗng canh nước lọc, sợi miến sẽ mềm bóng trở lại.', 'korean', 'mon_xao', NULL, 'medium', 20, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Miến xào","Thịt bò","Japchae","Hàn Quốc","Tiệc gia đình"]', '["lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["beef","sesame","soybean","wheat"]', 459, 459.1, 1921, 12.7, 18.8, 3.7, 61.4, 3.4, 11.2, 1140, 2.85, '["USDA FDC 168462","USDA FDC 168833","USDA FDC 168952","USDA FDC 169230","USDA FDC 169251","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '25e57b7467398768c010fd75a6a6fd6abbb6417c125a6bb14564cbe5080ddc08', '7eea0f32b7f575337889e28bf644d6213b3da063a0f2e4565f217274538013d4', 4),
('imp-09e07baa201acf28', 'chao-tom-han', 463, 'Cháo tôm Hàn Quốc (Saewoo-juk)', 'Cháo gạo tẻ rang dầu mè ninh sánh mịn cùng tôm tươi giòn ngọt, cà rốt, hành tây, vân trứng gà béo nhẹ và rong biển nướng vụn', 'Tô cháo tôm Saewoo-juk kiểu Hàn sánh mịn mượt mà với hạt gạo rang dầu mè thơm bùi, thịt tôm tươi thái nhỏ ngọt tự nhiên cùng cà rốt, hành tây, vân trứng gà mềm mịn và rong biển nướng giòn rắc mặt.', 'Múc cháo nóng ra tô, rắc rong biển lá khô bóp vụn cùng hạt mè trắng rang giã dập lên trên; thưởng thức ngay khi còn nóng, ăn kèm kim chi củ cải nếu thích.', 'Cháo thừa bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi hâm nóng hãy thêm khoảng 50–100 ml nước lọc khuấy đều trên lửa nhỏ đến khi sôi sánh trở lại.', 'korean', 'mon_canh', NULL, 'easy', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Món cháo","Tôm tươi","Hàn Quốc","Ấm bụng","Dễ tiêu"]', '["breakfast","lunch","dinner"]', '["stir_fry","simmer"]', '["crustaceans","egg","fish","sesame","shrimp"]', 328, 327.6, 1371, 18.6, 7.7, 1.5, 45.4, 2.1, 2.3, 895, 2.24, '["USDA FDC 168456","USDA FDC 169230","USDA FDC 169756","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170393","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '16eeb2e459bbaebf306011de98dd4c25b25ce5e7e6793b916e8a534c8c08e783', 'e660f7b1b27b31cf59f2ba5206101ae146d0b2de29928bf4156827e8174fb158', 4),
('imp-9c2f22829fd3d3f1', 'bo-xao-kim-chi', 464, 'Thịt bò xào kim chi Hàn Quốc', 'Thịt thăn bò thái lát mỏng xào lửa lớn mềm ngọt cùng kim chi cải thảo chua cay, hành tây giòn thơm và sốt mật ong dầu hào', 'Đĩa thịt bò xào kim chi Hàn Quốc hấp dẫn với từng lát thịt thăn bò mềm ẩm thấm gia vị, kết hợp hoàn hảo cùng kim chi cải thảo chua cay đậm đà và hành tây giòn ngọt quyện sốt mật ong dầu hào bóng đẹp.', 'Trút thịt bò xào kim chi ra đĩa, rắc thêm hành lá và hạt mè trắng rang lên trên; thưởng thức ngay khi còn nóng hổi với cơm trắng dẻo.', 'Món xào ngon nhất khi ăn nóng ngay; nếu bảo quản hộp kín trong ngăn mát tối đa 2 ngày, chỉ đảo nóng nhanh trên chảo lửa lớn 1–2 phút để thịt bò giữ được độ mềm.', 'korean', 'mon_xao', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Kim chi","Hàn Quốc","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","sesame","soybean","wheat"]', 278, 278.4, 1165, 20.2, 17.3, 4.7, 11.1, 2, 6.5, 982, 2.46, '["USDA FDC 169230","USDA FDC 169640","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '0000f56f952196fb4951018982dc644e3fc8487db7b07e6d4ccebfd4b08e4415', '17b9200720f3d0e7ff6450b400d256a007d4160638732643d7d6c4e4fd14f673', 4),
('imp-d7b9a40e678c0e29', 'ga-nuong-muoi-han', 465, 'Gà nướng muối kiểu Hàn', 'Đùi gà rút xương còn da áp chảo không dầu vàng giòn rụm với muối tiêu, ăn kèm hành lá nướng xém, tỏi nguyên tép và chanh tươi', 'Món gà nướng muối kiểu Hàn (Dak-sogeum-gui) giản dị mà cực kỳ cuốn hút: thịt đùi gà rút xương được áp chảo tự tiết mỡ giúp lớp da mỏng giòn tan, thịt bên trong ngọt mọng quyện hành lá tỏi nướng xém thơm nức.', 'Thái gà thành miếng vừa ăn xếp ra đĩa cùng hành lá và tỏi nướng xém vàng, vắt thêm múi chanh tươi và chấm muối tiêu dầu mè rang.', 'Gà nướng da giòn ngon nhất khi dùng nóng ngay sau khi chế biến; nếu còn dư có thể cất ngăn mát tối đa 2 ngày và quay nóng bằng nồi chiên không dầu 180°C trong 4–5 phút.', 'korean', 'mon_chien', NULL, 'easy', 15, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Gà nướng","Đùi gà","Hàn Quốc","Da giòn","Bữa cơm gia đình"]', '["lunch","dinner"]', '["pan_fry","grill_roast"]', '["chicken","sesame"]', 384, 384.2, 1608, 37.1, 23.7, 6, 4.1, 0.9, 0.5, 855, 2.14, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 172385","USDA FDC 173468"]', '102b728313bb05c99ee4f9fac01a232cef02e254917eca0a0bce1b8779d73d12', '31d066809a882c198f2ce5dd04ea1fd1a299db92d0288bcf551a5a26f6bfead1', 4),
('imp-2b289d9040d46110', 'dau-phu-kho-gung-han', 466, 'Đậu phụ kho gừng kiểu Hàn', 'Từng miếng đậu phụ chiên vàng hai mặt kho thấm sốt xì dầu gừng băm sánh đậm, thơm dịu dầu mè cho bữa cơm chay thanh đạm', 'Đĩa đậu phụ kho gừng Hàn Quốc (Dubu Jorim) thơm nức mùi gừng tỏi xào quyện nước tương xì dầu mặn ngọt hài hòa, miếng đậu bên ngoài săn vàng thấm vị mà bên trong vẫn giữ được độ mềm béo thanh tao.', 'Xếp các miếng đậu phụ kho ra đĩa, rưới phần sốt sệt còn lại trong chảo lên trên rồi rắc hạt mè trắng rang và hành lá; dùng nóng hoặc nguội với cơm trắng đều rất bắt vị.', 'Món đậu kho bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 3 ngày như một món ăn kèm (banchan); có thể ăn nguội trực tiếp hoặc hâm nóng lại với 1 muỗng canh nước lọc trên chảo.', 'korean', 'mon_chay', NULL, 'easy', 12, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Đậu phụ","Món kho","Gừng tươi","Hàn Quốc"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["sesame","soybean","wheat"]', 259, 258.7, 1082, 16.1, 18.5, 2.7, 11.6, 2.5, 5.9, 772, 1.93, '["Korean Chili Flake Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', '2bd3f02b85403aa9e7f3f1dbd88b814865d14733a55541bf598acf7ca184fc80', '5a134208b11c73dcf60cc4847b9a0739b23e05c9405bc9e057fd13eaa4ea3314', 4),
('imp-7cb7368109956ad5', 'canh-kim-chi-gia', 467, 'Canh kim chi giá đỗ Hàn Quốc', 'Nước canh kim chi chua cay trong thanh kết hợp cùng giá đỗ giòn ngọt và nước dùng cá cơm tảo bẹ giúp giải nhiệt ấm bụng', 'Tô canh kim chi giá đỗ (Kimchi Kongnamul-guk) nóng hổi thanh nhẹ mà đậm đà: giá đỗ giữ nguyên độ giòn ngọt tự nhiên hòa quyện nước dùng cá cơm tảo bẹ cùng vị chua cay dịu của kim chi chín kỹ.', 'Để canh nghỉ 2–3 phút sau khi tắt bếp cho vị ngọt sâu rồi múc ra tô, rắc hành lá xanh lên trên; ăn nóng kèm cơm trắng hoặc chan trực tiếp thành canh cơm.', 'Nên dùng hết trong ngày để giá đỗ giữ độ giòn tươi; phần thừa bảo quản ngăn mát tối đa 24 giờ và đun sôi nhanh trên lửa vừa trước khi dùng.', 'korean', 'mon_canh', NULL, 'easy', 10, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Kim chi","Giá đỗ","Hàn Quốc","Thanh mát"]', '["breakfast","lunch","dinner"]', '["stir_fry","simmer"]', '["fish","sesame","soybean","wheat"]', 124, 123.8, 519, 8, 5.7, 0.8, 12.6, 3.6, 5.4, 1569, 3.92, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","USDA FDC 169230","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170497","USDA FDC 171028","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 174277"]', 'db9df6ee08293cb66776f5dbe9956c8946bc23229f6f9b0db8256405a7b636f2', 'aeda83fb5c044d099f78f38967f596cc3490b9811ad2ce21c219629ecabfa0a2', 4),
('imp-a3e676be13c4c51c', 'bo-ham-nam-han', 468, 'Thịt bò hầm nấm Hàn Quốc', 'Thịt bò thái mỏng ướp sốt Bulgogi mềm ngọt nấu cùng nấm đùi gà, nấm hương, cải thảo và miến khoai lang trong nước dùng thanh ngọt', 'Nồi thịt bò hầm nấm Hàn Quốc (Beoseot Bulgogi Jeongol) ấm áp sang trọng với nước dùng tảo bẹ củ cải trong ngọt, kết hợp thịt thăn bò ướp sốt đậm đà cùng nấm đùi gà, nấm hương, rau củ tươi và miến khoai lang dai mềm.', 'Đặt nồi hầm nóng ngay giữa bàn ăn, rắc hành lá lên trên để mọi người vừa gắp thịt bò và nấm vừa chan nước dùng thanh ngọt ăn cùng cơm trắng.', 'Nếu còn dư, vớt riêng phần miến khoai lang để không bị nở nát; bảo quản thịt, nấm và nước dùng trong ngăn mát tối đa 2 ngày và đun sôi lại khi ăn.', 'korean', 'mon_lau_tiec', NULL, 'medium', 25, 30, 5, '/frigo/illustrations/delicious-meal.png', '["Món hầm","Thịt bò","Nấm tươi","Hàn Quốc","Lẩu gia đình"]', '["lunch","dinner"]', '["simmer"]', '["beef","sesame","soybean","wheat"]', 354, 353.6, 1480, 25, 13.9, 4.6, 32.7, 3.2, 10.6, 1164, 2.91, '["MEXT Hon-Mirin 16031","USDA FDC 168452","USDA FDC 168457","USDA FDC 168580","USDA FDC 168952","USDA FDC 169230","USDA FDC 169251","USDA FDC 169640","USDA FDC 169655","USDA FDC 169977","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'ce065df0b1e804d11dbf0b4a0cdb5af0de80a141a9d49beede8d10a24ccfb081', '99c900d7ef4f7503c5edafc77f98cbe87145a5f36a9c1af85c83a4f54401c262', 4),
('imp-1b54108818405e6a', 'com-chien-ba-chi-kim-chi', 469, 'Cơm chiên ba chỉ kim chi Hàn Quốc', 'Cơm trắng rang săn hạt cùng thịt ba chỉ xém cạnh béo giòn, kim chi chua cay, sốt Gochujang và trứng ốp la lòng đào', 'Món cơm chiên ba chỉ kim chi Hàn Quốc (Kimchi Bokkeumbap) đậm đà khó cưỡng với từng hạt cơm săn tơi phủ màu đỏ cam bắt mắt của tương ớt Gochujang, quyện thịt ba chỉ chiên xém béo giòn, kim chi chua cay và trứng ốp la lòng đào.', 'Nén nhẹ cơm chiên ra chén rồi úp ra đĩa, đặt trứng ốp la lên trên, rắc thêm hành lá xanh, hạt mè trắng rang và rong biển cắt sợi để thưởng thức nóng.', 'Cơm chiên ngon nhất khi dùng nóng ngay vừa ra chảo; phần thừa bảo quản hộp kín trong ngăn mát tối đa 2 ngày và đảo nóng lại trên chảo chống dính với lửa vừa.', 'korean', 'mon_xao', NULL, 'easy', 12, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Ba chỉ heo","Kim chi","Hàn Quốc","Bữa tối nhanh"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["egg","pork","sesame","soybean","wheat"]', 740, 740.2, 3097, 18.8, 45.1, 14.4, 63.3, 2.9, 3.7, 1276, 3.19, '["USDA / Korean Gochujang Ref","USDA FDC 167820","USDA FDC 168456","USDA FDC 168878","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', 'f4b8185c520b79aee5819e91f65ff314451a9500354614bf83cbca076d13a949', 'dcf5a4f70d4941352e968c9c7e10795b151dad4d64efb096369f71b194954208', 4),
('imp-9328a098d7bd1f6f', 'ga-nuong-chanh-ot', 470, 'Gà nướng chanh ớt kiểu Thái (Gai Yang)', 'Đùi gà góc tư ướp nước mắm, tỏi, ớt hiểm và nước cốt chanh nướng vàng giòn lớp da, thịt bên trong mọng nước đậm đà', 'Món gà nướng chanh ớt kiểu Thái hấp dẫn với từng chiếc đùi gà góc tư da vàng óng giòn rụm, thịt thớ mềm mọng thấm đẫm hương vị chua thanh của nước cốt chanh, mặn thơm nước mắm cùng vị cay nồng ấm của tỏi và ớt hiểm.', 'Chặt đùi gà nướng thành miếng vừa ăn hoặc để nguyên chiếc, rắc hành lá thái nhỏ; dọn nóng cùng xôi nếp hoặc cơm trắng, xà lách, dưa leo và chén tương ớt chấm kèm.', 'Thưởng thức nóng ngay sau khi nướng để lớp da giữ độ giòn; nếu dư, bọc kín bảo quản tủ mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 6–8 phút.', 'thai', 'mon_lau_tiec', NULL, 'medium', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Gai Yang","Gà nướng","Thái Lan","Chanh ớt","Món tiệc"]', '["lunch","dinner"]', '["grill_roast"]', '["chicken","fish"]', 386, 385.7, 1615, 32.9, 22.9, 5.6, 11.2, 0.9, 7.3, 1311, 3.28, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC Sriracha Ref"]', 'c3d65c06a86046bab08531b7ea4931e6e96505185986a50453f69f619098e9f5', 'daaf9da1e9869fd01e2f8b6e6e21d35c37285cf45ad8b9bd87a4a4a7ec34dbf2', 4),
('imp-cc203adb1d5aa11b', 'canh-ca-sa-ca-chua', 471, 'Canh cá nấu sả cà chua kiểu Thái', 'Canh cá nước trong ngọt thanh nấu cùng sả đập dập và cà chua chín mọng, hậu chua dịu từ nước cốt chanh tươi rất dễ ăn', 'Tô canh cá sả cà chua kiểu Thái có phần nước dùng trong veo, thơm dịu tinh dầu sả tươi, hòa quyện cùng thịt cá trắng ngọt chắc, vị chua nhẹ từ cà chua chín và chanh tươi giúp bữa cơm thêm nhẹ bụng, ấm áp.', 'Múc canh cá ra tô lớn khi còn nóng hổi, rắc hành lá và ngò rí lên trên; dùng cùng cơm trắng và chén nước mắm ớt để chấm thịt cá.', 'Nên dùng hết trong ngày để thịt cá giữ nguyên độ ngọt chắc; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi nhẹ lại trên lửa nhỏ mà không khuấy mạnh để tránh làm nát cá.', 'thai', 'mon_canh', NULL, 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Canh cá","Sả cà chua","Nước trong","Thái Lan","Thanh mát"]', '["lunch","dinner"]', '["simmer"]', '["fish"]', 180, 180, 752, 24.5, 5.3, 1.1, 8.6, 1.8, 5.3, 1281, 3.2, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176"]', '08d84085f6302a125cb88a34241535158f0ff1f489fd7efcd120233f38569282', 'f7b0b89ead643070fa29ea5146ff56c8a248e47d30b8b332a575dbdcd7e8278b', 4),
('imp-7bd81a7e8fb33958', 'muc-om-sa-thai', 472, 'Mực hấp om sả chanh kiểu Thái', 'Mực ống tươi khứa vảy rồng hấp om cùng sả thơm nồng, rưới nước sốt mắm chanh tỏi ớt chua cay mặn ngọt đậm vị biển', 'Món mực om sả kiểu Thái kết hợp kỹ thuật hấp nhanh giữ trọn độ giòn ngọt tự nhiên của mực ống tươi cùng hương tinh dầu sả nồng nàn, hòa quyện với nước sốt hải sản Nam Jim chua cay mặn ngọt bùng vị.', 'Dọn đĩa mực hấp nóng hổi ngay khi vừa rưới sốt, rắc thêm ngò rí và hành lá; ăn kèm cơm trắng nóng hoặc rau sống dưa leo giải ngấy.', 'Mực hấp ngon nhất khi ăn nóng ngay lúc vừa chế biến; nếu dư, bảo quản tủ mát tối đa 24 giờ và hấp cách thủy lại 2–3 phút trên lửa lớn để mực nóng mà không bị dai.', 'thai', 'mon_hap_luoc', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Mực hấp","Sả chanh","Hải sản Thái","Chua cay","Ít dầu mỡ"]', '["lunch","dinner"]', '["steam","simmer"]', '["fish","molluscs","squid"]', 198, 197.7, 827, 23.9, 2.2, 0.5, 20.8, 1.1, 8.7, 1168, 2.92, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 172185","USDA FDC 173647","USDA FDC 174223"]', 'd26f0c3659d61c5f0569245da29c2dd0afc20b9d99cb87ac0e7d6b51c0bc8b09', '1754c7e2d23dd9a7fe88b2900a6a790dcd5437e81e3c82f25ebf4cf1457bcbab', 4),
('imp-0abadc2e606770a7', 'cua-hap-sa', 473, 'Cua biển hấp sả gừng kiểu Thái', 'Cua thịt chắc hấp cách thủy cùng sả cây đập dập, gừng lát và rượu vang trắng khử tanh, chấm muối tiêu chanh ớt cay thơm đậm đà', 'Cua biển hấp sả gừng kiểu Thái giữ trọn vị ngọt chắc nguyên bản của thịt cua tươi, quyện cùng hương thơm nồng ấm của sả cây, gừng tươi và rượu vang trắng bốc hơi trong xửng hấp, ăn kèm muối tiêu chanh ớt cay thanh rất bắt vị.', 'Gỡ nhẹ dây buộc, tách đôi mai cua hoặc chặt miếng lớn bày lên đĩa cùng vài khúc sả hấp thơm; dọn nóng kèm muối tiêu chanh ớt và rau răm.', 'Nên dùng hết ngay khi cua vừa hấp nóng để thịt ngọt và không bị tanh; nếu còn dư, gỡ sẵn thịt cua bọc kín bảo quản tủ mát tối đa 24 giờ và hấp nóng lại 3 phút trước khi ăn.', 'thai', 'mon_hap_luoc', NULL, 'medium', 20, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Cua hấp","Sả gừng","Hải sản","Thái Lan","Món tiệc"]', '["lunch","dinner"]', '["steam"]', '["crab","crustaceans","sulphites"]', 226, 225.5, 943, 37, 5.2, 0.9, 5.2, 0.5, 1.3, 1134, 2.84, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 174208","VN/Asian Seasoning Powder Avg"]', '8bf42fe69f20f981eb5d6c8071c63ea75866cf122668893e68e14014a6213faa', 'd4c9fdfb52c9417ce3502305aed166180edeb1a094a83d5daafcd37ec4413346', 4),
('imp-cc6a0ca585b502d4', 'larb-ga', 474, 'Larb gà bằm trộn thính gạo kiểu Isaan', 'Thịt gà bằm xào tơi vừa chín tới trộn cùng thính gạo rang thơm bùi, hành tím, lá bạc hà và sốt chanh mắm ớt chuẩn vị Đông Bắc Thái', 'Larb gà kiểu Isaan là món gỏi thịt ấm nổi tiếng của vùng Đông Bắc Thái Lan, gây ấn tượng với thịt gà bằm mềm ẩm không khô, quyện thính gạo rang giòn bùi, vị chua thanh của chanh, mặn thơm nước mắm và hương lá bạc hà tươi mát.', 'Bày larb gà ra đĩa, rắc thêm lá bạc hà tươi lên trên; dùng ấm kèm xôi nếp hoặc cơm trắng cùng dưa leo, bắp cải giòn và đậu que sống.', 'Nên trộn thính gạo và rau thơm ngay trước khi ăn để thính không bị ỉu hút hết nước sốt; nếu bảo quản tủ mát tối đa 24 giờ, chỉ giữ riêng phần thịt xào sốt và trộn thính, rau thơm lúc ăn.', 'thai', 'mon_cuon_nom', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Larb gà","Isaan","Thính gạo","Chua cay","Thái Lan"]', '["lunch","dinner"]', '["stir_fry","toss_mix"]', '["chicken","fish"]', 276, 276.1, 1155, 34.6, 8.1, 2, 15.2, 1.8, 3.7, 1193, 2.98, '["Citrus Leaf Culinary Ref","Toasted Rice Powder Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 171477","USDA FDC 172185","USDA FDC 172385","USDA FDC 173474","USDA FDC 173647"]', '91fd1e262bcc12a9764cec8398a90d8abb0a3f4e380e0864b29ab3278487b16c', '2381082acdaf96c70202747c16cc26fd431b9d86f608c078f381e9cfdfed1ac6', 4),
('imp-6e4967b3145dee09', 'nam-xao-hung-que-thai', 475, 'Nấm đùi gà xào húng quế kiểu Thái chay', 'Nấm đùi gà áp chảo cháy cạnh xào tỏi ớt cay nồng cùng dầu hào chay, xì dầu và lá húng quế thơm nức chuẩn vị Pad Krapao Hed', 'Phiên bản chay thanh đạm nhưng cực kỳ bắt cơm của món xào đường phố Thái Pad Krapao: nấm đùi gà xém cạnh giòn ngọt sần sật thấm sốt xì dầu đậm đà, quyện hương cay nồng của tỏi ớt và lá húng quế tươi bùng vị.', 'Xúc nấm xào nóng hổi ra đĩa, rắc thêm hành lá thái khúc; dùng ngay với cơm trắng nóng dẻo hoặc kèm dưa leo thái lát thanh mát.', 'Nên ăn nóng ngay sau khi xào để nấm giòn ngon và lá húng quế còn xanh thơm; nếu còn dư, bảo quản tủ mát tối đa 24 giờ và đảo nhanh trên chảo nóng không đậy nắp.', 'thai', 'mon_xao', NULL, 'easy', 12, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Pad Krapao","Món chay","Nấm đùi gà","Húng quế","Thái Lan"]', '["lunch","dinner"]', '["stir_fry"]', '["soybean","wheat"]', 182, 181.7, 760, 7.6, 8.2, 1.2, 24.1, 5.1, 10.7, 930, 2.32, '["Dark Soy Sauce Label Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 171413","USDA FDC 172232","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref"]', '0682d6e6f48ccba026e97c67ffa3086aa4c810c0e2dccc4c759b2e2af1242bd2', '34d4219554a013b8bd22ef3297f8f3cccfa32969879a129cc21127037167dca1', 4),
('imp-4d9fae75b597d2c5', 'bo-nuong-sa-thai', 476, 'Thịt bò ướp sả nướng kiểu Thái', 'Thịt thăn bò thái lát mỏng ướp sả non, tỏi, tiêu đen, nước mắm và đường nâu nướng xém cạnh thơm lừng, ăn kèm chanh ớt tươi', 'Từng lát thịt thăn bò mềm mọng thấm đẫm hương thơm nồng nàn của sả non băm nhuyễn, tỏi, tiêu đen, xì dầu và nước mắm ngon, nướng nhanh trên lửa lớn cho mặt thịt xém cạnh thơm phức, cực kỳ hợp cho bữa tiệc hay cơm gia đình.', 'Xếp thịt bò nướng sả ra đĩa khi còn nóng, bày kèm chanh cắt múi cau và ớt hiểm thái lát; dùng với xôi nếp, cơm trắng, bún tươi hoặc cuốn rau sống.', 'Bò nướng ngon nhất khi dùng nóng ngay sau khi nướng và để nghỉ vài phút; nếu dư, bọc kín bảo quản tủ mát tối đa 2 ngày và áp chảo nóng nhanh 1 phút mỗi mặt cho thịt mềm ẩm trở lại.', 'thai', 'mon_lau_tiec', NULL, 'medium', 20, 12, 4, '/frigo/illustrations/delicious-meal.png', '["Bò nướng","Sả thơm","Thái Lan","Món nhậu","Nướng vỉ"]', '["lunch","dinner"]', '["grill_roast"]', '["beef","fish","sesame","soybean","wheat"]', 316, 315.8, 1322, 27.2, 17.8, 5.8, 11.3, 0.5, 5.4, 881, 2.2, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 168833","USDA FDC 169230","USDA FDC 170106","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172185","USDA FDC 174277"]', '3d276aefdbc22f127cb71d3e55a0df851bbc9fa11ada3cc1ca058bd034121cbc', 'a42178363f3afa985b4af7e1c9db05f8d0fadd0ce2e88b4d3b902848b6c11d98', 4),
('imp-a97820d3080e47eb', 'tom-xien-sa-nuong', 477, 'Tôm sú xiên cây sả nướng thơm nồng', 'Tôm sú ướp dầu hào, nước mắm và hành tỏi sả băm rồi xiên dọc thân vào cây sả tươi nướng vàng thơm, chấm muối ớt chanh cay thanh', 'Tôm sú xiên sả nướng mang hương thơm nhiệt đới quyến rũ: dùng chính thân cây sả vót nhọn xiên dọc mình tôm giúp thịt tôm chín giữ dáng thẳng đẹp, thấm đẫm tinh dầu sả hòa quyện vị đậm đà của dầu hào, nước mắm và muối ớt chanh.', 'Bày các xiên tôm nướng còn nóng hổi ra đĩa cùng xà lách, dưa leo tươi; vắt nhẹ chút nước cốt chanh lên tôm và chấm kèm chén muối ớt chanh giã nhuyễn.', 'Tôm nướng ngon nhất khi ăn nóng ngay lúc vừa chín; nếu còn dư, gỡ vỏ bảo quản tủ mát tối đa 24 giờ và làm nóng nhanh trong nồi chiên không dầu ở 180°C khoảng 2–3 phút.', 'thai', 'mon_lau_tiec', NULL, 'easy', 25, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Xiên sả","Hải sản Thái","Món tiệc","Chanh ớt"]', '["lunch","dinner"]', '["grill_roast"]', '["crustaceans","fish","molluscs","shrimp","soybean","wheat"]', 191, 191.1, 800, 27.4, 5.2, 0.8, 10, 0.7, 3.3, 1403, 3.51, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '12839d0a0031963b051e8d36bd0c67f72d7df8c127d520f77c55402e9e07303f', '871619709c94c357a0c0eec53b58706dbb4b4d91b8cfa9ca4036ff9766e66540', 4),
('imp-a9d8b4d783b986d1', 'com-tom-sa-thai', 478, 'Cơm chiên tôm sả kiểu Thái', 'Cơm nguội rang tơi hạt cùng tôm tươi giòn ngọt, sả non thái lát mỏng, cà rốt, trứng gà và bộ ba sốt xì dầu, dầu hào, nước mắm đậm vị', 'Đĩa cơm chiên tôm sả kiểu Thái thơm nức mùi sả non phi vàng và hương khói chảo wok, hòa quyện thịt tôm săn ngọt, cà rốt giòn thanh, trứng chiên tơi xốp cùng vị đậm đà hài hòa của xì dầu, dầu hào và nước mắm.', 'Xới cơm chiên tôm sả ra đĩa khi còn nóng hổi, rắc thêm hành lá và tiêu trắng; dọn kèm vài lát dưa leo, chanh tươi cắt múi để vắt nhẹ khi ăn.', 'Món cơm chiên ngon nhất khi ăn nóng ngay lúc vừa tắt bếp; nếu bảo quản tủ mát tối đa 24 giờ, nên đảo lại trên chảo nóng không dầu khoảng 3 phút cho hạt cơm săn tơi.', 'thai', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Tôm sả","Thái Lan","Nhanh gọn","Bữa chính"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","egg","fish","molluscs","shrimp","soybean","wheat"]', 427, 427, 1787, 25.3, 12.6, 2.4, 53, 1.8, 4.1, 1136, 2.84, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170933","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '5a1805dae89fc01503b09388d5a72fd3d7d88c20d538ba07e1d3937cc969de4c', 'e221d28ecfff2a12102c3e0f161489678c3ec02f0287bd7aff0aeac81f6a6d06', 4),
('imp-4095c816782acd82', 'salad-ca-chua-cay-thai', 479, 'Salad cà chua trộn cay kiểu Thái', 'Cà chua chín mọng bổ múi cau trộn nước mắm chanh tỏi ớt chua cay mặn ngọt, rắc tôm khô và đậu phộng rang giòn bùi mát lành', 'Món salad cà chua cay kiểu Thái (Yum Makhuea Thet) thanh mát đầy sức sống với từng múi cà chua chín đỏ mọng nước thấm sốt mắm chanh đường thốt nốt, điểm xuyết vị giòn bùi của đậu phộng rang và tôm khô đậm đà.', 'Múc salad cà chua ra đĩa sâu lòng cùng phần nước sốt chua cay tự nhiên, rắc hành lá, ngò rí và đậu phộng rang giã dập lên trên; dùng mát làm món khai vị hoặc ăn kèm đồ nướng.', 'Salad cà chua ngon nhất khi trộn và dùng trong vòng 1–2 giờ; nếu ướp lạnh trong tủ mát, chỉ rắc đậu phộng rang và rau thơm ngay trước khi dọn để giữ độ giòn.', 'thai', 'mon_cuon_nom', NULL, 'easy', 12, 3, 3, '/frigo/illustrations/delicious-meal.png', '["Salad Thái","Cà chua","Chua cay","Khai vị","Mát lành"]', '["lunch","dinner"]', '["toss_mix"]', '["crustaceans","fish","peanut","shrimp"]', 148, 148, 618, 8.8, 6.3, 0.8, 17.2, 3.8, 10.5, 1071, 2.68, '["USDA / Asian Dried Shrimp Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 172185","USDA FDC 172430","USDA FDC Palm Sugar Ref"]', '209f986debc39e6a6190cb1cd1a80eb02f8f7d9d2fa9f8a36bd7b9493bad3fc7', 'e540fabf7847365d2b1cfb91e8b03cecbab6d93a810507c363b1337f918bbeb6', 4),
('imp-0e9c9740a6232263', 'heo-xao-hung-que', 480, 'Thịt heo bằm xào húng quế kiểu Thái (Pad Krapao)', 'Thịt heo xay xào săn trên lửa lớn với tỏi ớt giã nồng, dầu hào, nước mắm và lá húng quế Thái thơm lừng, chan cơm trắng cùng trứng ốp la', 'Món ăn quốc dân của đường phố Thái Lan: thịt nạc vai heo xay xào tơi đậm đà cùng đậu đũa giòn ngọt, quyện mùi thơm cay nồng của tỏi ớt phi và lá húng quế, ăn kèm cơm trắng nóng và trứng gà ốp la viền giòn lòng đào béo ngậy.', 'Xới cơm trắng nóng ra đĩa, xúc thịt heo xào húng quế đặt cạnh cùng 1 quả trứng gà ốp la lòng đào, rắc thêm hành lá và thưởng thức ngay.', 'Ngon nhất khi ăn nóng ngay sau khi xào; nếu còn dư, bảo quản hộp kín trong tủ mát tối đa 2 ngày và đảo nóng lại trên chảo 2 phút với 1 muỗng canh nước lọc.', 'thai', 'mon_xao', NULL, 'easy', 12, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Pad Krapao","Thịt heo bằm","Húng quế","Đường phố Thái","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["egg","fish","molluscs","pork","soybean","wheat"]', 585, 585.3, 2448, 33.3, 45, 14.5, 11, 1.3, 6.3, 1336, 3.34, '["Dark Soy Sauce Label Ref","USDA FDC 167902","USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170106","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173647","USDA FDC 174277"]', '9a46dbf1d53171e08859b8b5047c28ac4adddeac8519fd7c662e70ea820f022c', '0a29d98d010923ad6234aefd785c916f180fe395a8cbe5b69ea05f2f635dca91', 4),
('imp-b6d6788784da6342', 'ca-chien-sot-cay-thai', 481, 'Cá chiên giòn rưới sốt ớt tỏi kiểu Thái (Pla Rad Prik)', 'Cá điêu hồng nguyên con áo mỏng bột chiên vàng giòn rụm, phủ sốt tỏi ớt đường thốt nốt, nước mắm và chanh tươi sánh bóng đậm vị', 'Cá chiên sốt cay kiểu Thái (Pla Rad Prik) gây thương nhớ bởi lớp da cá chiên giòn tan vàng ruộm ôm lấy thớ thịt cá trắng ngọt mềm ẩm, quyện cùng nước sốt tỏi ớt đường thốt nốt sánh dẻo chua cay mặn ngọt bùng vị.', 'Bày cá chiên giòn ra đĩa lớn, chỉ rưới phần sốt tỏi ớt nóng hổi lên mình cá ngay trước khi ăn, rắc thêm hành lá thái lát và dùng kèm cơm trắng nóng.', 'Nên ăn nóng ngay sau khi rưới sốt để giữ độ giòn rụm của da cá; nếu chưa ăn hết, tách riêng phần cá chiên và nước sốt trong tủ mát tối đa 24 giờ, làm nóng giòn cá bằng nồi chiên không dầu ở 180°C trong 6 phút rồi mới hâm sốt rưới lên.', 'thai', 'mon_chien', NULL, 'medium', 20, 22, 4, '/frigo/illustrations/delicious-meal.png', '["Cá chiên giòn","Pla Rad Prik","Sốt cay","Thái Lan","Đưa cơm"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["fish","wheat"]', 359, 359.2, 1502, 32.1, 19.4, 3.3, 13.1, 0.8, 6.6, 1440, 3.6, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169761","USDA FDC 170005","USDA FDC 170106","USDA FDC 170933","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176","USDA FDC Palm Sugar Ref"]', '6b48a622b5cd76927552168417f985b4a52c6ae74260b638567444dcd7b1180b', '9ba6dfa5147cbabdc52ae114d27e5074f2bc4bc6d5a2728523d6153d5c89a57a', 4),
('imp-71cac2085659d819', 'ga-xao-dua-thai', 482, 'Thịt đùi gà xào dứa chua ngọt kiểu Thái', 'Đùi gà áp chảo vàng mềm xào cùng dứa chín ngọt, ớt chuông, hành tây và đậu Hà Lan áo sốt giấm gạo tương ớt ngọt sánh bóng', 'Đĩa gà xào dứa kiểu Thái rực rỡ sắc màu với thịt đùi gà áp chảo mềm ngọt săn cạnh, quyện cùng dứa chín thơm mọng, ớt chuông đỏ và đậu Hà Lan giòn tươi trong lớp sốt chua ngọt cay nhẹ bóng mượt từ giấm gạo, đường nâu và nước mắm.', 'Xúc gà xào dứa nóng hổi ra đĩa lớn, rắc thêm hành lá và ớt hiểm thái lát; ăn kèm cơm trắng nóng hoặc cơm gạo lứt đều rất đưa cơm.', 'Ngon nhất khi ăn nóng để rau củ giữ độ giòn tươi; nếu bảo quản tủ mát tối đa 2 ngày, đảo nhanh trên chảo nóng trong 3 phút để gà nóng đều mà rau không bị nhũn.', 'thai', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Gà xào dứa","Chua ngọt","Thái Lan","Màu sắc","Cơm gia đình"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","fish"]', 470, 470, 1967, 35, 23.8, 5.8, 29.3, 4.1, 19, 995, 2.49, '["USDA FDC 168833","USDA FDC 169124","USDA FDC 169230","USDA FDC 169698","USDA FDC 169961","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC Sriracha Ref"]', '712c57cbde15e3a00da27e3cbdc722c1f582d53628a9f23e3328bcb142997b9b', '3464df55053f46d473a5b62dd7e6373d1190fab945683a26001f404b86cdb784', 4),
('imp-b398545ca76325f1', 'canh-bap-cai-sa-thai', 483, 'Canh bắp cải nấu sả chanh Thái chay', 'Canh bắp cải giòn ngọt nấu cùng đậu phụ non, cà rốt và sả tươi đập dập, nước dùng chay trong thanh hậu chua dịu của chanh tươi', 'Tô canh bắp cải sả Thái chay thanh nhẹ trong veo, kết hợp vị ngọt mát tự nhiên của bắp cải xanh và cà rốt, đậu phụ non mềm mịn cùng hương thơm nồng dịu của sả đập dập và nước cốt chanh tươi rất dễ ăn.', 'Múc canh nóng ra tô lớn, gắp bỏ bớt khúc sả già, rắc hành lá và ngò rí lên trên; dùng khai vị hoặc ăn kèm cơm trắng trong bữa cơm thanh đạm.', 'Nên dùng hết trong ngày để bắp cải giữ màu xanh giòn ngọt và giữ trọn mùi thơm chanh tươi; nếu bảo quản tủ mát trong 24 giờ, chỉ đun sôi lại phần nước canh và rau rồi vắt thêm chút chanh tươi trước khi ăn.', 'thai', 'mon_canh', NULL, 'easy', 12, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Canh chay","Bắp cải","Sả chanh","Thanh mát","Thái Lan"]', '["lunch","dinner"]', '["simmer"]', '["soybean"]', 137, 136.9, 573, 8.4, 6.3, 0.9, 15.2, 4.5, 7.9, 1001, 2.5, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169655","USDA FDC 169975","USDA FDC 169997","USDA FDC 170005","USDA FDC 170393","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","Vegetarian Fish Sauce Ref","Vegetarian Seasoning Powder Ref"]', '23c6175ba486eee480a01b83e8a082d2c33951699b9f8174682e59310b921c36', '8d073ab3731c90ebf1b65ec8b717314dc6721ef42e80062f16ce6218c0cf31fd', 4),
('imp-9f9a3f24b4141acb', 'cua-chien-toi-ot-thai', 484, 'Cua lột chiên giòn xóc tỏi ớt kiểu Thái', 'Cua lột áo bột chiên ngập dầu giòn rụm, xóc nhanh trên chảo nóng cùng tỏi phi vàng, rễ ngò rí và ớt hiểm đỏ thơm nức đậm vị', 'Cua lột chiên tỏi ớt kiểu Thái hấp dẫn với lớp vỏ ngoài giòn rụm vàng ươm bọc lấy phần thịt cua ngọt béo mềm tan, xóc đều cùng bộ ba hương liệu Thái gồm rễ ngò rí, tỏi chiên giòn và ớt hiểm cay nồng thơm lừng.', 'Xếp cua chiên nóng hổi ra đĩa, rắc ngập tỏi phi giòn, hành lá và ngò rí lên trên; ăn nguyên con khi còn nóng giòn cùng cơm trắng hoặc chấm tương ớt.', 'Món cua lột chiên giòn ngon nhất khi thưởng thức ngay sau khi nấu để giữ trọn độ giòn tan; không nên để qua đêm vì vỏ bột sẽ ỉu mềm.', 'thai', 'mon_chien', NULL, 'medium', 20, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Cua chiên giòn","Cua lột","Tỏi ớt","Hải sản Thái","Món nhậu"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["crab","crustaceans","soybean","wheat"]', 404, 404.1, 1691, 36.7, 16.3, 2.5, 26.8, 1.6, 2.4, 1419, 3.55, '["Panko / Batter Mix Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170933","USDA FDC 171413","USDA FDC 173468","USDA FDC 174208","USDA FDC 174277"]', '7315becc8f984c50260a41c95473e989105afa4ae6273a7a7f287a6745043b7b', '02f63ea26f3754e265c320d123779d763c90535d0b47c2f75ecbbbc9a7674707', 4),
('imp-8fecebfe6dc0f0a2', 'mi-y-rau-bina', 485, 'Mì Ý sốt kem rau bina và hạnh nhân', 'Sợi spaghetti trộn sốt pesto rau bina xanh mướt xay mịn cùng phô mai ricotta, parmesan và hạnh nhân rang bùi', 'Món mì Ý chay nhẹ nhàng nhưng đầy đặn dinh dưỡng với lớp sốt xanh ngọc mượt mà từ rau bina chần xay nhuyễn cùng phô mai ricotta béo thanh, parmesan đậm vị và hạnh nhân rang thơm bùi.', 'Dọn mì ngay ra đĩa nông khi còn ấm nóng, rắc thêm chút phô mai parmesan bào sợi và hạnh nhân rang giã dập lên mặt để tăng độ giòn thơm.', 'Món sốt xanh rau bina ngon nhất khi ăn ngay sau khi trộn để giữ màu xanh tươi. Nếu bảo quản tủ lạnh tối đa 1 ngày, hâm nhẹ trên chảo lửa thật nhỏ cùng 1–2 muỗng nước ấm.', 'italian', 'mon_bun_pho', NULL, 'easy', 12, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Ý","Rau bina","Sốt kem","Nhanh gọn","Thanh đạm"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["almond","milk","tree_nuts","wheat"]', 604, 604.4, 2529, 22.6, 24.7, 6, 74.1, 5.7, 3.3, 562, 1.4, '["USDA FDC 168462","USDA FDC 168927","USDA FDC 169230","USDA FDC 170567","USDA FDC 170848","USDA FDC 170853","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647"]', '1dc7105639ae114b0a176a81e5ca5aaad822acd2444074d3cd9260be65142373', '31b88d7e364bec9ae16906a541f8d564b7a4c8a5bfac39802bc1cb2c7d2926a2', 4),
('imp-20d3992a65cb17fd', 'mi-y-ga-nam', 486, 'Mì Ý gà nấm sốt cà chua', 'Ức gà áp chảo vàng cạnh cùng nấm đùi gà giòn ngọt và cà chua chín mọng ôm trọn từng sợi mì spaghetti', 'Đĩa mì Ý đầy đặn dinh dưỡng cho bữa tối gia đình với ức gà mềm mọng thấm gia vị, nấm đùi gà xào lửa lớn giữ trọn độ giòn ngọt và vị chua thanh nhẹ tự nhiên từ cà chua chín tươi.', 'Múc mì ra đĩa sâu lòng khi còn nóng, rắc phô mai Parmesan bào mịn cùng chút tiêu đen xay mới và thưởng thức ngay.', 'Nếu chưa dùng hết, cất hộp kín trong ngăn mát tối đa 2 ngày. Hâm nóng trên chảo với 2 muỗng canh nước lọc trên lửa vừa trong 3–4 phút cho mì mềm tơi trở lại.', 'italian', 'mon_bun_pho', NULL, 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Mì Ý","Ức gà","Nấm đùi gà","Cà chua","Bữa tối"]', '["lunch","dinner"]', '["boil","pan_fry","stir_fry"]', '["chicken","milk","wheat"]', 553, 553.1, 2314, 38.6, 14, 3.2, 67.5, 4.9, 4.5, 568, 1.42, '["USDA FDC 168580","USDA FDC 168927","USDA FDC 169230","USDA FDC 170416","USDA FDC 170457","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 173468","USDA FDC 173647"]', 'a3a79f3d9fea651a5f605b1c6e3583acd9bc06c861d78b547384b2bc7be4b85e', '119f7667d3e2058ed0f50eb80457a71b0316772ff4de2c1904a407d035865648', 4),
('imp-38137393c32d70d7', 'risotto-tom', 487, 'Risotto tôm tươi nấu nước dùng vỏ tôm', 'Cơm Ý Arborio sánh kem mượt mà thấm đẫm vị ngọt tự nhiên từ nước dùng ninh vỏ đầu tôm, rượu vang trắng và bơ lạt', 'Đĩa risotto chuẩn phong cách Ý với hạt gạo Arborio dẻo mềm nhưng vẫn giữ độ sần nhẹ ở lõi, tỏa hương ngọt biển sâu lắng nhờ nước dùng ninh từ vỏ và đầu tôm rang kỹ, kết thúc bằng bước đánh bơ tạo độ bóng kem mượt mà.', 'Múc risotto ra đĩa sâu lòng khi vừa nhấc khỏi bếp, xếp các con tôm áp chảo lên trên mặt và rắc ngò tây tươi băm nhỏ; theo truyền thống Ý, risotto hải sản không dùng kèm phô mai.', 'Risotto ngon nhất khi dùng ngay lúc vừa nấu xong để giữ độ sánh kem đặc trưng. Phần còn dư có thể bảo quản ngăn mát tối đa 2 ngày và hâm nóng trên chảo cùng 2–3 muỗng canh nước dùng hoặc nước lọc.', 'italian', 'mon_kho', NULL, 'medium', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Risotto","Tôm tươi","Cơm Ý","Hải sản","Sánh kem"]', '["lunch","dinner"]', '["simmer","pan_fry"]', '["celery","crustaceans","milk","shrimp","sulphites"]', 508, 507.5, 2124, 23.6, 13.6, 5, 67.9, 1.9, 1.8, 612, 1.53, '["USDA FDC 169230","USDA FDC 169988","USDA FDC 170393","USDA FDC 170416","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","USDA FDC Arborio Rice Ref"]', 'b08efae4eeca45921b80b7d4bdbe4450bcd0604212d44becff22105f34ff8a5a', 'd24203fcf893aaebbd07109ecffe013bb9e94c97fa9e782f74321c84c3a3cc8d', 4),
('imp-e61010e240534690', 'muc-om-ca-chua-y', 488, 'Mực om cà chua kiểu Ý', 'Mực ống tươi om mềm trong sốt cà chua pelati sánh đỏ cùng rượu vang trắng, tỏi thơm và ngò tây', 'Món mực om cà chua mang đậm hương vị vùng biển nước Ý với từng khoanh mực mềm mọng không hề bị dai, thấm đẫm nước sốt cà chua pelati chua thanh hòa quyện mùi tỏi, rượu vang trắng và ngò tây tươi.', 'Múc mực om nóng hổi ra đĩa sâu lòng cùng nước sốt đỏ sánh, rắc ngò tây băm nhỏ và ăn kèm bánh mì nướng giòn để chấm sốt.', 'Bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày. Khi ăn, hâm lại trên chảo với lửa nhỏ trong 4–5 phút để mực mềm ấm mà không bị dai.', 'italian', 'mon_kho', NULL, 'medium', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Mực om","Cà chua","Hải sản","Ẩm thực Ý","Món chính"]', '["lunch","dinner"]', '["braise","simmer"]', '["molluscs","squid","sulphites"]', 227, 226.9, 950, 21.8, 8.6, 1.4, 13, 2.2, 4.7, 672, 1.68, '["USDA FDC 169072","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 174223"]', '9617df795256461fe09ea114bae57d48f82f7b54e9196e83e4bbc371f4c62e4f', 'ada91f4fd6a3961a21cc41c3ce5a9e586904edbc79969a4727db1755aa20cea0', 4),
('imp-452ef6d0f8ec0de9', 'tom-om-ca-chua-y', 489, 'Tôm om sốt cà chua kiểu Ý', 'Tôm tươi săn ngọt chín tới trong nước sốt cà chua passata sóng sánh, thơm hương tỏi phi và lá húng quế Tây', 'Món tôm om sốt cà chua thanh nhẹ kiểu Ý hoàn thành chỉ trong 25 phút với nguyên liệu tinh gọn: tôm tươi bóc vỏ săn ngọt quyện trong sốt cà chua passata sánh mịn, điểm vị cay nhẹ từ ớt và hương thơm tươi mát của húng quế Tây.', 'Múc tôm cùng nước sốt cà chua ra đĩa sâu lòng, rưới thêm vài giọt dầu ô liu nguyên chất và dọn nóng ngay kèm bánh mì nướng giòn hoặc cơm trắng.', 'Món tôm ngon nhất khi dùng ngay lúc mới nấu để tôm giữ độ giòn ngọt. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hâm nhanh ở lửa nhỏ trong 2 phút.', 'italian', 'mon_kho', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm om","Sốt cà chua","Nhanh gọn","Hải sản","Ẩm thực Ý"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","shrimp"]', 202, 201.7, 844, 25.4, 8.1, 1.2, 8.7, 2.1, 4.5, 655, 1.64, '["USDA FDC 169072","USDA FDC 169230","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '5329af471b43c2718e68644fccd38a4bff4425aeab078525ef6f7e21577a3c77', '55efd411512ec44b3b3026e755a3a2050aa7d946b03bf9bafdff1162d3f71f2c', 4),
('imp-f44be7e8c88c20d3', 'sup-ca-hoi-kem-y', 490, 'Súp cá hồi kem tươi kiểu Ý', 'Nồi súp kem ấm áp sánh mịn từ khoai tây, cà rốt và cá hồi phi lê chín mềm béo thanh không tanh', 'Bát súp cá hồi nấu kem kiểu Ý sánh mịn tự nhiên nhờ khoai tây bở hòa cùng kem tươi béo dịu, tôn lên vị ngọt thơm đặc trưng của từng khối phi lê cá hồi tươi chín vừa tới.', 'Múc súp cá hồi ra tô sâu lòng khi còn nóng ấm, rắc ngò tây tươi thái nhỏ, chút thì là tươi và tiêu đen xay mới; ăn kèm bánh mì nướng giòn.', 'Bảo quản súp nguội trong hộp kín ở ngăn mát tối đa 2 ngày. Khi hâm, đun lửa thật nhỏ và khuấy nhẹ để kem không tách dầu và miếng cá hồi không bị nát.', 'italian', 'mon_canh', NULL, 'medium', 15, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Súp kem","Cá hồi","Khoai tây","Ẩm thực Ý","Mùa lạnh"]', '["lunch","dinner"]', '["simmer"]', '["fish","milk","salmon"]', 554, 554.1, 2318, 25.3, 38.6, 18.9, 27, 4.2, 7.8, 1100, 2.75, '["USDA FDC 170000","USDA FDC 170026","USDA FDC 170393","USDA FDC 170416","USDA FDC 170859","USDA FDC 170931","USDA FDC 171595","USDA FDC 172233","USDA FDC 173430","USDA FDC 173468","USDA FDC 175167"]', '58857cabe58684ca25f324437fc644f2ff9f896ac4c64d09513eb19f7f5a7881', 'c9b165fa61aa6ca0616f630827ac7392da3e42006513ce245f712ae5b89c60e7', 4),
('imp-e748a717f7250188', 'salad-ca-hoi-dua-leo', 491, 'Salad cá hồi áp chảo dưa leo sốt chanh', 'Cá hồi áp chảo xém cạnh mềm ngọt kết hợp dưa leo giòn mát, xà lách tươi và sốt dầu ô liu chanh vàng thanh nhẹ', 'Đĩa salad cá hồi thanh mát cân bằng dinh dưỡng với miếng phi lê cá hồi áp chảo vừa chín tới mềm ngọt, ăn cùng dưa leo ướp muối giữ độ giòn sần sật, rau xà lách tươi và nước sốt nhũ tương dầu ô liu chanh vàng dịu mát.', 'Bày salad cá hồi ra đĩa rộng hoặc tô nông lòng khi cá còn hơi ấm hoặc đã để mát, dùng kèm bánh mì nướng giòn để bữa ăn thêm tròn vị.', 'Salad trộn sốt ngon nhất khi dùng ngay trong vòng 1–2 giờ sau khi chế biến. Nếu chuẩn bị trước, nên bảo quản riêng phần cá hồi, rau củ và nước sốt chanh trong ngăn mát tối đa 24 giờ và chỉ trộn đều ngay trước khi ăn.', 'italian', 'mon_cuon_nom', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Salad","Cá hồi","Dưa leo","Thanh mát","Ít tinh bột"]', '["breakfast","lunch","dinner"]', '["pan_fry","toss_mix"]', '["fish","salmon"]', 394, 393.7, 1647, 26.1, 29.4, 5.5, 7.1, 2, 2.4, 475, 1.19, '["USDA FDC 167746","USDA FDC 168409","USDA FDC 169247","USDA FDC 170416","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173474","USDA FDC 175167"]', 'ffe972a9cd476d10b3596d20dc545bc59a30ae80013da34e07845f1508ee9351', '9d1d3ff34d0e9345ea631f5e5ca3adcb61fbb07c791469d72bbab4c83eb9c5fd', 4),
('imp-957396bc647d3798', 'bong-cai-om-ca-chua-y', 492, 'Bông cải xanh om cà chua kiểu Ý', 'Bông cải xanh chần giữ màu xanh mướt rồi om thấm vị cùng cà chua bi, tỏi phi dầu ô liu và chút ớt cay nhẹ', 'Món rau ăn kèm giản dị chuẩn bếp nhà Ý với từng nhánh bông cải xanh mềm ngọt nhưng vẫn giữ độ chắc, quyện trong nước sốt cà chua bi chua thanh sánh nhẹ, dậy mùi tỏi phi thơm trong dầu ô liu nguyên chất.', 'Dọn bông cải om cà chua ra đĩa nông lòng, rắc ngò tây tươi thái nhỏ lên trên; thích hợp ăn kèm thịt nướng, cá áp chảo hoặc bánh mì giòn.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày. Khi dùng, làm nóng trên chảo lửa vừa cùng 1–2 muỗng canh nước trong 3 phút.', 'italian', 'mon_chay', NULL, 'easy', 10, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Bông cải xanh","Cà chua","Món phụ","Món chay","Ẩm thực Ý"]', '["lunch","dinner"]', '["boil","braise"]', '[]', 149, 148.9, 622, 4.3, 10.9, 1.5, 11.7, 4.2, 3.8, 278, 0.7, '["USDA FDC 169230","USDA FDC 170106","USDA FDC 170379","USDA FDC 170416","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647"]', 'f21b49a116388f4fc809468df9105ee8a8f932d44a0768efc622acab6e662791', 'ca002c567928b3784aa667400854bb69c814de9194e4e0a16debfabc12ba6e85', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-c98aa0f1ffe2f469', 'suon-om-ca-chua-y', 493, 'Sườn heo om sốt cà chua kiểu Ý', 'Sườn non áp chảo xém vàng om mềm róc xương cùng sốt cà chua đậm đà, rượu vang trắng, ô liu đen và hương thảo', 'Món sườn heo om cà chua đậm đà kiểu Ý với dẻ sườn áp chảo xém cạnh thơm phức, hầm liu riu cùng hành tây, rượu vang trắng, cà chua đóng hộp và ô liu đen cho đến khi thịt mềm tơi dễ dàng tách khỏi xương.', 'Múc sườn om nóng hổi cùng phần sốt sánh ra đĩa lớn, dùng kèm bánh mì giòn chấm sốt, khoai tây nghiền hoặc trộn cùng mì Ý luộc chín.', 'Món sườn om bảo quản hộp kín trong ngăn mát tối đa 3 ngày và hương vị thường đậm ngon hơn vào ngày hôm sau. Hâm nóng lại trên lửa nhỏ, thêm 2–3 muỗng nước nếu sốt đặc.', 'italian', 'mon_kho', NULL, 'hard', 20, 80, 5, '/frigo/illustrations/delicious-meal.png', '["Sườn heo","Ragu Ý","Om cà chua","Ô liu đen","Cuối tuần"]', '["lunch","dinner"]', '["pan_fry","braise","simmer"]', '["pork","sulphites"]', 589, 588.9, 2464, 26.2, 45.9, 14.5, 15.9, 3.9, 7.1, 994, 2.48, '["USDA FDC 167861","USDA FDC 169072","USDA FDC 169094","USDA FDC 169230","USDA FDC 170000","USDA FDC 170393","USDA FDC 170917","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647"]', '6730c036020532afd7b11ee318883502274aa99b57d16aed626842a7fd93046b', '012219587ed4d63cfbd5f2040b330ff3c153da37953afe545851c53e75571da2', 4),
('imp-a286f8724d79a504', 'ca-chua-tron-pho-mai', 494, 'Cà chua trộn phô mai Mozzarella tươi kiểu Ý', 'Cà chua chín mọng xếp xen kẽ phô mai Mozzarella tươi mềm béo, rưới dầu ô liu nguyên chất và giấm Balsamic thanh dịu', 'Món khai vị lạnh thanh mát chuẩn phong cách Ý tôn vinh nguyên liệu tươi ngon nhất: cà chua chín mọng cắt lát dày quyện phô mai Mozzarella tươi mềm béo, dầu ô liu nguyên chất thơm nồng và lá húng quế Tây tươi mát.', 'Bày đĩa cà chua trộn phô mai ngay sau khi hoàn thiện để dùng làm món khai vị hoặc ăn kèm bánh mì nướng giòn chấm phần nước dầu ô liu cà chua tiết ra.', 'Món khai vị tươi sống ngon nhất khi ăn ngay lúc vừa trộn; không nên cất tủ lạnh vì nhiệt độ thấp làm cà chua bở và mất hương thơm.', 'italian', 'mon_cuon_nom', NULL, 'easy', 10, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Khai vị","Cà chua","Mozzarella","Salad Ý","Mát lành"]', '["breakfast","lunch","dinner"]', '["toss_mix","assemble"]', '["milk","sulphites"]', 304, 303.9, 1271, 17.3, 22.2, 7.9, 9.8, 2.1, 5.6, 753, 1.88, '["USDA FDC 169230","USDA FDC 170457","USDA FDC 170845","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173470"]', '7cc66d35f236cfcf6afeb064405591c96bf2efaa20b4412f6b0b2e1fea79ab73', '19680b1799d0cdc621bef1dfe169c386b719ccfe2a2854302b7714b9c33131e8', 4),
('imp-83ed31fc537569a6', 'bo-cuon-rau-bina-y', 495, 'Bò cuộn rau bina phô mai kiểu Ý', 'Thịt bò lát mỏng dần mềm cuộn nhân rau bina xào bơ và phô mai béo ngậy, áp chảo vàng rồi om sốt rượu vang trắng', 'Những cuộn thịt bò involtini khéo léo ôm trọn phần nhân rau bina xanh mướt xào bơ tỏi, phô mai Mozzarella tan chảy và cà rốt ngọt thanh, áp chảo xém cạnh rồi om mềm cùng cà chua và rượu vang trắng.', 'Rút bỏ dây buộc hoặc tăm cố định, cắt đôi cuộn thịt bò theo lát chéo để lộ lớp nhân xanh vàng đẹp mắt, rưới sốt om nóng lên trên và dùng kèm khoai tây nghiền hoặc mì Ý.', 'Bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày. Khi dùng, hâm lại cùng nước sốt trên chảo lửa nhỏ đậy nắp khoảng 5–6 phút.', 'italian', 'mon_kho', NULL, 'medium', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Involtini","Bò cuộn","Rau bina","Phô mai","Ẩm thực Ý"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["beef","milk","sulphites"]', 600, 599.6, 2509, 46.3, 39.2, 16.6, 13.7, 4.2, 5.2, 896, 2.24, '["USDA FDC 168462","USDA FDC 169230","USDA FDC 170187","USDA FDC 170393","USDA FDC 170457","USDA FDC 170499","USDA FDC 170845","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647"]', '4713e8616370e5cf8671c51937c12ff5182fef4cfb89909d18557b96cd4cc316', '47cc012efdf360aea669448a002b166bc6887d580d48f3fb865de6e9eab290ca', 4),
('imp-a92103c19952bcf0', 'ga-chien-chanh-y', 496, 'Gà chiên giòn ướp chanh vàng kiểu Ý', 'Ức gà ướp nước cốt chanh vàng và thảo mộc đậm đà, áo lớp bột chiên xù trộn Parmesan rồi chiên vàng và nướng giòn', 'Món gà chiên thơm mát hương chanh vàng vùng Địa Trung Hải: ức gà ướp rượu vang trắng, chanh tươi và tỏi thảo mộc giúp thịt mềm ẩm, bọc lớp bột chiên xù giòn rụm trộn phô mai Parmesan và vỏ chanh bào.', 'Xếp gà nóng ra đĩa, rắc thêm ngò tây tươi băm nhỏ và vỏ chanh vàng bào sợi; ăn kèm salad rau xanh dầu giấm hoặc khoai tây chiên.', 'Bảo quản thịt gà nguội trong hộp kín ở ngăn mát tối đa 2 ngày. Khi dùng, làm nóng bằng nồi chiên không dầu hoặc lò nướng ở 180°C khoảng 6–8 phút để lớp vỏ giòn trở lại.', 'italian', 'mon_chien', NULL, 'medium', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Gà chiên","Chanh vàng","Parmesan","Giòn rụm","Ẩm thực Ý"]', '["lunch","dinner"]', '["pan_fry","grill_roast"]', '["chicken","milk","sulphites","wheat"]', 426, 425.5, 1780, 45, 13.4, 3.9, 28.9, 2.5, 1.9, 1112, 2.78, '["Panko / Batter Mix Ref","USDA FDC 167746","USDA FDC 169230","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 173190","USDA FDC 173468","USDA FDC 173475"]', 'bbefd24f7c898d7b37dbac53bff10d06dd9fa2713e3fd857339386f98251dc28', '4e0a8ae6b51b98cf31b2a88b41f746d343613accaae7e4e564903bdee360309f', 4),
('imp-afdcd866c1f92192', 'ca-om-ca-chua-y', 497, 'Cá phi lê om cà chua bi kiểu Ý', 'Phi lê cá thịt trắng om dịu trong nước dùng cà chua bi, hành tây, rượu vang trắng và ô liu đen đậm vị biển', 'Món cá om thanh tao kiểu ngư dân vùng biển Naples nước Ý với từng miếng phi lê cá thịt trắng mềm ngọt giữ nguyên thớ, nấu trong nước dùng cà chua bi tươi mát quyện hương tỏi, rượu vang trắng và quả ô liu đen.', 'Gắp cá ra 4 đĩa sâu lòng, chan đều nước dùng cà chua và ô liu nóng hổi lên mặt cá, rắc ngò tây tươi băm nhỏ và ăn kèm bánh mì giòn chấm nước sốt.', 'Món cá om ngon nhất khi dùng ngay lúc mới nấu. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hâm lại trên lửa thật nhỏ để thịt cá không bị nát.', 'italian', 'mon_kho', NULL, 'medium', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Cá om","Cà chua bi","Hải sản","Thanh nhẹ","Ẩm thực Ý"]', '["lunch","dinner"]', '["braise","simmer"]', '["fish","sulphites"]', 290, 289.8, 1213, 32.2, 13.4, 2.3, 8.1, 2, 3.6, 624, 1.56, '["USDA FDC 169094","USDA FDC 169230","USDA FDC 170000","USDA FDC 170106","USDA FDC 170416","USDA FDC 170457","USDA FDC 170917","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647","USDA FDC 175148"]', '96368b117e8cd5928cdf72cb448cd75c2e3024cf743ed9dca99a2c1957fcc098', '6a00f89aa89b3fb8744b2e00469f65843991cb83f8208492b22afbd5a8af892d', 4),
('imp-6d26ce6b0af4fb79', 'rau-bina-om-kem-y', 498, 'Rau bina om sốt kem Béchamel kiểu Ý', 'Rau bina hấp xào mềm mượt quyện trong sốt kem Béchamel béo thanh, phô mai Parmesan và thoảng hương nhục đậu khấu', 'Món rau ăn kèm sang trọng chuẩn cổ điển Ý với rau bina nấu chín bằng chính độ ẩm tự nhiên rồi vắt ráo, xào thơm cùng hành tây và hòa quyện trong lớp sốt kem trắng Béchamel sánh mịn, thơm vị bơ sữa, Parmesan và nhục đậu khấu.', 'Múc rau bina om sốt kem nóng ra đĩa sâu lòng và thưởng thức ngay cùng thịt gà nướng, bò áp chảo hoặc phi lê cá nướng lò.', 'Món ăn ngon nhất khi dùng ngay lúc mới nấu xong. Nếu bảo quản ngăn mát tối đa 24 giờ, hâm nóng nhẹ trên chảo với 1–2 muỗng canh sữa tươi và khuấy đều tay.', 'italian', 'mon_chay', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Rau bina","Béchamel","Sốt kem","Món phụ","Món chay"]', '["lunch","dinner"]', '["steam","simmer","toss_mix"]', '["milk","wheat"]', 273, 273.2, 1143, 12.8, 17.8, 8.4, 18.7, 4.5, 5.7, 850, 2.13, '["USDA FDC 168462","USDA FDC 169761","USDA FDC 170000","USDA FDC 170848","USDA FDC 170931","USDA FDC 171265","USDA FDC 171326","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468"]', 'bcd39cc4f63da275678b9a14e0eed055e31ab9ca81ac39853424489be4324059', '52adc251baac5e19a044a0cfb1eaa0313c91300c85fccae387c8e5708fcadf02', 4),
('imp-bd34e8ea2eaa1cd4', 'sup-bap-cai-y', 499, 'Súp bắp cải đậu trắng thịt xông khói kiểu Ý', 'Súp hầm ấm bụng với bắp cải ngọt mềm, đậu trắng bở béo, thịt xông khói thơm lừng cùng nui Ý và Parmesan', 'Nồi súp bắp cải kiểu nông thôn Ý đầy đặn dinh dưỡng với nền rau củ xào thơm quyện thịt xông khói, ninh mềm cùng đậu trắng cannellini, bắp cải ngọt thanh và nui Ý hạt nhỏ, hoàn thiện bằng lớp phô mai Parmesan béo dịu.', 'Múc nui Ý luộc sẵn ra 4 tô sâu lòng, chan súp bắp cải đậu trắng nóng hổi lên trên và rắc phô mai Parmesan bào mịn; ăn kèm bánh mì nướng giòn.', 'Nếu chuẩn bị ăn nhiều bữa, nên bảo quản riêng phần nui đã luộc và nồi súp trong ngăn mát tối đa 3 ngày; khi dùng đun sôi lại phần súp rồi chan lên nui để nui không bị bở nát.', 'italian', 'mon_canh', NULL, 'easy', 15, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Súp Ý","Bắp cải","Đậu trắng","Thịt xông khói","Mùa lạnh"]', '["lunch","dinner"]', '["simmer","boil"]', '["celery","milk","pork","wheat"]', 503, 502.7, 2104, 18.5, 26.4, 9.7, 49.8, 7.8, 7.4, 1231, 3.08, '["USDA FDC 167923","USDA FDC 168927","USDA FDC 169230","USDA FDC 169975","USDA FDC 169988","USDA FDC 170000","USDA FDC 170026","USDA FDC 170393","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 172883","USDA FDC 173430","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647","USDA FDC 175200"]', 'c033996f841f549b17724f1beeaf3c519cff13093942674c33341b45b4d011ed', 'd03297a6273f63b2e84a6ec276b8df7d20e587f28465cbd3605edddcf18c1a1e', 4);

