('imp-bd34e8ea2eaa1cd4_v4_ing_15', 'imp-bd34e8ea2eaa1cd4', 14, 'PARMESAN_CHEESE', 'Phô mai Parmesan bào mịn', '25 g', 'rắc mặt tô súp nóng trước khi dùng', 'garnish', 25, 'g', 25, 1, 25, 0, 1),
('imp-bd34e8ea2eaa1cd4_v4_ing_16', 'imp-bd34e8ea2eaa1cd4', 15, 'SALT', 'Muối ăn', '5 g (~1 muỗng cà phê)', 'dùng 3 g cho vào nước luộc nui (bỏ nước), 2 g nêm nồi súp', 'broth', 5, 'g', 5, 0.5, 2.5, 0, 1),
('imp-bd34e8ea2eaa1cd4_v4_ing_17', 'imp-bd34e8ea2eaa1cd4', 16, 'BLACK_PEPPER', 'Tiêu đen xay', '1,5 g (~1/2 muỗng cà phê)', 'nêm vào nồi súp khi ninh', 'broth', 1.5, 'g', 1.5, 1, 1.5, 0, 1),
('imp-bd34e8ea2eaa1cd4_v4_ing_18', 'imp-bd34e8ea2eaa1cd4', 17, 'COOKING_WATER', 'Nước lọc (luộc riêng nui Ý)', '1000 ml (1 lít)', 'đun sôi với muối để luộc nui chín al dente rồi chắt bỏ nước', 'broth', 1000, 'ml', 1000, 0.05, 50, 0, 0);

INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-e427b91ce9f574c3_v4_step_1', 'imp-e427b91ce9f574c3', 1, 'prep', 'Lau sạch và phân chia nấm đùi gà, rau thơm', 'Dùng khăn ẩm lau sạch 400 g nấm đùi gà tươi (tránh rửa ngập nước), cắt bỏ phần gốc già. Chọn 2 cây nấm đẹp thái dọc thành các lát mỏng khoảng 0,4 cm để riêng làm phần trang trí, phần nấm còn lại thái miếng vuông vừa. Thái hạt lựu nhỏ 1 củ hành tây, bóc vỏ 2 tép tỏi khô và băm nhỏ 10 g ngò tây tươi.', NULL, NULL),
('imp-e427b91ce9f574c3_v4_step_2', 'imp-e427b91ce9f574c3', 2, 'cook', 'Xào thơm nấm đùi gà cùng tỏi và hành tây', 'Đun nóng 25 ml dầu ô liu trong chảo lớn ở lửa vừa, cho tỏi khô nguyên tép và phần nấm thái miếng vuông vào cùng 2 g muối ăn, xào mở nắp khoảng 8–10 phút đến khi nấm ra nước và hơi vàng thơm. Gắp bỏ tép tỏi để súp không bị hăng, tiếp tục cho hành tây vào đảo thêm 3–4 phút cho hành mềm trong.', 'Vớt bỏ tép tỏi trước khi xay súp giúp giữ trọn hương thơm dịu mà không bị mùi hăng nồng lấn át vị ngọt thanh của nấm.', 12),
('imp-e427b91ce9f574c3_v4_step_3', 'imp-e427b91ce9f574c3', 3, 'sauce', 'Nấu nền sốt sữa bơ bột mì', 'Trong nồi súp chính trên lửa nhỏ, đun chảy 30 g bơ lạt, trút 30 g bột mì đa dụng vào khuấy đều liên tục 2 phút cho bột chín thơm màu vàng nhạt. Rót từ từ 250 ml sữa tươi không đường vào nồi, vừa rót vừa đánh liên tục bằng phới lồng đến khi sốt sôi nhẹ và sánh mịn không vón cục.', 'Rót sữa tươi từ từ từng chút một và khuấy đều tay ngay từ đầu là bí quyết giúp nền bột mì tan mượt hoàn toàn không vón cục.', 5),
('imp-e427b91ce9f574c3_v4_step_4', 'imp-e427b91ce9f574c3', 4, 'cook', 'Ninh súp nấm với nước dùng rau củ và xay nhuyễn', 'Trút toàn bộ nấm và hành tây đã xào vào nồi sốt sữa, đổ thêm 500 ml nước dùng rau củ, 3 g muối ăn và 1 g tiêu đen xay. Hạ lửa nhỏ ninh liu riu khoảng 12 phút cho nấm chín mềm ngọt, sau đó dùng máy xay cầm tay xay thật nhuyễn mịn ngay trong nồi. Rót thêm 100 ml kem tươi nấu ăn vào khuấy đều, giữ ấm trên lửa thật nhỏ mà không để sôi bùng.', 'Nếu thích súp loãng nhẹ hơn có thể pha thêm chút nước dùng rau củ nóng, đồng thời không đun sôi sau khi cho kem tươi để giữ kết cấu súp mượt mà.', 12),
('imp-e427b91ce9f574c3_v4_step_5', 'imp-e427b91ce9f574c3', 5, 'cook', 'Áp chảo lát nấm trang trí và nướng giòn bánh mì', 'Làm nóng 10 ml dầu ô liu còn lại trên chảo nhỏ, xếp các lát nấm mỏng để riêng vào áp chảo mỗi mặt 1–2 phút cho vàng thơm, rắc 1 g muối ăn, 0,5 g tiêu đen xay và một nửa lượng ngò tây băm (5 g). Đồng thời nướng giòn hoặc áp chảo vàng 4 lát bánh mì hai mặt để ăn kèm.', NULL, NULL),
('imp-e427b91ce9f574c3_v4_step_6', 'imp-e427b91ce9f574c3', 6, 'finish', 'Múc súp nóng và trang trí hoàn thiện', 'Múc súp nấm kem nóng hổi ra 4 bát sâu lòng, xếp các lát nấm áp chảo lên trên mặt, rắc nốt 5 g ngò tây tươi băm còn lại rồi dọn ngay cùng bánh mì nướng giòn.', NULL, NULL),
('imp-f3eb85959cb62d3e_v4_step_1', 'imp-f3eb85959cb62d3e', 1, 'prep', 'Sơ chế rau củ thái hạt lựu và ức gà', 'Gọt vỏ cà rốt và khoai tây rồi thái hạt lựu đều cỡ 1,5 cm (ngâm khoai tây vào nước lạnh cho khỏi thâm rồi vớt ráo). Băm nhỏ hành tây, thái lát mỏng cần tây, băm nhuyễn tỏi khô và thái nhỏ 12 g ngò tây tươi. Rửa sạch 500 g ức gà phi lê dưới vòi nước lạnh.', 'Thái cà rốt và khoai tây kích thước đồng đều giúp hai loại củ chín mềm cùng lúc mà không bị nát.', NULL),
('imp-f3eb85959cb62d3e_v4_step_2', 'imp-f3eb85959cb62d3e', 2, 'cook', 'Luộc ức gà lấy nước dùng trong ngọt', 'Đặt 500 g ức gà vào nồi cùng 2 lá nguyệt quế khô và 4 g muối ăn, đổ 1000 ml nước lọc lạnh ngập gà rồi đun sôi. Khi nước sôi, hớt sạch bọt nổi để nước dùng thật trong, hạ lửa nhỏ đậy nắp và luộc liu riu 20 phút cho thịt gà chín mềm hoàn toàn.', 'Bắt đầu luộc gà từ nước lạnh và hớt bọt kỹ giúp chất ngọt từ thịt tiết ra từ từ và nồi nước dùng trong veo.', 20),
('imp-f3eb85959cb62d3e_v4_step_3', 'imp-f3eb85959cb62d3e', 3, 'cook', 'Xào thơm rau củ nền với dầu ô liu', 'Trong lúc chờ gà chín, làm nóng 40 ml dầu ô liu trong nồi súp lớn ở lửa vừa. Cho hành tây băm vào xào 2 phút cho trong, sau đó thêm cà rốt, cần tây và tỏi băm vào đảo đều tay thêm 5 phút cho rau củ dậy mùi thơm và hơi dịu mềm.', NULL, 7),
('imp-f3eb85959cb62d3e_v4_step_4', 'imp-f3eb85959cb62d3e', 4, 'prep', 'Lọc nước dùng và xé nhỏ thịt ức gà', 'Vớt ức gà ra đĩa để nguội bớt rồi dùng tay xé sợi hoặc cắt miếng nhỏ vừa ăn. Lọc toàn bộ phần nước luộc gà qua rây mịn để loại bỏ cặn bọt và lá nguyệt quế.', NULL, NULL),
('imp-f3eb85959cb62d3e_v4_step_5', 'imp-f3eb85959cb62d3e', 5, 'cook', 'Ninh mềm khoai tây, cà rốt và thịt gà', 'Rót phần nước luộc gà đã lọc cùng 500 ml nước lọc còn lại vào nồi rau củ đã xào. Thêm khoai tây cắt hạt lựu, 15 g cà chua cô đặc, 4 g muối ăn còn lại và 1,5 g tiêu đen xay. Đun sôi nhẹ rồi hạ lửa nhỏ đậy nắp nấu 18 phút đến khi khoai tây và cà rốt chín bùi, sau đó thả thịt gà xé vào nấu thêm 5 phút cho hòa vị.', 'Thả thịt gà xé vào ở 5 phút cuối giúp thịt thấm vị súp rau củ mà vẫn giữ được độ mềm ngọt, không bị bã xơ.', 23),
('imp-f3eb85959cb62d3e_v4_step_6', 'imp-f3eb85959cb62d3e', 6, 'finish', 'Nêm lại và múc súp nóng rắc ngò tây', 'Nêm nếm lại muối và tiêu đen cho vừa khẩu vị gia đình, múc súp ra 4 tô sâu lòng khi còn nóng hổi rồi rắc ngò tây tươi thái nhỏ cùng 0,5 g tiêu đen xay lên mặt trước khi thưởng thức.', NULL, NULL),
('imp-f4c5afa7ccc2a9ed_v4_step_1', 'imp-f4c5afa7ccc2a9ed', 1, 'prep', 'Làm nóng lò, khoét ruột và làm ráo cà chua', 'Bật lò nướng làm nóng trước ở 180°C chế độ hai lửa trên-dưới và phết 15 ml dầu ô liu đều xuống đáy khay nướng. Rửa sạch 6 quả cà chua chín to chắc tay, lau khô, cắt ngang phần chóp trên làm nắp đậy. Dùng thìa nhỏ cẩn thận nạo sạch ruột cà chua ra bát riêng sao cho không làm rách vỏ. Rắc 2 g muối ăn vào lòng từng quả cà chua rồi úp ngược xuống rổ 10 phút để chảy bớt nước.', 'Rắc chút muối và úp ngược vỏ cà chua trong 10 phút giúp rút bớt lượng nước thừa, giữ thành quả cà chua chắc chắn và nhân thịt không bị nhão khi nướng.', 10),
('imp-f4c5afa7ccc2a9ed_v4_step_2', 'imp-f4c5afa7ccc2a9ed', 2, 'prep', 'Băm nhỏ nguyên liệu thơm và phần ruột cà chua', 'Bóc vỏ băm thật nhuyễn 2–3 tép tỏi khô và băm nhuyễn 15 g ngò tây tươi. Chắt bỏ bớt hạt và nước loãng trong bát ruột cà chua, cắt nhỏ phần thịt ruột cà chua để trộn nhân.', NULL, NULL),
('imp-f4c5afa7ccc2a9ed_v4_step_3', 'imp-f4c5afa7ccc2a9ed', 3, 'prep', 'Trộn nhân thịt heo xay cùng phô mai và gia vị', 'Cho 300 g thịt heo xay vào tô lớn cùng 1 quả trứng gà, 50 g bột chiên xù, 25 g phô mai Parmesan bào mịn, tỏi băm, ngò tây băm, phần ruột cà chua cắt nhỏ, 4 g muối ăn còn lại và 1,5 g tiêu đen xay. Trộn thật đều tay đến khi hỗn hợp nhân thịt hòa quyện dẻo mịn.', 'Trộn phần ruột cà chua cùng bột chiên xù giúp nhân giữ được độ mọng ẩm tự nhiên suốt quá trình nướng lò mà không bị khô cứng.', NULL),
('imp-f4c5afa7ccc2a9ed_v4_step_4', 'imp-f4c5afa7ccc2a9ed', 4, 'cook', 'Nhồi nhân vào cà chua và xếp lên khay', 'Dùng giấy thấm khô bên trong lòng 6 quả cà chua đã ráo nước. Múc nhân thịt nhồi đầy vào từng quả (chỉ ấn nhẹ vừa tay, không nén quá chặt để nhân còn độ nở tơi), rắc nốt 15 g phô mai Parmesan bào mịn lên mặt nhân rồi đậy nắp cà chua lên trên. Xếp đứng gọn các quả vào khay nướng đã phết dầu và rưới đều 25 ml dầu ô liu còn lại lên bề mặt.', NULL, NULL),
('imp-f4c5afa7ccc2a9ed_v4_step_5', 'imp-f4c5afa7ccc2a9ed', 5, 'cook', 'Nướng cà chua ở 180°C đến khi nhân chín hẳn', 'Đặt khay vào ngăn giữa lò nướng ở 180°C trong khoảng 30–35 phút đến khi thịt heo bên trong chín hoàn toàn (xiên tăm vào tâm nhân thấy nước chảy ra trong, không còn màu hồng), vỏ cà chua mềm nhăn nhẹ mà vẫn giữ nguyên dáng và phô mai hơi xém vàng.', 'Nếu phần nắp cà chua có dấu hiệu sậm màu nhanh ở 10 phút cuối, có thể phủ hờ một tờ giấy bạc lên trên để nhân bên trong chín kỹ hoàn toàn.', 35),
('imp-f4c5afa7ccc2a9ed_v4_step_6', 'imp-f4c5afa7ccc2a9ed', 6, 'finish', 'Để nghỉ định hình và trình bày ra đĩa', 'Lấy khay cà chua ra khỏi lò và để nghỉ 5 phút cho phần nhân ổn định kết cấu. Chuyển cà chua ra đĩa sâu lòng, rưới phần nước sốt tiết ra dưới đáy khay, trang trí thêm vài lá húng quế Tây tươi lên trên và dùng nóng hoặc ấm.', NULL, NULL),
('imp-0d54a1288223d8ac_v4_step_1', 'imp-0d54a1288223d8ac', 1, 'prep', 'Làm nóng lò và thấm khô đùi gà', 'Làm nóng lò nướng ở 200°C trước 15 phút và lót giấy nến lên khay nướng. Rửa sạch 900 g đùi gà dưới vòi nước lạnh, sau đó dùng khăn giấy thấm thật khô cả mặt da lẫn mặt thịt để khi nướng da lên màu vàng giòn đều.', 'Da gà càng ráo nước thì khi gặp nhiệt cao càng nhanh giòn rụm và không bị ra nước hấp hơi.', NULL),
('imp-0d54a1288223d8ac_v4_step_2', 'imp-0d54a1288223d8ac', 2, 'marinate', 'Xát hỗn hợp gia vị khô lên thịt gà', 'Trộn đều 3 g bột tỏi, 3 g ớt bột paprika ngọt, 2 g thảo mộc Ý khô, 6 g muối ăn và 2 g tiêu đen xay trong chén nhỏ. Xát đều hỗn hợp gia vị này lên cả hai mặt của từng chiếc đùi gà, ấn nhẹ để gia vị bám chắc vào da và thịt.', NULL, NULL),
('imp-0d54a1288223d8ac_v4_step_3', 'imp-0d54a1288223d8ac', 3, 'sauce', 'Đun chảy bơ lạt và phi thơm tỏi tươi', 'Đặt chảo nhỏ lên lửa nhỏ, cho 45 g bơ lạt vào đun tan chảy hoàn toàn rồi cho toàn bộ tỏi tươi băm nhuyễn vào đảo nhanh tay khoảng 45 giây đến khi dậy mùi thơm dịu thì tắt bếp ngay, giữ cho tỏi không bị chuyển nâu.', 'Chỉ đun tỏi vừa dậy hương trên lửa nhỏ rồi nhấc chảo ra khỏi bếp để tỏi không bị cháy đắng khi vào lò nướng.', 1),
('imp-0d54a1288223d8ac_v4_step_4', 'imp-0d54a1288223d8ac', 4, 'marinate', 'Phết sốt bơ tỏi và xếp gà lên khay', 'Xếp các miếng đùi gà lên khay nướng đã lót giấy nến sao cho mặt da hướng lên trên và các miếng cách nhau khoảng 2 cm. Dùng cọ phết đều phần lớn hỗn hợp bơ tỏi lên mặt gà, phần bơ còn lại rưới nhẹ quanh khay để thịt luôn ẩm mềm.', NULL, NULL),
('imp-0d54a1288223d8ac_v4_step_5', 'imp-0d54a1288223d8ac', 5, 'cook', 'Nướng gà ở 200°C và rưới bơ giữa chừng', 'Đưa khay gà vào rãnh giữa của lò nướng ở 200°C trong 35 phút. Đến phút thứ 20, mở lò kéo nhẹ khay ra và dùng muỗng múc phần nước bơ tỏi chảy ra dưới khay rưới đều lại một lượt lên mặt da gà rồi nướng tiếp.', NULL, 35),
('imp-0d54a1288223d8ac_v4_step_6', 'imp-0d54a1288223d8ac', 6, 'cook', 'Tăng nhiệt làm giòn da và kiểm tra độ chín', 'Tăng nhiệt lò lên 220°C hoặc bật chế độ lửa trên nướng thêm 4–5 phút đến khi da gà vàng giòn và hơi xém cạnh đẹp mắt. Dùng que xiên vào phần thịt sát xương không thấy nước hồng chảy ra (nhiệt độ lõi đạt ít nhất 75°C) là gà chín hoàn toàn.', 'Quan sát kỹ 2 phút cuối khi bật lửa trên vì gia vị paprika và tỏi có thể sậm màu nhanh ở nhiệt cao.', 5),
('imp-0d54a1288223d8ac_v4_step_7', 'imp-0d54a1288223d8ac', 7, 'finish', 'Nghỉ thịt, rắc ngò tây và dọn nóng', 'Lấy khay gà ra khỏi lò, để thịt nghỉ 5 phút cho nước ngọt ổn định bên trong thớ thịt. Xếp đùi gà ra đĩa, rưới thêm nước sốt bơ tỏi từ khay và rắc ngò tây tươi thái nhỏ lên trên rồi dùng nóng ngay.', NULL, NULL),
('imp-70e5e19dd4073b76_v4_step_1', 'imp-70e5e19dd4073b76', 1, 'prep', 'Thái khối thịt bò và áo lớp bột mỏng', 'Thấm thật khô 1,1 kg thịt bò bằng khăn giấy rồi cắt thành các khối vuông đều cỡ 3,5–4 cm. Cho thịt vào tô lớn, rắc đều 35 g bột mì đa dụng, xóc nhẹ cho bột phủ một lớp mỏng rồi giũ bớt phần bột thừa ra ngoài.', 'Chỉ áo lớp bột rất mỏng và giũ sạch phần dư để nước sốt hầm sánh mịn tự nhiên mà không bị lợn cợn vón cục.', NULL),
('imp-70e5e19dd4073b76_v4_step_2', 'imp-70e5e19dd4073b76', 2, 'prep', 'Chuẩn bị nền rau củ và đun nóng nước dùng', 'Băm hạt lựu nhỏ hành tây vàng, cà rốt tươi và cần tây tươi để làm nền rau củ kiểu Ý. Đồng thời đặt 1 lít nước dùng bò lên một bếp khác đun nóng già và giữ ấm trên lửa nhỏ.', 'Luôn dùng nước dùng thật nóng khi châm vào thịt đang áp chảo để thớ bò không bị co cứng do sốc nhiệt.', NULL),
('imp-70e5e19dd4073b76_v4_step_3', 'imp-70e5e19dd4073b76', 3, 'cook', 'Xào thơm nền rau củ với bơ và dầu ô liu', 'Đặt nồi gang hoặc nồi đáy dày lên lửa vừa, cho 40 ml dầu ô liu nguyên chất và 35 g bơ lạt vào đun chảy. Thả hành tây, cà rốt và cần tây vào xào khoảng 5 phút đến khi rau củ mềm dịu và dậy mùi ngọt thơm.', NULL, 5),
('imp-70e5e19dd4073b76_v4_step_4', 'imp-70e5e19dd4073b76', 4, 'cook', 'Áp chảo xém vàng đều các khối thịt bò', 'Tăng lên lửa vừa-lớn, cho thịt bò đã áo bột vào nồi cùng rau củ (chia 2 mẻ nếu đáy nồi nhỏ) và áp chảo khoảng 8 phút đến khi các mặt thịt chuyển màu nâu vàng đẹp mắt. Thêm 3 g thảo mộc Ý khô vào đảo đều 30 giây cho dậy hương.', NULL, 8),
('imp-70e5e19dd4073b76_v4_step_5', 'imp-70e5e19dd4073b76', 5, 'cook', 'Khử cặn đáy nồi với rượu vang đỏ', 'Vặn lửa lớn, rót 150 ml rượu vang đỏ nấu ăn vào nồi. Dùng muỗng gỗ cạo nhẹ toàn bộ phần cháy xém thơm ngon bám ở đáy nồi hòa tan vào rượu, đun sôi khoảng 3 phút cho mùi cồn bay hơi hoàn toàn.', NULL, 3),
('imp-70e5e19dd4073b76_v4_step_6', 'imp-70e5e19dd4073b76', 6, 'cook', 'Thêm cà chua nghiền và hầm liu riu 90 phút', 'Đổ 300 g cà chua nghiền nhuyễn (passata) vào nồi, khuấy đều rồi rót tiếp 1 lít nước dùng bò nóng vào ngập mặt thịt. Nêm 8 g muối ăn và 3 g tiêu đen xay, đậy nắp kín, hạ xuống lửa thật nhỏ và hầm liu riu ít nhất 90 phút đến khi thịt bò mềm tơi, dùng nĩa xiên qua dễ dàng.', 'Thỉnh thoảng mở nắp đảo nhẹ đáy nồi và châm thêm chút nước nóng nếu thấy sốt cạn quá nhanh trước khi thịt kịp mềm.', 90),
('imp-70e5e19dd4073b76_v4_step_7', 'imp-70e5e19dd4073b76', 7, 'finish', 'Cô sánh sốt và hoàn thiện món bò hầm', 'Mở nắp kiểm tra: nếu nước sốt còn hơi loãng, vặn lửa vừa-lớn đun thêm 5–8 phút không đậy nắp để sốt rút bớt và sánh bóng lại. Nếm lại gia vị cho vừa miệng, tắt bếp rồi múc bò hầm nóng ra đĩa sâu lòng để thưởng thức.', NULL, NULL),
('imp-500ffbf4fd05f9da_v4_step_1', 'imp-500ffbf4fd05f9da', 1, 'prep', 'Sơ chế mực ống và rau thơm', 'Làm sạch kỹ 450 g mực ống tươi, rút bỏ túi mực, mai và phần răng cứng ở gốc râu rồi rửa sạch, cắt thân thành khoanh dày 1 cm và thấm thật khô bằng khăn giấy. Cà chua bi bổ đôi, tỏi tươi băm nhỏ, ớt tươi thái lát, 15 g ngò tây tươi thái nhỏ và hẹ lá cắt khúc ngắn.', 'Mực được thấm ráo nước trước khi vào chảo nóng sẽ xém cạnh thơm lừng thay vì tiết nước bị luộc dai.', NULL),
('imp-500ffbf4fd05f9da_v4_step_2', 'imp-500ffbf4fd05f9da', 2, 'cook', 'Áp chảo nhanh mực ống trên lửa lớn', 'Làm nóng chảo sâu lòng với 30 ml dầu ô liu nguyên chất trên lửa lớn đến khi dầu thật nóng. Thả mực vào áp chảo nhanh khoảng 4–5 phút, đảo vài lần cho đến khi mực săn cong và hơi xém vàng ở viền.', NULL, 5),
('imp-500ffbf4fd05f9da_v4_step_3', 'imp-500ffbf4fd05f9da', 3, 'cook', 'Phi tỏi ớt và om mực cùng cà chua bi', 'Hạ xuống lửa vừa, cho tỏi băm và ớt tươi vào đảo thơm 30 giây, sau đó thêm cà chua bi bổ đôi và rót 60 ml rượu vang trắng khô vào, cạo nhẹ đáy chảo cho tan phần cháy thơm. Nêm 3 g muối ăn và 1 g tiêu đen xay, đậy nắp om trên lửa nhỏ khoảng 15 phút đến khi cà chua nát quyện thành sốt đỏ sánh và mực chín mềm.', 'Mực cần được om đủ thời gian trên lửa liu riu để thớ thịt chuyển từ dai sang mềm ngọt và hòa quyện với nước cà chua.', 15),
('imp-500ffbf4fd05f9da_v4_step_4', 'imp-500ffbf4fd05f9da', 4, 'cook', 'Luộc mì Ý al dente song song khi om sốt', 'Trong lúc om sốt mực ở những phút cuối, đun sôi 2 lít nước lọc với 7 g muối ăn trong nồi lớn. Thả 320 g mì Ý spaghetti vào luộc khoảng 8–9 phút (ít hơn hướng dẫn bao bì 1 phút) đến độ chín dai vừa phải, giữ lại khoảng 100 ml nước luộc mì trước khi vớt mì ra.', NULL, 9),
('imp-500ffbf4fd05f9da_v4_step_5', 'imp-500ffbf4fd05f9da', 5, 'cook', 'Trộn hẹ, ngò tây và xóc mì quyện sốt', 'Mở nắp chảo sốt mực, cho phần lớn hẹ lá tươi và một nửa lượng ngò tây tươi vào đảo 1 phút cho vừa héo dậy mùi. Đổ mì Ý đã ráo vào chảo, thêm 15 ml dầu ô liu nguyên chất còn lại cùng từng muỗng nước luộc mì và xóc đều trên lửa lớn 1 phút để sốt bám bóng từng sợi mì.', 'Tinh bột trong nước luộc mì giúp kết dính dầu ô liu và nước cà chua thành lớp sốt mượt bám đều lên sợi spaghetti.', 2),
('imp-500ffbf4fd05f9da_v4_step_6', 'imp-500ffbf4fd05f9da', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Chia mì mực sốt cà chua ra 4 đĩa sâu lòng, rưới phần sốt mực còn lại lên trên mặt mì. Rắc nốt phần ngò tây tươi, hẹ lá tươi và 1 g tiêu đen xay còn lại rồi dọn thưởng thức ngay khi còn nóng hổi.', NULL, NULL),
('imp-ebc8bf739393ac91_v4_step_1', 'imp-ebc8bf739393ac91', 1, 'prep', 'Sơ chế tôm tươi, đậu phụ và cà chua', 'Bóc vỏ, bỏ đầu và rút sạch chỉ đen lưng 250 g tôm tươi, rửa sạch để ráo rồi cắt làm đôi theo chiều ngang (hoặc giã dập nhẹ 1/3 lượng tôm để nước ngọt hơn). Ướp tôm với 5 ml nước mắm, 2 g hạt nêm, 0,5 g tiêu đen xay và đầu hành lá băm nhỏ trong 10 phút. Cắt khối vuông 2 cm 2 bìa đậu phụ trắng; bổ múi cau 2 quả cà chua và băm nhỏ 1 quả.', NULL, 10),
('imp-ebc8bf739393ac91_v4_step_2', 'imp-ebc8bf739393ac91', 2, 'prep', 'Chuẩn bị gừng, hành lá và ngò rí', 'Cạo vỏ 10 g gừng tươi rồi thái sợi thật mảnh. Rửa sạch phần lá xanh hành lá và 10 g ngò rí, để ráo rồi thái khúc ngắn 1,5 cm.', NULL, NULL),
('imp-ebc8bf739393ac91_v4_step_3', 'imp-ebc8bf739393ac91', 3, 'cook', 'Phi thơm gừng hành và xào cà chua tạo màu', 'Làm nóng nồi trên lửa vừa với 15 ml dầu ăn, cho gừng thái sợi vào đảo 20 giây cho thơm rồi trút phần cà chua băm nhỏ cùng 1 g muối ăn vào xào đều 3 phút đến khi cà chua nhuyễn mềm ra màu đỏ cam đẹp.', 'Xào cà chua với chút muối trước khi cho tôm vào giúp tạo nền màu óng đẹp và giảm độ chua gắt của cà chua sống.', 3),
('imp-ebc8bf739393ac91_v4_step_4', 'imp-ebc8bf739393ac91', 4, 'cook', 'Xào săn tôm tươi và nấu sôi nước canh', 'Cho tôm đã ướp vào nồi đảo nhanh 1–2 phút đến khi tôm chuyển màu đỏ cam săn lại, sau đó đổ 1300 ml nước lọc vào đun lửa lớn đến khi sôi bùng rồi dùng vá hớt sạch bọt nổi để nước canh trong.', NULL, 3),
('imp-ebc8bf739393ac91_v4_step_5', 'imp-ebc8bf739393ac91', 5, 'cook', 'Thả đậu phụ và nêm gia vị thanh ngọt', 'Hạ xuống lửa vừa để nước sôi lăn tăn, trượt nhẹ 2 bìa đậu phụ cắt khối cùng 2 quả cà chua bổ múi cau vào nồi nấu khoảng 4 phút cho đậu phụ nóng mềm thấm vị và tôm chín chắc hoàn toàn. Nêm 15 ml nước mắm ngon, 3 g hạt nêm và 3 g muối ăn còn lại cho vừa khẩu vị.', 'Không khuấy mạnh sau khi đã thả đậu phụ vào nồi để các khối đậu trắng giữ nguyên hình dáng vuông đẹp.', 4),
('imp-ebc8bf739393ac91_v4_step_6', 'imp-ebc8bf739393ac91', 6, 'finish', 'Thêm hành ngò và tiêu xay hoàn thiện', 'Khi cà chua múi cau vừa mềm chín tới, tắt bếp và thả hành lá, ngò rí thái khúc vào lắc nhẹ nồi. Múc canh ra tô lớn, rắc 0,5 g tiêu đen xay lên trên rồi thưởng thức nóng cùng cơm trắng.', 'Thả hành ngò ngay lúc vừa tắt bếp sẽ giữ được màu xanh mướt và mùi thơm tươi mới cho bát canh.', NULL),
('imp-3446b3924b05eb7b_v4_step_1', 'imp-3446b3924b05eb7b', 1, 'prep', 'Thái lát mỏng và ướp thịt bò thăn', 'Thấm khô 300 g thịt bò thăn, thái lát mỏng ngang thớ để khi nấu thịt mềm dễ ăn. Ướp bò với 1/2 lượng tỏi khô băm, đầu hành lá băm nhỏ, 2 g hạt nêm, 2 g muối ăn, 1 g tiêu đen xay và 5 ml dầu ăn trong 15 phút.', 'Thái thịt bò ngang thớ thật mỏng và ướp thêm 1 muỗng cà phê dầu ăn sẽ giữ từng lát thịt mềm ngọt sau khi trụng nước sôi.', 15),
('imp-3446b3924b05eb7b_v4_step_2', 'imp-3446b3924b05eb7b', 2, 'prep', 'Sơ chế cà rốt, bắp cải và hành lá', 'Gọt vỏ 1 củ cà rốt, rửa sạch rồi thái khoanh tròn dày 0,4 cm cho nhanh chín. Tách lá 1/2 bắp cải trắng, rửa sạch và cắt miếng vuông 4 cm. Rửa sạch phần lá xanh hành lá rồi cắt khúc dài 2 cm.', NULL, NULL),
('imp-3446b3924b05eb7b_v4_step_3', 'imp-3446b3924b05eb7b', 3, 'cook', 'Phi thơm tỏi và xào tái thịt bò', 'Làm nóng nồi trên lửa lớn vừa với 10 ml dầu ăn còn lại, phi thơm phần tỏi băm còn lại trong 30 giây. Cho thịt bò đã ướp vào đảo nhanh 1 phút đến khi thịt săn nhẹ và vừa chuyển tái thì trút ngay ra đĩa riêng.', NULL, 1),
('imp-3446b3924b05eb7b_v4_step_4', 'imp-3446b3924b05eb7b', 4, 'cook', 'Nấu chín cà rốt và bắp cải lấy nước ngọt', 'Đổ 1400 ml nước lọc vào nồi vừa xào thịt, bật lửa lớn đun sôi bùng rồi hớt bọt. Thả cà rốt thái khoanh vào nấu 5 phút trên lửa vừa, tiếp theo cho toàn bộ bắp cải vào nấu thêm 5 phút đến khi cả hai loại rau củ chín mềm ngọt.', 'Cho cà rốt vào nấu trước bắp cải 5 phút để hai loại rau củ chín đồng đều cùng lúc mà bắp cải không bị nhũn nát.', 10),
('imp-3446b3924b05eb7b_v4_step_5', 'imp-3446b3924b05eb7b', 5, 'cook', 'Nêm gia vị và làm chín thịt bò', 'Nêm 18 ml nước mắm ngon, 3 g hạt nêm, 4 g muối ăn và 3 g đường cát trắng vào nồi canh, khuấy nhẹ cho tan đều. Đổ đĩa thịt bò xào tái cùng nước tiết vào nồi, đun sôi bùng lại khoảng 30 giây đến khi thịt bò chín tới hoàn toàn rồi tắt bếp ngay.', 'Không đun sôi lâu sau khi thả thịt bò trở lại vì nhiệt kéo dài sẽ làm thịt bò bị dai xác.', NULL),
('imp-3446b3924b05eb7b_v4_step_6', 'imp-3446b3924b05eb7b', 6, 'finish', 'Rắc hành lá, tiêu xay và hoàn thiện', 'Thả hành lá cắt khúc vào nồi đảo nhẹ một lượt, múc canh ra tô lớn và rắc 0,5 g tiêu đen xay lên trên trước khi dùng nóng với cơm trắng.', NULL, NULL),
('imp-6e3eb737c7d88a2c_v4_step_1', 'imp-6e3eb737c7d88a2c', 1, 'prep', 'Làm sạch gà và luộc bóc vỏ trứng gà', 'Chà xát 750 g đùi gà với 4 g muối hạt và 15 g gừng đập dập để khử mùi tanh, rửa lại nước lạnh rồi để ráo, chặt miếng vừa ăn. Luộc 8 quả trứng gà trong nồi nước sôi 7 phút cho vừa chín tới, vớt ra ngâm nước lạnh 3 phút rồi bóc sạch vỏ.', 'Dùng muối kết hợp gừng đập dập chà xát da gà là cách làm sạch mùi hôi hiệu quả nhất trước khi chặt miếng.', 7),
('imp-6e3eb737c7d88a2c_v4_step_2', 'imp-6e3eb737c7d88a2c', 2, 'marinate', 'Giã gia vị thơm và ướp thịt gà', 'Cho hành tím, tỏi khô, đầu hành lá và 1 quả ớt sừng đỏ vào cối giã thật nhuyễn. Trộn hỗn hợp này với 35 ml nước mắm ngon, 10 g đường cát trắng, 4 g hạt nêm và 1 g tiêu đen xay rồi xoa đều lên thịt gà, ướp 30 phút cho ngấm sâu.', NULL, 30),
('imp-6e3eb737c7d88a2c_v4_step_3', 'imp-6e3eb737c7d88a2c', 3, 'sauce', 'Thắng nước màu cánh gián và xào săn gà', 'Làm nóng nồi đáy dày với 15 ml dầu ăn và 15 g đường cát trắng còn lại trên lửa nhỏ đến khi đường tan và chuyển màu nâu cánh gián. Tắt bếp tạm 5 giây rồi bật lại lửa lớn, cho toàn bộ thịt gà đã ướp vào đảo săn 5 phút đến khi thịt đổi màu vàng nâu đẹp mắt.', 'Xào săn gà trên lửa lớn ngay trong nồi nước màu giúp miếng gà áo đều màu nâu cánh gián bóng đẹp từ bên ngoài.', 5),
('imp-6e3eb737c7d88a2c_v4_step_4', 'imp-6e3eb737c7d88a2c', 4, 'cook', 'Đổ nước ngập gà và thả trứng vào kho', 'Rót 450 ml nước lọc vào nồi xâm xấp mặt thịt gà, đun sôi bùng và hớt sạch bọt nổi để nước kho được trong. Nhẹ nhàng thả 8 quả trứng gà đã bóc vỏ vào nồi rồi hạ lửa nhỏ.', NULL, NULL),
('imp-6e3eb737c7d88a2c_v4_step_5', 'imp-6e3eb737c7d88a2c', 5, 'cook', 'Kho nhỏ lửa cho gà mềm và trứng thấm màu', 'Đậy hé vung và kho liu riu trong 25 phút, cứ mỗi 10 phút đảo nhẹ tay một lần để thịt gà chín mềm đều, nước kho rút sánh nhẹ và trứng lên màu nâu đậm vị.', 'Đảo nhẹ tay hoặc múc nước kho rưới lên mặt trứng tránh làm rách lòng trắng trứng gà.', 25),
('imp-6e3eb737c7d88a2c_v4_step_6', 'imp-6e3eb737c7d88a2c', 6, 'finish', 'Nêm lại, rắc hành lá và tiêu thưởng thức', 'Mở nắp nêm nếm lại độ mặn ngọt vừa miệng rồi tắt bếp. Múc gà kho trứng ra tô sâu lòng, rắc phần lá hành thái nhỏ và 1 g tiêu đen xay còn lại lên trên rồi ăn nóng với cơm trắng.', NULL, NULL),
('imp-6251f57b97918111_v4_step_1', 'imp-6251f57b97918111', 1, 'prep', 'Làm sạch tôm tươi và băm nhuyễn hành tỏi', 'Rửa sạch 500 g tôm tươi, cắt bỏ râu và chân, dùng tăm rút sạch chỉ đen dọc sống lưng (nếu dùng tôm càng có thể tách riêng phần gạch đầu tôm để chưng riêng) rồi để thật ráo nước. Hành tím và tỏi khô băm nhuyễn chia làm hai phần; hành lá rửa sạch thái nhỏ.', 'Để tôm thật ráo nước sau khi rửa giúp phần nước sốt bám chặt vào vỏ tôm khi đảo trên lửa lớn.', NULL),
('imp-6251f57b97918111_v4_step_2', 'imp-6251f57b97918111', 2, 'sauce', 'Pha nước sốt nước tương và ướp tôm', 'Trong chén riêng, khuấy tan 25 ml nước tương, 20 ml dầu hào, 10 g đường cát trắng và 20 ml rượu nấu ăn. Trộn tôm trong tô với một nửa phần hành tím tỏi băm, 15 ml nước mắm ngon, nửa lượng tiêu đen xay và hỗn hợp nước sốt vừa pha, ướp 15 phút cho thấm vị.', NULL, 15),
('imp-6251f57b97918111_v4_step_3', 'imp-6251f57b97918111', 3, 'cook', 'Phi thơm hành tỏi với dầu ăn và dầu màu điều', 'Làm nóng nồi đất hoặc chảo với 20 ml dầu ăn và 10 ml dầu màu điều trên lửa vừa, cho phần hành tím và tỏi băm còn lại vào phi thơm khoảng 1 phút cho dậy mùi và lên màu đỏ cam đẹp mắt.', 'Nếu dùng tôm càng có gạch, có thể xào nhanh phần gạch tôm với chút hành tỏi phi trước rồi múc riêng ra chén để rưới lên mặt khi hoàn thành.', NULL),
('imp-6251f57b97918111_v4_step_4', 'imp-6251f57b97918111', 4, 'cook', 'Đảo săn tôm trên lửa vừa lớn', 'Trút toàn bộ tôm cùng phần nước ướp vào nồi, tăng lên lửa vừa lớn và đảo đều tay trong 3 phút cho đến khi vỏ tôm chuyển màu đỏ cam rực rỡ và thân tôm săn cong lại.', NULL, 3),
('imp-6251f57b97918111_v4_step_5', 'imp-6251f57b97918111', 5, 'cook', 'Kho liu riu cho tôm thấm đẫm sốt sánh', 'Rót 40 ml nước lọc vào nồi, hạ lửa nhỏ kho mở nắp liu riu trong 6–7 phút, lật nhẹ hai mặt tôm cho chín đều hoàn toàn và nước sốt rút sánh bóng ôm quanh từng con tôm.', 'Chừa lại một lượng nước sốt sánh sệt vừa đủ dưới đáy nồi để chan cùng cơm nóng sẽ rất đậm vị.', 7),
('imp-6251f57b97918111_v4_step_6', 'imp-6251f57b97918111', 6, 'finish', 'Rắc hành lá, tiêu đen và thưởng thức', 'Nêm nếm lại vừa khẩu vị rồi tắt bếp. Gắp tôm kho nước tương ra đĩa, rưới phần sốt sánh cùng hành lá thái nhỏ và nửa lượng tiêu đen xay còn lại lên trên rồi dọn ăn nóng.', NULL, NULL),
('imp-977a3409383d743f_v4_step_1', 'imp-977a3409383d743f', 1, 'prep', 'Làm sạch khử tanh mực bằng giấm gạo', 'Cắt bỏ mắt, răng, túi mực, nội tạng và rút thanh nang trắng bên trong thân mực ống. Rửa mực qua nước pha 2 g muối ăn, sau đó ngâm 5 phút trong thau nước lạnh có pha 15 ml giấm gạo để khử sạch mùi tanh, xả lại thật sạch dưới vòi nước rồi thái khoanh tròn vừa ăn và để ráo.', 'Ngâm nhanh mực với nước pha giấm gạo giúp khử tanh hiệu quả mà thịt mực vẫn giữ được độ trắng giòn.', 5),
('imp-977a3409383d743f_v4_step_2', 'imp-977a3409383d743f', 2, 'marinate', 'Ướp mực và sơ chế bông cải xanh', 'Ướp mực đã ráo nước với 20 g hành tím khô thái lát mỏng, 4 g muối ăn, 8 g đường cát trắng, 5 g hạt nêm và 1 g tiêu đen xay trong 15 phút. Trong lúc chờ, tách bông cải xanh thành từng nhánh vừa ăn, rửa sạch; băm nhỏ 10 g hành tím còn lại cùng tỏi khô; cắt khúc hành lá.', NULL, 15),
('imp-977a3409383d743f_v4_step_3', 'imp-977a3409383d743f', 3, 'prep', 'Chần sơ bông cải xanh giữ màu tươi', 'Đun sôi nồi nước với 2 g muối ăn còn lại, thả bông cải xanh vào chần nhanh trong khoảng 1 phút cho vừa chuyển sắc xanh mướt rồi vớt ra rổ để thật ráo nước.', 'Chỉ chần bông cải xanh đúng 1 phút để bông cải giữ độ giòn sần sật khi xào chung với mực.', NULL),
('imp-977a3409383d743f_v4_step_4', 'imp-977a3409383d743f', 4, 'cook', 'Phi thơm hành tỏi và xào nóng bông cải', 'Làm nóng 25 ml dầu ăn trong chảo rộng trên lửa vừa, phi thơm hành tím băm và tỏi băm. Trút bông cải xanh đã ráo vào đảo đều khoảng 1,5 phút cho thấm dầu tỏi thơm.', NULL, NULL),
('imp-977a3409383d743f_v4_step_5', 'imp-977a3409383d743f', 5, 'cook', 'Xào lửa lớn cho mực săn giòn quyện xì dầu', 'Tăng lên lửa lớn nhất, trút toàn bộ mực đã ướp vào chảo bông cải xanh và đảo nhanh tay liên tục khoảng 3 phút cho đến khi khoanh mực săn chắc, chuyển màu trắng đục viền hồng và chín hoàn toàn. Rưới 15 ml nước tương (xì dầu) vào đảo đều thêm 30 giây, nêm nếm lại cho vừa miệng.', 'Giữ lửa lớn khi cho mực vào giúp mực chín nhanh, giữ độ giòn ngọt mà không bị ra nhiều nước.', 3),
('imp-977a3409383d743f_v4_step_6', 'imp-977a3409383d743f', 6, 'finish', 'Hoàn thiện với hành lá, ớt bột và tiêu', 'Thả hành lá cắt khúc và 1,5 g ớt bột (nếu thích cay) vào đảo nhanh 15 giây rồi tắt bếp. Bày mực xào bông cải xanh ra đĩa, rắc 1 g tiêu đen xay còn lại lên trên và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-a4ff266c02427746_v4_step_1', 'imp-a4ff266c02427746', 1, 'prep', 'Sơ chế bông cải xanh và băm nhuyễn tỏi', 'Tách bông cải xanh thành các nhánh nhỏ vừa ăn, gọt bỏ lớp vỏ xơ ở phần cuống rồi ngâm nước muối loãng 5 phút và rửa sạch 2–3 lần nước, để ráo. Tỏi khô bóc vỏ, đập dập và băm nhuyễn.', 'Cắt các nhánh bông cải xanh đều kích thước để khi chần và xào chín đồng đều cùng lúc.', NULL),
('imp-a4ff266c02427746_v4_step_2', 'imp-a4ff266c02427746', 2, 'prep', 'Chần bông cải xanh và ngâm nước đá lạnh', 'Đun sôi nồi nước trên lửa lớn với 6 g muối ăn, thả bông cải xanh vào chần khoảng 1,5–2 phút cho đến khi bông cải vừa chuyển màu xanh ngọc tươi thì vớt ngay ra ngâm vào tô nước đá lạnh 3 phút, sau đó vớt ra rổ để thật ráo nước.', 'Sốc nhiệt bằng nước đá lạnh sau khi chần giữ bông cải giòn sần sật và không bị ngả vàng.', 3),
('imp-a4ff266c02427746_v4_step_3', 'imp-a4ff266c02427746', 3, 'cook', 'Phi thơm vàng tỏi băm', 'Làm nóng 30 ml dầu ăn trong chảo trên lửa vừa, cho toàn bộ tỏi băm vào phi đều tay khoảng 30–40 giây đến khi tỏi chuyển vàng nhẹ và tỏa mùi thơm nức.', 'Đảo liên tục khi phi tỏi để tỏi vàng đều mà không bị cháy đắng.', NULL),
('imp-a4ff266c02427746_v4_step_4', 'imp-a4ff266c02427746', 4, 'cook', 'Xào bông cải xanh thấm dầu tỏi', 'Tăng lên lửa lớn, trút bông cải xanh đã để ráo vào chảo dầu tỏi và đảo đều tay khoảng 1 phút cho các nhánh bông cải áo lớp dầu bóng mịn.', NULL, NULL),
('imp-a4ff266c02427746_v4_step_5', 'imp-a4ff266c02427746', 5, 'cook', 'Nêm gia vị và đảo nhanh cho thấm đều', 'Rắc 8 g hạt nêm, 2 g muối ăn còn lại, 2 g bột ngọt, rưới 8 ml nước tương (xì dầu) và 60 ml nước lọc vào chảo. Tiếp tục đảo đều trên lửa lớn khoảng 1,5–2 phút cho nước gia vị cạn bám đều quanh bông cải xanh mà rau vẫn giòn ngọt.', NULL, 2),
('imp-a4ff266c02427746_v4_step_6', 'imp-a4ff266c02427746', 6, 'finish', 'Nêm lại và dọn nóng', 'Nêm nếm lại cho vừa khẩu vị rồi tắt bếp ngay. Gắp bông cải xanh xào tỏi ra đĩa phẳng, thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-f9f08651bc712e93_v4_step_1', 'imp-f9f08651bc712e93', 1, 'prep', 'Làm sạch khử nhớt cá và lọc mịn cơm mẻ', 'Chà xát phi lê cá lăng với 3 g muối ăn, gừng tươi đập dập và 1/2 quả chanh tươi trong 2 phút cho hết nhớt tanh rồi rửa lại nước lạnh, thấm thật khô và cắt miếng vuông dày khoảng 1,5–2 cm. Cho 40 g cơm mẻ qua rây miết lấy phần nước mịn, bỏ bã.', 'Rửa cá lăng với muối, gừng và chanh giúp loại bỏ hoàn toàn chất nhớt và mùi tanh đặc trưng của cá da trơn.', NULL),
('imp-f9f08651bc712e93_v4_step_2', 'imp-f9f08651bc712e93', 2, 'marinate', 'Ướp cá thấm gia vị riềng mẻ nghệ mắm tôm', 'Trộn đều cá với riềng giã nhuyễn, nước mẻ lọc mịn, 5 g bột nghệ, 10 g mắm tôm, 12 g đường cát trắng, 10 ml nước mắm ngon, 2 g muối ăn, 2 g tiêu đen xay, tỏi băm, hành tím băm và 15 ml dầu ăn. Bọc kín đặt ngăn mát tủ lạnh ướp ít nhất 30 phút cho thịt cá săn và thấm vàng đều.', 'Lọc bỏ bã mẻ và bã riềng thô giúp miếng chả cá khi áp chảo không bị cháy đen bề mặt.', 30),
('imp-f9f08651bc712e93_v4_step_3', 'imp-f9f08651bc712e93', 3, 'prep', 'Sơ chế thì là, hành lá, lạc rang và bún tươi', 'Trong lúc chờ ướp cá, rửa sạch thì là và hành lá để thật ráo nước; phần củ hành trắng chẻ đôi, phần lá xanh và thì là cắt khúc 4 cm. Nhặt rửa rau húng láng để ráo; giã dập đậu phộng rang; chuẩn bị sẵn 400 g bún tươi và ớt tươi thái lát.', NULL, NULL),
('imp-f9f08651bc712e93_v4_step_4', 'imp-f9f08651bc712e93', 4, 'cook', 'Áp chảo cá vàng ươm hai mặt trên lửa vừa', 'Làm nóng 20 ml dầu ăn trong chảo chống dính hoặc chảo gang trên lửa vừa, xếp từng miếng cá đã ướp (gạt bớt xác riềng bám ngoài) vào áp chảo khoảng 4 phút mỗi mặt đến khi hai mặt vàng nghệ xém cạnh và thịt cá chín trắng đục hoàn toàn, gắp nhẹ ra đĩa.', 'Không lật cá liên tục trong 3 phút đầu để bề mặt cá se vàng đẹp và không bị vỡ nát.', 8),
('imp-f9f08651bc712e93_v4_step_5', 'imp-f9f08651bc712e93', 5, 'sauce', 'Pha mắm tôm đánh bông sủi bọt', 'Cho 25 g mắm tôm còn lại, 6 g đường cát trắng, 1 g bột ngọt (nếu dùng) và nước cốt của 1/2 quả chanh tươi vào chén nhỏ, dùng đũa đánh mạnh liên tục 1 phút đến khi mắm tôm chuyển màu tím nhạt sủi bọt bông mịn rồi thêm vài lát ớt tươi.', 'Đánh mắm tôm cùng nước cốt chanh và đường thật đều tay đến khi nổi bọt trắng mịn sẽ giúp dậy hương thơm đặc trưng và dịu vị.', NULL),
('imp-f9f08651bc712e93_v4_step_6', 'imp-f9f08651bc712e93', 6, 'finish', 'Đảo nóng cá cùng hành lá, thì là và dọn ăn', 'Thêm 10 ml dầu ăn vào chảo nóng, thả phần đầu hành trắng vào đảo nhanh 30 giây rồi cho cá đã áp chảo, hành lá xanh và thì là vào đảo nhẹ tay khoảng 1 phút cho rau vừa chín tới còn xanh mướt thì tắt bếp. Rắc đậu phộng rang giã dập lên mặt và ăn nóng ngay cùng bún tươi, húng láng và mắm tôm.', NULL, 2),
('imp-0d6c454ae1073ef6_v4_step_1', 'imp-0d6c454ae1073ef6', 1, 'prep', 'Gọt vỏ khử nhựa và cắt miếng su su non', 'Ngâm 3 quả su su non vào thau nước sạch hoặc đeo găng tay khi gọt bỏ lớp vỏ ngoài để tránh nhựa dính tay. Bổ đôi từng quả theo chiều dọc, khoét bỏ phần hạt trắng mềm ở giữa, rửa sạch lại rồi thái thành những miếng dài cỡ ngón tay út cho nhanh chín đều.', 'Gọt vỏ su su trực tiếp dưới chậu nước mát giúp nhựa mủ trôi sạch ngay, tay không bị rít mà miếng su su vẫn trắng xanh đẹp mắt.', NULL),
('imp-0d6c454ae1073ef6_v4_step_2', 'imp-0d6c454ae1073ef6', 2, 'prep', 'Sơ chế tỏi băm và hành lá thái nhỏ', 'Bóc vỏ 1 củ tỏi khô, đập dập rồi băm vừa (không băm quá nát để tỏi phi giòn thơm). Rửa sạch hành lá tươi, để ráo rồi thái nhỏ để sẵn sàng hoàn thiện món ăn.', NULL, NULL),
('imp-0d6c454ae1073ef6_v4_step_3', 'imp-0d6c454ae1073ef6', 3, 'cook', 'Hấp su su vừa chín tới giữ độ giòn ngọt', 'Đun sôi 500 ml nước lọc trong nồi hấp ở lửa lớn. Trộn nhẹ su su với 2 g muối ăn rồi xếp đều vào xửng hấp không chồng quá dày, đậy kín nắp và hấp trong 10 phút đến khi dùng đũa xiên nhẹ thấy miếng su su vừa chín mềm trong nhẹ nhưng vẫn giữ độ giòn.', 'Chỉ hấp su su khoảng 10 phút tính từ lúc nước sôi để miếng rau giữ màu xanh ngọc tươi và độ ngọt giòn, tránh hấp nhừ.', 10),
('imp-0d6c454ae1073ef6_v4_step_4', 'imp-0d6c454ae1073ef6', 4, 'sauce', 'Phi tỏi vàng thơm và pha sốt mắm rưới', 'Trong lúc chờ hấp su su, làm nóng 20 ml dầu ăn trên chảo nhỏ ở lửa vừa, cho tỏi băm vào phi khoảng 2 phút đến khi vàng thơm thì tắt bếp. Rót vào chảo dầu tỏi đang ấm 15 ml nước mắm ngon, 15 ml xì dầu và 5 g đường cát trắng, khuấy đều cho đường tan hoàn toàn.', 'Tắt bếp ngay khi tỏi vừa ngả vàng sáng rồi mới rót nước mắm đường vào để tránh bắn dầu và giữ hương tỏi thơm nồng.', 2),
('imp-0d6c454ae1073ef6_v4_step_5', 'imp-0d6c454ae1073ef6', 5, 'cook', 'Rắc hành lá giữ màu xanh mướt trên xửng', 'Gắp su su chín ra đĩa sâu lòng, rắc đều hành lá thái nhỏ lên trên mặt su su khi còn đang bốc hơi nóng để hành dịu bớt vị hăng nhưng vẫn giữ sắc xanh tươi.', NULL, NULL),
('imp-0d6c454ae1073ef6_v4_step_6', 'imp-0d6c454ae1073ef6', 6, 'finish', 'Rưới nước mắm dầu tỏi và dọn ăn nóng', 'Rưới đều toàn bộ phần nước mắm dầu tỏi phi vàng lên khắp các miếng su su và hành lá, đảo nhẹ cho sốt áo đều rồi dọn thưởng thức nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-4d81607829384874_v4_step_1', 'imp-4d81607829384874', 1, 'prep', 'Làm sạch khử mùi và khứa đùi gà', 'Làm sạch lông tơ trên 4 chiếc đùi gà, dùng 4 g muối hạt và 15 g gừng đập dập chà xát khắp mặt da và thịt trong 2 phút để khử mùi hôi, sau đó xả sạch lại với nước mát và thấm khô. Dùng dao sắc khứa 2–3 đường chéo trên phần thịt dày để gà thấm gia vị và chín nhanh hơn.', NULL, NULL),
('imp-4d81607829384874_v4_step_2', 'imp-4d81607829384874', 2, 'marinate', 'Sơ chế gừng hành và ướp đùi gà thấm vị', 'Thái sợi chỉ 45 g gừng còn lại; hành tím thái lát mỏng; hành lá cắt khúc dài 5 cm; ớt tươi thái sợi. Trộn ướp đùi gà với 4 g muối hạt, 5 g hạt nêm, 1 g tiêu đen xay, 15 ml xì dầu (nếu dùng) và 25 g gừng thái sợi, xoa kỹ vào các đường khứa rồi ướp 20 phút.', 'Xoa gia vị vào sâu bên trong các đường khứa giúp phần thịt sát xương đậm đà mà không cần ướp quá mặn bên ngoài.', 20),
('imp-4d81607829384874_v4_step_3', 'imp-4d81607829384874', 3, 'cook', 'Xếp đĩa hấp gà cách thủy lửa vừa', 'Trải một nửa lượng hành lá cắt khúc, hành tím thái lát và ít gừng sợi xuống đáy đĩa sâu lòng chịu nhiệt, đặt đùi gà đã ướp lên trên. Đun sôi 700 ml nước lọc trong nồi hấp, cho đĩa gà vào xửng, đậy kín vung và hấp trên lửa vừa trong 22 phút.', 'Lót hành lá và hành tím dưới đáy đĩa giúp ngăn da gà dính vào đĩa và tạo hơi thơm ngấm ngược vào thịt.', 22),
('imp-4d81607829384874_v4_step_4', 'imp-4d81607829384874', 4, 'cook', 'Thêm hành lá, gừng sợi hấp chín tới', 'Mở nắp xửng, rải phần hành lá cắt khúc và 20 g gừng thái sợi còn lại phủ lên mặt đùi gà rồi đậy nắp hấp tiếp thêm 5 phút. Dùng tăm xiên vào phần thịt dày nhất gần khớp xương thấy nước tiết ra trong suốt không còn màu hồng là gà đã chín hoàn toàn.', 'Thêm hành lá và lớp gừng sợi mới vào 5 phút cuối giúp rau giữ được sắc xanh tươi và hương thơm cay ấm nổi bật khi dọn.', 5),
('imp-4d81607829384874_v4_step_5', 'imp-4d81607829384874', 5, 'sauce', 'Pha chén muối tiêu chanh chấm gà', 'Trộn 4 g muối hạt còn lại với 1 g tiêu đen xay trong chén nhỏ, vắt nước cốt 1 quả chanh tươi vào khuấy nhẹ cho muối tan bớt.', NULL, NULL),
('imp-4d81607829384874_v4_step_6', 'imp-4d81607829384874', 6, 'finish', 'Rưới dầu mè và trình bày đĩa gà hấp nóng', 'Nhấc đĩa gà ra khỏi xửng, rưới 5 ml dầu mè thơm đều lên mặt da gà và rắc ớt tươi thái sợi trang trí; chặt miếng vừa ăn hoặc để nguyên đùi dọn nóng cùng chén muối tiêu chanh.', NULL, NULL),
('imp-1b518ba2f068f3ab_v4_step_1', 'imp-1b518ba2f068f3ab', 1, 'prep', 'Gọt thái dứa chín và ngâm đá giòn cà rốt', 'Gọt sạch vỏ và mắt quả dứa chín vàng, rửa sơ để ráo rồi thái miếng dày khoảng 0,5 cm, dài 3–4 cm vừa gắp. Cà rốt gọt vỏ bào sợi mảnh, ngâm vào tô nước đá lạnh trong 10 phút cho sợi giòn cứng rồi vớt ra để thật ráo nước.', 'Chọn quả dứa chín vàng đều, mùi thơm ngọt dịu để nộm đậm hương vị tự nhiên mà không bị gắt chua.', 10),
('imp-1b518ba2f068f3ab_v4_step_2', 'imp-1b518ba2f068f3ab', 2, 'cook', 'Rang giã đậu phộng và sơ chế rau gia vị', 'Cho đậu phộng vào chảo rang trên lửa nhỏ khoảng 8 phút đến khi chín vàng thơm đều, để nguội xát sạch vỏ lụa và giã dập vừa giữ độ giòn bùi. Rửa sạch hành lá cắt khúc 3 cm; băm thật nhuyễn tỏi khô và 1 quả ớt hiểm, quả ớt còn lại thái vát mỏng.', NULL, 8),
('imp-1b518ba2f068f3ab_v4_step_3', 'imp-1b518ba2f068f3ab', 3, 'sauce', 'Pha nước trộn nộm chua cay hài hòa', 'Hòa tan 35 ml nước mắm ngon, 25 g đường cát trắng, 22 ml giấm gạo và 60 ml nước lọc trong chén đến khi đường tan hết. Thêm nước cốt 2 quả chanh tươi, tỏi băm và ớt hiểm băm vào khuấy đều, nêm thêm 2 g muối ăn nếu thích đậm vị hơn.', 'Cho tỏi ớt vào sau khi đường đã tan hết giúp hương thơm dậy đều và màu sắc bát nước trộn bắt mắt.', NULL),
('imp-1b518ba2f068f3ab_v4_step_4', 'imp-1b518ba2f068f3ab', 4, 'prep', 'Trộn thấm dứa và cà rốt lượt đầu', 'Cho dứa thái lát và cà rốt bào sợi đã ráo nước vào âu lớn. Rưới 2/3 lượng nước trộn nộm vào, đảo nhẹ nhàng cho miếng dứa không bị dập nát rồi để yên khoảng 8 phút cho ngấm vị.', NULL, 8),
('imp-1b518ba2f068f3ab_v4_step_5', 'imp-1b518ba2f068f3ab', 5, 'prep', 'Trộn hành lá và điều chỉnh vị cuối', 'Cho hành lá cắt khúc vào âu nộm cùng 1/3 lượng nước trộn còn lại, đảo đều nhẹ tay thêm một lượt để hành lá giữ nguyên màu xanh tươi và độ giòn.', NULL, NULL),
('imp-1b518ba2f068f3ab_v4_step_6', 'imp-1b518ba2f068f3ab', 6, 'finish', 'Bày đĩa, rắc đậu phộng và thưởng thức mát', 'Gắp nộm dứa ra đĩa sâu lòng, rắc toàn bộ đậu phộng rang giã dập và vài lát ớt hiểm lên trên mặt. Dọn thưởng thức ngay khi nộm còn tươi giòn và mát lành.', 'Chỉ rắc đậu phộng rang ngay trước khi ăn để hạt đậu giữ được độ giòn bùi, không bị ỉu do hút ẩm.', NULL),
('imp-0f336e8735d9ce75_v4_step_1', 'imp-0f336e8735d9ce75', 1, 'cook', 'Làm sạch và trụng mực ống vừa chín tới', 'Làm sạch túi mực, nang và mắt mực ống, rửa kỹ với nước pha 1 g muối ăn rồi xả sạch. Đun sôi 680 ml nước lọc trên lửa lớn cùng 1 g muối ăn, thả mực vào trụng nhanh khoảng 3 phút đến khi thịt mực săn trắng đục chín hoàn toàn thì vớt ngay ra ngâm nước nguội cho giòn rồi để ráo, thái khoanh dày 1 cm.', 'Trụng nhanh mực trong nước sôi rồi làm nguội ngay giúp khoanh mực giòn sần sật, không bị dai cứng.', 3),
('imp-0f336e8735d9ce75_v4_step_2', 'imp-0f336e8735d9ce75', 2, 'prep', 'Ướp muối và vắt thật ráo dưa leo, cà rốt', 'Bổ đôi dưa leo, nạo bỏ hết phần ruột hạt rồi thái lát mỏng; cà rốt gọt vỏ bào sợi mảnh. Trộn đều dưa leo và cà rốt với 3 g muối ăn trong 10 phút cho ra bớt nước rồi dùng tay hoặc khăn sạch vắt thật ráo.', 'Loại bỏ ruột dưa leo và vắt thật ráo rau củ là bước quyết định giúp món gỏi giòn lâu và không bị lõng bõng nước.', 10),
('imp-0f336e8735d9ce75_v4_step_3', 'imp-0f336e8735d9ce75', 3, 'cook', 'Phi thơm tỏi băm và sơ chế sả, rau thơm', 'Phi thơm tỏi băm với 12 ml dầu ăn trên lửa nhỏ đến khi vừa vàng giòn thì vớt ra giấy thấm dầu. Thái khoanh thật mỏng cây sả; nhặt rửa sạch rau răm, rau húng quế và cần tây rồi cắt nhỏ. Băm nhỏ 1 quả ớt tươi và thái lát quả còn lại.', NULL, NULL),
('imp-0f336e8735d9ce75_v4_step_4', 'imp-0f336e8735d9ce75', 4, 'sauce', 'Pha nước mắm đường trộn gỏi', 'Khuấy tan 25 ml nước mắm ngon với 18 g đường cát trắng và 20 ml nước lọc đến khi đường tan hoàn toàn thành bát nước trộn đậm dịu.', NULL, NULL),
('imp-0f336e8735d9ce75_v4_step_5', 'imp-0f336e8735d9ce75', 5, 'prep', 'Trộn thấm mực, rau củ cùng sả và ớt bột', 'Cho mực thái khoanh, dưa leo, cà rốt đã vắt ráo, sả thái khoanh, 2 g ớt bột khô, ớt băm, rau răm, rau húng quế và cần tây vào thố lớn. Rưới bát nước mắm đường vào đảo đều nhẹ tay cho các nguyên liệu ngấm gia vị.', NULL, NULL),
('imp-0f336e8735d9ce75_v4_step_6', 'imp-0f336e8735d9ce75', 6, 'finish', 'Thêm nước cốt chanh, rắc tỏi phi và thưởng thức', 'Vắt nước cốt 1,5 quả chanh tươi rưới đều lên thố gỏi, trộn nhẹ lần cuối và để thấm 5 phút cho vị chua cay mặn ngọt hài hòa. Bày gỏi ra đĩa, rắc tỏi phi vàng giòn cùng vài lát ớt tươi lên trên và dọn ăn ngay kèm bánh phồng tôm.', 'Cho nước cốt chanh vào bước cuối giúp giữ nguyên hương thơm tươi mát của chanh và độ giòn của dưa leo.', 5),
('imp-f93013fb234d39d0_v4_step_1', 'imp-f93013fb234d39d0', 1, 'prep', 'Sơ chế nấm đùi gà, bắp cải, cà rốt và trụng bún', 'Nấm đùi gà cắt bỏ gốc, rửa nhanh trong nước pha 2 g muối ăn rồi xả sạch, để ráo và thái lát mỏng. Bắp cải rửa sạch, thái sợi; cà rốt gọt vỏ thái sợi mỏng; tỏi khô băm nhỏ; hành lá cắt khúc 3 cm. Đun sôi nồi nước, trụng nhanh 400 g bún gạo tươi khoảng 1 phút rồi vớt ra rổ để thật ráo và trộn nhẹ với 10 ml dầu ăn cho sợi tơi.', 'Trộn nhẹ bún ráo nước với một chút dầu ăn giúp từng sợi bún tơi rời, không dính chảo và không bị nát khi đảo.', 2),
('imp-f93013fb234d39d0_v4_step_2', 'imp-f93013fb234d39d0', 2, 'cook', 'Phi thơm tỏi và xào cà rốt, bắp cải', 'Làm nóng chảo rộng với 20 ml dầu ăn còn lại trên lửa vừa, cho tỏi băm vào phi 30 giây đến khi thơm vàng nhẹ. Bật lửa lớn, cho cà rốt và bắp cải thái sợi vào đảo đều tay 3 phút đến khi rau hơi mềm mà vẫn giữ độ giòn.', NULL, 3),
('imp-f93013fb234d39d0_v4_step_3', 'imp-f93013fb234d39d0', 3, 'cook', 'Xào chín nấm đùi gà cùng rau củ', 'Cho nấm đùi gà thái lát vào chảo rau củ, tiếp tục đảo đều trên lửa lớn trong 3 phút cho nấm chín mềm và tiết nước ngọt tự nhiên hòa vào rau.', 'Xào cà rốt và bắp cải trước rồi mới thêm nấm đùi gà thái lát mỏng giúp cả ba nguyên liệu chín tới đồng đều.', 3),
('imp-f93013fb234d39d0_v4_step_4', 'imp-f93013fb234d39d0', 4, 'sauce', 'Nêm gia vị đậm đà cho hỗn hợp rau nấm', 'Nêm vào chảo 25 ml nước tương, 4 g hạt nêm chay, 3 g muối ăn còn lại và 8 g đường cát trắng, đảo đều tay 1 phút cho đường tan hết và rau nấm thấm đẫm gia vị.', NULL, NULL),
('imp-f93013fb234d39d0_v4_step_5', 'imp-f93013fb234d39d0', 5, 'cook', 'Đảo tơi bún gạo tươi quyện đều rau nấm', 'Hạ xuống lửa vừa, trút bún gạo tươi đã ráo vào chảo, dùng đũa xới đảo nhẹ tay cho sợi bún hòa quyện với rau nấm. Rưới thêm 15 ml nước tương còn lại vào bún và đảo đều thêm 2 phút cho sợi bún thấm màu vàng nâu nhẹ đẹp mắt.', 'Dùng hai chiếc đũa đảo hất nhẹ từ dưới lên thay vì xẻng đè mạnh để sợi bún không bị gãy vụn.', 2),
('imp-f93013fb234d39d0_v4_step_6', 'imp-f93013fb234d39d0', 6, 'finish', 'Thêm hành lá, tiêu xay và dọn bún xào nóng', 'Nêm nếm lại vừa miệng rồi cho hành lá cắt khúc vào đảo nhanh 15 giây, tắt bếp. Gắp bún xào chay ra đĩa, rắc 1 g tiêu đen xay lên trên và thưởng thức nóng kèm chén nước tương ớt.', NULL, NULL),
('imp-6af3e18fdac79061_v4_step_1', 'imp-6af3e18fdac79061', 1, 'cook', 'Luộc chín thịt đùi gà với gừng tươi', 'Chà rửa thịt đùi gà với 4 g muối ăn rồi xả sạch. Cho gà vào nồi cùng 1,2 lít nước lọc, gừng tươi thái lát, 2 g muối ăn và 3 g hạt nêm, đun sôi rồi hạ lửa vừa luộc khoảng 18–20 phút. Xiên đũa vào phần thịt dày nhất thấy không chảy nước hồng là gà chín kỹ.', NULL, 20),
('imp-6af3e18fdac79061_v4_step_2', 'imp-6af3e18fdac79061', 2, 'prep', 'Ngâm lạnh thịt gà và thái lát vừa ăn', 'Vớt thịt đùi gà ra ngâm ngay vào tô nước lọc nguội mát trong 5 phút cho phần da săn giòn và thịt không bị khô thâm, sau đó vớt ráo, lọc xương và thái lát mỏng vừa ăn.', 'Ngâm gà vừa luộc vào nước nguội giúp thịt săn chắc, dễ thái lát đẹp mắt mà không bị nát.', 5),
('imp-6af3e18fdac79061_v4_step_3', 'imp-6af3e18fdac79061', 3, 'cook', 'Chần giá đỗ và miến dong trong nước luộc gà', 'Vớt bỏ lát gừng trong nồi nước luộc gà, đun sôi trở lại rồi thả giá đỗ vào chần nhanh 30 giây và vớt ra ngay cho giữ độ giòn. Tiếp theo thả miến dong khô đã rửa sơ vào nồi nước dùng gà đang sôi chần khoảng 1 phút cho sợi miến chín mềm dai vừa tới, vớt ra xóc thật ráo nước và cắt ngắn nếu cần.', 'Chần miến trực tiếp bằng nước luộc gà đang sôi giúp sợi miến ngọt thơm tự nhiên và không bị nhạt.', 2),
('imp-6af3e18fdac79061_v4_step_4', 'imp-6af3e18fdac79061', 4, 'prep', 'Sơ chế rau thơm và giã dập lạc rang', 'Rửa sạch rau húng bạc hà, ngò gai, rau răm và hành lá rồi vẩy ráo nước và thái nhỏ. Giã dập lạc rang cho vỡ làm đôi, làm ba; băm thật nhuyễn tỏi khô và ớt hiểm tươi.', NULL, NULL),
('imp-6af3e18fdac79061_v4_step_5', 'imp-6af3e18fdac79061', 5, 'sauce', 'Pha nước trộn miến nước tương chua ngọt', 'Cho vào chén 30 ml nước mắm ngon, 25 ml nước tương, 8 g đường cát trắng, 15 ml giấm gạo và vắt thêm nước cốt của 1/2 quả chanh tươi, khuấy tan hoàn toàn đường rồi mới thả tỏi khô và ớt hiểm băm vào.', 'Kết hợp cả nước mắm ngon và nước tương giúp nước trộn có chiều sâu hương vị mà màu miến trộn bóng đẹp hơn.', NULL),
('imp-6af3e18fdac79061_v4_step_6', 'imp-6af3e18fdac79061', 6, 'finish', 'Trộn đều miến gà và thưởng thức ngay', 'Chia miến dong ra 3 tô, xếp giá đỗ chần, thịt đùi gà thái lát, rau húng bạc hà, ngò gai, rau răm và hành lá lên trên. Rưới đều nước trộn đã pha vào tô, trộn đều tay cho sợi miến thấm vị rồi rắc lạc rang giã dập lên trên cùng và thưởng thức ngay.', NULL, NULL),
('imp-2e39be75d8f72249_v4_step_1', 'imp-2e39be75d8f72249', 1, 'prep', 'Sơ chế nấm đùi gà, cà chua và hành tỏi', 'Nấm đùi gà cắt bỏ gốc, rửa nhanh qua nước sạch rồi thấm thật ráo, thái lát xéo dày 0,5 cm. Cà chua chín bỏ cuống, bổ múi cau; tỏi khô băm nhỏ; hành lá rửa sạch, tách riêng đầu hành cắt khúc 2 cm và phần lá xanh thái nhỏ.', 'Thấm thật ráo nước nấm đùi gà trước khi xào giúp lát nấm nhanh xém cạnh và giữ độ dai giòn thay vì bị luộc trong nước nấm.', NULL),
('imp-2e39be75d8f72249_v4_step_2', 'imp-2e39be75d8f72249', 2, 'sauce', 'Pha chén nước sốt nước tương và bột năng', 'Cho vào chén 15 ml nước tương, 8 ml dầu hào chay, 5 g đường cát trắng, 4 g bột năng và 35 ml nước lọc. Khuấy đều tay cho đường và bột năng tan hoàn toàn để sẵn bên cạnh bếp.', 'Pha sẵn bột năng cùng nước tương và đường giúp khi rưới vào chảo sốt sánh đều ngay lập tức mà không bị vón cục.', NULL),
('imp-2e39be75d8f72249_v4_step_3', 'imp-2e39be75d8f72249', 3, 'cook', 'Phi thơm tỏi và xào xém cạnh nấm đùi gà', 'Làm nóng chảo với 25 ml dầu ăn trên lửa vừa, thả tỏi băm vào phi khoảng 40 giây đến khi vàng thơm. Bật lửa lớn, cho nấm đùi gà vào đảo đều 4 phút đến khi lát nấm săn chắc và hơi xém vàng hai mặt.', 'Đợi chảo nóng và xào nấm ở lửa lớn giúp nấm giữ được độ giòn ngọt và màu xém cạnh hấp dẫn.', 4),
('imp-2e39be75d8f72249_v4_step_4', 'imp-2e39be75d8f72249', 4, 'cook', 'Xào mềm cà chua tiết nước sốt đỏ tự nhiên', 'Đưa cà chua bổ múi cau vào chảo nấm, hạ xuống lửa vừa và đảo nhẹ tay trong 3 phút để cà chua chín mềm, tiết ra phần nước đỏ cam hòa quyện quanh nấm mà múi cà vẫn giữ được dáng.', NULL, 3),
('imp-2e39be75d8f72249_v4_step_5', 'imp-2e39be75d8f72249', 5, 'cook', 'Rưới chén sốt làm sánh bóng và nêm vừa vị', 'Khuấy đều lại chén sốt rồi đổ vào chảo, thêm 3 g muối ăn và đảo nhẹ trong 2 phút đến khi sốt sôi nhẹ, sánh bóng bao phủ đều từng lát nấm và múi cà chua.', NULL, 2),
('imp-2e39be75d8f72249_v4_step_6', 'imp-2e39be75d8f72249', 6, 'finish', 'Hoàn thiện với đầu hành và lá hành xanh', 'Thả phần đầu hành lá cắt khúc vào đảo nhanh 30 giây rồi tắt bếp. Múc cà chua xào nấm ra đĩa sâu lòng, rắc phần lá hành xanh thái nhỏ lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-11b65c6b18266849_v4_step_1', 'imp-11b65c6b18266849', 1, 'prep', 'Sơ chế đậu phụ, dứa chín và pha sốt kho', 'Đậu phụ trắng thấm thật khô bằng khăn giấy rồi cắt miếng vuông dày 1,5 cm. Dứa chín gọt sạch vỏ và mắt, cắt lát tam giác dày 0,8 cm. Băm nhỏ tỏi khô và hành tím; hành lá chẻ đầu hành để riêng, lá xanh cắt khúc; ớt sừng thái lát. Khuấy tan trong tô 45 ml nước tương, 15 ml dầu hào chay, 8 g đường cát trắng, 3 g muối ăn và 100 ml nước lọc; hòa riêng 8 g bột năng với 30 ml nước lọc còn lại.', 'Thấm thật khô đậu phụ trước khi rán giúp dầu không bị bắn và lớp vỏ ngoài vàng giòn chắc chắn hơn.', NULL),
('imp-11b65c6b18266849_v4_step_2', 'imp-11b65c6b18266849', 2, 'cook', 'Rán vàng giòn đều các mặt đậu phụ', 'Làm nóng chảo với 40 ml dầu ăn trên lửa vừa đến khi dầu sôi tăm, thả từng miếng đậu phụ vào rán khoảng 7 phút. Lật nhẹ tay cho đến khi các mặt vàng giòn đều thì gắp ra đĩa lót giấy thấm dầu.', 'Chỉ thả đậu vào khi dầu đã nóng già giúp đậu không dính sát đáy chảo và tạo vỏ giòn đều.', 7),
('imp-11b65c6b18266849_v4_step_3', 'imp-11b65c6b18266849', 3, 'cook', 'Phi thơm hành tím, tỏi băm và xào dứa chín', 'Chắt bớt dầu thừa ra khỏi chảo, giữ lại khoảng 15 ml dầu ăn trên lửa vừa rồi cho hành tím băm, tỏi băm và đầu hành trắng vào phi thơm 40 giây. Cho dứa chín thái lát vào đảo đều 4 phút cho dứa hơi mềm và tiết nước chua ngọt thơm lừng.', NULL, 4),
('imp-11b65c6b18266849_v4_step_4', 'imp-11b65c6b18266849', 4, 'cook', 'Kho rim đậu phụ với dứa và nước sốt', 'Xếp nhẹ các miếng đậu phụ đã rán vàng vào chảo dứa, rưới đều tô nước sốt nước tương đã pha vào. Đun sôi nhẹ rồi hạ xuống lửa nhỏ, kho liu riu khoảng 10 phút và nhẹ nhàng trở mặt đậu một lần để đậu thấm đượm vị chua ngọt mặn hài hòa.', 'Kho ở lửa nhỏ và trở nhẹ mặt đậu một lần giúp đậu thấm đều vị chua ngọt mà không bị nát.', 10),
('imp-11b65c6b18266849_v4_step_5', 'imp-11b65c6b18266849', 5, 'sauce', 'Tạo độ sánh mượt cho sốt kho dứa', 'Khuấy đều lại chén nước bột năng rồi rót từ từ vào chảo, nghiêng lắc nhẹ chảo khoảng 1 phút cho đến khi nước sốt sánh bóng quyện quanh từng miếng đậu và dứa thì tắt bếp.', NULL, NULL),
('imp-11b65c6b18266849_v4_step_6', 'imp-11b65c6b18266849', 6, 'finish', 'Hoàn thiện món đậu phụ kho dứa nóng hổi', 'Rắc hành lá xanh cắt khúc, ớt sừng thái lát và 2 g tiêu đen xay lên mặt chảo. Múc đậu phụ kho dứa ra đĩa sâu lòng, chan đều nước sốt sánh vàng lên trên và dùng nóng với cơm trắng.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-2ae4c4cdd97c5d02_v4_step_1', 'imp-2ae4c4cdd97c5d02', 1, 'marinate', 'Thái lát mỏng và ướp mềm thịt bò thăn', 'Thấm khô 300 g thịt bò thăn bằng khăn giấy rồi thái lát mỏng ngang thớ. Cho bò vào tô, ướp với 15 ml xì dầu, 15 ml dầu hào, 2 g hạt nêm, 3 g đường cát trắng, 1 g tiêu đen xay, 1/2 lượng tỏi băm, 10 g gừng băm nhuyễn và 5 ml dầu ăn trong 12 phút cho thấm đều.', 'Thêm 5 ml dầu ăn khi ướp giúp lát thịt bò khóa ẩm, khi xào trên lửa lớn sẽ mềm mượt mà không bị ra nước.', 12),
('imp-2ae4c4cdd97c5d02_v4_step_2', 'imp-2ae4c4cdd97c5d02', 2, 'prep', 'Sơ chế hành tây, hành lá và chuẩn bị cơm nóng', 'Bóc vỏ 1,5 củ hành tây, bổ múi cau mỏng vừa ăn và tách rời từng cánh hành. Rửa sạch hành lá, cắt khúc dài 3 cm. Chuẩn bị sẵn 540 g cơm trắng nấu chín còn nóng hổi.', NULL, NULL),
('imp-2ae4c4cdd97c5d02_v4_step_3', 'imp-2ae4c4cdd97c5d02', 3, 'cook', 'Xào nhanh thịt bò chín tái trên lửa lớn', 'Làm nóng 10 ml dầu ăn trong chảo lớn trên lửa lớn, phi thơm một nửa phần tỏi băm còn lại. Trút toàn bộ thịt bò đã ướp vào trải đều mặt chảo, đảo nhanh tay khoảng 90 giây đến khi thịt bò vừa chuyển màu chín tái 80% thì trút ngay ra đĩa riêng (kèm phần nước tiết ngọt).', 'Chỉ xào bò vừa chín tái ở bước đầu để khi trộn chung với hành tây ở bước cuối thịt chín tới hoàn toàn mà vẫn mềm mọng.', 2),
('imp-2ae4c4cdd97c5d02_v4_step_4', 'imp-2ae4c4cdd97c5d02', 4, 'cook', 'Xào hành tây giữ độ giòn ngọt tự nhiên', 'Cho 10 ml dầu ăn còn lại vào chảo nóng, phi thơm phần tỏi băm còn lại rồi cho hành tây bổ múi cau vào đảo nhanh trên lửa lớn khoảng 2 phút. Nêm 10 ml xì dầu còn lại và 2 g hạt nêm để hành tây vừa trong cạnh, ngọt thanh mà vẫn còn độ giòn.', 'Xào hành tây trên lửa lớn trong 2 phút giúp hành bớt hăng mà không bị mềm nhũn.', 2),
('imp-2ae4c4cdd97c5d02_v4_step_5', 'imp-2ae4c4cdd97c5d02', 5, 'cook', 'Trộn thịt bò, hành lá vào chảo cho quyện sốt', 'Trút đĩa thịt bò xào (cùng phần nước sốt ngọt) và hành lá cắt khúc vào chảo hành tây, đảo nhanh tay thêm 30 giây trên lửa lớn cho thịt bò chín hoàn toàn và nước sốt sánh nhẹ rồi tắt bếp.', NULL, NULL),
('imp-2ae4c4cdd97c5d02_v4_step_6', 'imp-2ae4c4cdd97c5d02', 6, 'finish', 'Chan bò xào hành tây lên cơm trắng và dùng nóng', 'Xới cơm trắng nóng ra 3 đĩa, múc đều thịt bò xào hành tây kèm nước sốt đậm đà chan lên mặt cơm, rắc 1 g tiêu đen xay còn lại và thưởng thức ngay.', NULL, NULL),
('imp-9a2994a529126adb_v4_step_1', 'imp-9a2994a529126adb', 1, 'prep', 'Trụng tơi sợi mì và sơ chế rau củ, đánh trứng', 'Đun sôi 1,2 lít nước lọc, thả 3 vắt mì vào trụng nhanh khoảng 90 giây cho sợi vừa bung rời, vớt ra xả ngay nước lạnh, để thật ráo rồi trộn với 5 ml dầu ăn chống dính. Thái sợi bắp cải trắng và cà rốt; băm nhỏ tỏi; tách riêng đầu hành trắng băm và lá hành xanh cắt khúc. Đập 3 quả trứng gà đánh tan cùng 2 g muối ăn và 1 g tiêu đen xay.', 'Xả nhanh nước lạnh và trộn chút dầu ăn ngay sau khi trụng giúp sợi mì săn dai và tách rời hoàn toàn lúc xào.', 2),
('imp-9a2994a529126adb_v4_step_2', 'imp-9a2994a529126adb', 2, 'cook', 'Chiên tơi trứng gà vàng xốp để riêng', 'Làm nóng 10 ml dầu ăn trong chảo lớn trên lửa vừa, đổ tô trứng gà vào đảo nhẹ nhàng khoảng 90 giây cho đến khi trứng vừa chín tới thành từng mảng vàng xốp mềm thì trút riêng ra đĩa.', 'Chiên riêng trứng trước rồi mới xào rau mì giúp trứng giữ được màu vàng tươi, xốp mềm mà không bị thâm màu xì dầu.', 2),
('imp-9a2994a529126adb_v4_step_3', 'imp-9a2994a529126adb', 3, 'cook', 'Phi thơm tỏi, đầu hành và xào rau củ giòn ngọt', 'Làm nóng 15 ml dầu ăn còn lại trong chảo trên lửa lớn, phi thơm tỏi băm và đầu hành trắng. Cho cà rốt và bắp cải trắng vào xào nhanh 2 phút cho vừa chín tới giữ độ giòn, nêm 10 ml nước mắm ngon và 3 g hạt nêm rồi gạt gọn sang một bên chảo.', NULL, 2),
('imp-9a2994a529126adb_v4_step_4', 'imp-9a2994a529126adb', 4, 'cook', 'Áp chảo mì thấm sốt xì dầu, dầu hào', 'Trút toàn bộ 225 g mì đã trụng vào phần chảo trống, rưới đều 20 ml xì dầu, 15 ml dầu hào, 5 g đường cát trắng và 2 g hạt nêm còn lại lên mì. Đảo đều cùng rau củ trên lửa lớn khoảng 2 phút đến khi sợi mì khô ráo, săn bóng và lên màu nâu đẹp mắt.', 'Giữ lửa lớn khi đảo mì và rau củ giúp nước sốt bám quyện đều vào sợi mì mà không bị đọng nước dưới đáy chảo.', NULL),
('imp-9a2994a529126adb_v4_step_5', 'imp-9a2994a529126adb', 5, 'cook', 'Trộn lại trứng gà chiên vào chảo mì rau', 'Cho đĩa trứng gà chiên tơi trở lại chảo mì, đảo nhẹ tay thêm 30 giây cho trứng, sợi mì và rau củ hòa quyện đều mà không làm vụn nát mảng trứng rồi tắt bếp.', NULL, NULL),
('imp-9a2994a529126adb_v4_step_6', 'imp-9a2994a529126adb', 6, 'finish', 'Rắc hành lá, tiêu xay và dọn nóng', 'Rắc toàn bộ lá hành xanh cắt khúc và 1 g tiêu đen xay còn lại vào chảo đảo thêm 2 lượt cho hành vừa chín tái xanh mướt. Bày mì xào trứng rau ra 3 đĩa và dùng nóng ngay.', NULL, NULL),
('imp-990934aa20b70964_v4_step_1', 'imp-990934aa20b70964', 1, 'prep', 'Chần xương bò và ninh nước dùng ngọt sâu', 'Chặt nhỏ 500 g xương ống bò, chần nước sôi 4 phút với 2 g muối hạt rồi vớt ra xả sạch bọt bẩn. Cho xương vào nồi cùng 2200 ml nước lọc, 1/2 củ hành tây bổ múi cau và 3 g muối hạt, đun sôi rồi hạ lửa nhỏ liu riu ninh 30 phút và hớt bọt thường xuyên để nước dùng trong ngọt.', 'Chần kỹ xương bò trước khi ninh sẽ loại bỏ hết mùi hôi và cặn đục, giúp nồi nước dùng lẩu trong thanh.', 30),
('imp-990934aa20b70964_v4_step_2', 'imp-990934aa20b70964', 2, 'prep', 'Thái mỏng ướp bò và sơ chế nấm, rau thơm', 'Thái lát mỏng ngang thớ 650 g thịt bò, trộn đều cùng một nửa tỏi băm, 3 g hạt nêm, 1 g tiêu đen xay và 5 ml dầu ăn để thịt mềm thơm, xếp lên đĩa cùng 1/2 củ hành tây thái lát mỏng. Cắt gốc rửa sạch nấm đùi gà thái lát; rửa sạch rau muống, húng quế, ngò rí, hành lá; bổ múi cau 2 quả cà chua, băm nhỏ 1 quả cà chua và vắt nước cốt 2 quả chanh tươi.', 'Trộn 5 ml dầu ăn khi ướp lát thịt bò mỏng giúp miếng thịt giữ độ ẩm mượt và không bị khô xác lúc nhúng vào nước lẩu sôi.', NULL),
('imp-990934aa20b70964_v4_step_3', 'imp-990934aa20b70964', 3, 'cook', 'Phi thơm tỏi và xào nền cà chua tạo màu', 'Làm nóng chảo với 15 ml dầu ăn còn lại trên lửa vừa, phi thơm phần tỏi băm còn lại trong 30 giây. Trút phần cà chua băm nhỏ và cà chua bổ múi cau vào xào đều 3 phút đến khi cà chua mềm và tiết sắc đỏ cam đẹp mắt.', NULL, 3),
('imp-990934aa20b70964_v4_step_4', 'imp-990934aa20b70964', 4, 'cook', 'Nêm nước lẩu bò đậm đà thanh dịu', 'Vớt bỏ xương ống và xác hành tây từ nồi nước ninh cho gọn nồi, đổ hỗn hợp cà chua xào vào nấu sôi 3 phút. Nêm 30 ml nước mắm ngon, 7 g hạt nêm, 2 g muối hạt còn lại và 8 g đường cát trắng sao cho nước dùng đậm đà thanh ngọt.', NULL, 3),
('imp-990934aa20b70964_v4_step_5', 'imp-990934aa20b70964', 5, 'cook', 'Tạo vị chua thanh từ nước cốt chanh tươi', 'Hạ nhỏ lửa nồi nước dùng rồi từ từ rưới nước cốt 2 quả chanh tươi vào khuấy nhẹ, nếm lại vị chua nhẹ hài hòa với vị ngọt từ xương bò.', 'Chỉ rưới nước cốt chanh sau khi nước dùng đã nêm xong và không đun sôi mạnh để giữ mùi thơm thanh mát của chanh tươi.', NULL),
('imp-990934aa20b70964_v4_step_6', 'imp-990934aa20b70964', 6, 'finish', 'Nhúng bò thái lát cùng nấm và rau thơm ăn nóng', 'Chuyển nồi lẩu lên bếp bàn giữ sôi lăn tăn, thả nấm đùi gà, đầu hành lá, hành lá cắt khúc và 1 g tiêu đen xay vào nấu 3 phút cho nấm chín ngọt. Khi ăn, nhúng từng lát thịt bò cùng hành tây thái lát khoảng 20–30 giây cho thịt vừa chín tới tái hồng mềm ngọt, nhúng rau muống, húng quế và ngò rí thưởng thức nóng kèm bún tươi và 15 ml nước mắm ngon còn lại.', NULL, NULL),
('imp-d0569e8ec34b2bfc_v4_step_1', 'imp-d0569e8ec34b2bfc', 1, 'prep', 'Làm ráo giá đỗ và thái hành tỏi', 'Rửa sạch 200 g giá đỗ tươi, nhặt bỏ rễ dài hoặc vỏ đậu xanh rồi trút ra rổ để thật ráo nước. Tỏi khô băm nhỏ, hành lá tươi cắt khúc dài 3 cm. Thịt thăn bò thấm khô bằng khăn giấy, thái lát mỏng ngang thớ cho mềm.', 'Giá đỗ càng ráo nước thì khi xào lửa lớn càng nhanh chín giòn mà không làm loãng nước sốt trong chảo.', NULL),
('imp-d0569e8ec34b2bfc_v4_step_2', 'imp-d0569e8ec34b2bfc', 2, 'marinate', 'Ướp thịt bò thấm gia vị', 'Cho thịt bò thái lát vào tô cùng 1/3 lượng tỏi băm, 15 ml xì dầu, 10 ml dầu hào, 10 ml rượu Thiệu Hưng, 4 g hạt nêm, 3 g đường cát trắng và 1 g tiêu đen xay. Trộn đều rồi ướp trong 15 phút cho thịt mềm thấm vị đậm đà.', 'Không cho muối ăn vào bước ướp thịt bò để tránh muối rút hết nước khiến thịt bị khô cứng khi xào.', 15),
('imp-d0569e8ec34b2bfc_v4_step_3', 'imp-d0569e8ec34b2bfc', 3, 'cook', 'Xào nhanh thịt bò trên lửa lớn', 'Làm nóng chảo rộng với 10 ml dầu ăn thực vật trên lửa vừa, phi thơm 1/3 lượng tỏi băm trong 20 giây. Sau đó tăng lên lửa lớn, trút thịt bò đã ướp vào đảo nhanh tay khoảng 2 phút đến khi thịt bò vừa săn chín tái đều các mặt thì trút ngay ra đĩa riêng.', NULL, 2),
('imp-d0569e8ec34b2bfc_v4_step_4', 'imp-d0569e8ec34b2bfc', 4, 'cook', 'Xào giá đỗ giữ độ giòn tươi', 'Lau nhanh chảo nếu còn nhiều nước, cho 15 ml dầu ăn thực vật còn lại vào đun nóng rồi phi thơm phần tỏi băm cuối cùng. Tăng lửa lớn, đổ toàn bộ giá đỗ vào xào nhanh tay khoảng 2 phút cùng 2 g muối ăn đến khi cọng giá vừa trong nhẹ, hơi xẹp mà vẫn giòn.', NULL, 2),
('imp-d0569e8ec34b2bfc_v4_step_5', 'imp-d0569e8ec34b2bfc', 5, 'cook', 'Đảo quyện thịt bò và giá đỗ', 'Trút ngay đĩa thịt bò vào chảo giá đỗ, rưới thêm 10 ml xì dầu còn lại quanh thành chảo. Đảo đều tay trên lửa lớn thêm khoảng 1 phút cho thịt bò chín hoàn toàn và gia vị quyện đều vào giá đỗ.', 'Tổng thời gian đảo chung không nên quá 1–2 phút để giá không bị chảy nước và thịt bò giữ trọn độ mềm ngọt.', 1),
('imp-d0569e8ec34b2bfc_v4_step_6', 'imp-d0569e8ec34b2bfc', 6, 'finish', 'Thêm hành lá, dầu mè và hoàn thiện món xào', 'Thả hành lá cắt khúc vào chảo đảo nhanh 20 giây cho hành vừa chín xanh mướt rồi tắt bếp ngay. Rưới 5 ml dầu mè thơm và rắc 0,5 g tiêu đen xay còn lại lên trên, đảo nhẹ một lượt rồi múc bò xào giá đỗ ra đĩa dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-531f59c246a56bcb_v4_step_1', 'imp-531f59c246a56bcb', 1, 'marinate', 'Trộn gia vị và quết thịt với nước cho dẻo', 'Cho 500 g thịt heo xay vào tô lớn cùng 20 ml xì dầu nhạt, 5 ml xì dầu đặc, 15 ml rượu Thiệu Hưng, tỏi băm nhuyễn và gừng băm nhuyễn, trộn đều. Tiếp theo, rót từng muỗng canh trong 45 ml nước lọc vào tô, dùng đũa khuấy và quết mạnh theo một chiều đến khi nước ngấm hết và thịt dẻo quánh rồi mới thêm lượt nước tiếp theo.', 'Quết thịt theo một chiều với từng ít nước giúp cấu trúc protein liên kết chặt, viên thịt chiên xong sẽ dẻo giòn mà không bị khô bở.', 5),
('imp-531f59c246a56bcb_v4_step_2', 'imp-531f59c246a56bcb', 2, 'marinate', 'Ướp gia vị khô và trộn trứng bột năng', 'Thêm 4 g muối ăn, 8 g đường cát trắng, 1,5 g tiêu trắng xay và 1 g ngũ vị hương vào tô thịt trộn đều, ướp khoảng 15 phút cho ngấm vị. Sau đó đánh tan trứng gà rồi đổ vào tô cùng hành lá thái nhỏ và 15 g bột năng, trộn thật đều đến khi hỗn hợp dẻo mịn đồng nhất.', NULL, 15),
('imp-531f59c246a56bcb_v4_step_3', 'imp-531f59c246a56bcb', 3, 'prep', 'Vo tròn từng viên thịt đều nhau', 'Thoa một lớp dầu ăn thật mỏng lên lòng bàn tay để chống dính, múc từng phần thịt vừa ăn rồi nắm và xoay tròn thành những viên đường kính khoảng 2,5 đến 3 cm xếp đều ra đĩa.', 'Vo các viên thịt kích thước đồng đều giúp toàn bộ mẻ chiên chín cùng lúc, không bị viên sống viên cháy.', NULL),
('imp-531f59c246a56bcb_v4_step_4', 'imp-531f59c246a56bcb', 4, 'cook', 'Làm nóng dầu và chiên vàng các viên thịt', 'Đổ 400 ml dầu ăn thực vật vào nồi hoặc chảo sâu lòng, đun trên lửa vừa đến khi thử đầu đũa tre thấy sủi bọt đều quanh đũa (khoảng 175–180°C). Nhẹ nhàng thả từng mẻ viên thịt vào chiên, giữ khoảng cách thoáng để dầu không bị tụt nhiệt, chiên khoảng 3 phút cho mặt dưới se vàng rồi trở mặt.', NULL, 3),
('imp-531f59c246a56bcb_v4_step_5', 'imp-531f59c246a56bcb', 5, 'cook', 'Chiên chín hoàn toàn bên trong viên thịt', 'Tiếp tục chiên lửa vừa thêm khoảng 3 đến 4 phút nữa, đảo nhẹ liên tục để viên thịt vàng nâu giòn đều các mặt. Kiểm tra độ chín bằng cách cắt thử một viên thấy thịt bên trong chín trắng hoàn toàn, không còn màu hồng sống và tứa nước trong là đạt.', 'Không chiên trên lửa quá lớn vì vỏ ngoài sẽ sậm cháy trước khi nhân thịt bên trong kịp chín kỹ.', 4),
('imp-531f59c246a56bcb_v4_step_6', 'imp-531f59c246a56bcb', 6, 'finish', 'Thấm ráo dầu và dọn nóng', 'Vớt toàn bộ thịt viên chiên ra rổ lưới hoặc đĩa có lót sẵn khăn giấy thấm dầu trong 2 phút cho ráo bớt dầu thừa, sau đó xếp ra đĩa sạch và dọn dùng nóng.', NULL, NULL),
('imp-3767b2e36f535b7b_v4_step_1', 'imp-3767b2e36f535b7b', 1, 'prep', 'Thấm khô ức gà và pha xốt ướp ngũ vị', 'Rửa sạch 700 g ức gà phi lê, dùng khăn giấy thấm thật khô rồi khía nhẹ vài đường nông trên mặt thịt để gia vị thấm sâu. Trong tô nhỏ, khuấy đều 35 ml xì dầu đặc, 20 ml xì dầu nhạt, 12 ml mật ong nguyên chất, 2 g bột ngũ vị hương, tỏi băm nhuyễn, gừng băm nhuyễn, 10 ml dầu mè thơm, 15 ml dầu ăn thực vật và 1,5 g tiêu trắng xay; múc tách riêng 1 muỗng canh hỗn hợp xốt sạch ra chén nhỏ để phết gà khi nướng.', 'Thấm khô hoàn toàn mặt ức gà trước khi ướp giúp hỗn hợp xì dầu ngũ vị bám chặt vào thịt mà không bị trôi loãng.', NULL),
('imp-3767b2e36f535b7b_v4_step_2', 'imp-3767b2e36f535b7b', 2, 'marinate', 'Ướp thịt gà ít nhất 60 phút cho đậm vị', 'Đặt ức gà vào tô lớn hoặc túi zip, đổ toàn bộ phần xốt ướp vào xoa bóp đều khắp các mặt thịt. Đậy kín và ướp trong ngăn mát tủ lạnh ít nhất 1 đến 2 giờ (thỉnh thoảng trở mặt cho gà thấm đều), sau đó lấy ra để nhiệt độ phòng khoảng 20 phút trước khi nướng.', 'Để gà bớt lạnh trước khi vào lò giúp miếng ức gà chín đều từ ngoài vào trong mà không bị khô mặt ngoài.', 60),
('imp-3767b2e36f535b7b_v4_step_3', 'imp-3767b2e36f535b7b', 3, 'cook', 'Nướng mặt thứ nhất ở nhiệt độ vừa', 'Làm nóng lò nướng ở 170°C, lót giấy nến hoặc giấy bạc vào khay rồi xếp các miếng ức gà đã rũ nhẹ phần xốt bám trên bề mặt thành một lớp thưa (bỏ phần nước ướp thịt sống còn dư trong tô). Đặt khay ở rãnh giữa lò, nướng trong 20 phút trên lửa vừa để thịt chín từ từ mà xốt xì dầu không bị cháy khét.', NULL, 20),
('imp-3767b2e36f535b7b_v4_step_4', 'imp-3767b2e36f535b7b', 4, 'cook', 'Lật mặt và phết lớp mật ong bóng đẹp', 'Lấy khay gà ra khỏi lò, nhẹ nhàng lật từng miếng gà sang mặt còn lại. Hòa 8 ml mật ong nguyên chất còn lại với 1 muỗng canh xốt xì dầu sạch đã tách riêng từ bước 1 rồi dùng cọ phết đều lên bề mặt thịt gà.', 'Chỉ phết mật ong ở nửa sau quá trình nướng để tạo lớp caramel nâu bóng đẹp mắt mà không làm đường cháy đắng.', NULL),
('imp-3767b2e36f535b7b_v4_step_5', 'imp-3767b2e36f535b7b', 5, 'cook', 'Nướng hoàn tất đến khi gà chín mềm mọng', 'Đưa khay gà trở lại lò ở 170°C nướng thêm 15 đến 20 phút nữa (có thể tăng 200°C ở 3 phút cuối nếu thích cạnh gà xém nhẹ, đứng canh sát). Kiểm tra phần dày nhất của miếng gà thấy thịt chín trắng hoàn toàn, nước tiết ra trong suốt không còn sắc hồng là đạt.', NULL, 18),
('imp-3767b2e36f535b7b_v4_step_6', 'imp-3767b2e36f535b7b', 6, 'finish', 'Để gà nghỉ, thái lát và rắc hành lá', 'Lấy gà ra khỏi lò để nghỉ trên thớt khoảng 5 phút cho nước thịt ổn định lại bên trong, sau đó thái lát xéo dày 1,5 cm xếp ra đĩa. Chan phần nước xốt nóng thơm tiết ra trong khay nướng lên mặt thịt, rắc hành lá tươi thái nhỏ và dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-08b08cad387c7c9f_v4_step_1', 'imp-08b08cad387c7c9f', 1, 'prep', 'Rút nước muối và thấm khô đậu phụ', 'Cắt 3,5 bìa đậu phụ trắng thành các miếng chữ nhật hoặc vuông dày khoảng 2 cm xếp ra khay. Rắc đều 5 g muối ăn lên các mặt đậu, để yên 5 phút cho muối rút bớt ẩm, sau đó dùng khăn giấy lau sạch muối thừa và thấm thật khô từng miếng đậu phụ.', 'Đậu phụ được rút bớt nước và lau sạch muối sẽ ít bắn dầu khi chiên và tạo được lớp vỏ giòn lâu hơn.', 5),
('imp-08b08cad387c7c9f_v4_step_2', 'imp-08b08cad387c7c9f', 2, 'prep', 'Áo lớp bột bắp mỏng và chuẩn bị tỏi hành', 'Đổ 25 g bột bắp ra đĩa rộng, lăn nhẹ từng miếng đậu phụ cho bột phủ kín một lớp mỏng đều rồi giũ nhẹ phần bột thừa. Băm nhuyễn 6 tép tỏi khô, thái nhỏ hành lá tươi và thái lát mỏng 1 quả ớt sừng đỏ.', NULL, NULL),
('imp-08b08cad387c7c9f_v4_step_3', 'imp-08b08cad387c7c9f', 3, 'sauce', 'Dội dầu nóng làm sốt tỏi dầu hào chay', 'Cho tỏi băm nhuyễn, hành lá thái nhỏ và 15 g đường cát trắng vào bát sứ chịu nhiệt. Đun nóng 35 ml dầu ăn thực vật trong chảo nhỏ trên lửa lớn đến khi mặt dầu hơi gợn sóng và bốc khói nhẹ thì tắt bếp, lập tức rưới dầu nóng vào bát tỏi nghe tiếng xèo thơm lừng, khuấy đều rồi thêm 20 ml xì dầu nhạt và 30 ml dầu hào chay nấm đông cô trộn tan thành sốt sánh.', 'Dầu phải thật nóng mới làm chín thơm tỏi băm tức thì; dùng bát sứ hoặc thủy tinh chịu nhiệt để đảm bảo an toàn.', NULL),
('imp-08b08cad387c7c9f_v4_step_4', 'imp-08b08cad387c7c9f', 4, 'cook', 'Chiên vàng giòn mặt đầu tiên của đậu phụ', 'Làm nóng chảo chống dính với 45 ml dầu ăn thực vật còn lại trên lửa vừa-lớn, xếp các miếng đậu phụ đã áo bột vào thành một lớp thoáng. Chiên yên khoảng 4 phút đến khi mặt dưới chuyển vàng nâu giòn rụm rồi mới nhẹ nhàng trở mặt.', 'Không xếp đậu phụ quá chật và không đảo liên tục trong 3 phút đầu để lớp bột bắp không bị dính vỡ.', 4),
('imp-08b08cad387c7c9f_v4_step_5', 'imp-08b08cad387c7c9f', 5, 'cook', 'Chiên giòn các mặt còn lại và thấm dầu', 'Tiếp tục chiên mặt còn lại thêm 4 phút nữa trên lửa vừa đến khi tất cả các mặt miếng đậu đều vàng giòn đều mắt. Gắp đậu phụ ra đĩa có lót sẵn khăn giấy thấm bớt dầu thừa.', NULL, 4),
('imp-08b08cad387c7c9f_v4_step_6', 'imp-08b08cad387c7c9f', 6, 'finish', 'Rưới sốt tỏi nóng và trang trí', 'Xếp đậu phụ chiên giòn ra đĩa sạch, khuấy đều lại bát sốt tỏi rồi rưới phủ lên từng miếng đậu nóng. Rắc hạt mè trắng rang và ớt sừng đỏ thái lát lên trên rồi dùng ngay với cơm trắng.', NULL, NULL),
('imp-cbbfa59518b7d47d_v4_step_1', 'imp-cbbfa59518b7d47d', 1, 'prep', 'Sơ chế hành lá chẻ sợi và băm tỏi', 'Rửa sạch 40 g hành lá tươi, dùng khăn giấy lau thật khô nước để khi phi không bị bắn dầu, sau đó cắt khúc 5 cm và chẻ dọc thành sợi mảnh. Tỏi khô bóc vỏ, băm nhỏ đều tay để khi phi chín vàng đồng loạt.', 'Hành lá phải thật khô ráo trước khi cho vào chảo dầu thì hành mới giòn thơm mà không bị nổ dầu.', NULL),
('imp-cbbfa59518b7d47d_v4_step_2', 'imp-cbbfa59518b7d47d', 2, 'cook', 'Luộc mì trứng và giữ lại nước luộc', 'Đun sôi 1500 ml nước lọc cùng 8 g muối ăn trên lửa lớn, thả 180 g mì trứng khô vào luộc khoảng 5 đến 6 phút đến khi sợi mì vừa chín tới còn độ dai nhẹ. Trước khi vớt mì ra rổ để ráo, múc giữ lại khoảng 60 ml nước luộc mì nóng.', NULL, 6),
('imp-cbbfa59518b7d47d_v4_step_3', 'imp-cbbfa59518b7d47d', 3, 'cook', 'Phi giòn hành lá tạo dầu hành thơm', 'Đun nóng 40 ml dầu ăn thực vật trong chảo rộng trên lửa vừa, thả toàn bộ hành lá chẻ sợi vào đảo đều liên tục khoảng 4 đến 5 phút đến khi hành chuyển màu vàng nâu giòn nhẹ thì gắp hành phi ra bát để riêng, giữ lại toàn bộ phần dầu hành thơm trong chảo.', 'Hạ xuống lửa vừa-nhỏ nếu thấy hành chuyển màu quá nhanh để hành giòn đều mà không bị đắng khét.', 5),
('imp-cbbfa59518b7d47d_v4_step_4', 'imp-cbbfa59518b7d47d', 4, 'cook', 'Phi thơm tỏi băm trong dầu hành', 'Cho tỏi băm nhỏ vào chảo dầu hành đang ấm trên lửa vừa-nhỏ, đảo nhanh tay khoảng 1 đến 2 phút đến khi tỏi vừa chuyển màu vàng nhạt và tỏa mùi thơm nức thì hạ ngay lửa nhỏ.', NULL, 2),
('imp-cbbfa59518b7d47d_v4_step_5', 'imp-cbbfa59518b7d47d', 5, 'sauce', 'Nấu sôi nhẹ sốt xì dầu đường cát', 'Rót 25 ml xì dầu nhạt, 12 ml xì dầu đặc và 5 g đường cát trắng vào chảo tỏi, khuấy đều và đun sôi lăn tăn khoảng 1 phút trên lửa nhỏ đến khi đường tan hết và hỗn hợp sốt hơi sánh bóng rồi tắt bếp.', 'Không đun nước sốt quá cạn ở bước này vì sốt nguội sẽ sệt lại nhanh; giữ độ sánh vừa phải giúp dễ trộn đều với mì.', NULL),
('imp-cbbfa59518b7d47d_v4_step_6', 'imp-cbbfa59518b7d47d', 6, 'finish', 'Trộn mì nóng quyện sốt và rắc hành phi', 'Trút ngay mì trứng đã ráo nước vào chảo sốt còn nóng, rưới thêm 5 ml dầu mè thơm và dùng đũa đảo trộn thật đều cho từng sợi mì áo bóng sốt. Nếu thấy mì hơi khô, thêm từng muỗng canh nước luộc mì đã giữ lại vào trộn đến khi vừa mướt, bày ra đĩa rồi rắc hành phi giòn lên trên và dùng nóng ngay.', NULL, NULL),
('imp-266587069d92cb79_v4_step_1', 'imp-266587069d92cb79', 1, 'prep', 'Làm sạch vỏ cua biển và sơ chế gừng hành', 'Làm lạnh cua sống trong ngăn mát 10 phút cho dịu lại rồi dùng bàn chải chà sạch đất cát ở mai, càng và các kẽ chân dưới vòi nước lạnh chảy, để ráo. Gừng tươi thái lát mỏng một nửa lượng (khoảng 18 g) để lót hấp, phần còn lại băm thật nhuyễn; hành lá thái nhỏ để riêng.', NULL, NULL),
('imp-266587069d92cb79_v4_step_2', 'imp-266587069d92cb79', 2, 'sauce', 'Pha nước chấm giấm đen Trấn Giang gừng băm', 'Trong bát vừa, khuấy tan hoàn toàn 10 g đường nâu với 50 ml giấm đen Trấn Giang, 30 ml giấm gạo, 30 ml xì dầu nhạt và 30 ml nước lọc. Sau đó cho toàn bộ gừng băm nhuyễn và một nửa lượng hành lá thái nhỏ vào trộn đều.', 'Pha nước chấm trước giúp hương thơm của gừng tươi kịp tiết ra hòa quyện vào giấm đen và đường nâu.', NULL),
('imp-266587069d92cb79_v4_step_3', 'imp-266587069d92cb79', 3, 'prep', 'Lót gừng và xếp cua vào xửng hấp', 'Đổ khoảng 770 ml nước lọc vào đáy nồi hấp (mực nước thấp hơn vỉ xửng), đun sôi mạnh trên lửa lớn. Xếp các lát gừng tươi phủ lên mặt vỉ hấp rồi đặt cua lên trên theo tư thế ngửa bụng lên (mai úp xuống) để giữ trọn nước ngọt và gạch cua, rưới đều 15 ml rượu Thiệu Hưng lên mình cua.', 'Đặt cua ngửa bụng khi hấp giúp nước ngọt tự nhiên và gạch béo bên trong mai không bị chảy xuống nước nồi.', NULL),
('imp-266587069d92cb79_v4_step_4', 'imp-266587069d92cb79', 4, 'cook', 'Hấp cua trên lửa lớn đến khi chín đỏ', 'Đậy kín nắp nồi, hấp liên tục trên lửa lớn trong khoảng 9 đến 10 phút tính từ lúc nước sôi mạnh (với cua cỡ 250–350 g/con). Quan sát thấy vỏ mai cua chuyển đỏ cam rực rỡ, thân cua chín săn và phần thịt càng chuyển trắng đục hoàn toàn là cua đã chín.', 'Không mở nắp xửng nhiều lần trong lúc hấp để giữ áp suất hơi nóng ổn định giúp cua chín đều và giữ trọn vị ngọt.', 10),
('imp-266587069d92cb79_v4_step_5', 'imp-266587069d92cb79', 5, 'cook', 'Để ráo hơi nước trên mặt cua', 'Tắt bếp, mở hé nắp cho hơi nóng thoát bớt rồi nhấc cua ra đĩa rộng, để nghỉ khoảng 2 phút cho bề mặt vỏ ráo nước và nguội bớt dễ cầm tay hơn.', NULL, 2),
('imp-266587069d92cb79_v4_step_6', 'imp-266587069d92cb79', 6, 'finish', 'Bày đĩa cua hấp và thưởng thức nóng', 'Rắc phần hành lá thái nhỏ còn lại lên đĩa cua cho đẹp mắt, dọn nóng ngay kèm bát nước chấm giấm đen gừng hành. Khi ăn gỡ bỏ yếm và mang xám hai bên mai, chấm thịt cua vào nước chấm chua ngọt ấm vị gừng.', NULL, NULL),
('imp-b02fdf7cecfae119_v4_step_1', 'imp-b02fdf7cecfae119', 1, 'prep', 'Làm sạch khử tanh và cắt khoanh mực ống', 'Nhẹ nhàng rút đầu và nội tạng mực ống ra khỏi thân, gỡ bỏ túi mực đen cẩn thận tránh làm vỡ, bỏ mắt và nang cứng trong thân. Chà xát đều 8 g muối ăn cùng 10 g gừng tươi đập dập lên khắp mình mực khoảng 2 phút để khử sạch mùi tanh và nhớt, sau đó rửa lại nhiều lần với nước lạnh, để ráo rồi cắt khoanh tròn dày 1,5 cm.', 'Không làm vỡ túi mực khi sơ chế và rửa lại thật sạch muối gừng giúp khoanh mực trắng giòn, thơm ngọt.', NULL),
('imp-b02fdf7cecfae119_v4_step_2', 'imp-b02fdf7cecfae119', 2, 'marinate', 'Ướp mực cùng xì dầu, rượu Thiệu Hưng và gừng sợi', 'Thái sợi mảnh 15 g gừng tươi còn lại và cắt khúc 3 cm phần hành lá tươi. Cho mực vào tô ướp cùng 45 ml xì dầu, 10 ml xì dầu đặc, 15 ml rượu Thiệu Hưng, 25 g đường cát trắng, 1 g tiêu đen xay và gừng thái sợi, trộn đều rồi ướp trong 15 phút cho thấm gia vị.', NULL, 15),
('imp-b02fdf7cecfae119_v4_step_3', 'imp-b02fdf7cecfae119', 3, 'cook', 'Xào săn khoanh mực trên lửa vừa-lớn', 'Làm nóng chảo sâu lòng hoặc nồi đáy dày với 30 ml dầu ăn thực vật trên lửa vừa-lớn, trút toàn bộ tô mực cùng nước ướp vào đảo đều khoảng 3 phút đến khi khoanh mực vừa săn lại và chuyển màu trắng đục.', 'Không nên chần mực qua nước sôi trước khi kho vì mực rất dễ bị co rút và dai khi nấu tiếp.', 3),
('imp-b02fdf7cecfae119_v4_step_4', 'imp-b02fdf7cecfae119', 4, 'cook', 'Thêm nước lọc đun sôi đều vị', 'Rót 100 ml nước lọc vào nồi mực sao cho nước xâm xấp mặt nguyên liệu, bật lửa lớn đun sôi bùng và đảo nhẹ cho nước sốt hòa quyện đều.', NULL, NULL),
('imp-b02fdf7cecfae119_v4_step_5', 'imp-b02fdf7cecfae119', 5, 'cook', 'Kho liu riu đến khi nước sốt sánh nâu bóng', 'Hạ xuống lửa vừa-nhỏ, kho liu riu khoảng 10 đến 12 phút không đậy nắp, thỉnh thoảng đảo nhẹ cho các khoanh mực thấm đều nước sốt. Khi nước kho rút cạn chỉ còn độ sánh sệt màu nâu bóng ôm quanh từng khoanh mực, nếm lại thấy vị mặn ngọt hài hòa là đạt.', 'Canh thời gian kho vừa đủ cho nước sánh lại; tránh kho quá lâu trên 20 phút khiến thịt mực bị cứng dai.', 12),
('imp-b02fdf7cecfae119_v4_step_6', 'imp-b02fdf7cecfae119', 6, 'finish', 'Thêm hành lá, dầu mè và dọn nóng', 'Tắt bếp ngay khi sốt đạt độ sánh mong muốn, rưới 5 ml dầu mè thơm vào cùng hành lá tươi cắt khúc và 0,5 g tiêu đen xay còn lại, đảo nhẹ một lượt rồi múc ra đĩa dùng nóng với cơm trắng.', NULL, NULL),
('imp-4693d6520fbd9d49_v4_step_1', 'imp-4693d6520fbd9d49', 1, 'prep', 'Thái lát thịt bò ngang thớ và chuẩn bị tỏi hành', 'Rửa nhanh 450 g thịt thăn bò, thấm thật khô rồi cho vào ngăn đá 20 phút cho hơi se mặt để dễ thái lát mỏng 4 đến 5 mm theo chiều ngang thớ. Bóc vỏ tỏi khô, chia một nửa băm nhỏ và một nửa thái lát mỏng đều 2 mm; rửa sạch hành lá tươi rồi cắt khúc 3 đến 4 cm.', 'Thái tỏi thành lát mỏng đều giúp khi phi tạo thành từng miếng tỏi giòn rụm vàng đều mà không dễ cháy khét như tỏi băm.', NULL),
('imp-4693d6520fbd9d49_v4_step_2', 'imp-4693d6520fbd9d49', 2, 'marinate', 'Ướp thịt bò với xì dầu và dầu hào', 'Cho thịt bò thái lát vào tô lớn cùng phần tỏi băm nhỏ, 30 ml xì dầu, 10 ml dầu hào, 10 ml dầu ăn thực vật, 2,5 g muối ăn và 1 g tiêu đen xay. Trộn nhẹ cho gia vị bám đều khắp mặt thịt, bọc kín ướp trong ngăn mát 20 phút.', NULL, 20),
('imp-4693d6520fbd9d49_v4_step_3', 'imp-4693d6520fbd9d49', 3, 'cook', 'Phi tỏi thái lát vàng giòn rìa', 'Đặt chảo nhỏ lên bếp với 10 ml dầu ăn thực vật trên lửa vừa-nhỏ, cho toàn bộ tỏi thái lát vào đảo nhẹ liên tục khoảng 3 phút đến khi rìa lát tỏi vừa ngả màu vàng nhạt thơm lừng thì vớt ngay ra đĩa lót khăn giấy cho giòn ráo dầu.', 'Phải vớt tỏi phi ngay khi còn màu vàng nhạt vì lượng dầu nóng bám trên lát tỏi sẽ tiếp tục làm tỏi vàng đậm thêm sau khi vớt.', 3),
('imp-4693d6520fbd9d49_v4_step_4', 'imp-4693d6520fbd9d49', 4, 'cook', 'Làm nóng vỉ nướng hoặc chảo gang lửa lớn', 'Làm nóng vỉ nướng than, bếp nướng điện hoặc chảo gang dày trên lửa lớn trong 5 phút cho bề mặt thật nóng, sau đó phết 5 ml dầu ăn thực vật còn lại lên mặt vỉ để chống dính.', NULL, 5),
('imp-4693d6520fbd9d49_v4_step_5', 'imp-4693d6520fbd9d49', 5, 'cook', 'Nướng nhanh thịt bò cháy cạnh hai mặt', 'Xếp các lát thịt bò lên mặt vỉ nóng thành một lớp thưa không chồng chéo, nướng nhanh trên lửa lớn khoảng 2 phút mỗi mặt đến khi thịt xém vàng nhẹ ở rìa và bên trong chín mềm vừa tới (không còn sắc đỏ sống nếu thích ăn chín kỹ). Nếu nhiều thịt hãy chia làm 2 mẻ nướng.', 'Không xếp các lát thịt quá sát nhau khiến hơi nước bốc lên làm thịt bị hấp mềm thay vì cháy cạnh thơm ngon.', 4),
('imp-4693d6520fbd9d49_v4_step_6', 'imp-4693d6520fbd9d49', 6, 'finish', 'Pha muối tiêu và trình bày đĩa bò nướng', 'Trộn đều 2,5 g muối ăn còn lại với 2 g tiêu đen xay ra chén nhỏ làm đồ chấm. Xếp thịt bò nướng nóng ra đĩa, rắc đều tỏi lát phi vàng giòn cùng hành lá tươi cắt khúc lên trên và dọn dùng nóng ngay.', NULL, NULL),
('imp-dd48c08a9b9ed207_v4_step_1', 'imp-dd48c08a9b9ed207', 1, 'prep', 'Làm sạch khử mùi và thấm khô sườn non', 'Chặt 650 g sườn non thành từng khúc dài khoảng 4 đến 5 cm, cho vào thau cùng 6 g muối ăn chà xát kỹ khắp mặt thịt xương trong 2 phút để khử mùi hôi, sau đó rửa lại nhiều lần bằng nước sạch rồi thấm thật khô bằng khăn giấy.', 'Khúc sườn ráo nước hoàn toàn sẽ giúp gia vị ướp bám chặt và lớp bột chiên không bị tuột khi thả vào dầu.', NULL),
('imp-dd48c08a9b9ed207_v4_step_2', 'imp-dd48c08a9b9ed207', 2, 'marinate', 'Ướp sườn non thấm gia vị ngũ vị', 'Cho sườn vào tô lớn cùng tỏi băm nhuyễn, 30 ml xì dầu, 15 ml dầu hào, 5 g đường cát trắng, 2 g tiêu đen xay, 2 g muối ăn còn lại và 1,5 g ngũ vị hương. Trộn xoa đều từng khúc sườn, bọc kín để ướp trong ngăn mát ít nhất 30 phút (hoặc 2 giờ cho đậm vị).', NULL, 30),
('imp-dd48c08a9b9ed207_v4_step_3', 'imp-dd48c08a9b9ed207', 3, 'prep', 'Pha hỗn hợp trứng gà bột chiên giòn', 'Đập 2 quả trứng gà vào tô lớn, đánh tan đều rồi cho 140 g bột chiên giòn cùng 60 ml nước lọc vào khuấy kỹ đến khi thu được hỗn hợp bột sền sệt, mịn mượt không vón cục.', 'Nếu hỗn hợp quá đặc có thể thêm từng muỗng cà phê nước để lớp bột áo vừa đủ mỏng giòn, không bị dày cộp.', NULL),
('imp-dd48c08a9b9ed207_v4_step_4', 'imp-dd48c08a9b9ed207', 4, 'cook', 'Nhúng bột và chiên sườn trên lửa vừa', 'Đổ 350 ml dầu ăn thực vật vào chảo sâu lòng, đun trên lửa vừa đến khi đầu đũa sủi tăm đều (khoảng 170°C). Gắp từng khúc sườn đã ướp (gạt bớt nước ướp thừa) nhúng ngập vào tô bột chiên giòn rồi thả từng mẻ vào chảo dầu, không xếp chồng lên nhau.', NULL, NULL),
('imp-dd48c08a9b9ed207_v4_step_5', 'imp-dd48c08a9b9ed207', 5, 'cook', 'Chiên chín vàng đều bên trong sườn non', 'Chiên sườn trên lửa vừa khoảng 9 đến 10 phút, thỉnh thoảng lật trở đều các mặt đến khi lớp vỏ ngoài chuyển màu vàng nâu giòn rụm và phần thịt sát xương bên trong chín trắng hoàn toàn không còn máu hồng.', 'Giữ nhiệt dầu ở mức vừa phải giúp sườn non có xương chín kỹ từ bên trong trước khi lớp vỏ ngoài bị sậm màu.', 10),
('imp-dd48c08a9b9ed207_v4_step_6', 'imp-dd48c08a9b9ed207', 6, 'finish', 'Thấm ráo dầu thừa và dọn nóng', 'Vớt các khúc sườn ra đĩa có lót sẵn khăn giấy thấm dầu trong 2 phút để giữ độ giòn lâu, sau đó xếp ra đĩa sạch và dọn dùng nóng với cơm trắng hoặc chấm kèm tương ớt.', NULL, NULL),
('imp-b4924a7d33d5acff_v4_step_1', 'imp-b4924a7d33d5acff', 1, 'prep', 'Vo sạch và ngâm gạo tẻ cho nhanh nhừ', 'Vo sạch 150 g gạo tẻ qua 2 đến 3 lần nước, sau đó ngâm gạo trong nước lạnh khoảng 30 đến 60 phút cho hạt gạo hút nước nở mềm rồi chắt ráo bỏ nước ngâm.', 'Ngâm gạo trước giúp hạt gạo nhanh nở bung khi nấu, nồi cháo sánh mịn đều mà không tốn nhiều thời gian ninh.', 30),
('imp-b4924a7d33d5acff_v4_step_2', 'imp-b4924a7d33d5acff', 2, 'cook', 'Ninh gạo tẻ trên lửa liu riu đến khi sánh mịn', 'Cho gạo đã ngâm cùng 1600 ml nước lọc vào nồi đáy dày, đun sôi bùng trên lửa lớn rồi lập tức hạ xuống lửa nhỏ-vừa. Ninh liu riu khoảng 35 phút, thỉnh thoảng khuấy đều đáy nồi để tránh bén khét cho đến khi hạt gạo nở bung mềm nhừ và nước cháo sánh mịn.', 'Khuấy nhẹ sát đáy nồi khoảng mỗi 7–10 phút trong giai đoạn đầu để tinh bột gạo không lắng dính cháy đáy nồi.', 35),
('imp-b4924a7d33d5acff_v4_step_3', 'imp-b4924a7d33d5acff', 3, 'prep', 'Đánh tan trứng gà và thái hành gừng', 'Trong lúc chờ cháo nhừ, đập 3 quả trứng gà vào bát đánh thật tan đều lòng đỏ và lòng trắng. Rửa sạch hành lá tươi thái nhỏ, đồng thời thái sợi chỉ 10 g gừng tươi để riêng.', NULL, NULL),
('imp-b4924a7d33d5acff_v4_step_4', 'imp-b4924a7d33d5acff', 4, 'cook', 'Rưới trứng tạo vân mây và nêm gia vị', 'Khi nồi cháo đã đạt độ sánh mịn, giữ lửa vừa cho cháo sôi lăn tăn, một tay khuấy nhẹ cháo theo một chiều, tay kia rót từ từ bát trứng đánh tan thành dòng thật mảnh vào nồi để tạo thành những sợi vân trứng mềm mượt. Đun thêm 2 phút cho trứng chín hoàn toàn rồi nêm 4 g muối ăn, 2 g tiêu trắng xay và 3 g hạt nêm khuấy đều.', 'Rưới trứng thành dòng thật mảnh kết hợp khuấy chậm một chiều giúp vân trứng tơi mịn như lụa, không bị vón cục to.', 2),
('imp-b4924a7d33d5acff_v4_step_5', 'imp-b4924a7d33d5acff', 5, 'cook', 'Ủ hành lá với dầu ăn cho cháo bóng mượt', 'Cho hành lá thái nhỏ và 5 ml dầu ăn thực vật vào nồi cháo, khuấy nhẹ thêm một lượt rồi tắt bếp, đậy vung ủ 2 phút để hành lá chín tới giữ màu xanh tươi và bề mặt cháo óng mượt.', NULL, 2),
('imp-b4924a7d33d5acff_v4_step_6', 'imp-b4924a7d33d5acff', 6, 'finish', 'Múc cháo ra tô và rưới xì dầu nhạt', 'Múc cháo trứng vân mây nóng hổi ra tô, rắc gừng tươi thái sợi lên trên, rưới nhẹ vài giọt xì dầu nhạt (hoặc dọn chén xì dầu nhạt bên cạnh để tự nêm) rồi thưởng thức ngay.', NULL, NULL),
('imp-4a712c9f5f9913be_v4_step_1', 'imp-4a712c9f5f9913be', 1, 'prep', 'Sơ chế tôm tươi, cải thìa và nấm', 'Rửa sạch 340 g tôm tươi, bóc vỏ bỏ đầu, rút sạch chỉ đen dọc sống lưng rồi thấm ráo nước. Cải thìa tươi rửa sạch cắt khúc 4 cm, nấm mỡ trắng thái lát mỏng 0,5 cm, gừng tươi và tỏi khô băm nhuyễn, còn hành lá tươi thái nhỏ để riêng.', NULL, NULL),
('imp-4a712c9f5f9913be_v4_step_2', 'imp-4a712c9f5f9913be', 2, 'cook', 'Phi thơm gừng tỏi và xào săn tôm', 'Làm nóng nồi sâu lòng với 10 ml dầu ăn thực vật trên lửa vừa, cho gừng băm và tỏi băm vào phi thơm khoảng 40 giây đến khi dậy mùi mà không cháy xém. Tăng lên lửa lớn, thả tôm vào đảo nhanh khoảng 2 phút đến khi tôm chuyển màu hồng cam săn nhẹ thì gắp riêng ra đĩa.', 'Xào sơ tôm rồi vớt ra giúp tôm thơm mùi gừng tỏi mà không bị nấu quá lâu thành dai cứng trong lúc luộc mì.', 2),
('imp-4a712c9f5f9913be_v4_step_3', 'imp-4a712c9f5f9913be', 3, 'cook', 'Đun sôi nước dùng gà và luộc mì trứng', 'Đổ 700 ml nước dùng gà, 700 ml nước lọc cùng 25 ml xì dầu vào nồi vừa xào tôm, đun sôi bùng trên lửa lớn. Khi nước dùng sôi mạnh, thả 180 g mì trứng khô vào nấu khoảng 5 phút, thỉnh thoảng khuấy nhẹ để các sợi mì tơi đều và vừa chín mềm tới.', 'Chỉ luộc mì đến độ dai vừa phải vì mì sẽ tiếp tục hút thêm nước dùng nóng khi nấu tiếp cùng rau và tôm.', 5),
('imp-4a712c9f5f9913be_v4_step_4', 'imp-4a712c9f5f9913be', 4, 'cook', 'Nấu chín cải thìa và nấm thái lát', 'Thả cải thìa tươi và nấm thái lát vào nồi nước dùng, đun tiếp ở lửa vừa-lớn khoảng 2 phút đến khi cọng cải vừa chín tới xanh mướt và nấm chín mềm ngọt.', 'Cho cải thìa vào sau cùng gần lúc tắt bếp giúp rau giữ màu xanh đẹp mắt và độ giòn thanh tự nhiên.', 2),
('imp-4a712c9f5f9913be_v4_step_5', 'imp-4a712c9f5f9913be', 5, 'cook', 'Thả tôm trở lại và nêm nước dùng', 'Trút toàn bộ phần tôm đã xào trở lại nồi đun thêm 1 phút cho tôm nóng đều, chín chắc hoàn toàn bên trong và hòa quyện vị ngọt vào nước dùng. Nêm 3 g muối ăn và 1 g tiêu trắng xay, nếm thử và điều chỉnh lại cho vừa khẩu vị.', NULL, 1),
('imp-4a712c9f5f9913be_v4_step_6', 'imp-4a712c9f5f9913be', 6, 'finish', 'Múc mì ra tô, rưới dầu mè và dùng nóng', 'Chia đều mì trứng, tôm tươi, cải thìa và nấm ra 3 tô lớn, chan ngập nước dùng gà nóng hổi lên trên. Rưới 5 ml dầu mè thơm và rắc hành lá tươi thái nhỏ lên mặt tô mì rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-a27445c786a3fd67_v4_step_1', 'imp-a27445c786a3fd67', 1, 'prep', 'Thái hành tây, hành lá và tách rời thịt bò', 'Bóc vỏ hành tây, bổ đôi rồi thái lát mỏng đều nhau. Rửa sạch hành lá tươi và thái khoanh xéo mỏng; gọt vỏ gừng tươi và thái sợi thật mảnh (nếu dùng). Cắt 340 g thịt bò thái lát mỏng thành đoạn dài 6–7 cm và tách tơi từng lát.', 'Nếu tự thái thịt bò nguyên khối tại nhà, cho thịt vào ngăn đá khoảng 15 phút cho hơi se cứng rồi thái sẽ cho lát mỏng đều đẹp hơn.', NULL),
('imp-a27445c786a3fd67_v4_step_2', 'imp-a27445c786a3fd67', 2, 'sauce', 'Pha nước sốt om vào chảo nguội', 'Đặt chảo rộng còn nguội (chưa bật bếp) lên bàn, cho 180 ml nước dùng Dashi, 45 ml rượu Sake, 45 ml rượu ngọt Mirin, 60 ml xì dầu Nhật Bản và 18 g đường cát trắng vào khuấy đều cho đường tan bớt.', 'Xếp hành tây và thịt bò vào chảo nước sốt lạnh trước khi bật bếp giúp thịt thấm vị từ từ và giữ kết cấu mềm mại không bị co rút đột ngột.', NULL),
('imp-a27445c786a3fd67_v4_step_3', 'imp-a27445c786a3fd67', 3, 'prep', 'Xếp hành tây và thịt bò lên mặt sốt lạnh', 'Tách rời các lát hành tây rải đều xuống lớp đáy nước sốt, sau đó xếp từng lát thịt bò trải phủ thành một lớp đều lên trên hành tây, tránh để thịt vón cục chồng dày vào một chỗ.', NULL, NULL),
('imp-a27445c786a3fd67_v4_step_4', 'imp-a27445c786a3fd67', 4, 'cook', 'Đậy nắp om mềm thịt bò và hành tây', 'Đậy nắp chảo và bật bếp lửa vừa, đun đến khi nước sốt bắt đầu sôi lăn tăn thì hạ xuống lửa nhỏ, tiếp tục om đậy nắp khoảng 4 phút cho hành tây chín mềm ngọt và thịt bò chín đều.', 'Phải đậy nắp suốt lúc om để giữ hơi ẩm, giúp nước sốt không bị cạn gắt mà vẫn đủ phần nước ngon chan cơm.', 4),
('imp-a27445c786a3fd67_v4_step_5', 'imp-a27445c786a3fd67', 5, 'cook', 'Hớt bọt và thêm hành lá vào nồi', 'Mở nắp, dùng muôi lưới hớt sạch lớp bọt và váng mỡ nổi trên mặt nước sốt cho nước trong thanh. Rắc hành lá thái xéo lên trên thịt bò, đậy nắp om thêm 1 phút cho hành chín tới rồi tắt bếp.', NULL, 1),
('imp-a27445c786a3fd67_v4_step_6', 'imp-a27445c786a3fd67', 6, 'finish', 'Xới cơm nóng, phủ bò hành và thưởng thức', 'Xới 600 g cơm trắng hạt ngắn Nhật nóng hổi ra 3 tô lớn (200 g/tô), rưới trước một muỗng nước sốt om lên mặt cơm, sau đó gắp đều thịt bò và hành tây phủ kín lên trên, chan thêm chút sốt tùy thích và đặt ít gừng tươi thái sợi bên cạnh rồi thưởng thức nóng.', NULL, NULL),
('imp-aba623dc468a9569_v4_step_1', 'imp-aba623dc468a9569', 1, 'prep', 'Ngâm tảo bẹ Kombu lấy nước dùng umami', 'Dùng khăn sạch hơi ẩm lau nhẹ bụi trên 10 g tảo bẹ Kombu khô (giữ nguyên lớp phấn trắng tự nhiên trên bề mặt), sau đó thả vào nồi chứa 1200 ml nước lọc ngâm khoảng 20–30 phút cho tảo nở mềm và tiết vị ngọt.', 'Không rửa trực tiếp tảo bẹ Kombu dưới vòi nước mạnh vì sẽ làm trôi lớp phấn trắng tạo vị umami quý giá.', 20),
('imp-aba623dc468a9569_v4_step_2', 'imp-aba623dc468a9569', 2, 'prep', 'Ướp muối khử tanh cá hồi và sơ chế rau nấm', 'Cắt 400 g cá hồi phi lê thành miếng vuông vừa ăn khoảng 3 cm, rắc đều 2,5 g muối ăn lên các mặt cá và để yên 15 phút cho muối rút bớt dịch tanh. Trong lúc chờ, thái lát nấm đùi gà dày 0,5 cm, thái lát mỏng gừng tươi và cắt xéo hành lá.', NULL, 15),
('imp-aba623dc468a9569_v4_step_3', 'imp-aba623dc468a9569', 3, 'prep', 'Chần nhanh cá hồi theo kỹ thuật Shimofuri', 'Đun sôi một nồi nước nhỏ khác, thả nhanh các miếng cá hồi đã ướp muối vào trụng đúng 30 giây cho bề mặt thịt cá vừa se trắng rồi vớt ngay ra thau nước lạnh, rửa sạch nhẹ nhàng phần váng đục bám quanh cá và để ráo.', 'Kỹ thuật chần nhanh Shimofuri giúp loại bỏ hoàn toàn mùi tanh và giữ cho nồi nước canh sau khi nấu trong veo không bị váng đục.', 1),
('imp-aba623dc468a9569_v4_step_4', 'imp-aba623dc468a9569', 4, 'cook', 'Nấu nước dùng Kombu với nấm đùi gà và gừng', 'Đặt nồi nước ngâm tảo bẹ Kombu lên bếp đun trên lửa vừa; ngay khi thấy đáy nồi sủi bọt tăm lăn tăn chuẩn bị sôi thì vớt bỏ miếng tảo bẹ Kombu ra. Thêm 30 ml rượu Sake Nhật Bản, gừng thái lát và nấm đùi gà vào nồi, đun sôi nhẹ 5 phút và hớt bọt nếu có.', 'Vớt tảo bẹ Kombu ra ngay trước khi nước sôi bùng để tránh nước dùng bị nhớt hoặc có vị chát đắng.', 5),
('imp-aba623dc468a9569_v4_step_5', 'imp-aba623dc468a9569', 5, 'cook', 'Thả cá hồi vào nấu chín tới', 'Thả nhẹ từng miếng cá hồi đã chần vào nồi canh đang sôi lăn tăn, hạ lửa nhỏ và nấu khoảng 6 phút đến khi thịt cá hồi chuyển hồng cam đục đồng nhất, chín mềm tận lõi mà không bị nát vụn, đồng thời hớt sạch bọt nổi.', NULL, 6),
('imp-aba623dc468a9569_v4_step_6', 'imp-aba623dc468a9569', 6, 'finish', 'Nêm xì dầu, muối và hoàn thiện tô canh', 'Nêm 30 ml xì dầu Nhật Bản và 2,5 g muối ăn còn lại vào nồi canh, khuấy nhẹ tay và nếm lại cho vừa vị thanh ngọt. Cho hành lá thái xéo vào nồi rồi tắt bếp ngay, múc canh nóng ra 4 bát và thưởng thức.', NULL, NULL),
('imp-4f398ac575200416_v4_step_1', 'imp-4f398ac575200416', 1, 'prep', 'Sơ chế đùi gà, rau củ và bẻ nhỏ viên cà ri', 'Cắt 360 g thịt đùi gà rút xương thành miếng vừa ăn khoảng 2,5 cm. Bóc vỏ hành tây thái lát mỏng, gọt vỏ cà rốt thái lát hình bán nguyệt dày 0,4 cm, rửa sạch hành lá tươi thái khoanh nhỏ và bẻ nhỏ 75 g viên cà ri Nhật để sẵn. Bắc một nồi lớn chứa khoảng 980 ml nước lọc lên bếp chuẩn bị trụng mì.', NULL, NULL),
('imp-4f398ac575200416_v4_step_2', 'imp-4f398ac575200416', 2, 'cook', 'Xào thơm hành tây và thịt đùi gà', 'Làm nóng nồi đáy dày trên lửa vừa với 20 ml dầu ăn thực vật, cho hành tây thái lát vào xào khoảng 3 phút cho đến khi hành mềm trong và dậy mùi ngọt. Tiếp tục cho thịt đùi gà vào đảo đều đến khi mặt ngoài thịt săn trắng thì rưới 22 ml rượu Sake Nhật Bản vào xào thêm 1 phút.', NULL, 3),
('imp-4f398ac575200416_v4_step_3', 'imp-4f398ac575200416', 3, 'cook', 'Ninh cà rốt và đùi gà với nước dùng Dashi', 'Đổ 300 ml nước dùng Dashi, 600 ml nước lọc cùng cà rốt thái lát vào nồi thịt gà, đun sôi rồi hạ lửa vừa nhỏ, đậy nắp nấu khoảng 7 phút cho đến khi thịt gà chín hoàn toàn tận lõi và cà rốt mềm vừa ăn; hớt sạch bọt nổi nếu có.', 'Pha loãng Dashi với nước lọc và hớt bọt giúp nước cà ri Udon thanh mượt, vừa vị khi hòa cùng viên cà ri Nhật.', 7),
('imp-4f398ac575200416_v4_step_4', 'imp-4f398ac575200416', 4, 'cook', 'Trụng chín sợi mì Udon riêng', 'Trong lúc ninh nước dùng, đun sôi nồi nước lọc đã chuẩn bị và thả 3 gói mì Udon lúa mì vào trụng khoảng 2 phút (hoặc theo đúng hướng dẫn trên bao bì) cho sợi mì tơi mềm và nóng đều, sau đó vớt ra để ráo nước và chia vào 3 tô.', 'Trụng mì Udon ở nồi riêng thay vì thả trực tiếp vào nồi cà ri giúp sợi mì không bị nát và giữ độ dai mượt.', 2),
('imp-4f398ac575200416_v4_step_5', 'imp-4f398ac575200416', 5, 'sauce', 'Hòa tan viên cà ri Nhật và nêm xì dầu', 'Tắt bếp hoặc hạ xuống mức lửa nhỏ nhất ở nồi nước dùng, cho 75 g viên cà ri Nhật vào vá múc canh, khuấy tan dần với nước dùng nóng cho tan mịn hoàn toàn rồi hòa đều vào nồi. Bật lại lửa nhỏ, thêm 10 ml xì dầu Nhật Bản, khuấy đều 2 phút đến khi nước cà ri sánh mịn; nếu muốn sánh hơn có thể hòa tan 10 g bột bắp với 20 ml nước lọc rót từ từ vào khuấy nhẹ.', 'Hòa tan viên cà ri khi nước không sôi mạnh giúp ngăn roux chìm xuống đáy nồi và cháy khét.', 2),
('imp-4f398ac575200416_v4_step_6', 'imp-4f398ac575200416', 6, 'finish', 'Chan nước cà ri lên mì Udon và thưởng thức nóng', 'Chan đều nước sốt cà ri gà nóng hổi kèm thịt và cà rốt phủ ngập mì Udon trong từng tô, rắc hành lá thái nhỏ lên mặt và dùng ngay khi còn nóng.', NULL, NULL),
('imp-b8731e057182331b_v4_step_1', 'imp-b8731e057182331b', 1, 'prep', 'Thái sợi bắp cải và hành lá', 'Tách bỏ lá già bên ngoài của 480 g bắp cải tươi, bổ tư cắt bỏ lõi cứng rồi thái thành sợi mỏng đều khoảng 0,5 cm, rửa sạch và vẩy thật ráo. Rửa sạch hành lá tươi, thấm khô và thái khoanh mỏng.', NULL, NULL),
('imp-b8731e057182331b_v4_step_2', 'imp-b8731e057182331b', 2, 'prep', 'Bóp muối nhẹ cho bắp cải dịu giòn và vắt ráo', 'Cho bắp cải thái sợi vào tô lớn, rắc 2 g muối ăn rồi dùng tay bóp nhẹ nhàng khoảng 1 phút cho muối bám đều, để yên 5 phút cho bắp cải ra bớt nước hăng. Sau đó dùng tay vắt nhẹ cho ráo nước nhưng không vắt quá kiệt để bắp cải vẫn giữ độ giòn mát.', 'Vắt bắp cải vừa ráo tay giúp sợi rau giòn ngọt và thấm sốt đậm đà mà không bị dai hay làm loãng sốt trộn.', 5),
('imp-b8731e057182331b_v4_step_3', 'imp-b8731e057182331b', 3, 'prep', 'Rang thơm và giã dập hạt mè trắng', 'Cho 18 g hạt mè trắng vào chảo khô, rang trên lửa nhỏ khoảng 3 phút và đảo đều tay đến khi mè vàng nhạt dậy mùi thơm bùi thì trút ra đĩa cho nguội bớt. Cho 2/3 lượng mè vào cối giã dập thơm dầu, giữ lại 1/3 nguyên hạt để rắc mặt.', 'Đảo liên tục trên lửa nhỏ khi rang vì hạt mè rất nhỏ và dễ cháy khét nếu để chảo quá nóng.', 3),
('imp-b8731e057182331b_v4_step_4', 'imp-b8731e057182331b', 4, 'sauce', 'Pha sốt trộn mè xì dầu giấm gạo', 'Trong tô nhỏ, trộn đều phần hạt mè trắng đã giã dập với 15 ml xì dầu Nhật Bản, 10 g đường cát trắng, 8 ml dầu mè thơm và 10 ml giấm gạo Nhật đến khi đường tan hết tạo thành hỗn hợp sốt sánh thơm.', 'Khuấy kỹ đến khi đường tan hoàn toàn để khi trộn gia vị bám đều lên từng sợi bắp cải.', NULL),
('imp-b8731e057182331b_v4_step_5', 'imp-b8731e057182331b', 5, 'prep', 'Trộn đều bắp cải với hành lá và sốt mè', 'Cho bắp cải đã vắt ráo và hành lá thái mỏng vào tô lớn, rưới đều toàn bộ sốt mè lên trên và trộn đều tay cho sốt phủ kín từng sợi rau.', NULL, NULL),
('imp-b8731e057182331b_v4_step_6', 'imp-b8731e057182331b', 6, 'finish', 'Ủ thấm vị, rắc mè nguyên hạt và bày đĩa', 'Để bắp cải trộn nghỉ khoảng 3 phút cho gia vị thấm sâu rồi đảo nhẹ lại lần cuối, bày ra đĩa, rắc nốt phần hạt mè trắng nguyên hạt lên trên và thưởng thức mát.', NULL, NULL),
('imp-f04b28987d7cd34a_v4_step_1', 'imp-f04b28987d7cd34a', 1, 'prep', 'Xả băng và cắt tách nửa vỏ chân cua', 'Nếu dùng chân cua đông lạnh, xả nhanh dưới vòi nước chảy cho sạch lớp băng bọc ngoài rồi để rã đông hoàn toàn và thấm ráo. Dùng kéo bếp sắc cắt dọc hai bên mép mỗi chân cua, nhẹ nhàng tách bỏ nửa mặt vỏ phía trên để lộ phần thịt cua bên trong và dùng khăn giấy thấm khô nước đọng.', 'Cắt mở sẵn nửa vỏ trước khi nướng giúp người ăn thưởng thức dễ dàng mà không bị bỏng tay khi tách vỏ nóng.', NULL),
('imp-f04b28987d7cd34a_v4_step_2', 'imp-f04b28987d7cd34a', 2, 'marinate', 'Rưới rượu Sake và rắc muối biển thô lên vỏ cua', 'Rưới đều 30 ml rượu Sake Nhật Bản lên phần thịt cua đã lộ mặt để khử mùi tanh hải sản và giữ độ mọng nước. Rắc đều 15 g muối ăn hạt thô lên khắp mặt vỏ và viền cua; đồng thời thái nhỏ hành lá tươi và cắt múi cau quả chanh vàng để sẵn.', 'Rắc muối chủ yếu lên mặt vỏ giúp tạo lớp hương biển thơm mặn tự nhiên mà thịt cua bên trong vẫn ngọt thanh, không bị gắt.', NULL),
('imp-f04b28987d7cd34a_v4_step_3', 'imp-f04b28987d7cd34a', 3, 'cook', 'Làm nóng vỉ nướng than hoặc lò nướng', 'Làm nóng bếp than hoa hoặc vỉ nướng điện ở mức nhiệt vừa lớn trong khoảng 4 phút cho mặt vỉ thật nóng đều.', NULL, NULL),
('imp-f04b28987d7cd34a_v4_step_4', 'imp-f04b28987d7cd34a', 4, 'cook', 'Nướng cua úp mặt vỏ trước trong 5 phút', 'Đặt các chân cua lên vỉ với phần vỏ bên dưới hướng xuống lửa, nướng khoảng 5 phút cho vỏ cua chuyển màu đỏ cam rực, hơi xém cạnh và phần nước ngọt trong vỏ bắt đầu sôi lăn tăn.', NULL, 5),
('imp-f04b28987d7cd34a_v4_step_5', 'imp-f04b28987d7cd34a', 5, 'cook', 'Phết bơ lạt và nướng chín tới thịt cua', 'Lật hoặc giữ nguyên mặt thịt hướng lên tùy độ nóng vỉ, đặt 20 g bơ lạt cắt nhỏ lên mặt thịt cua rồi nướng tiếp trên lửa vừa thêm 4–5 phút đến khi thịt cua chuyển màu trắng đục săn chắc hoàn toàn và bơ tan thơm lừng.', 'Không nướng quá lâu sau khi thịt cua đã đục săn để tránh làm thịt bị khô xơ và mất nước ngọt tự nhiên.', 5),
('imp-f04b28987d7cd34a_v4_step_6', 'imp-f04b28987d7cd34a', 6, 'finish', 'Bày đĩa, rắc hành lá và thưởng thức kèm chanh xì dầu', 'Gắp cua nướng ra đĩa lớn, rắc hành lá thái nhỏ lên mặt thịt cua, xếp các múi chanh vàng xung quanh và dọn kèm chén xì dầu Nhật Bản để vắt chanh chấm thưởng thức nóng.', NULL, NULL),
('imp-bf6c9c4d92b2e04c_v4_step_1', 'imp-bf6c9c4d92b2e04c', 1, 'prep', 'Cắt tỉa và làm sạch tôm tươi với muối', 'Dùng kéo cắt gọn phần râu, chân và gai nhọn ở đuôi của 300 g tôm tươi nguyên con, dùng tăm xiên qua đốt lưng thứ 2 rút bỏ chỉ đen. Xát nhẹ tôm với 5 g muối ăn rồi rửa thật sạch dưới vòi nước lạnh và để ráo.', NULL, NULL),
('imp-bf6c9c4d92b2e04c_v4_step_2', 'imp-bf6c9c4d92b2e04c', 2, 'prep', 'Thái gừng tươi hai kiểu và cắt hành lá', 'Gọt vỏ 45 g gừng tươi: lấy 25 g thái lát mỏng 0,5 cm để om lấy hương, 20 g còn lại thái sợi thật mảnh và ngâm nhanh qua nước mát cho giòn bớt hăng. Rửa sạch hành lá tươi và thái khoanh mỏng.', NULL, NULL),
('imp-bf6c9c4d92b2e04c_v4_step_3', 'imp-bf6c9c4d92b2e04c', 3, 'sauce', 'Đun sôi hỗn hợp nước om Nhật Bản', 'Cho 300 ml nước lọc, 45 ml rượu Sake Nhật Bản, 45 ml rượu ngọt Mirin, 45 ml xì dầu Nhật Bản và 18 g đường cát trắng vào nồi nông rộng đáy, khuấy cho đường tan bớt rồi đun trên lửa vừa đến khi sôi. Thả 25 g gừng thái lát vào nồi nước om.', 'Dùng nồi đáy rộng để xếp tôm thành một lớp phẳng giúp từng con tôm ngập đều trong nước sốt mà không bị dập nát.', NULL),
('imp-bf6c9c4d92b2e04c_v4_step_4', 'imp-bf6c9c4d92b2e04c', 4, 'cook', 'Xếp tôm om thấm vị trong 5 phút', 'Khi nước om sôi đều trở lại, nhẹ nhàng xếp tôm thành một lớp trong nồi, đậy hé vung (hoặc đặt giấy bạc khoét lỗ phủ nhẹ mặt tôm) và om trên lửa vừa khoảng 5 phút cho đến khi vỏ tôm đỏ au, thịt chín đục săn chắc; trong lúc om dùng muôi hớt sạch bọt nổi.', 'Tôm chín nhanh nên chỉ om đúng khoảng 5 phút trên lửa vừa để thịt giữ độ giòn ngọt, tránh om quá lâu làm tôm dai.', 5),
('imp-bf6c9c4d92b2e04c_v4_step_5', 'imp-bf6c9c4d92b2e04c', 5, 'cook', 'Tắt bếp ngâm ủ cho tôm ngấm sâu nước sốt', 'Tắt bếp và giữ nguyên tôm trong nồi nước om ấm khoảng 8–10 phút để tôm từ từ hút ngược hương vị gừng xì dầu ngọt thanh vào tận bên trong thịt.', 'Bước ngâm ủ sau khi tắt bếp là bí quyết của món om Nhật giúp hải sản thấm vị sâu mà thịt không bị co khô do nhiệt.', 8),
('imp-bf6c9c4d92b2e04c_v4_step_6', 'imp-bf6c9c4d92b2e04c', 6, 'finish', 'Bày đĩa, rắc gừng sợi và hành lá thưởng thức', 'Gắp tôm om xếp gọn ra đĩa sâu lòng, rưới 2–3 muỗng canh nước om ấm lên trên, phủ phần gừng tươi thái sợi mảnh cùng hành lá thái nhỏ lên mặt và dùng nóng với cơm trắng.', NULL, NULL),
('imp-92aabff659e3c551_v4_step_1', 'imp-92aabff659e3c551', 1, 'prep', 'Thấm khô thịt đùi gà và trộn hỗn hợp bột áo', 'Dùng khăn giấy thấm thật khô hai mặt 550 g thịt đùi gà rút xương rồi cắt thành miếng vừa ăn cỡ 4 cm. Trong tô lớn, trộn đều 32 g bột bắp, 31 g bột mì đa dụng, 2 g bột tỏi, 2 g muối ăn và 1 g tiêu đen xay. Lăn từng miếng gà qua tô bột khô cho áo một lớp mỏng đều rồi giũ nhẹ cho rơi hết bột thừa.', 'Thịt gà ráo nước và lớp bột áo mỏng vừa phải sẽ giúp gà áp chảo giòn rụm mà không bị bở bột khi gặp sốt.', NULL),
('imp-92aabff659e3c551_v4_step_2', 'imp-92aabff659e3c551', 2, 'sauce', 'Băm nhuyễn tỏi và khuấy sẵn chén sốt mật ong xì dầu', 'Băm nhuyễn 37 g tỏi khô và thái nhỏ hành lá. Trong bát con, khuấy tan đều 50 ml xì dầu đặc, 60 ml nước lọc, 30 ml mật ong nguyên chất, 30 ml giấm gạo, 25 g đường nâu, 5 ml dầu mè rang và 2 g ớt vảy khô đến khi đường tan hết.', NULL, NULL),
('imp-92aabff659e3c551_v4_step_3', 'imp-92aabff659e3c551', 3, 'cook', 'Áp chảo thịt đùi gà vàng giòn và chín hoàn toàn', 'Làm nóng chảo rộng đáy phẳng trên lửa vừa–lớn với 20 ml dầu ăn đến khi dầu hơi gợn sóng. Xếp gà thành một lớp phẳng (mặt da úp xuống trước), áp chảo khoảng 3 phút mỗi mặt đến khi lớp vỏ vàng giòn, thịt bên trong chín trắng hoàn toàn và nước thịt trong (không còn hồng đỏ ở lõi).', 'Không xếp chồng miếng gà quá dày trong chảo vì hơi nước tích tụ sẽ làm lớp bột bị mềm ỉu thay vì giòn.', 6),
('imp-92aabff659e3c551_v4_step_4', 'imp-92aabff659e3c551', 4, 'cook', 'Phi thơm tỏi băm ngay trên chảo nóng', 'Gạt nhẹ các miếng gà sang mép chảo, thả toàn bộ tỏi băm vào phần dầu nóng giữa chảo và đảo nhanh tay khoảng 30 giây đến khi tỏi dậy mùi thơm nức mà chưa kịp chuyển sậm cháy.', 'Tỏi băm rất dễ cháy đắng trên chảo nóng; ngay khi vừa thấy mùi thơm bốc lên hãy đổ bát sốt vào liền.', NULL),
('imp-92aabff659e3c551_v4_step_5', 'imp-92aabff659e3c551', 5, 'cook', 'Rim gà với sốt tỏi mật ong đến khi sánh bóng', 'Đổ chén sốt đã pha vào chảo, hạ xuống lửa vừa và đảo đều liên tục khoảng 4–5 phút đến khi nước sốt sôi nhẹ, keo sánh lại thành lớp men nâu cánh gián bóng mượt bám chặt quanh từng miếng gà.', NULL, 5),
('imp-92aabff659e3c551_v4_step_6', 'imp-92aabff659e3c551', 6, 'finish', 'Bày đĩa, rắc hành lá và hạt mè trang trí', 'Tắt bếp, gắp gà ra đĩa sâu lòng rồi rưới hết phần sốt tỏi sánh trong chảo phủ lên trên. Rắc hành lá thái nhỏ cùng hạt mè trắng rang tùy thích và dùng nóng ngay với cơm trắng.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-4b592ae31a81a527_v4_step_1', 'imp-4b592ae31a81a527', 1, 'prep', 'Thấm sạch thịt bò và sơ chế nguyên liệu thơm', 'Dùng khăn giấy lau sạch phần nước đỏ trên bề mặt 550 g thịt bò rồi cắt thành khối vuông lớn cỡ 5x5 cm để thịt giữ được thớ dài đẹp mắt sau khi hầm. Bóc vỏ giữ nguyên tép tỏi khô (chia riêng 20 g để hầm nước đầu và 30 g để kho sau), cắt khúc hành lá, thái lát gừng tươi và cắt khúc 2 cm ớt sừng tươi.', 'Cắt thịt bò thành khối lớn trước khi hầm giúp các thớ thịt dài đều, khi xé tay sẽ mềm tơi và không bị vụn nát.', NULL),
('imp-4b592ae31a81a527_v4_step_2', 'imp-4b592ae31a81a527', 2, 'cook', 'Hầm mềm thịt bò với hành lá, gừng và tỏi khử mùi', 'Cho thịt bò và 1.000 ml nước lọc vào nồi sâu lòng, đun lửa lớn 4 phút đến khi sôi mạnh rồi hớt sạch bọt nổi. Hạ xuống lửa vừa, thả hành lá, gừng tươi và 20 g tỏi khô vào hầm đậy nắp 30 phút cho thịt chín mềm. Vớt bỏ toàn bộ hành lá, gừng và 20 g tỏi đã hầm để nước dùng thật trong.', 'Vớt bỏ phần rau củ hầm nước đầu giúp nước kho thanh vị, không bị đắng hay đục khi cô đặc ở bước sau.', 30),
('imp-4b592ae31a81a527_v4_step_3', 'imp-4b592ae31a81a527', 3, 'cook', 'Kho thịt bò với xì dầu và đường đến khi cạn một nửa', 'Rót 110 ml xì dầu và cho 28 g đường cát trắng vào nồi thịt bò đang sôi, khuấy nhẹ cho đường tan hết. Tiếp tục kho trên lửa vừa–nhỏ không đậy nắp trong 30 phút đến khi nước kho cạn còn khoảng một nửa và khối thịt ngấm màu nâu đậm đẹp mắt.', NULL, 30),
('imp-4b592ae31a81a527_v4_step_4', 'imp-4b592ae31a81a527', 4, 'cook', 'Kho tỏi nguyên tép bùi thơm và ớt sừng tươi', 'Thả 30 g tỏi nguyên tép còn lại vào nồi kho thêm 10 phút cho tỏi chín bùi thấm vị tương. Cuối cùng cho ớt sừng tươi cắt khúc và 1 g tiêu đen xay vào đun thêm 3 phút cho dậy hương cay nhẹ rồi tắt bếp.', NULL, 13),
('imp-4b592ae31a81a527_v4_step_5', 'imp-4b592ae31a81a527', 5, 'finish', 'Vớt thịt bò xé dọc thớ và chan nước kho', 'Gắp các khối thịt bò ra đĩa đợi nguội bớt khoảng 5 phút rồi dùng tay xé dọc theo thớ thịt thành từng miếng dày cỡ 1 cm.', 'Xé thịt dọc theo chiều thớ tự nhiên giúp thịt bò kho giữ được độ mềm dai hấp dẫn và dễ thấm nước tương khi chấm.', 5),
('imp-4b592ae31a81a527_v4_step_6', 'imp-4b592ae31a81a527', 6, 'finish', 'Trình bày đĩa thịt bò kho tương Hàn Quốc', 'Xếp thịt bò xé lên đĩa sâu lòng, gắp tỏi kho và ớt sừng bày xung quanh rồi rưới ngập nước kho xì dầu đậm đà lên trên. Dọn ăn cùng cơm trắng nóng.', NULL, NULL),
('imp-72e70eb4e8fba4db_v4_step_1', 'imp-72e70eb4e8fba4db', 1, 'marinate', 'Làm sạch tôm và ướp cùng nước kim chi, tỏi gừng', 'Tôm tươi bóc vỏ, rút sạch chỉ đen dọc lưng, rửa qua nước lạnh rồi thấm thật khô bằng khăn giấy. Cắt kim chi cải thảo thành miếng vừa ăn và chắt riêng 25 ml nước kim chi. Trộn tôm trong tô với tỏi băm, gừng tươi băm nhuyễn, 25 ml nước kim chi và 1 g tiêu đen xay (nếu dùng), ướp trong ngăn mát 15 phút cho thấm vị.', 'Thấm thật khô tôm trước khi ướp và áp chảo giúp tôm xém mặt nhanh, giòn ngọt và không ra nhiều nước.', 15),
('imp-72e70eb4e8fba4db_v4_step_2', 'imp-72e70eb4e8fba4db', 2, 'prep', 'Thái cải thảo, ớt chuông và hành lá', 'Cải thảo rửa sạch, thái sợi bản 1 cm cho nhanh chín; ớt chuông đỏ bỏ lõi hạt, thái sợi dài vừa ăn; hành lá rửa sạch, cắt khúc 3–4 cm để riêng.', NULL, NULL),
('imp-72e70eb4e8fba4db_v4_step_3', 'imp-72e70eb4e8fba4db', 3, 'cook', 'Áp chảo tôm với bơ lạt đến khi chín hồng', 'Làm nóng chảo rộng trên lửa vừa, thả 25 g bơ lạt vào đun tan chảy hoàn toàn. Xếp tôm đã ướp thành một lớp và áp chảo khoảng 2 phút mỗi mặt đến khi tôm chuyển màu hồng cam tươi, thân cong săn lại và phần thịt đục chín hoàn toàn (không còn trong). Gắp tôm ra đĩa riêng, giữ lại phần bơ thơm trong chảo.', 'Vớt tôm ra trước khi xào rau giúp tôm không bị nấu quá lửa dẫn đến dai và mất độ giòn.', 4),
('imp-72e70eb4e8fba4db_v4_step_4', 'imp-72e70eb4e8fba4db', 4, 'cook', 'Xào cải thảo và ớt chuông giữ độ giòn tươi', 'Thêm 10 ml dầu ăn vào chảo bơ, tăng bếp lên lửa vừa–lớn rồi trút cải thảo và ớt chuông đỏ vào đảo nhanh tay khoảng 3 phút cho rau vừa chín tới vẫn giữ màu tươi và độ giòn nhẹ (rắc thêm chút muối ăn nếu thích vị đậm hơn).', NULL, 3),
('imp-72e70eb4e8fba4db_v4_step_5', 'imp-72e70eb4e8fba4db', 5, 'cook', 'Xào kim chi với xì dầu và trộn lại cùng tôm', 'Thả kim chi cải thảo đã cắt khúc cùng 30 ml xì dầu vào chảo rau, đảo đều khoảng 1 phút cho kim chi nóng dậy mùi thơm mà vẫn giữ được độ giòn chua đặc trưng. Tắt bếp rồi trút toàn bộ tôm đã áp chảo trở lại chảo, đảo nhanh tay cho tôm quyện đều sốt.', 'Chỉ cho kim chi vào xào ngắn 1 phút ở cuối để giữ trọn độ giòn và vị chua thanh tươi mới.', 1),
('imp-72e70eb4e8fba4db_v4_step_6', 'imp-72e70eb4e8fba4db', 6, 'finish', 'Rưới dầu mè, rắc hành lá và mè rang hoàn thiện', 'Rưới 8 ml dầu mè rang lên khắp mặt chảo, cho hành lá cắt khúc vào đảo đều lần cuối. Bày tôm xào kim chi ra đĩa, rắc hạt mè trắng rang tùy thích và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-88b58c0233dec53e_v4_step_1', 'imp-88b58c0233dec53e', 1, 'prep', 'Cắt nhỏ kim chi và thái nhuyễn hành lá', 'Gắp 150 g kim chi cải thảo ra thớt, vắt nhẹ lấy khoảng 25 ml nước kim chi để riêng rồi cắt phần cái thành miếng nhỏ cỡ 1,5 cm để dễ hòa quyện với trứng. Hành lá rửa sạch, thái nhuyễn để rắc hoàn thiện.', NULL, NULL),
('imp-88b58c0233dec53e_v4_step_2', 'imp-88b58c0233dec53e', 2, 'prep', 'Đánh tan trứng gà với dầu mè và gia vị', 'Đập 6 quả trứng gà vào tô lớn, thêm 4 ml dầu mè rang, 5 ml xì dầu (tùy chọn), 1,5 g muối ăn và 1 g tiêu đen xay. Dùng đũa hoặc phới lồng đánh đều tay đến khi lòng trắng và lòng đỏ hòa quyện hoàn toàn, nổi bọt nhẹ.', 'Không cho quá nhiều muối vì kim chi và xì dầu đã mặn sẵn; giữ lại phần nước kim chi để rưới hoặc nêm nhẹ sau cùng giúp trứng không bị vón tách nước.', NULL),
('imp-88b58c0233dec53e_v4_step_3', 'imp-88b58c0233dec53e', 3, 'cook', 'Xào thơm kim chi trên chảo chống dính', 'Làm nóng chảo chống dính trên lửa vừa với 20 ml dầu ăn, cho kim chi cắt nhỏ vào xào đều trong 2 phút đến khi kim chi săn ráo và dậy mùi chua cay thơm nồng.', NULL, 2),
('imp-88b58c0233dec53e_v4_step_4', 'imp-88b58c0233dec53e', 4, 'cook', 'Đổ trứng và đảo nhẹ ở lửa nhỏ tạo mảng mềm mịn', 'Hạ bếp xuống lửa nhỏ, rót từ từ tô trứng đã đánh tan vào chảo kim chi rồi rưới nhẹ 25 ml nước kim chi lên trên. Dùng phới silicon gạt nhẹ nhàng từ mép chảo vào giữa theo từng đường chậm rãi trong 3–4 phút cho trứng đông thành từng mảng bông mềm, ẩm mướt.', 'Giữ lửa nhỏ và đảo chậm tay là bí quyết giúp trứng chín mềm mịn như lụa, không bị khô xác hay cháy đáy.', 4),
('imp-88b58c0233dec53e_v4_step_5', 'imp-88b58c0233dec53e', 5, 'finish', 'Tắt bếp sớm tận dụng nhiệt dư', 'Khi mặt trứng vừa se lại nhưng vẫn còn hơi bóng ẩm khoảng 90%, tắt bếp ngay và đảo nhẹ thêm 10 giây để nhiệt dư trong chảo làm trứng chín vừa tới hoàn hảo mà không bị dai.', 'Không đợi trứng khô hẳn trên bếp mới tắt vì hơi nóng của chảo sẽ tiếp tục làm trứng cứng và bớt béo.', NULL),
('imp-88b58c0233dec53e_v4_step_6', 'imp-88b58c0233dec53e', 6, 'finish', 'Bày đĩa, rắc hành lá và mè rang dùng nóng', 'Trút trứng xào kim chi ra đĩa, rắc hành lá thái nhuyễn và hạt mè trắng rang tùy thích lên trên rồi dọn ăn nóng ngay với cơm trắng.', NULL, NULL),
('imp-e5d49dd8dc1449d1_v4_step_1', 'imp-e5d49dd8dc1449d1', 1, 'marinate', 'Sơ chế và ướp thịt ba chỉ khử mùi với Mirin', 'Thịt ba chỉ heo rửa sạch, thấm khô rồi cắt thành từng miếng dày 1,5 cm, dài 6 cm. Cho thịt vào tô ướp cùng 30 ml rượu Mirin Nhật và 1 g tiêu đen xay, trộn đều rồi để nghỉ 10 phút cho thịt thơm và nhanh mềm khi kho.', 'Nên chọn loại kim chi cải thảo đã lên men chua kỹ ít nhất 3–4 tuần thì khi kho cùng thịt ba chỉ mới dậy được vị chua sâu đặc trưng.', 10),
('imp-e5d49dd8dc1449d1_v4_step_2', 'imp-e5d49dd8dc1449d1', 2, 'sauce', 'Pha sốt tương Doenjang ớt bột và thái hành', 'Băm nhuyễn gừng tươi và tỏi khô, trộn đều trong chén nhỏ với 8 g ớt bột Hàn Quốc (Gochugaru), 15 ml xì dầu, 10 g tương đậu tương Hàn (Doenjang) và 6 g đường cát trắng thành hỗn hợp sốt sệt. Thái lát mỏng hành tây, thái vát hành lá và ớt sừng tươi.', NULL, NULL),
('imp-e5d49dd8dc1449d1_v4_step_3', 'imp-e5d49dd8dc1449d1', 3, 'cook', 'Xếp lớp kim chi, thịt ba chỉ và rưới sốt vào nồi kho', 'Xếp toàn bộ 750 g kim chi cải thảo cùng nước kim chi xuống đáy nồi gang hoặc nồi đáy dày, xếp thịt ba chỉ đã ướp lên trên mặt kim chi rồi rải đều hành tây thái lát. Phết hết phần sốt tương đã trộn lên trên thịt và từ từ rót 250 ml nước lọc (hoặc nước vo gạo lần hai) vào quanh thành nồi.', 'Xếp kim chi lót dưới đáy và đặt thịt lên trên giúp mỡ ba chỉ tiết xuống thấm vào từng bẹ kim chi, đồng thời ngăn thịt bị bén cháy đáy nồi.', NULL),
('imp-e5d49dd8dc1449d1_v4_step_4', 'imp-e5d49dd8dc1449d1', 4, 'cook', 'Đun sôi bùng và kho liu riu đến khi thịt mềm tan', 'Đậy kín nắp nồi, đun trên lửa lớn khoảng 5 phút cho nước kho sôi bùng lên. Sau đó hạ xuống lửa nhỏ, tiếp tục kho liu riu đậy nắp trong 55 phút, thỉnh thoảng mở nắp múc nước kho rưới lên mặt thịt cho đến khi thịt ba chỉ chín mềm nhừ hoàn toàn và kim chi chuyển màu trong mướt.', 'Nếu thấy nước cạn nhanh khi kho gần đủ thời gian, có thể châm thêm 50 ml nước nóng để món kho giữ được độ sánh ẩm.', 55),
('imp-e5d49dd8dc1449d1_v4_step_5', 'imp-e5d49dd8dc1449d1', 5, 'finish', 'Cân chỉnh vị cuối và cắt kim chi vừa ăn', 'Mở nắp nếm thử nước kho: nếu kim chi quá chua có thể thêm một chút đường, còn nếu nhạt thì chỉnh thêm ít xì dầu. Dùng kéo bếp và kẹp gắp cắt kim chi trong nồi thành những khúc ngắn vừa gắp.', NULL, NULL),
('imp-e5d49dd8dc1449d1_v4_step_6', 'imp-e5d49dd8dc1449d1', 6, 'finish', 'Rắc hành lá, ớt sừng và dọn nóng cùng cơm', 'Tắt bếp, rắc hành lá và ớt sừng tươi thái lát lên mặt nồi thịt ba chỉ kho kim chi. Dọn nóng trực tiếp hoặc múc ra đĩa sâu lòng để thưởng thức cùng cơm trắng.', NULL, NULL),
('imp-daec3b038c4f43af_v4_step_1', 'imp-daec3b038c4f43af', 1, 'prep', 'Làm sạch, khứa thân và ướp cá thu với muối, rượu', 'Rửa sạch cá thu Nhật cả ngoài da lẫn phần màng đen dọc sống lưng trong bụng cá, dùng khăn giấy thấm thật khô nước. Khứa 3–4 đường chéo sâu vừa phải lên mỗi bên thân cá để cá chín đều và không bị nổ da. Thoa đều 30 ml rượu gạo nấu ăn (nếu dùng) để 10 phút rồi thấm khô lại, sau đó phết 20 ml dầu ăn và rắc đều 4 g muối ăn lên cả hai mặt cá.', 'Thấm thật khô thân cá và phết lớp dầu ăn mỏng lên da cá là bí quyết giúp da cá giòn rụm và không bị dính rách vào vỉ nướng.', 10),
('imp-daec3b038c4f43af_v4_step_2', 'imp-daec3b038c4f43af', 2, 'sauce', 'Pha chén nước tương xì dầu tỏi ớt chanh tươi', 'Băm thật nhuyễn tỏi khô, thái nhỏ hành lá và ngò rí, vắt chanh tươi lấy khoảng 25 ml nước cốt (bỏ hạt). Trong chén, khuấy tan 55 ml xì dầu nhạt, 15 ml nước lọc, nước cốt chanh, tỏi băm, 4 g ớt bột Hàn Quốc (Gochugaru), hành lá thái nhỏ, 10 ml dầu mè rang và 5 g hạt mè trắng rang giã dập.', NULL, NULL),
('imp-daec3b038c4f43af_v4_step_3', 'imp-daec3b038c4f43af', 3, 'cook', 'Làm nóng vỉ nướng và nướng vàng mặt đầu tiên', 'Làm nóng vỉ nướng (hoặc lò nướng chế độ 220°C) và phết 10 ml dầu ăn còn lại lên bề mặt vỉ. Đặt cá thu lên vỉ, nướng ở lửa vừa–lớn khoảng 7 phút cho đến khi lớp da mặt dưới săn vàng giòn và tỏa mùi thơm béo.', 'Chỉ nên lật cá đúng một lần khi mặt dưới đã vàng giòn hẳn để tránh làm nát thịt cá.', 7),
('imp-daec3b038c4f43af_v4_step_4', 'imp-daec3b038c4f43af', 4, 'cook', 'Lật mặt cá nướng chín đều toàn thân', 'Dùng xẻng bản rộng nhẹ nhàng lật cá sang mặt còn lại, tiếp tục nướng thêm 6–7 phút đến khi cả hai mặt da vàng giòn đều và phần thịt ở chỗ dày nhất chuyển trắng đục hoàn toàn, dễ tách khỏi xương.', 'Nếu không có vỉ nướng, có thể áp chảo chống dính lửa vừa mỗi mặt 6–7 phút với nắp hé nhẹ để cá chín đều từ trong ra ngoài.', 7),
('imp-daec3b038c4f43af_v4_step_5', 'imp-daec3b038c4f43af', 5, 'finish', 'Rưới nước tương chấm và rắc ngò rí lên mặt cá', 'Gắp cá thu nướng ra đĩa dài, múc một nửa lượng nước tương tỏi ớt chanh đã pha rưới đều lên thân cá nóng rồi rắc ngò rí thái nhỏ lên trên để tăng hương thơm tươi mát.', NULL, NULL),
('imp-daec3b038c4f43af_v4_step_6', 'imp-daec3b038c4f43af', 6, 'finish', 'Dọn cá nướng nóng kèm chén nước chấm và cơm trắng', 'Đặt phần nước tương chấm còn lại vào chén nhỏ dọn bên cạnh để chấm thêm khi ăn cùng cơm trắng nóng dẻo.', NULL, NULL),
('imp-4ca7d6f55d5b7937_v4_step_1', 'imp-4ca7d6f55d5b7937', 1, 'prep', 'Thái sợi rau củ, thịt bò và pha chén sốt Japchae', 'Thái sợi diêm cà rốt, thái lát mỏng hành tây và nấm hương tươi, cắt khúc 5 cm hành lá và thái thịt thăn bò thành sợi mỏng dài 5 cm. Băm nhuyễn tỏi khô rồi cho vào chén khuấy tan cùng 40 ml xì dầu, 25 g đường nâu, 20 ml dầu mè rang, 4 g hạt mè trắng rang và 1,5 g tiêu đen xay.', 'Dùng đường nâu pha sốt giúp sợi miến lên màu nâu óng ả đẹp mắt và thơm dịu hơn so với đường trắng.', NULL),
('imp-4ca7d6f55d5b7937_v4_step_2', 'imp-4ca7d6f55d5b7937', 2, 'cook', 'Luộc mềm miến khoai lang và chần rau chân vịt', 'Đun sôi 1.200 ml nước lọc trong nồi rộng, thả 150 g miến khoai lang Hàn vào luộc khoảng 7 phút đến khi sợi miến trong suốt và mềm dẻo hoàn toàn. Vớt miến ra rổ xả nước lạnh, để ráo rồi dùng kéo cắt đoạn 15–18 cm, cho vào tô lớn trộn đều với 1/3 lượng sốt đã pha. Tận dụng nồi nước sôi thêm 1 g muối ăn vào chần rau chân vịt 1 phút cho vừa héo, vớt ngay xả nước lạnh, vắt thật kiệt nước rồi cắt làm đôi.', 'Miến khoai lang phải luộc mềm dẻo hoàn toàn thay vì để sượng lõi; đồng thời vắt kiệt nước rau chân vịt để món trộn không bị chảy nước.', 8),
('imp-4ca7d6f55d5b7937_v4_step_3', 'imp-4ca7d6f55d5b7937', 3, 'cook', 'Xào săn sợi miến cho bóng mượt', 'Làm nóng chảo rộng trên lửa vừa với 8 ml dầu ăn, cho phần miến đã trộn sốt vào đảo đều liên tục trong 3 phút cho sợi miến săn bóng và thấm sâu gia vị, sau đó trút lại vào tô lớn.', NULL, 3),
('imp-4ca7d6f55d5b7937_v4_step_4', 'imp-4ca7d6f55d5b7937', 4, 'cook', 'Xào nhanh cà rốt, hành tây và hành lá còn độ giòn', 'Thêm 8 ml dầu ăn vào chảo trên lửa vừa–lớn, cho cà rốt vào xào 1 phút với 2 g muối ăn còn lại, gạt sang một bên rồi thả hành tây vào xào thêm 1 phút đến khi vừa trong và hành lá vào đảo nhanh 30 giây. Trút toàn bộ rau củ vào tô miến.', 'Xào rau trên lửa vừa–lớn trong thời gian ngắn để giữ độ giòn ngọt tự nhiên tương phản với sợi miến mềm dai.', 2),
('imp-4ca7d6f55d5b7937_v4_step_5', 'imp-4ca7d6f55d5b7937', 5, 'cook', 'Xào chín thịt bò và nấm hương tươi', 'Đổ 9 ml dầu ăn còn lại vào chảo nóng, cho thịt thăn bò và nấm hương tươi vào xào cùng 1/3 lượng sốt trên lửa lớn khoảng 3 phút đến khi thịt bò chín đều săn mềm và nấm thấm vị thơm thì trút tất cả vào tô miến.', NULL, 3),
('imp-4ca7d6f55d5b7937_v4_step_6', 'imp-4ca7d6f55d5b7937', 6, 'finish', 'Trộn đều miến Japchae và rắc mè rang thưởng thức', 'Cho rau chân vịt đã vắt ráo và 1/3 lượng sốt còn lại vào tô, dùng tay đeo găng thực phẩm trộn đều nhẹ nhàng để mọi nguyên liệu quyện sốt mà không làm đứt sợi miến. Bày ra đĩa lớn, rắc 2 g hạt mè trắng rang còn lại lên trên và thưởng thức.', NULL, NULL),
('imp-09e07baa201acf28_v4_step_1', 'imp-09e07baa201acf28', 1, 'prep', 'Vo ngâm gạo tẻ và hơ giòn rong biển lá khô', 'Vo sạch 200 g gạo tẻ hạt ngắn 2–3 lần nước rồi ngâm trong nước lạnh 30 phút cho hạt gạo ngậm nước, sau đó vớt ra rổ để thật ráo. Hơ nhanh 2 tờ rong biển lá khô trên lửa nhỏ vài giây đến khi giòn rụm, cho vào túi sạch bóp vụn và giã dập nhẹ 12 g hạt mè trắng rang.', 'Ngâm gạo đủ 30 phút trước khi rang và ninh giúp hạt gạo bung nở đều, cho nồi cháo sánh mịn mà không cần xay nhuyễn.', 30),
('imp-09e07baa201acf28_v4_step_2', 'imp-09e07baa201acf28', 2, 'prep', 'Băm nhỏ tôm tươi và thái hạt lựu rau củ', 'Tôm tươi bóc vỏ, rút chỉ đen sống lưng, rửa sạch và thái hạt lựu nhỏ. Thái hạt lựu nhỏ cà rốt và hành tây, băm nhuyễn tỏi khô, thái nhỏ hành lá và đánh tan 2 quả trứng gà trong chén.', NULL, NULL),
('imp-09e07baa201acf28_v4_step_3', 'imp-09e07baa201acf28', 3, 'cook', 'Phi thơm hành tỏi và rang gạo với dầu mè, tôm tươi', 'Đặt nồi lớn đáy dày lên bếp ở lửa vừa, cho 15 ml dầu mè rang, tỏi băm và hành tây vào đảo đều 2 phút đến khi hành mềm trong. Trút gạo đã ráo vào rang tiếp 2 phút cho hạt gạo hơi trong lại, rồi thả tôm tươi thái nhỏ vào đảo nhanh 1 phút cho tôm chuyển hồng thơm.', 'Rang gạo cùng dầu mè rang giúp hạt gạo săn thơm và tạo độ sánh béo tự nhiên đặc trưng của các món cháo Hàn Quốc.', 5),
('imp-09e07baa201acf28_v4_step_4', 'imp-09e07baa201acf28', 4, 'cook', 'Ninh nhừ gạo cùng cà rốt thành cháo sánh mịn', 'Cho cà rốt thái hạt lựu và 1.800 ml nước lọc vào nồi, khuấy đều tránh bén đáy rồi đậy nắp nấu trên lửa vừa 20 phút (hé nhẹ nắp hoặc khuấy khi sôi để tránh trào). Hạ xuống lửa nhỏ tiếp tục ninh thêm 10 phút nữa đến khi hạt gạo nở bung mềm nhừ và nước cháo sánh quyện.', NULL, 30),
('imp-09e07baa201acf28_v4_step_5', 'imp-09e07baa201acf28', 5, 'cook', 'Tạo vân trứng gà mềm mịn và nêm nước mắm', 'Mở nắp khuấy đều nồi cháo, rắc hành lá vào rồi từ từ rót dòng mỏng trứng gà đã đánh tan lên bề mặt cháo theo vòng tròn. Đậy nắp giữ lửa nhỏ thêm 1 phút cho vân trứng chín mềm rồi mới khuấy nhẹ. Nêm 25 ml nước mắm ngon và 2 g muối ăn cho vừa khẩu vị.', 'Không khuấy mạnh ngay lúc vừa rót trứng vào cháo để tạo được những dải vân trứng vàng đẹp mắt thay vì bị vụn đục.', 1),
('imp-09e07baa201acf28_v4_step_6', 'imp-09e07baa201acf28', 6, 'finish', 'Múc cháo nóng, rắc rong biển và mè rang', 'Tắt bếp, múc cháo tôm nóng hổi ra từng tô, rắc rong biển lá khô bóp vụn và hạt mè trắng rang giã dập lên trên rồi thưởng thức ngay.', NULL, NULL),
('imp-9c2f22829fd3d3f1_v4_step_1', 'imp-9c2f22829fd3d3f1', 1, 'marinate', 'Thái mỏng và ướp thịt bò thấm gia vị', 'Thái 260 g thịt thăn bò thành lát mỏng khoảng 3 mm theo chiều ngang thớ để thịt mềm ngọt. Cho thịt vào tô ướp đều với 1/2 lượng tỏi băm, 5 ml xì dầu, 3 g đường cát trắng, 2 g hạt nêm, 1 g tiêu đen xay và 5 ml dầu ăn, để thấm trong 15 phút.', 'Thái ngang thớ và trộn thêm 5 ml dầu ăn vào tô ướp giúp thịt bò giữ được độ mọng nước và không bị ra nước khi xào.', 15),
('imp-9c2f22829fd3d3f1_v4_step_2', 'imp-9c2f22829fd3d3f1', 2, 'prep', 'Sơ chế kim chi, hành tây và hành lá', 'Cắt kim chi cải thảo thành miếng vừa ăn khoảng 3 cm, hành tây thái múi cau mỏng, hành lá cắt khúc 3 cm và băm nhuyễn 1/2 lượng tỏi khô còn lại.', NULL, NULL),
('imp-9c2f22829fd3d3f1_v4_step_3', 'imp-9c2f22829fd3d3f1', 3, 'cook', 'Xào tái nhanh thịt bò trên lửa lớn', 'Đun nóng chảo rộng trên lửa lớn với 15 ml dầu ăn, cho phần tỏi băm còn lại vào phi thơm 20 giây rồi trút thịt bò đã ướp vào đảo nhanh tay khoảng 2 phút đến khi thịt vừa săn chuyển màu tái chín thì trút ngay ra đĩa riêng.', 'Xào riêng thịt bò trên lửa lớn rồi trút ra sớm giúp thịt không bị chín quá kỹ dẫn đến dai cứng khi xào tiếp với kim chi.', 2),
('imp-9c2f22829fd3d3f1_v4_step_4', 'imp-9c2f22829fd3d3f1', 4, 'cook', 'Xào săn kim chi cho dậy hương thơm', 'Dùng lại chảo nóng đó trên lửa vừa–lớn, cho kim chi cải thảo vào đảo đều khoảng 2 phút đến khi kim chi săn lại, tỏa mùi chua cay thơm nồng và hơi xém cạnh.', NULL, 2),
('imp-9c2f22829fd3d3f1_v4_step_5', 'imp-9c2f22829fd3d3f1', 5, 'cook', 'Xào quyện thịt bò, hành tây với sốt mật ong dầu hào', 'Trút đĩa thịt bò cùng hành tây thái múi cau trở lại chảo kim chi, nêm 15 ml xì dầu còn lại, 8 ml dầu hào và 8 ml mật ong nguyên chất. Đảo nhanh tay trên lửa lớn khoảng 2–3 phút đến khi thịt bò chín hoàn toàn, hành tây vừa chín giòn và nước sốt sánh bóng bám đều.', NULL, 3),
('imp-9c2f22829fd3d3f1_v4_step_6', 'imp-9c2f22829fd3d3f1', 6, 'finish', 'Thêm hành lá, dầu mè và mè rang dọn nóng', 'Thả hành lá cắt khúc vào đảo nhanh 30 giây rồi tắt bếp, rưới 5 ml dầu mè rang lên trên và đảo đều. Trút thịt bò xào kim chi ra đĩa, rắc hạt mè trắng rang tùy thích và dùng nóng ngay với cơm trắng.', 'Chỉ rưới dầu mè rang khi đã tắt bếp để hương thơm béo dịu được giữ trọn vẹn và không bị đắng.', NULL),
('imp-d7b9a40e678c0e29_v4_step_1', 'imp-d7b9a40e678c0e29', 1, 'marinate', 'Xăm da, thấm khô và ướp muối tiêu cho đùi gà', 'Lọc bỏ phần mỡ thừa ở mép 750 g thịt đùi gà rút xương, dùng mũi dao nhọn xăm nhẹ vài lỗ nhỏ trên bề mặt da (tránh đâm sâu vào thịt) và rạch mỏng ở những chỗ thịt quá dày để chín đều. Rắc đều 6 g muối ăn và 2 g tiêu đen xay lên cả hai mặt, để thấm 10 phút rồi dùng khăn giấy thấm thật khô lại mặt da.', 'Muối sẽ kéo bớt nước ra bề mặt thịt, vì vậy hãy thấm khô lại một lần nữa ngay trước khi cho lên chảo để da gà nổ giòn đẹp và không bắn mỡ.', 10),
('imp-d7b9a40e678c0e29_v4_step_2', 'imp-d7b9a40e678c0e29', 2, 'prep', 'Cắt khúc hành lá, chuẩn bị tỏi tép và chén chấm dầu mè', 'Cắt hành lá thành khúc dài 5 cm và bóc vỏ tỏi khô giữ nguyên tép. Trong chén nhỏ, trộn 15 ml dầu mè rang với 1 g muối ăn, 0,5 g tiêu đen xay và 4 g hạt mè trắng rang làm nước chấm. Cắt chanh tươi thành múi cau.', NULL, NULL),
('imp-d7b9a40e678c0e29_v4_step_3', 'imp-d7b9a40e678c0e29', 3, 'cook', 'Áp chảo mặt thịt rồi lật áp giòn mặt da không cần dầu', 'Đặt chảo gang hoặc chảo chống dính khô lên bếp lửa vừa, không cần cho dầu ăn. Đặt từng miếng đùi gà sao cho mặt thịt tiếp xúc với chảo trước khoảng 1 phút cho thịt định hình phẳng, sau đó lật úp mặt da xuống dưới, dùng xẻng ép nhẹ và nướng yên trong 7–8 phút. Thỉnh thoảng nghiêng chảo dùng giấy thấm bớt mỡ tiết ra (chừa lại khoảng 1 muỗng canh mỡ).', 'Áp mặt thịt trước 1 phút giúp miếng gà không bị co rút méo mó; không lật đi lật lại liên tục và thấm bớt mỡ thừa để da gà được nướng giòn thay vì bị ngập mỡ.', 8),
('imp-d7b9a40e678c0e29_v4_step_4', 'imp-d7b9a40e678c0e29', 4, 'cook', 'Chiên chín hoàn toàn mặt thịt và cho gà nghỉ', 'Khi mặt da đã vàng giòn rụm và tự bong khỏi đáy chảo, lật lại áp mặt thịt thêm 2 phút đến khi thịt gà chín trắng hoàn toàn và nước tiết ra trong suốt (nhiệt độ lõi đạt trên 75°C). Gắp gà ra thớt để nghỉ 3 phút trước khi thái miếng vừa ăn.', NULL, 5),
('imp-d7b9a40e678c0e29_v4_step_5', 'imp-d7b9a40e678c0e29', 5, 'cook', 'Nướng xém hành lá và tỏi nguyên tép trong mỡ gà', 'Tận dụng lượng mỡ gà thơm còn lại trong chảo, bật lửa lớn cho hành lá cắt khúc và tỏi nguyên tép vào áp chảo 2 phút, rắc thêm 1 g muối ăn và 0,5 g tiêu đen xay rồi đảo đều đến khi hành lá xém cạnh thơm ngọt và tỏi chuyển vàng bùi.', 'Nướng hành lá cắt khúc dài và tỏi nguyên tép trực tiếp trong mỡ gà giúp dậy hương thơm ngọt tự nhiên và cân bằng vị béo.', 2),
('imp-d7b9a40e678c0e29_v4_step_6', 'imp-d7b9a40e678c0e29', 6, 'finish', 'Bày gà nướng muối kèm chanh tươi và chấm dầu mè', 'Thái gà thành miếng vừa ăn xếp ra đĩa, gắp hành lá và tỏi nướng xém bày lên cạnh cùng múi chanh tươi. Khi thưởng thức hãy vắt vài giọt chanh lên thịt gà nóng và chấm với chén dầu mè muối tiêu.', NULL, NULL),
('imp-2b289d9040d46110_v4_step_1', 'imp-2b289d9040d46110', 1, 'prep', 'Thấm khô, cắt miếng đậu phụ và pha sốt kho', 'Cắt 420 g đậu phụ trắng thành từng miếng chữ nhật dày khoảng 1 cm, đặt lên khăn giấy sạch thấm khô hai mặt khoảng 5 phút để đậu săn và không bị bắn dầu khi chiên. Băm nhỏ gừng tươi, tỏi khô, thái hạt lựu hành tây và thái nhỏ hành lá. Khuấy tan 35 ml xì dầu, 12 g đường cát trắng, 2 g ớt bột Hàn Quốc (nếu dùng) cùng 60 ml nước lọc.', 'Thấm thật ráo nước trên bề mặt miếng đậu phụ trước khi áp chảo giúp tạo lớp vỏ vàng giòn nhanh mà không bị nát khi lật.', 5),
('imp-2b289d9040d46110_v4_step_2', 'imp-2b289d9040d46110', 2, 'cook', 'Áp chảo vàng giòn hai mặt từng miếng đậu phụ', 'Làm nóng chảo chống dính lớn trên lửa vừa với 25 ml dầu ăn, xếp đậu phụ vào áp chảo mỗi mặt 3–4 phút đến khi hai mặt vàng ươm và săn chắc, sau đó gắp ra đĩa riêng.', 'Chờ mặt dưới đậu phụ vàng cứng hẳn rồi mới lật sẽ giữ được miếng đậu nguyên vẹn, vuông vắn đẹp mắt.', 7),
('imp-2b289d9040d46110_v4_step_3', 'imp-2b289d9040d46110', 3, 'cook', 'Phi thơm hành tây, tỏi, gừng tươi và tráng chảo', 'Vẫn dùng chảo đó với lượng dầu thơm còn lại, cho hành tây, tỏi băm, gừng băm và 2/3 lượng hành lá vào xào đều trên lửa vừa khoảng 1 phút cho dậy mùi thơm nồng. Rót 60 ml nước lọc còn lại vào chảo tráng đều để hòa tan lớp hương thơm bám dưới đáy rồi đổ tiếp bát sốt xì dầu đã pha vào đun sôi nhẹ.', NULL, 1),
('imp-2b289d9040d46110_v4_step_4', 'imp-2b289d9040d46110', 4, 'cook', 'Kho thấm đậu phụ và rưới sốt đều hai mặt', 'Xếp đậu phụ đã chiên trở lại chảo nước sốt đang sôi nhẹ, hạ lửa vừa–nhỏ và kho 3 phút đồng thời dùng muỗng múc sốt rưới liên tục lên mặt trên của từng miếng đậu cho thấm đều.', NULL, 3),
('imp-2b289d9040d46110_v4_step_5', 'imp-2b289d9040d46110', 5, 'cook', 'Lật mặt đậu phụ kho đến khi nước sốt keo sánh', 'Nhẹ nhàng lật từng miếng đậu sang mặt còn lại và kho tiếp 2 phút nữa đến khi phần nước sốt cạn còn khoảng 1/3, sánh bóng bám quanh từng miếng đậu (giữ lại một ít sốt sệt để chan cơm).', 'Không kho cạn kiệt nước mà giữ lại lớp sốt sánh nhẹ giúp miếng đậu phụ bóng đẹp và đậm đà hơn khi chan cơm.', 2),
('imp-2b289d9040d46110_v4_step_6', 'imp-2b289d9040d46110', 6, 'finish', 'Rưới dầu mè, rắc mè rang và thưởng thức', 'Tắt bếp ngay, rưới 12 ml dầu mè rang lên khắp mặt chảo và lắc nhẹ cho đều. Xếp đậu phụ kho gừng ra đĩa, rưới hết phần sốt sệt lên trên, rắc 4 g hạt mè trắng rang cùng 1/3 hành lá còn lại rồi dùng nóng với cơm trắng.', NULL, NULL),
('imp-7cb7368109956ad5_v4_step_1', 'imp-7cb7368109956ad5', 1, 'prep', 'Rửa sạch giá đỗ và sơ chế kim chi, hành tỏi', 'Nhặt sạch vỏ đậu trên 400 g giá đỗ tươi nhưng giữ nguyên phần rễ vì rễ giá giúp nước canh ngọt và thanh hơn, ngâm nước lạnh 5 phút rồi xả sạch để ráo. Cắt kim chi cải thảo thành miếng vừa ăn (giữ lại 100 ml nước kim chi), băm nhuyễn tỏi khô, thái vát hành lá và thái lát ớt sừng tươi.', 'Giữ nguyên phần rễ giá đỗ khi nấu canh là mẹo truyền thống giúp nước canh ngọt mát và giàu dưỡng chất hơn.', 5),
('imp-7cb7368109956ad5_v4_step_2', 'imp-7cb7368109956ad5', 2, 'cook', 'Xào thơm tỏi và kim chi trên lửa vừa', 'Đun nóng nồi trên lửa vừa với 15 ml dầu ăn, cho tỏi băm vào phi thơm 20 giây rồi thả kim chi cùng 100 ml nước kim chi vào xào đều tay trong 3 phút đến khi kim chi săn lại và dậy mùi thơm.', NULL, 3),
('imp-7cb7368109956ad5_v4_step_3', 'imp-7cb7368109956ad5', 3, 'cook', 'Đun sôi nước dùng cá cơm tảo bẹ và nêm gia vị nền', 'Đổ 1.400 ml nước dùng cá cơm tảo bẹ Hàn vào nồi kim chi, đun sôi mạnh trên lửa lớn rồi nêm 10 ml xì dầu, 15 ml nước mắm ngon, 8 g ớt bột Hàn Quốc (nếu dùng) và ớt sừng tươi thái lát, nấu sôi liu riu 4 phút cho nước canh ra hết vị chua cay nền.', NULL, 4),
('imp-7cb7368109956ad5_v4_step_4', 'imp-7cb7368109956ad5', 4, 'cook', 'Thả giá đỗ và nấu mở nắp giữ độ giòn không hăng', 'Khi nước canh đang sôi mạnh, thả toàn bộ 400 g giá đỗ vào và giữ nguyên trạng thái mở nắp, đun trên lửa lớn khoảng 5–6 phút (thỉnh thoảng đảo nhẹ) cho đến khi hết mùi hăng đậu sống mà thân giá vẫn giòn ngọt.', 'Tuyệt đối mở nắp suốt quá trình nấu giá đỗ để hơi hăng bay thoát hết ra ngoài, giúp tô canh thanh khiết không bị mùi nồng.', 6),
('imp-7cb7368109956ad5_v4_step_5', 'imp-7cb7368109956ad5', 5, 'finish', 'Nêm muối cân chỉnh vị và thêm hành lá, dầu mè', 'Nếm lại nước canh rồi chỉ điều chỉnh thêm tối đa 1 g muối ăn nếu cần (vì nước dùng, kim chi và nước mắm đã có độ mặn sẵn). Thả hành lá thái vát vào nấu sôi bùng lại 30 giây, rưới 5 ml dầu mè rang rồi tắt bếp.', NULL, NULL),
('imp-7cb7368109956ad5_v4_step_6', 'imp-7cb7368109956ad5', 6, 'finish', 'Ủ ấm vài phút rồi múc tô dùng nóng', 'Để nồi canh nghỉ trên bếp khoảng 2 phút cho các vị hòa quyện sâu hơn trước khi múc ra tô, thưởng thức nóng cùng cơm trắng.', 'Cho canh nghỉ 2 phút sau khi tắt bếp giúp nước dùng trong và đậm vị hài hòa hơn hẳn.', 2),
('imp-a3e676be13c4c51c_v4_step_1', 'imp-a3e676be13c4c51c', 1, 'prep', 'Ninh nước dùng tảo bẹ củ cải thanh ngọt', 'Cho 1.200 ml nước lọc, 10 g tảo bẹ Kombu khô, 85 g củ cải trắng cắt khối và 1/4 củ hành tây vào nồi, đun sôi rồi hạ lửa vừa nấu 15 phút. Vớt bỏ toàn bộ tảo bẹ, củ cải trắng và hành tây, sau đó nêm nước dùng với 15 ml xì dầu, 3 g muối ăn và 0,5 g tiêu đen xay rồi giữ ấm.', 'Không đun tảo bẹ quá lâu trên lửa lớn để nước dùng luôn trong trẻo, ngọt thanh mà không bị nhớt hay đắng.', 15),
('imp-a3e676be13c4c51c_v4_step_2', 'imp-a3e676be13c4c51c', 2, 'marinate', 'Thái lát và ướp thịt bò theo kiểu Bulgogi', 'Thái thịt thăn bò thành lát mỏng 3 mm ngang thớ, cho vào tô lớn trộn đều với 50 ml xì dầu, 12 g đường cát trắng, 15 ml mật ong nguyên chất, 15 ml rượu Mirin Nhật, tỏi băm, 15 ml dầu mè rang và 1 g tiêu đen xay. Bóp nhẹ cho gia vị thấm đều rồi ướp 15 phút trong lúc sơ chế rau nấm.', NULL, 15),
('imp-a3e676be13c4c51c_v4_step_3', 'imp-a3e676be13c4c51c', 3, 'prep', 'Sơ chế nấm đùi gà, nấm hương, rau củ và ngâm miến', 'Thái lát dày 1 cm nấm đùi gà và thái lát dày 0,6 cm nấm hương tươi (tránh thái quá mỏng vì nấm sẽ ngót khi hầm). Thái lát mỏng cà rốt và 3/4 củ hành tây còn lại, cắt miếng vừa ăn cải thảo và cắt khúc 5 cm hành lá. Nếu dùng miến khoai lang Hàn, ngâm trong nước ấm 20 phút cho mềm rồi vớt ráo.', NULL, 20),
('imp-a3e676be13c4c51c_v4_step_4', 'imp-a3e676be13c4c51c', 4, 'cook', 'Xếp cụm thịt bò, nấm, rau củ và chế nước dùng', 'Dùng nồi lẩu hoặc nồi gốm nông lòng, lần lượt xếp thịt bò đã ướp, nấm đùi gà, nấm hương tươi, cà rốt, cải thảo, hành tây và miến khoai lang (nếu dùng) thành từng cụm xen kẽ đẹp mắt quanh lòng nồi. Chế khoảng 750 ml nước dùng nóng vào xâm xấp 2/3 nguyên liệu (phần nước dùng còn lại giữ nóng để châm thêm).', 'Xếp từng loại nguyên liệu theo cụm thay vì trộn lẫn giúp món hầm trông hấp dẫn và từng thành phần chín đều đẹp mắt.', NULL),
('imp-a3e676be13c4c51c_v4_step_5', 'imp-a3e676be13c4c51c', 5, 'cook', 'Nấu sôi tách thịt bò và hầm mềm nấm ngọt nước', 'Đặt nồi lên bếp ở lửa lớn đến khi nước dùng sôi bùng khoảng 3 phút, dùng đũa tách nhẹ các lát thịt bò cho khỏi dính chùm. Hạ xuống lửa vừa và nấu thêm 6 phút nữa đến khi thịt bò chín mềm hoàn toàn và các loại nấm thấm đẫm nước sốt ngọt dịu.', 'Thịt bò thái lát mỏng rất nhanh chín nên không hầm quá lâu sau khi nước sôi để giữ thớ thịt mềm ngọt không bị dai.', 6),
('imp-a3e676be13c4c51c_v4_step_6', 'imp-a3e676be13c4c51c', 6, 'finish', 'Rắc hành lá và thưởng thức nóng tại bàn', 'Nêm chỉnh lại nước hầm cho vừa miệng, thả hành lá cắt khúc lên trên rồi tắt bếp hoặc giữ lửa liu riu dùng nóng tại bàn kèm cơm trắng.', NULL, NULL),
('imp-1b54108818405e6a_v4_step_1', 'imp-1b54108818405e6a', 1, 'prep', 'Làm tơi cơm nguội, thái thịt ba chỉ và sơ chế kim chi', 'Dùng tay sạch bóp nhẹ cho 580 g cơm trắng nguội tơi rời từng hạt. Thái 180 g thịt ba chỉ heo thành miếng nhỏ 1,5 cm rồi ướp với 1 g muối ăn và 0,5 g tiêu đen xay. Cắt nhỏ kim chi cải thảo (giữ lại 60 ml nước kim chi), thái hạt lựu hành tây, tách riêng đầu hành trắng và lá xanh hành lá, cắt sợi mảnh rong biển lá khô.', 'Dùng cơm nguội để tủ lạnh qua đêm đã bóp tơi sẽ giúp cơm chiên săn hạt và không bị bết dính chảo.', NULL),
('imp-1b54108818405e6a_v4_step_2', 'imp-1b54108818405e6a', 2, 'cook', 'Áp chảo thịt ba chỉ vàng giòn và tiết mỡ thơm', 'Làm nóng chảo rộng trên lửa vừa với 5 ml dầu ăn, cho thịt ba chỉ đã ướp vào đảo đều khoảng 5–6 phút đến khi thịt chín vàng đều các mặt, xém cạnh giòn và tiết ra mỡ thơm (nếu mỡ tiết ra quá nhiều, chắt bớt chỉ giữ lại khoảng 1,5 muỗng canh mỡ trong chảo).', NULL, 6),
('imp-1b54108818405e6a_v4_step_3', 'imp-1b54108818405e6a', 3, 'cook', 'Phi thơm hành tây và xào kỹ kim chi với Gochujang', 'Cho hành tây thái hạt lựu và phần đầu hành trắng vào chảo mỡ thịt đảo nhanh 30 giây trên lửa lớn cho thơm. Sau đó trút kim chi cải thảo, 60 ml nước kim chi, 20 ml xì dầu và 25 g tương ớt Hàn Quốc (Gochujang) vào xào đều trong 3 phút đến khi kim chi mềm sậm màu và sốt quyện đều.', 'Xào kỹ kim chi cùng tương ớt Gochujang trước khi cho cơm vào giúp vị chua cay thấm sâu và loại bỏ hơi ẩm dư.', 3),
('imp-1b54108818405e6a_v4_step_4', 'imp-1b54108818405e6a', 4, 'cook', 'Rang cơm thấm đều sốt đỏ cam trên lửa vừa rồi tăng lửa lớn', 'Hạ bếp xuống lửa vừa–nhỏ, trút toàn bộ cơm nguội đã bóp tơi vào chảo, dùng muôi tán nhẹ và đảo đều 3 phút cho từng hạt cơm nhuộm màu đỏ cam bóng đẹp. Tiếp theo, tăng lên lửa lớn đảo thưa tay thêm 2 phút cho hạt cơm săn giòn và thơm mùi chảo.', 'Hạ lửa lúc mới trộn để cơm không dính đáy, rồi tăng lửa lớn ở 2 phút cuối giúp hạt cơm săn thơm cháy cạnh nhẹ.', 5),
('imp-1b54108818405e6a_v4_step_5', 'imp-1b54108818405e6a', 5, 'finish', 'Nêm chỉnh vị, rưới dầu mè và chiên trứng ốp la ăn kèm', 'Nếm thử và chỉnh thêm tối đa 1 g muối ăn cùng 0,5 g tiêu đen xay nếu cần, tắt bếp rồi rưới 10 ml dầu mè rang và phần lá xanh hành lá vào đảo đều. Trên một chảo chống dính nhỏ khác, đun nóng 10 ml dầu ăn còn lại và chiên ốp la 3 quả trứng gà đến độ chín mong muốn.', NULL, NULL),
('imp-1b54108818405e6a_v4_step_6', 'imp-1b54108818405e6a', 6, 'finish', 'Trình bày đĩa cơm chiên ba chỉ kim chi nóng hổi', 'Múc cơm chiên ba chỉ kim chi ra từng đĩa hoặc tô, đặt trứng ốp la lên trên, rắc thêm hạt mè trắng rang và rong biển lá khô cắt sợi rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-9328a098d7bd1f6f_v4_step_1', 'imp-9328a098d7bd1f6f', 1, 'prep', 'Làm sạch và khứa đùi gà cho thấm gia vị', 'Xát 3 g muối ăn lên khắp 800 g đùi gà góc tư để khử mùi hôi, rửa lại thật sạch dưới vòi nước lạnh rồi dùng khăn giấy thấm khô hoàn toàn. Dùng dao sắc khứa 2–3 đường sâu tới gần xương trên cả hai mặt đùi gà, sau đó xoa đều 3 g muối còn lại và 3 g tiêu đen xay để 10 phút.', 'Khứa sâu gần sát xương không chỉ giúp gia vị thấm tận lõi thịt mà còn giúp phần thịt dày quanh khớp xương chín kỹ đều khi nướng.', 10),
('imp-9328a098d7bd1f6f_v4_step_2', 'imp-9328a098d7bd1f6f', 2, 'marinate', 'Pha sốt chanh ớt và ướp lạnh đùi gà', 'Băm nhuyễn tỏi khô và 3 quả ớt hiểm đỏ. Trộn đều 30 ml nước cốt chanh tươi, 30 ml nước mắm ngon, 20 g đường cát trắng, 25 ml dầu ăn thực vật cùng tỏi và ớt băm đến khi đường tan hết. Quét kỹ hỗn hợp sốt vào các rãnh khứa và hai mặt đùi gà, bọc kín cho vào ngăn mát tủ lạnh ướp ít nhất 60 phút.', 'Ướp gà trong ngăn mát tủ lạnh vừa đảm bảo an toàn thực phẩm vừa giúp lớp da se khô nhẹ, khi nướng sẽ lên màu vàng giòn hơn.', 60),
('imp-9328a098d7bd1f6f_v4_step_3', 'imp-9328a098d7bd1f6f', 3, 'cook', 'Làm nóng lò và nướng đùi gà lần đầu', 'Làm nóng trước lò nướng hoặc nồi chiên không dầu ở mức 195–200°C trong 10 phút. Xếp đùi gà lên vỉ có lót khay hứng mỡ phía dưới (ngửa mặt da xuống dưới trước), phết thêm một lớp sốt ướp còn dư rồi nướng ở 200°C trong 20 phút.', NULL, 20),
('imp-9328a098d7bd1f6f_v4_step_4', 'imp-9328a098d7bd1f6f', 4, 'cook', 'Lật mặt, phết sốt và nướng vàng giòn lớp da', 'Mở lò, lật mặt da đùi gà lên trên, phết thêm một lớp mỏng sốt ướp còn lại (nếu thấy sốt đặc nhanh cháy thì giảm nhiệt xuống 185°C) và nướng tiếp 15–20 phút nữa. Kiểm tra bằng cách xiên tăm vào phần thịt dày nhất gần xương thấy nước chảy ra trong veo, không còn dịch hồng và da gà vàng cánh gián giòn rụm là gà chín hoàn toàn.', 'Canh kỹ 10 phút cuối để tránh phần đường trong sốt làm xém đen da gà; có thể che giấy bạc lên đầu xương nếu cần.', 18),
('imp-9328a098d7bd1f6f_v4_step_5', 'imp-9328a098d7bd1f6f', 5, 'sauce', 'Để thịt nghỉ giữ nước và pha sốt chấm', 'Lấy đùi gà ra đĩa, để nghỉ 5 phút cho nước thịt ổn định bên trong thớ thịt. Trong lúc chờ, trộn 30 ml tương ớt Thái với 15 ml nước cốt chanh tươi còn lại và 1 quả ớt hiểm thái lát làm chén sốt chấm chua cay.', NULL, 5),
('imp-9328a098d7bd1f6f_v4_step_6', 'imp-9328a098d7bd1f6f', 6, 'finish', 'Chặt miếng, rắc hành lá và dọn nóng', 'Chặt đùi gà thành từng miếng vừa ăn (hoặc bày nguyên chiếc), rắc hành lá thái nhỏ lên bề mặt da giòn và dọn nóng kèm chén tương ớt chanh.', NULL, NULL),
('imp-cc203adb1d5aa11b_v4_step_1', 'imp-cc203adb1d5aa11b', 1, 'prep', 'Khử nhớt cá và sơ chế sả, cà chua', 'Cá tươi đánh sạch vảy, bỏ mang và màng đen trong bụng, xát đều 4 g muối ăn lên mình cá trong 1 phút rồi rửa lại thật sạch bằng nước lạnh, để ráo và cắt khúc dày 2,5 cm. Sả tươi bóc vỏ già, đập dập rồi cắt khúc 6 cm. Cà chua bỏ cuống, bổ 6 múi cau; chanh tươi vắt lấy 40 ml nước cốt; hành lá tách riêng đầu hành đập dập và lá xanh cắt khúc 2 cm, ngò rí cắt khúc.', 'Rửa sạch màng đen trong bụng cá và thấm khô giúp nước canh trong veo, không có mùi tanh.', NULL),
('imp-cc203adb1d5aa11b_v4_step_2', 'imp-cc203adb1d5aa11b', 2, 'cook', 'Xào sơ cà chua và ninh nước sả thơm', 'Đun nóng 10 ml dầu ăn thực vật trong nồi ở lửa vừa, thả đầu hành lá và 1 nửa lượng cà chua vào đảo nhanh 2 phút cho cà chua hơi mềm tiết màu tự nhiên. Chế 1400 ml nước lọc vào cùng 3 cây sả đập dập, bật lửa lớn đun sôi rồi hạ lửa vừa nấu 5 phút cho nước dậy mùi sả thơm nồng.', NULL, 5),
('imp-cc203adb1d5aa11b_v4_step_3', 'imp-cc203adb1d5aa11b', 3, 'cook', 'Nêm nước dùng và nấu chín cá', 'Nêm vào nồi nước sả 35 ml nước mắm ngon, 4 g muối ăn còn lại và 8 g đường cát trắng, khuấy tan. Khi nước đang sôi lăn riu ở lửa vừa, nhẹ nhàng thả từng khúc cá vào nấu khoảng 4 phút cho thịt cá se chắc lại, thường xuyên hớt sạch bọt nổi để nước canh trong.', 'Chỉ thả cá khi nước đang sôi và giữ lửa vừa sôi lăn riu, không dùng đũa đảo mạnh để khúc cá không bị nát.', 4),
('imp-cc203adb1d5aa11b_v4_step_4', 'imp-cc203adb1d5aa11b', 4, 'cook', 'Thêm cà chua còn lại và nấu chín hoàn toàn', 'Cho nốt phần cà chua múi cau còn lại và ớt hiểm đỏ vào nồi nấu thêm 3–4 phút cho đến khi cà chua vừa mềm giữ nguyên vỏ và thịt cá chín trắng đục hoàn toàn, dễ tách khỏi xương.', NULL, 4),
('imp-cc203adb1d5aa11b_v4_step_5', 'imp-cc203adb1d5aa11b', 5, 'finish', 'Tắt bếp nêm nước cốt chanh tươi', 'Tắt bếp rồi từ từ rót 40 ml nước cốt chanh tươi vào nồi, lắc nhẹ hoặc khuấy một vòng thật khẽ để giữ hương thơm thanh mát của chanh không bị bay hơi hay đắng.', 'Cho nước cốt chanh tươi sau khi tắt bếp giữ trọn hương thơm thanh mát và tránh làm nước canh bị đắng do tinh dầu vỏ chanh gặp nhiệt cao.', NULL),
('imp-cc203adb1d5aa11b_v4_step_6', 'imp-cc203adb1d5aa11b', 6, 'finish', 'Rắc rau thơm và dọn canh nóng', 'Thả hành lá thái khúc và ngò rí vào nồi canh, múc cá và nước dùng ra tô lớn (có thể gắp bỏ bớt khúc sả già) rồi thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-7bd81a7e8fb33958_v4_step_1', 'imp-7bd81a7e8fb33958', 1, 'prep', 'Làm sạch và khứa vảy rồng mực tươi', 'Mực ống tươi rút bỏ nội tạng, mai cứng, mắt và miệng mực; rửa sạch dưới vòi nước lạnh rồi dùng khăn giấy thấm thật khô cả mặt trong lẫn mặt ngoài. Dùng dao sắc khứa nhẹ mặt trong thân mực theo đường chéo đan lưới rồi cắt miếng cỡ 3×5 cm, râu mực cắt khúc vừa ăn.', 'Thấm thật khô thân mực trước khi hấp giúp mực không tiết ra quá nhiều nước làm nhạt vị sốt và giữ độ giòn ngọt.', NULL),
('imp-7bd81a7e8fb33958_v4_step_2', 'imp-7bd81a7e8fb33958', 2, 'prep', 'Sơ chế sả, tỏi ớt và rau thơm', 'Đập dập 4 cây sả tươi: lấy 2 cây thái lát chéo dày 0,3 cm lót kín đáy đĩa sâu lòng chịu nhiệt, 2 cây còn lại băm thật nhuyễn. Tỏi khô và 4 quả ớt hiểm đỏ băm nhỏ. Hành lá và ngò rí rửa sạch, để ráo, cắt khúc 2 cm (chừa lại ít gốc ngò băm nhỏ). Vắt chanh tươi lấy 50 ml nước cốt.', NULL, NULL),
('imp-7bd81a7e8fb33958_v4_step_3', 'imp-7bd81a7e8fb33958', 3, 'sauce', 'Pha nước om hấp và nước sốt chanh ớt Thái', 'Hòa tan 15 ml nước mắm ngon, 7 g đường cát trắng và 180 ml nước lọc để làm nước om, rưới đều lên mực đã xếp trên lớp sả trong đĩa. Trong chén riêng, khuấy tan 20 ml nước mắm ngon còn lại với 15 g đường cát trắng và 50 ml nước cốt chanh tươi, sau đó thêm sả băm, tỏi băm, ớt hiểm băm và gốc ngò băm vào trộn đều thành nước sốt Nam Jim.', 'Nếm thử chén sốt sao cho vị chua, cay, mặn, ngọt cân bằng rõ nét; nếu thích vị dịu hơn có thể thêm nửa muỗng cà phê đường.', 2),
('imp-7bd81a7e8fb33958_v4_step_4', 'imp-7bd81a7e8fb33958', 4, 'cook', 'Hấp om mực trên lửa lớn đúng thời gian', 'Đun sôi mạnh nước trong nồi hấp rồi đặt đĩa mực vào xửng, đậy kín nắp và hấp lửa lớn trong 4–5 phút. Quan sát thấy các miếng mực cuộn cong đẹp mắt, thịt chuyển trắng đục và săn chắc hoàn toàn là đạt.', 'Tuyệt đối không hấp mực quá 6 phút vì nhiệt cao kéo dài sẽ làm mực tiết hết nước ngọt và trở nên dai cứng.', 5),
('imp-7bd81a7e8fb33958_v4_step_5', 'imp-7bd81a7e8fb33958', 5, 'finish', 'Chắt bớt nước hấp và rưới sốt nóng hổi', 'Nhấc đĩa mực ra khỏi nồi hấp (cẩn thận hơi nóng), chắt bỏ bớt khoảng một nửa phần nước tiết ra trong đĩa để giữ lại độ đậm đà vừa phải, rồi rưới đều toàn bộ chén nước sốt chanh tỏi ớt lên khắp bề mặt mực khi còn đang bốc khói.', NULL, NULL),
('imp-7bd81a7e8fb33958_v4_step_6', 'imp-7bd81a7e8fb33958', 6, 'finish', 'Rắc hành ngò và thưởng thức ngay', 'Rắc hành lá và ngò rí cắt khúc lên trên đĩa mực hấp om sả, trộn nhẹ một lượt rồi dọn dùng nóng ngay với cơm trắng hoặc rau sống.', NULL, NULL),
('imp-0abadc2e606770a7_v4_step_1', 'imp-0abadc2e606770a7', 1, 'prep', 'Làm sạch cua biển và khử mùi tanh', 'Ngâm nguyên con 1800 g cua thịt biển trong thau nước đá lạnh khoảng 10 phút để cua dịu lại, không rụng càng khi hấp. Dùng bàn chải cứng chà sạch bùn đất quanh mai, yếm và kẽ chân cua dưới vòi nước chảy, cắt đôi 1 quả chanh tươi chà xát khắp mình cua để khử tanh rồi rửa lại thật sạch, để ráo.', 'Không tháo dây buộc cua trước khi hấp và giữ cua ngủ lạnh bằng đá giúp càng cua nguyên vẹn, không bị gãy rụng mất nước ngọt.', 10),
('imp-0abadc2e606770a7_v4_step_2', 'imp-0abadc2e606770a7', 2, 'prep', 'Sơ chế sả, gừng và chuẩn bị xửng hấp', 'Bóc bỏ vỏ già bên ngoài của 10 cây sả tươi, đập dập rồi cắt khúc dài 5 cm; gừng tươi cạo vỏ thái lát mỏng. Lót 2/3 lượng sả và một nửa lượng gừng kín đáy xửng hấp, đặt cua ngửa bụng lên trên (để giữ nguyên phần gạch ngọt không bị chảy ra) rồi xếp nốt 1/3 lượng sả và gừng còn lại lên mình cua.', 'Đặt ngửa mai cua xuống dưới giúp hơi nước lưu thông đều và giữ trọn phần gạch béo bùi trong mai.', NULL),
('imp-0abadc2e606770a7_v4_step_3', 'imp-0abadc2e606770a7', 3, 'cook', 'Hấp cua cùng hơi sả và rượu vang trắng', 'Rắc đều 6 g muối ăn và 2 g tiêu đen xay lên mình cua. Đổ 450 ml nước lọc và 120 ml rượu vang trắng nấu ăn vào đáy nồi (đảm bảo mực nước cách mặt xửng ít nhất 3 cm), đun sôi bùng trên lửa lớn rồi đặt xửng cua lên, đậy kín nắp hấp trong 7 phút.', NULL, 7),
('imp-0abadc2e606770a7_v4_step_4', 'imp-0abadc2e606770a7', 4, 'cook', 'Đảo vị trí cua và pha hỗn hợp dầu phết mai', 'Mở nắp nồi, cẩn thận đổi vị trí các con cua giữa lớp trên và lớp dưới cho chín đều, đậy nắp hấp tiếp 5 phút. Trong lúc chờ, khuấy đều 15 ml dầu ăn thực vật với 3 g muối ăn, 4 g hạt nêm và 4 g đường cát trắng thành hỗn hợp sệt.', NULL, 5),
('imp-0abadc2e606770a7_v4_step_5', 'imp-0abadc2e606770a7', 5, 'cook', 'Phết dầu gia vị và hấp hoàn thiện', 'Mở nắp nồi, dùng cọ phết đều hỗn hợp dầu gia vị lên mai và càng cua rồi đậy nắp hấp thêm 2 phút trên lửa lớn. Kiểm tra thấy vỏ cua chuyển màu đỏ cam tươi bóng, thịt ở khớp càng trắng đục săn chắc hoàn toàn là cua đã chín tới.', 'Phết một lớp mỏng dầu gia vị ở 2 phút cuối giúp vỏ cua đỏ bóng đẹp mắt và thơm dậy mùi hơn hẳn.', 2),
('imp-0abadc2e606770a7_v4_step_6', 'imp-0abadc2e606770a7', 6, 'finish', 'Giã muối tiêu chanh ớt và dọn cua nóng', 'Giã nhuyễn 3 quả ớt hiểm đỏ với 3 g muối ăn và 2 g tiêu đen xay còn lại, vắt nước cốt của 1 quả chanh tươi vào khuấy đều làm chén chấm. Gắp cua ra đĩa lớn cùng vài khúc sả hấp, cắt bỏ dây buộc và thưởng thức khi cua còn nóng hổi.', NULL, NULL),
('imp-cc6a0ca585b502d4_v4_step_1', 'imp-cc6a0ca585b502d4', 1, 'prep', 'Băm thịt gà và sơ chế hành tím, rau thơm', 'Kết hợp 300 g ức gà và 150 g thịt đùi gà lọc xương băm nhỏ vừa ăn bằng tay để thịt giữ được độ mọng nước. Băm nhuyễn tỏi khô và 3 quả ớt hiểm đỏ. Thái lát thật mỏng hành tím khô; thái chỉ lá chanh Thái; thái nhỏ hành lá và ngò rí; nhặt lá bạc hà tươi để ráo. Vắt 2 quả chanh tươi lấy 45 ml nước cốt.', 'Phối trộn ức gà cùng thịt đùi gà theo tỉ lệ 2:1 giúp món Larb vừa giàu đạm vừa mềm ngọt, không bị khô xác khi xào không dầu.', NULL),
('imp-cc6a0ca585b502d4_v4_step_2', 'imp-cc6a0ca585b502d4', 2, 'cook', 'Xào nước thịt gà bằm chín tơi mọng', 'Cho 50 ml nước lọc vào chảo rộng đun sôi lăn tăn trên lửa lớn. Trút toàn bộ thịt gà băm, tỏi băm và 5 ml nước mắm ngon vào, dùng muôi dằm và đảo liên tục khoảng 3–4 phút cho đến khi thịt gà tơi rời, chuyển trắng đục và chín hoàn toàn bên trong nhưng vẫn còn ít nước xào ẩm.', 'Tuyệt đối không xào khô cạn nước khiến thịt gà bị xơ; vừa thấy thịt chín hẳn không còn màu hồng là tắt bếp ngay.', 4),
('imp-cc6a0ca585b502d4_v4_step_3', 'imp-cc6a0ca585b502d4', 3, 'sauce', 'Tắt bếp ủ hành tím và nêm nước cốt chanh mắm', 'Tắt bếp rồi cho ngay hành tím thái lát mỏng vào chảo thịt gà còn nóng, đảo nhẹ để hơi ấm làm hành tím dịu bớt mùi hăng mà vẫn giữ độ giòn. Rưới tiếp 30 ml nước mắm ngon còn lại, 45 ml nước cốt chanh tươi và 4 g đường cát trắng vào trộn đều cho hòa vị.', NULL, 2),
('imp-cc6a0ca585b502d4_v4_step_4', 'imp-cc6a0ca585b502d4', 4, 'finish', 'Trộn thính gạo rang và ớt hiểm đỏ', 'Rắc từ từ 25 g thính gạo rang (Khao Khua) cùng ớt hiểm băm và lá chanh Thái thái chỉ vào chảo thịt ấm, đảo đều tay cho hạt thính thấm hút nước thịt quyện thành lớp áo sánh thơm đặc trưng.', 'Chỉ trộn thính gạo rang sau khi đã tắt bếp và ngay trước lúc dọn ăn để giữ mùi thơm bùi và độ sần sật chuẩn vị Isaan.', NULL),
('imp-cc6a0ca585b502d4_v4_step_5', 'imp-cc6a0ca585b502d4', 5, 'finish', 'Trộn hành lá, ngò rí và cân chỉnh vị', 'Thêm hành lá và ngò rí thái nhỏ vào đảo nhẹ một lượt. Nếm lại lần cuối để bảo đảm sự cân bằng giữa vị chua thanh của chanh, mặn thơm nước mắm, cay nồng của ớt và bùi béo của thính gạo.', NULL, NULL),
('imp-cc6a0ca585b502d4_v4_step_6', 'imp-cc6a0ca585b502d4', 6, 'finish', 'Bày đĩa cùng lá bạc hà tươi và dọn ấm', 'Múc larb gà ra đĩa, rắc lá bạc hà tươi lên trên mặt để giữ màu xanh mát không bị thâm nhiệt, dọn dùng ấm với xôi nếp hoặc cơm trắng và rau sống.', NULL, NULL),
('imp-6e4967b3145dee09_v4_step_1', 'imp-6e4967b3145dee09', 1, 'prep', 'Sơ chế nấm đùi gà, húng quế và pha sốt xào chay', 'Lau sạch 500 g nấm đùi gà bằng khăn ẩm, cắt bỏ gốc rồi thái lát vát dày 0,5 cm. Nhặt lá húng quế Thái rửa nhẹ rồi vẩy thật ráo nước. Thái miếng hành tây và ớt chuông đỏ; băm nhuyễn tỏi khô và 4 quả ớt hiểm đỏ; cắt khúc hành lá. Trong chén nhỏ, khuấy tan 30 ml dầu hào chay, 20 ml xì dầu nhạt, 8 ml xì dầu đặc, 15 g đường cát trắng và 20 ml nước lọc.', 'Vẩy thật ráo lá húng quế giúp chảo không bị bắn dầu và nước sốt xào giữ được độ sệt đậm đà không bị loãng.', NULL),
('imp-6e4967b3145dee09_v4_step_2', 'imp-6e4967b3145dee09', 2, 'cook', 'Áp chảo nấm đùi gà cho săn xém cạnh', 'Làm nóng chảo rộng trên lửa lớn với 15 ml dầu ăn thực vật, xếp nấm đùi gà dàn thành một lớp mỏng và để yên 2 phút cho mặt dưới hơi cháy xém vàng rồi mới đảo đều thêm 1 phút đến khi nấm săn lại, gạt nấm sang một bên chảo.', 'Để yên nấm 1–2 phút không đảo liên tục giúp nấm thoát bớt hơi nước và có lớp cháy cạnh thơm bùi thay vì bị ra nước nhũn.', 3),
('imp-6e4967b3145dee09_v4_step_3', 'imp-6e4967b3145dee09', 3, 'cook', 'Phi thơm tỏi ớt và xào rau củ', 'Thêm 10 ml dầu ăn thực vật còn lại vào phần trống trên chảo ở lửa vừa, cho tỏi băm và ớt hiểm băm vào phi khoảng 40 giây đến khi dậy mùi cay thơm nồng thì cho hành tây và ớt chuông đỏ vào đảo nhanh 1–2 phút cho rau củ vừa chín tới vẫn giữ độ giòn.', NULL, 2),
('imp-6e4967b3145dee09_v4_step_4', 'imp-6e4967b3145dee09', 4, 'cook', 'Áo đều sốt dầu hào chay trên lửa lớn', 'Bật lửa lớn, đảo chung nấm với rau củ rồi rưới đều chén sốt đã pha vào chảo. Xóc và đảo nhanh tay liên tục khoảng 2 phút cho đến khi nước sốt sôi sệt bóng mượt, áo bám đều từng lát nấm màu nâu hổ phách.', NULL, 2),
('imp-6e4967b3145dee09_v4_step_5', 'imp-6e4967b3145dee09', 5, 'finish', 'Tắt bếp trộn lá húng quế dậy hương', 'Tắt bếp ngay rồi trút toàn bộ 30 g lá húng quế Thái vào chảo nấm còn nóng, đảo nhanh tay trong 20–30 giây cho lá vừa héo mềm dưới nhiệt dư và dậy mùi thơm đặc trưng.', 'Luôn cho húng quế vào sau khi đã tắt bếp để giữ trọn tinh dầu thơm và màu xanh tươi, tránh bị thâm đen đắng.', NULL),
('imp-6e4967b3145dee09_v4_step_6', 'imp-6e4967b3145dee09', 6, 'finish', 'Trình bày ra đĩa và dùng nóng với cơm', 'Trút nấm xào húng quế ra đĩa, rắc thêm hành lá thái khúc lên trên và dọn dùng nóng ngay cùng cơm trắng dẻo.', NULL, NULL),
('imp-4d9fae75b597d2c5_v4_step_1', 'imp-4d9fae75b597d2c5', 1, 'prep', 'Thái thịt bò ngược thớ và băm nhuyễn sả tỏi', 'Đặt 500 g thịt thăn bò vào ngăn đá khoảng 20 phút cho hơi se cứng bề mặt rồi thái thành các lát mỏng đều khoảng 0,5 cm theo chiều ngang ngược thớ thịt. Bóc bỏ bẹ già của 3 cây sả tươi, lấy phần gốc trắng non băm thật nhuyễn; bóc vỏ tỏi khô rồi giã nhuyễn cùng 3 g tiêu đen xay.', 'Thái thịt bò ngược thớ giúp từng miếng thịt sau khi nướng dễ nhai, mềm ngọt và không bị dai gân.', 20),
('imp-4d9fae75b597d2c5_v4_step_2', 'imp-4d9fae75b597d2c5', 2, 'marinate', 'Trộn sốt sả và ướp lạnh thịt bò', 'Trong tô lớn, hòa tan 20 g đường nâu với 20 ml xì dầu nhạt, 20 ml nước mắm ngon, 15 ml dầu ăn thực vật và 5 ml dầu mè thơm đến khi đường tan hết. Thêm sả băm và hỗn hợp tỏi tiêu vào trộn đều rồi thả thịt bò vào bóp nhẹ cho gia vị áo đều từng lát. Bọc kín tô, ướp trong ngăn mát tủ lạnh ít nhất 30 phút.', 'Ướp thịt bò trong ngăn mát tối thiểu 30 phút (hoặc 2 giờ) giúp thịt ngấm sâu mùi sả tỏi và giữ được độ an toàn vệ sinh.', 30),
('imp-4d9fae75b597d2c5_v4_step_3', 'imp-4d9fae75b597d2c5', 3, 'prep', 'Làm nóng vỉ nướng và xiên que (nếu dùng)', 'Nếu xiên que tre, ngâm que trong nước sạch trước 30 phút để tránh cháy xém rồi xiên từng lát thịt bò dẹt theo dạng sóng. Làm nóng bếp than hoa hoặc vỉ nướng điện ở lửa vừa-lớn rồi phết lớp dầu mỏng lên mặt vỉ. Rũ nhẹ bớt vụn sả thừa bám dày trên thịt và bỏ phần nước ướp sống còn dư.', NULL, NULL),
('imp-4d9fae75b597d2c5_v4_step_4', 'imp-4d9fae75b597d2c5', 4, 'cook', 'Nướng nhanh thịt bò trên lửa vừa-lớn', 'Xếp các lát hoặc xiên thịt bò lên vỉ nóng sao cho không chồng lên nhau. Nướng khoảng 2–3 phút mỗi mặt đến khi bề mặt thịt chuyển nâu xém cạnh, mỡ rìa xèo thơm và thịt vừa chín tới bên trong mà không bị khô xác.', 'Lát thăn bò thái mỏng chín rất nhanh; tránh nướng quá 3 phút mỗi mặt kẻo thịt mất nước ngọt và bị dai.', 5),
('imp-4d9fae75b597d2c5_v4_step_5', 'imp-4d9fae75b597d2c5', 5, 'finish', 'Để thịt nghỉ ổn định nước ngọt', 'Gắp thịt bò nướng ra đĩa ấm, đậy hờ giấy bạc để thịt nghỉ trong 3 phút cho lượng nước ngọt phân bố đều trở lại trong từng thớ thịt.', NULL, 3),
('imp-4d9fae75b597d2c5_v4_step_6', 'imp-4d9fae75b597d2c5', 6, 'finish', 'Bày đĩa cùng chanh múi cau và ớt hiểm', 'Sắp xếp thịt bò nướng sả lên đĩa, đặt chanh tươi cắt múi cau và ớt hiểm đỏ thái lát bên cạnh để vắt thêm vị chua cay khi thưởng thức cùng cơm trắng, xôi nếp hoặc rau sống.', NULL, NULL),
('imp-a97820d3080e47eb_v4_step_1', 'imp-a97820d3080e47eb', 1, 'prep', 'Sơ chế tôm sú và chuẩn bị que xiên sả', 'Rửa sạch 500 g tôm sú tươi, cắt bỏ râu và chân, bóc vỏ phần thân nhưng giữ lại đầu và đuôi cho đẹp mắt; khía nhẹ dọc sống lưng rút sạch chỉ đen rồi thấm thật khô bằng khăn giấy. Lấy 2 cây sả tươi băm thật nhuyễn; 6 cây còn lại bóc lớp vỏ già, cắt khúc dài 15 cm, đập nhẹ phần gốc cho dậy mùi và vót nhọn một đầu làm que xiên.', 'Thấm thật khô con tôm giúp gia vị bám chặt và khi nướng không bị chảy nước làm nhạt thịt.', NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-a97820d3080e47eb_v4_step_2', 'imp-a97820d3080e47eb', 2, 'marinate', 'Ướp tôm với sả băm, dầu hào và nước mắm', 'Băm thật nhuyễn hành tím, tỏi khô và 2 quả ớt hiểm đỏ. Trộn đều tôm với sả băm, hành tỏi ớt băm, 15 ml dầu hào, 15 ml nước mắm ngon, 5 g đường cát trắng, 4 g hạt nêm, 2 g tiêu đen xay và 15 ml dầu ăn thực vật; ướp trong 20 phút cho tôm ngấm đều gia vị.', 'Chỉ dùng một lượng nhỏ đường cát trắng (5 g) để tôm lên màu vàng cam hấp dẫn mà không bị cháy đen bề mặt khi nướng nhiệt cao.', 20),
('imp-a97820d3080e47eb_v4_step_3', 'imp-a97820d3080e47eb', 3, 'prep', 'Xiên dọc thân tôm vào cây sả', 'Lần lượt dùng đầu nhọn của từng que sả xiên thẳng dọc từ phần đuôi xuyên qua thân tôm lên sát đầu để cố định dáng tôm thẳng đẹp và giúp tinh dầu sả tỏa thẳng vào phần thịt bên trong khi gặp nhiệt.', NULL, NULL),
('imp-a97820d3080e47eb_v4_step_4', 'imp-a97820d3080e47eb', 4, 'cook', 'Nướng tôm xiên sả vàng cam thơm lừng', 'Đặt các xiên tôm lên vỉ than hoa (hoặc xếp vào nồi chiên không dầu/lò nướng làm nóng sẵn ở 190°C) sao cho không chồng lên nhau. Nướng tổng cộng 8–10 phút, giữa chừng lật mặt một lần và phết nhẹ phần nước ướp còn lại trong âu lên thân tôm, đến khi vỏ đầu đuôi chuyển đỏ cam bóng đẹp và thịt tôm trắng đục săn chắc hoàn toàn.', 'Không nướng tôm quá lâu qua 10 phút vì thịt tôm sẽ mất nước, bị teo và khô dai.', 9),
('imp-a97820d3080e47eb_v4_step_5', 'imp-a97820d3080e47eb', 5, 'sauce', 'Giã chén muối ớt chanh chấm kèm', 'Trong lúc chờ tôm chín, giã nhuyễn 1 quả ớt hiểm đỏ còn lại với 3 g muối ăn trong cối nhỏ, sau đó vắt nước cốt 1 quả chanh tươi vào khuấy đều để tạo chén muối ớt chanh chua cay mặn hài hòa.', NULL, NULL),
('imp-a97820d3080e47eb_v4_step_6', 'imp-a97820d3080e47eb', 6, 'finish', 'Trình bày xiên tôm nướng và dùng nóng', 'Xếp các xiên tôm nướng sả còn bốc khói ra đĩa, dọn dùng nóng ngay cùng chén muối ớt chanh, xà lách và dưa leo tươi.', NULL, NULL),
('imp-a9d8b4d783b986d1_v4_step_1', 'imp-a9d8b4d783b986d1', 1, 'prep', 'Sơ chế tôm khô ráo, sả non và pha sốt cơm chiên', 'Tôm tươi bóc vỏ, rút chỉ đen, rửa sạch rồi dùng khăn giấy thấm thật khô. Bóc vỏ già 2 cây sả tươi, chỉ lấy phần gốc non thái lát thật mỏng. Tỏi khô băm nhỏ, cà rốt thái hạt lựu, hành lá tách riêng đầu trắng và lá xanh thái nhỏ, ớt hiểm thái lát. Đánh tơi 450 g cơm nguội và đánh tan 2 quả trứng gà. Hòa tan 20 ml xì dầu nhạt, 20 ml dầu hào, 10 ml nước mắm ngon, 5 g đường cát trắng và 20 ml nước lọc trong chén.', 'Chỉ dùng phần gốc non thái mỏng của cây sả giúp bạn ăn trực tiếp cùng cơm mà không bị xơ cứng, đồng thời thấm khô tôm để tôm không ra nước.', NULL),
('imp-a9d8b4d783b986d1_v4_step_2', 'imp-a9d8b4d783b986d1', 2, 'cook', 'Phi thơm sả tỏi và xào săn chín tôm tươi', 'Làm nóng 20 ml dầu ăn thực vật trong chảo lớn ở lửa lớn. Cho sả thái mỏng, đầu hành trắng, tỏi băm và ớt hiểm thái lát vào phi 30 giây đến khi thơm dịu (không để cháy tỏi), trút tôm vào xào nhanh 2–3 phút đến khi tôm cong tròn, chuyển màu hồng đỏ đục và chín hoàn toàn rồi gắp riêng ra đĩa.', 'Áp chảo tôm trước rồi gắp ra riêng giúp tôm giữ độ giòn ngọt và không bị nấu quá lửa dai cứng trong lúc rang cơm.', 3),
('imp-a9d8b4d783b986d1_v4_step_3', 'imp-a9d8b4d783b986d1', 3, 'cook', 'Chiên tơi trứng gà và xào cà rốt', 'Thêm 10 ml dầu ăn thực vật vào chảo đang nóng, đổ trứng gà đánh tan vào đảo nhanh tay cho tơi xốp rồi cho cà rốt vào xào thêm 2 phút trên lửa vừa-lớn đến khi cà rốt hơi mềm.', NULL, 2),
('imp-a9d8b4d783b986d1_v4_step_4', 'imp-a9d8b4d783b986d1', 4, 'cook', 'Rang cơm nguội tơi hạt trên lửa lớn', 'Trút toàn bộ 450 g cơm nguội vào chảo, tăng lửa lớn và đảo đều liên tục khoảng 3 phút cho hạt cơm nóng đều, tơi rời từng hạt và quyện cùng trứng, cà rốt.', NULL, 3),
('imp-a9d8b4d783b986d1_v4_step_5', 'imp-a9d8b4d783b986d1', 5, 'cook', 'Rưới sốt và đảo chung tôm hoàn thiện', 'Rưới đều chén sốt đã pha quanh thành chảo nóng cho bốc mùi thơm, đảo nhanh tay 2 phút đến khi cơm khô ráo thấm đều màu sắc hấp dẫn. Trút đĩa tôm đã xào trở lại chảo cùng tiêu trắng xay, đảo đều thêm 1 phút cho tôm nóng lại.', 'Đổ hỗn hợp sốt quanh thành chảo nóng rồi đảo nhanh tay giúp sốt sánh nhẹ thơm mùi khói chảo mà không làm hạt cơm bị ướt nhão.', 3),
('imp-a9d8b4d783b986d1_v4_step_6', 'imp-a9d8b4d783b986d1', 6, 'finish', 'Tắt bếp trộn hành lá và dọn nóng với chanh', 'Tắt bếp rồi cho phần lá hành xanh thái nhỏ vào đảo nhanh một vòng giữ màu xanh tươi. Xới cơm chiên tôm sả ra đĩa, xếp kèm chanh tươi cắt múi cau để vắt nhẹ và thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-4095c816782acd82_v4_step_1', 'imp-4095c816782acd82', 1, 'prep', 'Sơ chế cà chua, tôm khô và giã đậu phộng rang', 'Cà chua chín rửa sạch, dùng khăn thấm ráo, bỏ cuống rồi bổ 6 múi cau vừa ăn xếp vào âu trộn lớn. Tôm khô ngâm nước ấm 5 phút cho mềm rồi vớt để ráo. Làm nóng chảo khô ở lửa nhỏ, đảo đều 35 g đậu phộng trong 3 phút đến khi vàng giòn thơm, để nguội xát sạch vỏ lụa rồi giã dập thô.', 'Chọn cà chua vừa chín tới, cầm chắc tay để khi trộn múi cà chua không bị nát bấy và giữ được độ giòn mọng.', 3),
('imp-4095c816782acd82_v4_step_2', 'imp-4095c816782acd82', 2, 'prep', 'Chuẩn bị tỏi, ớt hiểm và rau thơm', 'Bóc vỏ tỏi khô rồi giã hoặc băm thật nhuyễn. Ớt hiểm đỏ thái lát mỏng (có thể bỏ bớt hạt nếu muốn giảm độ cay). Rửa sạch hành lá và ngò rí, để ráo nước rồi thái lát vát mỏng phần hành lá và cắt khúc ngắn ngò rí. Vắt 2 quả chanh tươi lấy khoảng 45 ml nước cốt.', NULL, NULL),
('imp-4095c816782acd82_v4_step_3', 'imp-4095c816782acd82', 3, 'sauce', 'Pha nước trộn salad chua cay mặn ngọt Thái', 'Cho 15 g đường thốt nốt, 30 ml nước mắm ngon và 45 ml nước cốt chanh tươi vào chén nhỏ, khuấy kỹ đến khi đường tan hoàn toàn. Thêm tỏi băm và ớt hiểm thái lát vào khuấy đều, nếm thử để chắc chắn vị chua, cay, mặn, ngọt hơi đậm một chút vì cà chua sẽ tiết thêm nước.', 'Dùng đường thốt nốt giúp nước trộn có độ sánh mượt nhẹ và vị ngọt hậu thanh hơn đường trắng thông thường.', NULL),
('imp-4095c816782acd82_v4_step_4', 'imp-4095c816782acd82', 4, 'finish', 'Trộn nhẹ tay cà chua và tôm khô với nước sốt', 'Rắc tôm khô mềm lên âu cà chua rồi rưới đều toàn bộ chén nước trộn lên trên. Dùng hai chiếc muỗng lớn hất trộn nhẹ tay 4–5 lượt cho nước sốt áo đều từng múi cà chua mà không làm dập ruột.', 'Dùng hai chiếc muỗng lớn hất trộn từ dưới lên thay vì khuấy vòng tròn giúp các múi cà chua nguyên vẹn và thấm đều nước trộn.', NULL),
('imp-4095c816782acd82_v4_step_5', 'imp-4095c816782acd82', 5, 'finish', 'Ướp thấm vị ngắn trước khi bày đĩa', 'Để âu salad cà chua nghỉ khoảng 5 phút ở nhiệt độ phòng (hoặc 10 phút trong ngăn mát tủ lạnh) cho cà chua tiết ra nước ngọt tự nhiên hòa quyện vào sốt chua cay.', NULL, 5),
('imp-4095c816782acd82_v4_step_6', 'imp-4095c816782acd82', 6, 'finish', 'Rắc hành lá, ngò rí và đậu phộng rang thưởng thức', 'Trút salad cà chua cùng nước sốt ra đĩa sâu lòng, rắc hành lá, ngò rí và đậu phộng rang giã dập lên trên cùng rồi dùng mát ngay.', NULL, NULL),
('imp-0e9c9740a6232263_v4_step_1', 'imp-0e9c9740a6232263', 1, 'prep', 'Giã tỏi ớt, sơ chế rau và pha sốt xào Thái', 'Cho tỏi khô đã bóc vỏ và 5 quả ớt hiểm đỏ vào cối giã thô (hoặc đập dập băm nhuyễn). Nhặt lá húng quế Thái rửa nhẹ và vẩy thật ráo nước; thái hạt lựu đậu đũa; thái nhỏ hành lá. Trong chén, hòa tan 25 ml dầu hào, 15 ml xì dầu nhạt, 5 ml xì dầu đặc, 15 ml nước mắm ngon, 10 g đường cát trắng và 30 ml nước lọc.', 'Giã thô tỏi và ớt bằng cối giúp tinh dầu vỡ ra nhiều hơn khi gặp dầu nóng, tạo mùi thơm nồng hơn hẳn so với băm bằng dao.', NULL),
('imp-0e9c9740a6232263_v4_step_2', 'imp-0e9c9740a6232263', 2, 'cook', 'Chiên trứng ốp la viền giòn lòng đào', 'Làm nóng chảo với 15 ml dầu ăn thực vật trên lửa vừa-lớn, đập từng quả trứng gà vào chiên khoảng 2 phút đến khi viền lòng trắng vàng giòn rụm còn lòng đỏ vẫn sánh dẻo, vớt ra đĩa lót giấy thấm dầu.', NULL, 2),
('imp-0e9c9740a6232263_v4_step_3', 'imp-0e9c9740a6232263', 3, 'cook', 'Phi thơm tỏi ớt và xào săn tơi thịt heo xay', 'Gạt bớt dầu thừa nếu cần hoặc dùng 15 ml dầu ăn thực vật còn lại trên lửa vừa-lớn, cho hỗn hợp tỏi ớt giã vào phi thơm 30 giây đến khi hơi vàng cạnh. Trút toàn bộ 450 g thịt heo xay vào, dùng xẻng dằm tơi liên tục trên lửa lớn trong 3 phút đến khi thịt tơi đều, hết màu hồng và chín hoàn toàn.', 'Xào thịt heo xay trên lửa lớn và dằm liên tục để thịt săn ráo tơi hạt, không bị vón cục hay ra nhiều nước đục.', 3),
('imp-0e9c9740a6232263_v4_step_4', 'imp-0e9c9740a6232263', 4, 'cook', 'Xào đậu đũa và rưới sốt áo đều thịt heo', 'Cho đậu đũa thái nhỏ vào đảo nhanh 1 phút cho giòn chín tới, rồi rưới đều toàn bộ chén sốt đã pha vào chảo. Tiếp tục đảo trên lửa lớn thêm 2 phút cho nước sốt sôi sệt, bám màu nâu cánh gián bóng mượt quanh từng hạt thịt và đậu.', NULL, 3),
('imp-0e9c9740a6232263_v4_step_5', 'imp-0e9c9740a6232263', 5, 'finish', 'Tắt bếp trộn lá húng quế Thái giữ hương thơm', 'Tắt bếp ngay rồi cho toàn bộ 30 g lá húng quế Thái vào chảo thịt còn nóng, đảo nhanh 15–20 giây để lá vừa héo mềm giữ nguyên màu xanh thẫm và tỏa hương thơm nồng đặc trưng.', 'Không xào húng quế quá lâu trên bếp đang bật lửa vì lá sẽ chuyển màu đen sẫm và mất mùi thơm tươi.', NULL),
('imp-0e9c9740a6232263_v4_step_6', 'imp-0e9c9740a6232263', 6, 'finish', 'Bày đĩa cùng trứng ốp la và dùng nóng', 'Múc thịt heo xào húng quế cùng phần sốt đọng trong chảo ra đĩa, rắc hành lá thái nhỏ lên trên, đặt bên cạnh cơm trắng nóng và trứng ốp la lòng đào để thưởng thức ngay.', NULL, NULL),
('imp-b6d6788784da6342_v4_step_1', 'imp-b6d6788784da6342', 1, 'prep', 'Làm sạch, khứa thân và ướp gia vị cho cá', 'Cá điêu hồng sau khi đánh vảy, bỏ mang và làm sạch bụng, dùng khăn giấy thấm thật khô cả trong lẫn ngoài rồi khía 3–4 đường chéo sâu trên hai bên thân cá. Xát đều 15 ml nước mắm ngon, 5 g muối ăn và 3 g tiêu trắng xay lên mình cá và vào các rãnh khứa, ướp 15 phút cho thịt cá săn đậm vị.', 'Thấm thật khô con cá trước khi ướp và trước khi áo bột là bước then chốt giúp dầu không bắn và da cá giòn phồng.', 15),
('imp-b6d6788784da6342_v4_step_2', 'imp-b6d6788784da6342', 2, 'prep', 'Áo bột mỏng và chuẩn bị tỏi ớt giã thô', 'Phủ nhẹ 20 g bột mì đa dụng thành lớp thật mỏng khắp hai mặt cá rồi giũ sạch phần bột thừa. Giã hoặc băm thô tỏi khô và 4 quả ớt hiểm đỏ sao cho còn hơi lợn cợn tự nhiên; băm nhỏ đường thốt nốt; vắt chanh tươi lấy 20 ml nước cốt; thái lát mỏng hành lá.', NULL, NULL),
('imp-b6d6788784da6342_v4_step_3', 'imp-b6d6788784da6342', 3, 'cook', 'Chiên cá vàng giòn hai mặt trên lửa vừa', 'Đun nóng 415 ml dầu ăn thực vật trong chảo sâu lòng trên lửa vừa đến khi nhúng đầu đũa thấy sủi tăm mạnh (khoảng 175°C). Cầm đuôi thả nhẹ cá trượt từ thành chảo vào, chiên 6–7 phút mỗi mặt đến khi lớp da chuyển vàng ruộm giòn tan và thịt cá bên trong chín trắng đục hoàn toàn, vớt ra đặt lên giá lưới cho ráo dầu.', 'Không lật cá quá sớm khi mặt dưới chưa đóng vảy giòn để tránh rách da dính chảo.', 14),
('imp-b6d6788784da6342_v4_step_4', 'imp-b6d6788784da6342', 4, 'sauce', 'Phi tỏi ớt và thắng nhẹ đường thốt nốt làm sốt', 'Đun nóng 35 ml dầu ăn thực vật trong chảo sạch ở lửa vừa, cho tỏi ớt giã thô vào phi khoảng 1–2 phút đến khi dậy mùi cay thơm và tỏi vừa chuyển vàng nhạt. Cho 25 g đường thốt nốt vào đảo đều 30 giây cho đường tan chảy hơi caramen nhẹ.', 'Phi tỏi ớt ở lửa vừa để tỏi chín thơm dịu mà không bị cháy đắng trước khi cho đường và nước mắm vào.', 2),
('imp-b6d6788784da6342_v4_step_5', 'imp-b6d6788784da6342', 5, 'sauce', 'Nấu sánh sốt mắm chanh cay ngọt kiểu Thái', 'Rót 25 ml nước mắm ngon còn lại, 60 ml nước lọc và 20 ml nước cốt chanh tươi vào chảo tỏi ớt, hạ lửa nhỏ đun sôi lăn riu và khuấy đều trong 2–3 phút cho đến khi nước sốt sánh sệt óng ả. Nếm lại bảo đảm đủ 4 vị mặn, ngọt, chua, cay cân bằng hài hòa.', NULL, 3),
('imp-b6d6788784da6342_v4_step_6', 'imp-b6d6788784da6342', 6, 'finish', 'Rưới sốt cay nóng lên cá giòn và dọn ăn ngay', 'Đặt cá chiên giòn ra đĩa lớn, rưới đều nước sốt tỏi ớt nóng hổi lên khắp thân cá vào phút cuối ngay trước khi dọn bàn, rắc hành lá thái lát lên trên và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-71cac2085659d819_v4_step_1', 'imp-71cac2085659d819', 1, 'prep', 'Ướp đùi gà và sơ chế dứa, rau củ đồng đều', 'Thấm khô 500 g thịt đùi gà lọc xương, cắt miếng vuông 2,5 cm rồi ướp với 2 g muối ăn và 2 g tiêu đen xay trong 10 phút. Dứa gọt vỏ bỏ mắt thái miếng vừa ăn; ớt chuông đỏ và hành tây cắt vuông 2,5 cm; đậu Hà Lan tước xơ cắt đôi; tỏi khô băm nhỏ; hành lá cắt khúc 2 cm; ớt hiểm thái lát.', 'Cắt thịt gà, ớt chuông, hành tây và dứa cùng kích thước vuông khoảng 2,5 cm giúp món xào chín đều và đẹp mắt.', 10),
('imp-71cac2085659d819_v4_step_2', 'imp-71cac2085659d819', 2, 'sauce', 'Pha sẵn nước sốt chua ngọt và nước bột bắp', 'Trong chén lớn, khuấy tan 45 ml giấm gạo, 20 g đường nâu, 15 ml tương ớt ngọt Thái và 15 ml nước mắm ngon. Trong chén nhỏ khác, hòa tan hoàn toàn 6 g bột bắp với 25 ml nước lọc để sẵn.', NULL, NULL),
('imp-71cac2085659d819_v4_step_3', 'imp-71cac2085659d819', 3, 'cook', 'Xào nhanh hành tây và ớt chuông giữ độ giòn', 'Làm nóng 10 ml dầu ăn thực vật trong chảo rộng ở lửa vừa-lớn, cho hành tây, ớt chuông đỏ và tỏi băm vào đảo nhanh khoảng 2 phút đến khi rau củ hơi xém cạnh thơm giòn thì trút riêng ra tô.', 'Xào sơ rau củ trước rồi lấy ra giúp giữ nguyên độ giòn ngọt tự nhiên và màu sắc tươi tắn không bị nhũn khi rim gà.', 2),
('imp-71cac2085659d819_v4_step_4', 'imp-71cac2085659d819', 4, 'cook', 'Áp chảo vàng thịt đùi gà và rim sốt chua ngọt', 'Cho 10 ml dầu ăn thực vật còn lại vào chảo, xếp thịt đùi gà thành một lớp và áp chảo khoảng 4 phút trên lửa vừa-lớn (lật mặt sau 2 phút) đến khi thịt gà xém vàng đều các cạnh. Rưới hỗn hợp sốt giấm đường đã pha vào đảo đều, hạ lửa vừa rim thêm 3 phút cho gà chín hoàn toàn bên trong và thấm vị.', NULL, 7),
('imp-71cac2085659d819_v4_step_5', 'imp-71cac2085659d819', 5, 'cook', 'Trộn dứa, đậu Hà Lan và làm sánh sốt với bột bắp', 'Trút lại tô hành tây, ớt chuông cùng dứa tươi và đậu Hà Lan vào chảo gà, đảo đều 1–2 phút cho đậu vừa chín tới. Khuấy đều chén nước bột bắp rồi rưới từ từ vào chảo, đảo liên tục thêm 1 phút đến khi nước sốt sánh trong óng ánh bám đều lên thịt gà và rau củ.', 'Cho dứa vào ở bước cuối cùng giúp dứa không bị nát và giữ được độ giòn mọng thanh mát.', 3),
('imp-71cac2085659d819_v4_step_6', 'imp-71cac2085659d819', 6, 'finish', 'Nêm lại vị, rắc hành lá và dùng nóng', 'Tắt bếp, nếm thử để bảo đảm vị chua ngọt hài hòa, rắc hành lá cắt khúc và ớt hiểm thái lát lên trên rồi dọn nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-b398545ca76325f1_v4_step_1', 'imp-b398545ca76325f1', 1, 'prep', 'Sơ chế bắp cải, đậu phụ, cà rốt và sả', 'Bắp cải xanh tách từng lá rửa sạch, lược bỏ phần cuống cứng rồi thái hoặc xé miếng vuông cỡ 4 cm để ráo. Cà rốt gọt vỏ, thái lát mỏng 0,3 cm. Đậu phụ trắng cắt khối vuông 2 cm. Sả tươi bóc bẹ già, dùng sống dao đập dập rồi cắt khúc 6 cm. Vắt 1,5 quả chanh tươi lấy 30 ml nước cốt; rửa sạch và thái nhỏ hành lá, ngò rí.', 'Thái bỏ bớt phần gân cứng ở cuống bắp cải giúp lá bắp cải chín đồng đều cùng lúc và giữ độ giòn ngọt.', NULL),
('imp-b398545ca76325f1_v4_step_2', 'imp-b398545ca76325f1', 2, 'cook', 'Xào thơm sả cà rốt và ninh nước dùng sả', 'Đun nóng 10 ml dầu ăn thực vật trong nồi ở lửa vừa, cho sả tươi đập dập và cà rốt thái lát vào đảo sơ 1 phút cho dậy mùi thơm dịu. Đổ 1000 ml nước lọc vào đun lửa lớn đến khi sôi bùng rồi hạ lửa vừa nấu 4 phút cho nước dùng thấm tinh dầu sả và cà rốt bắt đầu mềm.', NULL, 4),
('imp-b398545ca76325f1_v4_step_3', 'imp-b398545ca76325f1', 3, 'cook', 'Nấu bắp cải xanh và nêm gia vị chay', 'Thả toàn bộ bắp cải xanh vào nồi nước sả, nêm 8 g hạt nêm chay nấm hương và 6 g đường cát trắng. Nấu ở lửa vừa khoảng 4–5 phút đến khi lá bắp cải chuyển màu xanh trong, vừa chín mềm mà vẫn còn độ giòn nhẹ.', 'Không đậy nắp quá kín và không nấu bắp cải quá lâu để lá giữ màu xanh tươi đẹp mắt và nước canh không bị nồng.', 5),
('imp-b398545ca76325f1_v4_step_4', 'imp-b398545ca76325f1', 4, 'cook', 'Thả đậu phụ nấu nóng đều', 'Nhẹ nhàng thả các miếng đậu phụ cắt khối vào nồi, đun sôi lăn riu thêm 2 phút trên lửa vừa để đậu phụ nóng đều và thấm vị ngọt thanh của nước canh mà không bị vỡ nát.', NULL, 2),
('imp-b398545ca76325f1_v4_step_5', 'imp-b398545ca76325f1', 5, 'finish', 'Tắt bếp nêm nước mắm chay và nước cốt chanh', 'Tắt bếp rồi rót 25 ml nước mắm chay và 30 ml nước cốt chanh tươi vào nồi canh, khuấy nhẹ một vòng để vị chua thanh của chanh hòa quyện mà không bị bay mất hương tươi.', 'Luôn tắt bếp trước khi cho nước cốt chanh để canh có mùi thơm dịu tự nhiên và không bị đắng.', NULL),
('imp-b398545ca76325f1_v4_step_6', 'imp-b398545ca76325f1', 6, 'finish', 'Hoàn thiện với hành ngò và dùng nóng', 'Gắp bỏ bớt các khúc sả già, múc canh bắp cải sả ra tô lớn, rắc hành lá và ngò rí thái nhỏ lên trên rồi dùng nóng.', NULL, NULL),
('imp-9f9a3f24b4141acb_v4_step_1', 'imp-9f9a3f24b4141acb', 1, 'prep', 'Làm khô cua lột và băm hương liệu Thái', 'Rã đông hoàn toàn nếu dùng cua lột đông lạnh, rửa nhanh rồi cắt mỗi con làm 4 phần vừa ăn, dùng khăn giấy ép thấm thật khô ráo nước. Bóc vỏ 3 củ tỏi khô băm nhỏ (chia 2/3 để chiên vàng trước và 1/3 để xào); băm nhỏ 4 quả ớt hiểm đỏ và phần rễ ngò rí đã rửa sạch; hành lá tách riêng đầu trắng và lá xanh cắt khúc 2 cm, giữ lá ngò rí trang trí.', 'Cua lột phải được thấm thật khô ráo nước trước khi lăn bột thì dầu chiên mới không bắn và vỏ cua mới giữ độ giòn lâu.', NULL),
('imp-9f9a3f24b4141acb_v4_step_2', 'imp-9f9a3f24b4141acb', 2, 'cook', 'Chiên vàng giòn phần tỏi phi rắc mặt', 'Đun nóng 500 ml dầu ăn thực vật trong chảo sâu lòng ở lửa vừa-nhỏ. Thả 2/3 phần tỏi băm vào chiên đảo đều khoảng 2 phút đến khi tỏi vừa chuyển màu vàng sáng thì lập tức vớt ra rây hoặc giấy thấm dầu để nguội cho giòn rụm.', 'Vớt tỏi phi ngay khi màu vàng còn nhạt vì sức nóng dư sẽ tiếp tục làm tỏi vàng sẫm giòn tan mà không bị đắng khét.', 2),
('imp-9f9a3f24b4141acb_v4_step_3', 'imp-9f9a3f24b4141acb', 3, 'prep', 'Áo bột chiên giòn khô quanh miếng cua', 'Trộn đều 120 g bột chiên giòn khô với 2 g muối ăn và 2 g tiêu trắng xay trong tô lớn. Thả từng mẻ cua vào xóc nhẹ cho bột bám một lớp áo mỏng khô đều khắp các chân và thân cua, giũ rơi phần bột thừa.', NULL, NULL),
('imp-9f9a3f24b4141acb_v4_step_4', 'imp-9f9a3f24b4141acb', 4, 'cook', 'Chiên ngập dầu cua lột vàng giòn rụm', 'Tăng lửa vừa-lớn đưa dầu trong chảo lên khoảng 175–180°C. Thả cua đã áo bột vào chiên từng mẻ trong 4–5 phút đến khi vỏ cua chuyển màu vàng cam giòn rụm và thịt cua chín chắc hoàn toàn bên trong, vớt ra đặt lên giấy thấm dầu.', 'Chia cua chiên làm 2 mẻ để nhiệt dầu không bị tụt đột ngột khiến lớp bột bị ngấm dầu và ỉu mềm.', 5),
('imp-9f9a3f24b4141acb_v4_step_5', 'imp-9f9a3f24b4141acb', 5, 'cook', 'Phi thơm rễ ngò rí, tỏi ớt và xóc cua với xì dầu', 'Chắt gạn bớt dầu chiên ra bát riêng, chỉ chừa lại khoảng 15 ml dầu trong chảo ở lửa nhỏ. Phi thơm 1/3 lượng tỏi băm còn lại, rễ ngò rí băm và 2/3 lượng ớt hiểm băm trong 1 phút, sau đó bật lửa lớn cho đầu hành trắng và phần ớt băm còn lại vào đảo nhanh 30 giây. Trút cua chiên vào chảo, nêm 20 ml xì dầu, 3 g muối ăn còn lại và 5 g đường cát trắng rồi xóc đều thật nhanh tay trong 1 phút.', NULL, 2),
('imp-9f9a3f24b4141acb_v4_step_6', 'imp-9f9a3f24b4141acb', 6, 'finish', 'Trộn hành lá, rắc tỏi phi giòn và thưởng thức nóng', 'Cho phần lá hành xanh cắt khúc vào đảo nhanh 1 lượt rồi tắt bếp ngay. Gắp cua ra đĩa, rắc ngập phần tỏi phi vàng giòn lên trên, trang trí lá ngò rí và dùng ngay khi cua còn nóng giòn.', NULL, NULL),
('imp-8fecebfe6dc0f0a2_v4_step_1', 'imp-8fecebfe6dc0f0a2', 1, 'prep', 'Rang thơm hạnh nhân và sơ chế rau bina', 'Đặt chảo khô lên lửa vừa, cho 30 g hạnh nhân lát vào rang khoảng 2–3 phút, đảo liên tục đến khi hạnh nhân vàng nhẹ và dậy mùi thơm bùi thì đổ ra đĩa để nguội. Nhặt và rửa sạch 200 g rau bina tươi dưới vòi nước lạnh.', 'Rang hạnh nhân ở lửa vừa và đảo đều tay để hạt chín thơm từ trong mà không bị cháy sém bên ngoài.', 3),
('imp-8fecebfe6dc0f0a2_v4_step_2', 'imp-8fecebfe6dc0f0a2', 2, 'cook', 'Chần nhanh rau bina và vắt kiệt nước', 'Đun sôi 2 lít nước lọc trong nồi lớn, thả rau bina tươi vào chần khoảng 2 phút cho lá vừa chín xẹp và giữ màu xanh mướt. Vớt ngay rau ra rổ (giữ lại nồi nước trên bếp để luộc mì), để nguội bớt rồi dùng tay vắt thật kiệt nước.', 'Vắt thật ráo nước sau khi chần là bí quyết giúp sốt rau bina đặc mịn, đậm đà và không bị tách nước khi trộn mì.', 2),
('imp-8fecebfe6dc0f0a2_v4_step_3', 'imp-8fecebfe6dc0f0a2', 3, 'sauce', 'Xay nhuyễn sốt kem rau bina với phô mai', 'Cho rau bina đã vắt ráo, 20 g hạnh nhân rang, 60 g phô mai Ricotta tươi, 25 g phô mai Parmesan bào mịn, tỏi tươi bóc vỏ, 2 g muối ăn và 1,5 g tiêu đen xay vào cối xay. Bật máy xay đồng thời rót từ từ 40 ml dầu ô liu nguyên chất vào đến khi thu được hỗn hợp kem xanh sánh mịn.', NULL, NULL),
('imp-8fecebfe6dc0f0a2_v4_step_4', 'imp-8fecebfe6dc0f0a2', 4, 'cook', 'Luộc mì Ý al dente trong nước muối sôi', 'Cho 6 g muối ăn vào nồi nước vừa chần rau, đun sôi già trở lại rồi thả 270 g mì Ý spaghetti vào luộc khoảng 8–9 phút đến độ chín al dente (mềm ngoài, hơi dai nhẹ ở lõi). Trước khi chắt ráo, múc giữ lại 100 ml nước luộc mì nóng.', NULL, 9),
('imp-8fecebfe6dc0f0a2_v4_step_5', 'imp-8fecebfe6dc0f0a2', 5, 'finish', 'Trộn đều mì nóng với sốt rau bina', 'Cho mì Ý vừa vớt còn nóng vào tô trộn lớn cùng toàn bộ sốt kem rau bina. Đảo nhanh tay cho sốt bám đều từng sợi mì; nếu sốt hơi đặc, rưới thêm từng muỗng canh nước luộc mì ấm và trộn tiếp đến khi sốt bóng mượt.', 'Trộn sốt bằng sức nóng dư của sợi mì thay vì đun trực tiếp trên bếp giúp giữ trọn màu xanh ngọc và vị tươi thanh của rau bina.', NULL),
('imp-8fecebfe6dc0f0a2_v4_step_6', 'imp-8fecebfe6dc0f0a2', 6, 'finish', 'Trang trí hạnh nhân, parmesan và dọn ngay', 'Chia mì ra 3 đĩa sâu lòng, rắc 10 g phô mai Parmesan bào mịn và 10 g hạnh nhân rang còn lại lên trên mặt mì rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-20d3992a65cb17fd_v4_step_1', 'imp-20d3992a65cb17fd', 1, 'marinate', 'Sơ chế nguyên liệu và ướp ức gà', 'Ức gà phi lê rửa sạch, thấm khô, cắt miếng vuông cỡ 2 cm rồi ướp với 2 g muối ăn và 1 g tiêu đen xay trong 10 phút. Nấm đùi gà thái lát dày 0,5 cm, cà chua chín thái miếng nhỏ, tỏi tươi băm nhuyễn và ngò tây tươi băm nhỏ.', NULL, 10),
('imp-20d3992a65cb17fd_v4_step_2', 'imp-20d3992a65cb17fd', 2, 'cook', 'Áp chảo vàng đều miếng ức gà', 'Làm nóng 15 ml dầu ô liu nguyên chất trong chảo lớn trên lửa vừa-lớn. Dàn đều thịt ức gà thành một lớp, áp chảo khoảng 6 phút cho đến khi thịt vàng đều các mặt và chín tới hoàn toàn bên trong, rồi gắp gà ra đĩa riêng.', 'Không xếp thịt gà quá dày một lượt trong chảo để thịt không bị ra nước mà giữ được độ xém thơm mềm mọng.', 6),
('imp-20d3992a65cb17fd_v4_step_3', 'imp-20d3992a65cb17fd', 3, 'cook', 'Xào nấm đùi gà lửa lớn và nấu sốt cà chua', 'Vẫn chiếc chảo đó, thêm 20 ml dầu ô liu nguyên chất vào phi thơm tỏi băm trong 45 giây trên lửa vừa. Tăng lửa lớn, cho nấm đùi gà vào xào 5 phút đến khi nấm săn ráo và xém vàng nhẹ cạnh, nêm 2 g muối ăn và 1 g tiêu đen xay. Tiếp tục thả cà chua chín vào đảo 3 phút cho cà chua mềm tiết nước tạo sốt.', 'Xào nấm ở lửa lớn giúp nước nấm bay hơi nhanh, giữ được độ giòn ngọt và hương thơm đặc trưng.', 8),
('imp-20d3992a65cb17fd_v4_step_4', 'imp-20d3992a65cb17fd', 4, 'cook', 'Luộc mì Ý trong nồi nước muối sôi già', 'Trong lúc xào nấm và cà chua, đun sôi 2 lít nước lọc với 6 g muối ăn. Cho 320 g mì Ý spaghetti vào luộc khoảng 8–9 phút đến độ chín al dente, trước khi vớt nhớ múc giữ lại 120 ml nước luộc mì nóng.', 'Luộc mì ít hơn hướng dẫn bao bì 1 phút để sợi mì còn độ dai vừa phải khi đảo tiếp cùng sốt trên chảo.', 9),
('imp-20d3992a65cb17fd_v4_step_5', 'imp-20d3992a65cb17fd', 5, 'cook', 'Xóc mì Ý cùng thịt gà, nấm và nước luộc mì', 'Trút thịt ức gà đã áp chảo trở lại chảo sốt nấm cà chua, cho tiếp mì Ý vừa vớt ráo và khoảng 80–120 ml nước luộc mì vào. Xóc đảo đều tay trên lửa vừa-lớn trong 2 phút để tinh bột quyện sốt thành lớp áo bóng mượt bám quanh từng sợi mì.', NULL, 2),
('imp-20d3992a65cb17fd_v4_step_6', 'imp-20d3992a65cb17fd', 6, 'finish', 'Rắc ngò tây, phô mai Parmesan và dùng nóng', 'Tắt bếp, cho phần ngò tây tươi băm nhỏ vào đảo nhanh một lượt cho giữ màu và hương thơm tươi mát. Chia mì gà nấm ra 4 đĩa sâu lòng, rắc phô mai Parmesan bào (tùy thích) lên mặt rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-38137393c32d70d7_v4_step_1', 'imp-38137393c32d70d7', 1, 'prep', 'Bóc tôm giữ vỏ đầu và sơ chế rau củ', 'Rửa sạch 450 g tôm tươi, tách riêng phần đầu và vỏ tôm để nấu nước dùng. Rút sạch chỉ đen trên lưng tôm; giữ một nửa số thịt tôm nguyên con để áp chảo trang trí, nửa còn lại băm nhỏ. Cà rốt tươi và cần tây tươi cắt khúc to; tách riêng cọng và lá ngò tây tươi.', 'Tôm tươi còn nguyên đầu và vỏ là yếu tố tạo nên phần nước dùng ngọt đậm vị biển mà không cần thêm bột nêm.', NULL),
('imp-38137393c32d70d7_v4_step_2', 'imp-38137393c32d70d7', 2, 'cook', 'Rang vỏ tôm và ninh nước dùng hải sản', 'Làm nóng 10 ml dầu ô liu nguyên chất trong nồi trên lửa vừa, cho vỏ và đầu tôm vào rang đảo khoảng 3 phút đến khi chuyển màu hồng cam và dậy hương thơm. Thêm cà rốt, cần tây, 1 củ hành tím bổ đôi, 1 tép tỏi đập dập và cọng ngò tây vào xào thêm 3 phút. Rót 60 ml rượu vang trắng khô cho bay hơi cồn, đổ 1,5 lít nước lọc cùng 3 g muối ăn vào, đun sôi rồi hạ lửa nhỏ ninh 25 phút; lọc lấy phần nước dùng trong và giữ nóng trên bếp.', NULL, 25),
('imp-38137393c32d70d7_v4_step_3', 'imp-38137393c32d70d7', 3, 'cook', 'Áp chảo nhanh phần tôm nguyên con', 'Trong lúc ninh nước dùng, làm nóng chảo với 10 ml dầu ô liu nguyên chất trên lửa vừa-lớn. Thả phần tôm nguyên con vào áp chảo mỗi mặt 1–1,5 phút đến khi thịt tôm chuyển hồng đục, săn chắc và chín hoàn toàn thì gắp ra đĩa riêng cùng một ít lá ngò tây băm.', NULL, 3),
('imp-38137393c32d70d7_v4_step_4', 'imp-38137393c32d70d7', 4, 'cook', 'Phi hành tỏi và rang hạt gạo Arborio', 'Đun nóng 10 ml dầu ô liu nguyên chất còn lại trong chảo sâu lòng trên lửa vừa, cho phần hành tím và tỏi băm vào phi 4 phút đến khi hành mềm trong. Đổ 320 g gạo Ý Arborio (không vo) vào đảo liên tục 2 phút đến khi hạt gạo nóng ran và viền gạo hơi trong lại.', 'Bước rang gạo giúp lớp ngoài hạt gạo săn chắc, nhờ vậy hạt cơm dẻo sánh bên ngoài mà không bị nát vụn khi châm nước dùng.', 6),
('imp-38137393c32d70d7_v4_step_5', 'imp-38137393c32d70d7', 5, 'cook', 'Châm nước dùng tôm nấu chín cơm từng muôi', 'Rót 80 ml rượu vang trắng khô còn lại vào chảo gạo, đảo đều đến khi rượu bay hơi hết. Sau đó châm từng muôi nước dùng tôm đang nóng sủi tăm vào chảo, khuấy đều tay và đợi gạo hút gần cạn nước mới châm tiếp muôi kế tiếp; tiếp tục nấu khoảng 18 phút đến khi hạt gạo chín mềm sánh nhưng còn sần nhẹ ở lõi.', 'Luôn giữ nước dùng tôm ở trạng thái nóng sủi tăm khi châm vào gạo để quá trình chín diễn ra liên tục và hạt gạo không bị sượng.', 18),
('imp-38137393c32d70d7_v4_step_6', 'imp-38137393c32d70d7', 6, 'cook', 'Nấu chín tôm băm cùng cơm risotto', 'Khi gạo gần đạt độ chín mong muốn, thả phần thịt tôm băm nhỏ vào chảo cơm, đảo nhẹ tay thêm 2–3 phút đến khi tôm chuyển màu hồng đục chín hoàn toàn và hòa quyện vào nền cơm sánh.', NULL, 3),
('imp-38137393c32d70d7_v4_step_7', 'imp-38137393c32d70d7', 7, 'finish', 'Đánh bơ tạo độ bóng kem và trình bày', 'Tắt bếp ngay, thả 30 g bơ lạt lạnh cắt khối cùng phần lá ngò tây tươi băm nhỏ còn lại vào chảo, khuấy nhanh và dứt khoát khoảng 30 giây cho bơ tan nhũ hóa thành lớp kem bóng mượt. Nêm lại với 3 g muối ăn và 2 g tiêu đen xay cho vừa miệng, múc risotto ra đĩa sâu lòng, xếp tôm áp chảo lên trên và thưởng thức nóng.', NULL, NULL),
('imp-e61010e240534690_v4_step_1', 'imp-e61010e240534690', 1, 'prep', 'Làm sạch và cắt khoanh mực ống', 'Rửa sạch 600 g mực ống dưới vòi nước lạnh, rút bỏ túi mực, nội tạng, mai cứng và mắt răng mực. Thái thân mực thành các khoanh tròn dày đều 1 cm, phần râu cắt làm đôi rồi dùng khăn giấy thấm thật khô nước.', 'Thái khoanh mực dày đều nhau giúp mực chín đồng thời, tránh miếng nhỏ bị quắt trong khi miếng dày chưa mềm.', NULL),
('imp-e61010e240534690_v4_step_2', 'imp-e61010e240534690', 2, 'prep', 'Chuẩn bị tỏi, ớt và ngò tây', 'Bóc vỏ tỏi tươi, tách bỏ phần mầm xanh ở giữa rồi băm nhỏ. Ớt tươi rửa sạch, giữ nguyên quả nếu muốn vị cay nhẹ dịu hoặc thái lát nếu thích cay rõ; ngò tây tươi rửa sạch, thấm ráo rồi băm nhuyễn.', NULL, NULL),
('imp-e61010e240534690_v4_step_3', 'imp-e61010e240534690', 3, 'cook', 'Phi thơm tỏi ớt và xào săn mực', 'Đun nóng 30 ml dầu ô liu nguyên chất trong chảo sâu lòng trên lửa vừa. Cho tỏi băm và ớt tươi vào phi thơm khoảng 1 phút cho dậy hương (không để tỏi cháy vàng), rồi thả mực vào đảo nhanh tay 2 phút đến khi mực săn lại và chuyển màu trắng đục.', NULL, 3),
('imp-e61010e240534690_v4_step_4', 'imp-e61010e240534690', 4, 'cook', 'Khử mùi bằng rượu vang trắng khô', 'Vặn lửa lớn, rót 100 ml rượu vang trắng khô vào chảo mực và đun sôi mạnh khoảng 2–3 phút để cồn bay hơi hoàn toàn, đồng thời giữ lại vị ngọt thơm đậm đà.', 'Để lửa lớn ngay khi rót rượu giúp hơi cồn thoát nhanh trong khi hương trái cây thanh nhẹ của vang ngấm vào từng khoanh mực.', 3),
('imp-e61010e240534690_v4_step_5', 'imp-e61010e240534690', 5, 'cook', 'Om mực cùng cà chua pelati trên lửa liu riu', 'Đổ 400 g cà chua lột vỏ đóng hộp (pelati) vào chảo, dùng muỗng gỗ dằm nát phần thịt cà chua, nêm 5 g muối ăn và 1,5 g tiêu đen xay. Hạ xuống lửa nhỏ, đậy nắp kín và om liu riu 12 phút đến khi mực mềm hẳn.', 'Kiểm tra độ mềm bằng nĩa sau 12 phút; nếu mực cỡ lớn hơi dày, có thể om thêm 3–4 phút cho đến khi thớ mực mềm tơi.', 12),
('imp-e61010e240534690_v4_step_6', 'imp-e61010e240534690', 6, 'finish', 'Mở nắp sánh sốt, rắc ngò tây và dọn nóng', 'Mở nắp chảo, tăng lên lửa vừa-lớn đun thêm 3–4 phút cho nước sốt cà chua sánh đặc lại nhưng vẫn đủ độ ẩm để chấm bánh mì. Nếm lại gia vị cho vừa miệng, tắt bếp, rắc ngò tây tươi băm nhỏ lên trên, đảo nhẹ và dọn dùng nóng ngay.', NULL, NULL),
('imp-452ef6d0f8ec0de9_v4_step_1', 'imp-452ef6d0f8ec0de9', 1, 'prep', 'Làm sạch tôm và sơ chế tỏi ớt', 'Rửa sạch 350 g tôm tươi đã bóc vỏ, rạch nhẹ lưng lấy sạch chỉ đen rồi dùng khăn giấy thấm thật khô nước. Băm nhỏ tỏi tươi, thái lát ớt tươi đỏ và rửa sạch lá húng quế Tây để ráo.', 'Thấm khô tôm trước khi thả vào sốt sẽ giúp nước sốt cà chua giữ được độ sánh đậm mà không bị loãng nước.', NULL),
('imp-452ef6d0f8ec0de9_v4_step_2', 'imp-452ef6d0f8ec0de9', 2, 'cook', 'Phi thơm tỏi ớt trong dầu ô liu', 'Làm nóng chảo sâu lòng với 20 ml dầu ô liu nguyên chất trên lửa vừa, thả tỏi băm và ớt tươi vào đảo liên tục khoảng 1 phút cho dậy mùi thơm ấm mà không để tỏi chuyển vàng nâu.', NULL, 1),
('imp-452ef6d0f8ec0de9_v4_step_3', 'imp-452ef6d0f8ec0de9', 3, 'sauce', 'Nấu sánh sốt cà chua passata', 'Đổ 300 g cà chua nghiền nhuyễn (passata) cùng 50 ml nước lọc tráng lọ vào chảo. Nêm 3 g muối ăn và 1 g tiêu đen xay, khuấy đều và đun sôi lăn tăn trên lửa vừa khoảng 3 phút cho sốt hơi sánh lại.', 'Kiểm tra lại độ mặn trước khi cho tôm vào vì tôm biển vốn đã có vị mặn tự nhiên.', 3),
('imp-452ef6d0f8ec0de9_v4_step_4', 'imp-452ef6d0f8ec0de9', 4, 'cook', 'Om chín tới tôm tươi trong sốt cà chua', 'Thả tôm tươi vào chảo sốt đang sôi nhẹ, dàn đều cho tôm ngập trong nước sốt và om trên lửa vừa khoảng 4–5 phút, đảo nhẹ giữa chừng đến khi tôm uốn cong, chuyển màu đỏ cam và thịt săn đục chín hoàn toàn.', 'Không nấu tôm quá lâu vì tôm bóc vỏ chín rất nhanh, nấu quá 6 phút thịt tôm sẽ bị khô và mất độ giòn ngọt.', 5),
('imp-452ef6d0f8ec0de9_v4_step_5', 'imp-452ef6d0f8ec0de9', 5, 'finish', 'Trộn lá húng quế Tây và rưới dầu ô liu', 'Tắt bếp, xé nhỏ lá húng quế Tây tươi thả vào chảo tôm, đảo nhẹ cho lá héo dịu dậy hương. Múc tôm và sốt ra đĩa sâu lòng, rưới 5 ml dầu ô liu nguyên chất còn lại lên trên rồi thưởng thức nóng ngay.', NULL, NULL),
('imp-452ef6d0f8ec0de9_v4_step_6', 'imp-452ef6d0f8ec0de9', 6, 'finish', 'Thưởng thức cùng bánh mì nướng giòn', 'Dọn đĩa tôm om cà chua kèm các lát bánh mì nướng giòn hoặc bánh mì bơ tỏi ngay khi còn nóng ấm để chấm trọn phần nước sốt sánh thơm.', NULL, NULL),
('imp-f44be7e8c88c20d3_v4_step_1', 'imp-f44be7e8c88c20d3', 1, 'prep', 'Sơ chế rau củ và cắt khối cá hồi', 'Gọt vỏ khoai tây tươi và cắt hạt lựu 1,5 cm; cà rốt tươi thái lát mỏng; hành tây vàng băm nhỏ; ngò tây tươi và thì là tươi thái nhỏ. Cá hồi phi lê thấm khô, kiểm tra nhổ sạch xương dăm rồi cắt thành khối vuông 3 cm.', 'Cắt khoai tây kích thước đều nhau giúp khoai chín bở đồng thời, tạo độ sánh mượt tự nhiên cho nước súp.', NULL),
('imp-f44be7e8c88c20d3_v4_step_2', 'imp-f44be7e8c88c20d3', 2, 'cook', 'Xào mềm hành tây và rau củ với bơ lạt', 'Đun chảy 25 g bơ lạt trong nồi đáy dày trên lửa vừa. Thả hành tây băm vào xào dịu khoảng 4 phút cho trong mềm (không để cháy vàng), rồi thêm khoai tây và cà rốt vào đảo đều 2 phút cho rau củ ngấm bơ thơm.', NULL, 6),
('imp-f44be7e8c88c20d3_v4_step_3', 'imp-f44be7e8c88c20d3', 3, 'cook', 'Ninh mềm khoai tây và cà rốt trong nước dùng', 'Rót 900 ml nước dùng rau củ và nêm 3 g muối ăn vào nồi, đun sôi rồi hạ xuống lửa nhỏ, đậy nắp ninh liu riu khoảng 20 phút đến khi dùng nĩa xiên qua miếng khoai tây thấy mềm bở hoàn toàn.', NULL, 20),
('imp-f44be7e8c88c20d3_v4_step_4', 'imp-f44be7e8c88c20d3', 4, 'cook', 'Thả cá hồi nấu chín dịu trên lửa nhỏ', 'Nhẹ nhàng thả các khối cá hồi phi lê vào nồi súp, giữ lửa thật nhỏ và nấu khoảng 7 phút mà không khuấy mạnh tay để cá chín đục hoàn toàn, dễ tách thớ mà vẫn nguyên vẹn từng miếng.', 'Giữ lửa liu riu thay vì đun sôi mạnh sau khi cho cá vào giúp thịt cá hồi mềm mọng và không bị nát vụn trong nồi súp.', 7),
('imp-f44be7e8c88c20d3_v4_step_5', 'imp-f44be7e8c88c20d3', 5, 'sauce', 'Hòa kem tươi và nêm gia vị hoàn thiện', 'Từ từ rót 220 ml kem tươi vào nồi súp, khuấy thật nhẹ tay theo một chiều. Nêm 3 g muối ăn còn lại và 2 g tiêu đen xay, đun ấm thêm 2 phút trên lửa nhỏ rồi tắt bếp ngay khi mép nồi hơi lăn tăn.', 'Không đun sôi bùng sau khi đã cho kem tươi để tránh kem bị tách váng dầu.', 2),
('imp-f44be7e8c88c20d3_v4_step_6', 'imp-f44be7e8c88c20d3', 6, 'finish', 'Ủ ấm 5 phút và dọn súp nóng', 'Đậy nắp cho súp nghỉ 5 phút để hương vị hòa quyện sâu hơn. Múc súp cá hồi kem ra 4 tô sâu lòng, rắc 12 g ngò tây tươi và thì là tươi lên trên rồi dọn nóng cùng bánh mì nướng giòn.', NULL, NULL),
('imp-e748a717f7250188_v4_step_1', 'imp-e748a717f7250188', 1, 'prep', 'Xử lý dưa leo giòn và rau xà lách', 'Dưa leo giòn rửa sạch, bổ đôi dọc rồi thái lát mỏng 0,5 cm. Cho dưa leo vào rổ, rắc 1 g muối ăn xóc nhẹ và để ráo 12 phút cho thoát bớt nước thừa, sau đó vẩy nhẹ cho khô. Xà lách tươi rửa sạch, vẩy thật ráo rồi xé miếng vừa ăn.', 'Xóc muối cho dưa leo ra nước trước khi trộn sẽ giúp đĩa salad giòn rụm và không bị chảy nước lõng bõng.', 12),
('imp-e748a717f7250188_v4_step_2', 'imp-e748a717f7250188', 2, 'marinate', 'Sơ chế và ướp cá hồi phi lê', 'Thấm khô 360 g cá hồi phi lê bằng khăn giấy, nhổ sạch xương dăm rồi cắt miếng dày khoảng 2,5 cm. Ướp đều các mặt cá với 1,5 g muối ăn, 1 g tiêu đen xay và 10 ml dầu ô liu nguyên chất trong 10 phút cho thấm vị.', NULL, 10),
('imp-e748a717f7250188_v4_step_3', 'imp-e748a717f7250188', 3, 'sauce', 'Đánh nhũ tương sốt chanh vàng dầu ô liu', 'Vắt chanh vàng tươi lấy nước cốt lọc bỏ hạt, cho vào chén cùng 30 ml dầu ô liu nguyên chất, 1,5 g muối ăn, 0,5 g tiêu đen xay còn lại và 15 g ngò tây tươi thái nhuyễn. Dùng phới lồng hoặc nĩa đánh đều tay đến khi hỗn hợp hơi sánh quyện thành dạng nhũ tương.', 'Đánh kỹ nước cốt chanh và dầu ô liu thành nhũ tương sánh nhẹ sẽ giúp sốt bám đều lên cá và rau thay vì đọng đáy đĩa.', NULL),
('imp-e748a717f7250188_v4_step_4', 'imp-e748a717f7250188', 4, 'cook', 'Áp chảo cá hồi chín tới và tách miếng', 'Đun nóng chảo chống dính với 5 ml dầu ô liu nguyên chất còn lại trên lửa vừa-lớn. Đặt các miếng cá hồi vào áp chảo mỗi mặt 2,5–3 phút đến khi mặt ngoài xém vàng đẹp và phần lõi thịt chuyển hồng đục chín hoàn toàn. Gắp cá ra đĩa để nguội bớt 5 phút rồi tách thành miếng vừa ăn.', 'Không đảo lật cá quá sớm hoặc nấu quá lâu để cá không bị nát và giữ được độ mềm ẩm tự nhiên.', 6),
('imp-e748a717f7250188_v4_step_5', 'imp-e748a717f7250188', 5, 'finish', 'Trình bày và trộn nhẹ salad cá hồi', 'Lót xà lách tươi xuống đáy đĩa rộng, xếp dưa leo đã ráo nước và các miếng cá hồi áp chảo lên trên. Rưới đều nước sốt chanh vàng dầu ô liu khắp mặt đĩa rồi dùng hai muỗng trộn thật nhẹ tay để rau thấm sốt mà cá không bị vỡ.', NULL, NULL),
('imp-e748a717f7250188_v4_step_6', 'imp-e748a717f7250188', 6, 'finish', 'Trang trí lá bạc hà và thưởng thức mát', 'Rắc thêm vài lá bạc hà tươi xé nhỏ lên trên đĩa salad (tùy thích) và thưởng thức ngay khi rau còn giòn mát, hoặc làm lạnh nhanh 15 phút trong ngăn mát trước khi dọn.', NULL, NULL),
('imp-957396bc647d3798_v4_step_1', 'imp-957396bc647d3798', 1, 'prep', 'Tách nhánh bông cải xanh và sơ chế rau củ', 'Tách 600 g bông cải xanh thành các nhánh nhỏ vừa ăn, gọt sạch lớp vỏ xơ cứng ở cuống rồi rửa sạch. Cà chua bi bổ đôi, tỏi tươi đập dập, ớt tươi thái lát và 10 g ngò tây tươi thái nhỏ.', NULL, NULL),
('imp-957396bc647d3798_v4_step_2', 'imp-957396bc647d3798', 2, 'cook', 'Chần nhanh bông cải giữ màu xanh giòn', 'Đun sôi 1150 ml nước lọc với 4 g muối ăn, thả bông cải xanh vào chần khoảng 3 phút cho vừa chín tới rồi vớt ngay ra rổ để thật ráo nước (có thể xả nhanh qua nước lạnh để giữ màu xanh tươi sáng).', 'Chần sơ trước giúp bông cải chín đều từ thân tới bông mà không bị sậm màu khi om cùng cà chua.', 3),
('imp-957396bc647d3798_v4_step_3', 'imp-957396bc647d3798', 3, 'cook', 'Phi thơm tỏi với dầu ô liu và nấu cà chua', 'Làm nóng 45 ml dầu ô liu nguyên chất trong chảo lớn trên lửa vừa-nhỏ, cho tỏi đập dập vào phi thơm vàng nhẹ khoảng 2 phút. Thêm cà chua bi bổ đôi vào, tăng lên lửa vừa và đảo khoảng 6 phút đến khi cà chua mềm ra nước tạo sốt sánh.', 'Phi tỏi đập dập ở lửa vừa-nhỏ giúp dầu ô liu thấm trọn hương tỏi dịu mà không bị cháy đắng.', 8),
('imp-957396bc647d3798_v4_step_4', 'imp-957396bc647d3798', 4, 'cook', 'Om bông cải xanh thấm sốt cà chua', 'Cho toàn bộ bông cải xanh đã chần vào chảo sốt cà chua, đảo nhẹ cho sốt phủ đều các nhánh bông cải. Rưới thêm 50 ml nước lọc nóng, đậy nắp và om lửa nhỏ khoảng 8 phút đến khi bông cải mềm ngọt và ngấm đậm vị sốt.', 'Chỉ thêm lượng nước vừa đủ giữ ẩm đáy chảo để món om có lớp sốt sánh bám rau chứ không bị loãng thành canh.', 8),
('imp-957396bc647d3798_v4_step_5', 'imp-957396bc647d3798', 5, 'cook', 'Thêm ớt tươi và nêm gia vị', 'Mở nắp chảo, thả ớt tươi thái lát (nếu dùng) vào đảo đều 1 phút. Nêm 2 g muối ăn còn lại và 1,5 g tiêu đen xay cho vừa miệng.', NULL, NULL),
('imp-957396bc647d3798_v4_step_6', 'imp-957396bc647d3798', 6, 'finish', 'Trình bày và dọn ăn nóng', 'Gắp bỏ xác tỏi đập dập nếu muốn, bày bông cải xanh om cà chua ra đĩa sâu lòng, rắc ngò tây tươi thái nhỏ lên trên rồi dùng nóng hoặc ấm kèm món chính.', NULL, NULL),
('imp-c98aa0f1ffe2f469_v4_step_1', 'imp-c98aa0f1ffe2f469', 1, 'prep', 'Thấm khô sườn non và sơ chế rau củ', 'Rửa sạch 1,3 kg sườn non heo, chặt miếng vừa ăn rồi dùng khăn giấy thấm thật khô để sườn dễ xém vàng. Hành tây vàng và cà rốt tươi thái hạt lựu; tỏi tươi bóc vỏ để nguyên tép; lá nguyệt quế khô xé nhẹ bằng tay.', 'Thấm thật ráo nước trên mặt sườn trước khi áp chảo giúp miếng sườn vàng nâu thơm phức thay vì bị hấp hơi ra nước.', NULL),
('imp-c98aa0f1ffe2f469_v4_step_2', 'imp-c98aa0f1ffe2f469', 2, 'cook', 'Phi thơm thảo mộc và áp chảo vàng sườn non', 'Làm nóng 45 ml dầu ô liu nguyên chất trong nồi đáy dày trên lửa vừa, thả tỏi nguyên tép, thảo mộc Ý khô và lá nguyệt quế khô vào phi khoảng 1 phút cho dậy hương rồi gắp bỏ tỏi ra ngoài. Cho sườn non vào áp chảo khoảng 8 phút, trở đều các mặt đến khi sườn săn vàng đẹp.', 'Gắp tỏi ra trước khi áp chảo thịt lâu giúp nồi sốt không bị ám vị đắng do tỏi cháy.', 9),
('imp-c98aa0f1ffe2f469_v4_step_3', 'imp-c98aa0f1ffe2f469', 3, 'cook', 'Xào mềm hành tây, cà rốt và khử vang trắng', 'Thêm hành tây và cà rốt thái hạt lựu vào nồi đảo cùng sườn khoảng 10 phút trên lửa vừa không đậy nắp đến khi hành mềm thơm. Rưới 120 ml rượu vang trắng khô vào, vặn lửa lớn đun 4 phút đồng thời cạo nhẹ đáy nồi cho cồn bay hơi hoàn toàn.', NULL, 14),
('imp-c98aa0f1ffe2f469_v4_step_4', 'imp-c98aa0f1ffe2f469', 4, 'cook', 'Om sườn với cà chua đóng hộp 45 phút', 'Nếu trong nồi còn quá nhiều mỡ tiết ra thì chắt bớt, sau đó đổ 500 g cà chua đóng hộp vào cùng 8 g muối ăn và 2,5 g tiêu đen xay. Đảo đều, hạ xuống lửa nhỏ, đậy nắp kín và om liu riu khoảng 45 phút đến khi thịt sườn chín mềm và dễ dàng tách khỏi xương; thỉnh thoảng đảo và châm chút nước lọc nóng nếu sốt quá đặc.', 'Giữ lửa thật nhỏ và đậy kín nắp giúp hơi nóng tuần hoàn làm sườn mềm róc xương mà sốt cà chua không bị bén cháy đáy nồi.', 45),
('imp-c98aa0f1ffe2f469_v4_step_5', 'imp-c98aa0f1ffe2f469', 5, 'cook', 'Thêm quả ô liu đen và sánh sốt', 'Mở nắp, thả 120 g quả ô liu đen bỏ hạt vào đảo đều và nấu thêm 3 phút trên lửa vừa cho ô liu thấm vị sốt cà chua và nước sốt đạt độ sánh đậm mong muốn.', NULL, 3),
('imp-c98aa0f1ffe2f469_v4_step_6', 'imp-c98aa0f1ffe2f469', 6, 'finish', 'Vớt lá nguyệt quế và thưởng thức nóng', 'Vớt bỏ lá nguyệt quế khô, nêm lại gia vị cho vừa miệng rồi múc sườn om sốt cà chua ra đĩa sâu lòng để dùng nóng cùng bánh mì giòn hoặc cơm trắng.', NULL, NULL),
('imp-a286f8724d79a504_v4_step_1', 'imp-a286f8724d79a504', 1, 'prep', 'Chọn và thái lát cà chua chín mọng', 'Chọn 4 quả cà chua chín mọng để ở nhiệt độ phòng cho giữ trọn mùi thơm, rửa sạch, bỏ phần cuống cứng rồi thái thành các lát tròn ngang dày đều khoảng 0,8 cm.', 'Không dùng cà chua vừa lấy từ tủ lạnh vì hơi lạnh làm cấu trúc thịt cà chua bị bở và giảm hương vị tự nhiên.', NULL),
('imp-a286f8724d79a504_v4_step_2', 'imp-a286f8724d79a504', 2, 'prep', 'Để ráo và cắt lát phô mai Mozzarella tươi', 'Vớt 170 g phô mai Mozzarella tươi ra khỏi nước ngâm, đặt lên rây hoặc khăn giấy sạch để ráo khoảng 5 phút rồi cắt thành từng lát có độ dày tương đương lát cà chua.', NULL, 5),
('imp-a286f8724d79a504_v4_step_3', 'imp-a286f8724d79a504', 3, 'prep', 'Băm nhuyễn tỏi và xé lá húng quế Tây', 'Băm thật nhuyễn tỏi tươi và dùng tay xé nhẹ 12 g lá húng quế Tây tươi thành miếng vừa ăn để giữ mùi thơm tinh dầu mà không làm dập thâm lá.', 'Xé lá húng quế bằng tay thay vì thái dao kim loại giúp lá giữ màu xanh tươi lâu hơn.', NULL),
('imp-a286f8724d79a504_v4_step_4', 'imp-a286f8724d79a504', 4, 'finish', 'Xếp xen kẽ cà chua và phô mai ra đĩa', 'Xếp xen kẽ từng lát cà chua chín mọng với lát phô mai Mozzarella tươi thành vòng tròn hoặc hàng đều đặn trên đĩa phẳng lớn sao cho các lát hơi gối lên nhau.', NULL, NULL),
('imp-a286f8724d79a504_v4_step_5', 'imp-a286f8724d79a504', 5, 'finish', 'Rắc muối, tiêu, tỏi và rưới dầu ô liu', 'Rắc đều 3 g muối ăn và 1 g tiêu đen xay lên mặt cà chua và phô mai, tiếp tục rắc tỏi tươi băm nhuyễn và lá húng quế Tây tươi lên trên. Rưới đều 40 ml dầu ô liu nguyên chất phủ một lớp mỏng bóng mượt.', 'Nêm muối trực tiếp lên cà chua tươi là bước quan trọng giúp kéo vị ngọt dịu tự nhiên của cà chua hòa quyện với độ béo của phô mai.', NULL),
('imp-a286f8724d79a504_v4_step_6', 'imp-a286f8724d79a504', 6, 'finish', 'Hoàn thiện với giấm Balsamic và dùng ngay', 'Rưới thêm 15 ml giấm Balsamic Ý (tùy thích) lên trên mặt đĩa rồi để thấm nhẹ 2–3 phút và thưởng thức ngay ở nhiệt độ phòng.', NULL, 3),
('imp-83ed31fc537569a6_v4_step_1', 'imp-83ed31fc537569a6', 1, 'prep', 'Chần vắt rau bina và xào nhân thơm bơ tỏi', 'Đun sôi 1 lít nước lọc, chần sơ 350 g rau bina tươi trong 1–2 phút rồi vớt ra để nguội và vắt thật kiệt nước. Làm nóng 15 ml dầu ô liu nguyên chất và 15 g bơ lạt trong chảo trên lửa vừa, phi thơm tỏi tươi băm nhỏ, cho 2/3 lượng rau bina đã vắt vào xào 3 phút cùng 2 g muối ăn và 1 g tiêu đen xay rồi trút ra đĩa.', 'Vắt thật khô rau bina sau khi chần giúp phần nhân không bị ra nước làm bung cuộn thịt bò khi áp chảo.', 5),
('imp-83ed31fc537569a6_v4_step_2', 'imp-83ed31fc537569a6', 2, 'prep', 'Sơ chế rau củ và dần mỏng thịt bò', 'Thái hạt lựu cà chua chín tươi, băm nhỏ hành tím; cà rốt tươi chia 1/3 băm nhỏ và 2/3 thái hạt lựu vừa. Trải 8 lát thịt bò thái lát mỏng lên thớt, dùng búa dần nhẹ cho thịt phẳng đều; đặt lên mỗi lát 1 lát phô mai Mozzarella, một ít cà rốt băm nhỏ và phần rau bina đã xào.', NULL, NULL),
('imp-83ed31fc537569a6_v4_step_3', 'imp-83ed31fc537569a6', 3, 'prep', 'Cuộn chặt và cố định cuộn bò involtini', 'Gập nhẹ hai mép bên của lát thịt bò vào trong rồi cuộn tròn thật chắc tay, dùng chỉ nấu ăn buộc gọn hoặc ghim cố định bằng tăm nhọn để nhân phô mai không chảy tràn ra ngoài.', 'Gập hai mép ngang vào trước khi cuộn giúp giữ kín phô mai Mozzarella bên trong khi áp chảo và om.', NULL),
('imp-83ed31fc537569a6_v4_step_4', 'imp-83ed31fc537569a6', 4, 'cook', 'Áp chảo vàng các mặt cuộn bò và khử vang trắng', 'Đun chảy 25 g bơ lạt còn lại cùng 20 ml dầu ô liu nguyên chất trong chảo sâu lòng trên lửa vừa-lớn. Xếp các cuộn thịt bò vào áp chảo khoảng 7 phút, trở đều các mặt cho vàng thơm. Rót 80 ml rượu vang trắng khô vào đun sôi 2 phút cho cồn bay hơi hoàn toàn.', 'Áp chảo phần mép gấp xuống mặt chảo trước tiên giúp khóa kín cuộn thịt bò gọn đẹp.', 9),
('imp-83ed31fc537569a6_v4_step_5', 'imp-83ed31fc537569a6', 5, 'cook', 'Om cuộn bò với cà chua, hành tím và cà rốt', 'Thả hành tím băm và cà chua chín tươi thái hạt lựu vào chảo cùng 3 g muối ăn và 1 g tiêu đen xay còn lại. Đậy nắp, hạ xuống lửa nhỏ và om liu riu 15 phút. Sau đó thêm phần cà rốt thái hạt lựu vào om tiếp 5 phút, rồi thả 1/3 lượng rau bina còn lại vào nấu thêm 3 phút cho sốt sánh đậm và rau chín quyện.', NULL, 23),
('imp-83ed31fc537569a6_v4_step_6', 'imp-83ed31fc537569a6', 6, 'finish', 'Tháo dây buộc, cắt khoanh và dọn nóng', 'Tắt bếp, gắp các cuộn thịt bò ra thớt tháo bỏ dây buộc hoặc tăm, cắt vát làm đôi nếu thích rồi xếp ra đĩa sâu lòng. Chan phần nước sốt cà chua rau củ nóng hổi lên trên và dùng ngay.', NULL, NULL),
('imp-a92103c19952bcf0_v4_step_1', 'imp-a92103c19952bcf0', 1, 'prep', 'Chuẩn bị chanh vàng và sơ chế ức gà', 'Rửa sạch 3 quả chanh vàng tươi, bào mịn lấy khoảng 1 muỗng canh lớp vỏ vàng bên ngoài (tránh phần cùi trắng bị đắng) để riêng, sau đó vắt lấy nước cốt chanh lọc bỏ hạt. Cắt 650 g ức gà phi lê thành các miếng vừa ăn dày khoảng 1,8–2 cm và thấm khô.', 'Cắt miếng ức gà dày đều nhau giúp thịt chín thấu bên trong mà lớp vỏ ngoài không bị cháy.', NULL),
('imp-a92103c19952bcf0_v4_step_2', 'imp-a92103c19952bcf0', 2, 'marinate', 'Ướp thịt gà với nước cốt chanh và thảo mộc', 'Pha nước ướp gồm nước cốt chanh vàng, 50 ml rượu vang trắng khô, tỏi tươi cắt đôi, 3 g thảo mộc Ý khô và 4 g muối ăn. Trộn đều ức gà trong tô nước ướp, bọc kín rồi để ngăn mát tủ lạnh khoảng 60 phút cho thấm hương chanh dịu.', 'Không ướp ức gà trong nước chanh quá 2 giờ vì axit sẽ làm biến tính bề mặt khiến thịt gà bị bở.', 60),
('imp-a92103c19952bcf0_v4_step_3', 'imp-a92103c19952bcf0', 3, 'prep', 'Trộn lớp áo bột chiên xù Parmesan', 'Trộn đều 140 g bột chiên xù, 50 g phô mai Parmesan bào mịn, phần vỏ chanh vàng bào sợi, 10 g ngò tây tươi băm nhỏ, 4 g muối ăn còn lại và 1,5 g tiêu đen xay trong một đĩa trẹt rộng.', NULL, NULL),
('imp-a92103c19952bcf0_v4_step_4', 'imp-a92103c19952bcf0', 4, 'prep', 'Áo bột từng miếng ức gà đã ráo nước ướp', 'Làm nóng trước lò nướng ở 180°C và lót giấy nến lên khay nướng. Gắp từng miếng ức gà ra để ráo bớt nước ướp (không rửa lại), đặt vào đĩa bột chiên xù và ấn nhẹ hai mặt cho lớp bột bám kín đều.', NULL, NULL),
('imp-a92103c19952bcf0_v4_step_5', 'imp-a92103c19952bcf0', 5, 'cook', 'Chiên vàng hai mặt rồi nướng chín thấu trong lò', 'Đun nóng 180 ml dầu ô liu trong chảo lớn trên lửa vừa-lớn. Chiên từng mẻ gà mỗi mặt khoảng 3 phút cho lớp vỏ bột vàng giòn đẹp mắt rồi vớt ra giấy thấm dầu. Xếp gà lên khay nướng và cho vào lò ở 180°C nướng thêm 18–20 phút đến khi thịt gà chín trắng hoàn toàn bên trong, xiên vào không còn nước hồng.', 'Chiên nhanh tạo lớp vỏ giòn rồi nướng lò giúp thịt ức gà chín đều mọng nước và giảm lượng dầu thấm vào thịt.', 24),
('imp-a92103c19952bcf0_v4_step_6', 'imp-a92103c19952bcf0', 6, 'finish', 'Rắc ngò tây tươi và thưởng thức nóng', 'Xếp gà chiên chanh vàng ra đĩa, rắc nốt 5 g ngò tây tươi băm nhỏ còn lại lên trên rồi dọn dùng nóng ngay cùng salad rau xanh.', NULL, NULL),
('imp-afdcd866c1f92192_v4_step_1', 'imp-afdcd866c1f92192', 1, 'marinate', 'Thấm khô và ướp phi lê cá thịt trắng', 'Rửa sạch 600 g phi lê cá thịt trắng dưới vòi nước lạnh rồi dùng khăn giấy thấm thật khô. Rắc đều 2,5 g muối ăn và 1,5 g tiêu đen xay lên cả hai mặt miếng cá, để nghỉ 10 phút cho thịt cá săn và thấm gia vị.', 'Thấm thật khô bề mặt cá trước khi ướp muối tiêu giúp thịt cá săn chắc và giữ nguyên thớ đẹp khi om.', 10),
('imp-afdcd866c1f92192_v4_step_2', 'imp-afdcd866c1f92192', 2, 'prep', 'Sơ chế cà chua bi, hành tây và tỏi ớt', 'Cà chua bi rửa sạch, bổ đôi; hành tây vàng thái hạt lựu nhỏ; tỏi tươi thái lát mỏng; ớt tươi đỏ thái lát; ngò tây tươi băm nhỏ và chia làm hai phần.', NULL, NULL),
('imp-afdcd866c1f92192_v4_step_3', 'imp-afdcd866c1f92192', 3, 'cook', 'Phi thơm tỏi hành và nấu mềm cà chua bi', 'Làm nóng 35 ml dầu ô liu nguyên chất trong chảo sâu lòng rộng trên lửa vừa. Cho tỏi thái lát và ớt tươi vào đảo 1–2 phút đến khi vừa dậy mùi thơm (không để tỏi cháy vàng). Thêm hành tây, lá nguyệt quế khô và 2,5 g muối ăn còn lại vào xào 3 phút cho hành mềm trong, rồi cho cà chua bi và quả ô liu đen vào đảo nhẹ thêm 3 phút.', 'Xào tỏi thái lát trên lửa vừa giúp tỏi tiết mùi thơm dịu mà không bị cháy đắng.', 8),
('imp-afdcd866c1f92192_v4_step_4', 'imp-afdcd866c1f92192', 4, 'cook', 'Nấu nước dùng rượu vang trắng cho sôi', 'Rót 60 ml rượu vang trắng khô vào chảo, đun sôi 1 phút cho cồn bay hơi hết. Đổ tiếp 250 ml nước lọc và một nửa lượng ngò tây tươi băm vào chảo, đun sôi trở lại trên lửa vừa.', NULL, 2),
('imp-afdcd866c1f92192_v4_step_5', 'imp-afdcd866c1f92192', 5, 'cook', 'Om dịu phi lê cá chín tới trong nước dùng', 'Nhẹ nhàng xếp 4 miếng phi lê cá thành một lớp vào giữa chảo (mặt da hướng xuống dưới nếu có), gạt rau củ sang xung quanh và múc nước dùng rưới nhẹ lên mặt cá. Hạ xuống lửa nhỏ, đậy nắp om liu riu khoảng 7 phút cho thịt cá chuyển trắng đục hoàn toàn và dễ tách thớ khi ấn nhẹ bằng nĩa.', 'Không đảo lật mạnh miếng cá khi đang om để giữ phi lê nguyên vẹn, đẹp mắt và không bị nát.', 7),
('imp-afdcd866c1f92192_v4_step_6', 'imp-afdcd866c1f92192', 6, 'finish', 'Ủ ấm 3 phút, rắc ngò tây và dùng nóng', 'Tắt bếp, giữ nguyên nắp thêm 3 phút cho cá ngấm vị rồi gắp bỏ lá nguyệt quế khô. Múc cá ra 4 bát sâu lòng, chan nước dùng cà chua ô liu lên trên, rắc phần ngò tây tươi còn lại và dùng nóng kèm bánh mì giòn.', NULL, NULL),
('imp-6d26ce6b0af4fb79_v4_step_1', 'imp-6d26ce6b0af4fb79', 1, 'cook', 'Làm chín rau bina bằng độ ẩm tự nhiên và vắt kiệt nước', 'Nhặt và rửa thật sạch 600 g rau bina tươi dưới vòi nước, không cần vẩy quá khô mà cho thẳng rau còn ướt vào nồi to, đậy nắp đun lửa vừa 4–5 phút đến khi rau xẹp mềm. Vớt rau ra rổ để hơi nguội rồi dùng tay vắt thật kiệt hết nước thừa và thái thô.', 'Vắt kiệt nước rau bina sau khi hấp chín là bước quan trọng nhất để món om giữ độ kem sánh đặc chứ không bị tách nước.', 5),
('imp-6d26ce6b0af4fb79_v4_step_2', 'imp-6d26ce6b0af4fb79', 2, 'cook', 'Xào dịu hành tây và đảo thơm rau bina', 'Làm nóng 15 ml dầu ô liu nguyên chất trong chảo trên lửa thật nhỏ, cho hành tây vàng băm nhuyễn vào xào khoảng 8 phút đến khi hành mềm trong suốt mà không chuyển vàng. Thả rau bina đã vắt kiệt vào đảo nhanh 1 phút cho thấm hương hành rồi tạm tắt bếp.', 'Xào hành tây ở lửa thật nhỏ để hành tiết vị ngọt tự nhiên và trong mềm mà không bị cháy sém làm xỉn màu sốt trắng.', 9);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-6d26ce6b0af4fb79_v4_step_3', 'imp-6d26ce6b0af4fb79', 3, 'sauce', 'Nấu nền bột bơ và khuấy mịn sốt Béchamel', 'Đặt nồi nhỏ lên lửa nhỏ, cho 25 g bơ lạt vào đun chảy hoàn toàn rồi thêm 25 g bột mì đa dụng, khuấy liên tục bằng phới lồng trong 1–2 phút đến khi bột quyện bơ sủi bọt nhẹ mà không ngả nâu. Rót từ từ 250 ml sữa tươi không đường vào, vừa rót vừa khuấy đều tay để hỗn hợp hòa tan hoàn toàn không vón cục.', 'Rót sữa từng ít một ở bước đầu và khuấy liên tục bằng phới lồng giúp sốt Béchamel láng mịn tuyệt đối.', 3),
('imp-6d26ce6b0af4fb79_v4_step_4', 'imp-6d26ce6b0af4fb79', 4, 'sauce', 'Nấu sánh sốt và hòa tan phô mai Parmesan', 'Tiếp tục đun sốt trên lửa nhỏ khoảng 5 phút, khuấy đều tay đến khi sốt sánh mượt phủ đều mặt muỗng. Nêm 4 g muối ăn, 1 g tiêu đen xay và 0,5 g nhục đậu khấu xay, sau đó nhấc nồi khỏi bếp và khuấy tan 30 g phô mai Parmesan bào mịn.', NULL, 5),
('imp-6d26ce6b0af4fb79_v4_step_5', 'imp-6d26ce6b0af4fb79', 5, 'finish', 'Trộn quyện rau bina vào sốt kem Béchamel', 'Cho toàn bộ rau bina xào hành tây vào nồi sốt kem Béchamel, trộn đều nhẹ tay cho từng lá rau phủ kín lớp sốt trắng sánh mịn và nêm lại độ mặn vừa khẩu vị.', NULL, NULL),
('imp-6d26ce6b0af4fb79_v4_step_6', 'imp-6d26ce6b0af4fb79', 6, 'finish', 'Dọn nóng ngay khi sốt còn sánh mượt', 'Múc rau bina om sốt kem ra đĩa sâu lòng và dùng nóng ngay kèm các món thịt nướng hoặc cá áp chảo.', NULL, NULL),
('imp-bd34e8ea2eaa1cd4_v4_step_1', 'imp-bd34e8ea2eaa1cd4', 1, 'prep', 'Sơ chế bắp cải, rau củ và thịt xông khói', 'Thái sợi bắp cải xanh dày 1 cm; hành tây vàng thái lát mỏng; cần tây tươi và cà rốt tươi thái khoanh mỏng; khoai tây tươi cắt hạt lựu 1,5 cm; tỏi tươi băm nhỏ; ngò tây tươi thái nhỏ. Thịt ba chỉ xông khói thái hạt lựu cỡ 1 cm; đậu trắng đóng hộp tráng nước và để ráo.', NULL, NULL),
('imp-bd34e8ea2eaa1cd4_v4_step_2', 'imp-bd34e8ea2eaa1cd4', 2, 'cook', 'Xào thơm thịt xông khói và nền rau củ', 'Đun chảy 30 g bơ lạt cùng 30 ml dầu ô liu nguyên chất trong nồi súp lớn trên lửa vừa. Cho thịt ba chỉ xông khói, hành tây, cần tây, cà rốt, khoai tây và tỏi băm vào xào đảo khoảng 4 phút cho thịt tiết mỡ thơm và rau củ hơi dịu mềm.', 'Xào thịt ba chỉ xông khói cùng rau củ ngay từ đầu giúp hương khói đậm đà thấm đều vào nền nước dùng.', 4),
('imp-bd34e8ea2eaa1cd4_v4_step_3', 'imp-bd34e8ea2eaa1cd4', 3, 'cook', 'Om xẹp bắp cải với ngò tây và thảo mộc', 'Cho bắp cải xanh thái sợi, ngò tây tươi và 2 g thảo mộc Ý khô vào nồi cùng 200 ml nước dùng gà, đậy nắp nấu trên lửa vừa khoảng 5 phút cho bắp cải hơi xẹp xuống và ngấm vị.', NULL, 5),
('imp-bd34e8ea2eaa1cd4_v4_step_4', 'imp-bd34e8ea2eaa1cd4', 4, 'cook', 'Ninh mềm đậu trắng và rau củ 30 phút', 'Đổ đậu trắng đóng hộp và 500 ml nước dùng gà còn lại vào nồi, nêm 2 g muối ăn và 1,5 g tiêu đen xay. Đun sôi rồi hạ xuống lửa nhỏ, đậy nắp ninh liu riu khoảng 30 phút cho khoai tây, bắp cải và đậu trắng chín bở hòa quyện vị ngọt.', 'Nêm muối nhẹ tay lúc đầu và nêm lại cuối cùng vì thịt ba chỉ xông khói và phô mai Parmesan vốn đã có độ mặn.', 30),
('imp-bd34e8ea2eaa1cd4_v4_step_5', 'imp-bd34e8ea2eaa1cd4', 5, 'cook', 'Luộc riêng nui Ý hạt ngắn al dente', 'Trong lúc ninh súp, đun sôi 1 lít nước lọc với 3 g muối ăn trong nồi riêng. Cho 120 g nui Ý hạt ngắn (nếu dùng) vào luộc khoảng 8 phút đến độ chín al dente rồi vớt ra để ráo.', 'Luộc nui ở nồi riêng thay vì thả trực tiếp vào súp giúp nước súp thanh trong và nui không hút cạn nước dùng.', NULL),
('imp-bd34e8ea2eaa1cd4_v4_step_6', 'imp-bd34e8ea2eaa1cd4', 6, 'finish', 'Chia bát, chan súp nóng và rắc Parmesan', 'Nếm lại nồi súp cho vừa miệng. Chia nui Ý ra 4 tô sâu lòng, chan súp bắp cải đậu trắng nóng hổi lên trên, rắc 25 g phô mai Parmesan bào mịn và thưởng thức ngay kèm bánh mì giòn.', NULL, NULL);
